window.CANAL = {"actualizat":"07.11.2026","clipuri":[{"v":"1-fhMgpzndk","k":"s","t":"Free workout program to get you jacked","d":"07.11.2026","th":["program-si-split","volum-si-frecventa","incalzire","incepatori"],"i":["Programul ×4: 3 zile pe săptămână (piept-umeri-triceps, picioare, spate-bicepși), o zi liberă între ele; a patra zi, opțională, e pentru gât, antebrațe, abdomen, gambe.","Seturi de lucru pe exercițiu: 3 la începători, 2 la 2-3+ ani, 1 la avansați; 6-10 repetări la compuse, 8-15 la izolări; pauze 2-3 min și 1-2 min."],"e":[],"c":["3x4, 2x4, 1x4: seturi de lucru pe exercițiu, câte 4 exerciții pe antrenament","3 zile de antrenament + a 4-a opțională, 2 zile libere după ultimul antrenament","6-10 repetări la compuse, 8-15 la izolări","pauze 2-3 minute și 1-2 minute","încălzire 10 minute mers înclinat","seturi de rampă la 25%, 50%, 75%"]},{"v":"UHeYjD00oao","k":"l","t":"Jacked & Strong Workout Routine (Day 3 of 3)","d":"06.11.2026","th":["program-si-split","spate","brate","antebrate"],"i":["Ziua 3 din programul pe trei zile e spate și biceps: începi cu un maxim de antrenament pentru forță brută, apoi faci exerciții pentru masă musculară.","Maximul de antrenament al zilei e tracțiunea cu greutate: o singură repetare, un singur set, la circa 85% din maximul tău pentru o repetare.","După el vin helcometrul, ramatul cu sprijin la piept pe orizontală, flexiile cu bara și fluturările pentru deltoidul posterior.","Antrenamentul se încheie cu rulatul unei greutăți pe încheietură, ales pentru antebrațe."],"e":[["Weighted pull-up","training max: 1 repetare la ~85% din 1RM, un set"],["Lat pull down"],["Chest supported T-bar row","antrenează spatele superior pe orizontală"],["Barbell curl","pentru biceps, flexia cotului"],["Rear delt fly","pentru deltoidul posterior"],["Wrist roller","pentru antebrațe"]],"c":["85% din maximul pentru o repetare","1 repetare, 1 set la maximul de antrenament","3 zile pe săptămână"]},{"v":"YOZvoWwP7EQ","k":"s","t":"How to Get Lean and Stay Lean (Simply)","d":"04.11.2026","th":["slabit","cardio-si-pasi","nutritie","recuperare-si-somn"],"i":["Nu slăbi rapid: alege acțiuni zilnice sustenabile pe 6 luni (8.000-10.000 de pași, 3 antrenamente, mâncare întreagă, hidratare, somn).","Mersul după mese, în pauza de prânz sau la telefon, câte 10-20 de minute, se adună."],"e":[],"c":["8.000-10.000 de pași","3 antrenamente pe săptămână","6 luni","10-20 de minute de mers"]},{"v":"2eM-7Pj3Qmk","k":"l","t":"Jacked & Strong Workout Routine (Day 2 of 3)","d":"03.11.2026","th":["program-si-split","picioare","incalzire","volum-si-frecventa"],"i":["Ziua de picioare începe cu deadlift cu trap bar: o repetare la ~85% din maxim, într-un singur set, doar pentru forță.","Încălzire în rampă: 4–5 seturi cu greutate crescândă și repetări tot mai puține, ușoare ca să nu obosești înainte de singura repetare grea; pauză 2–3 minute.","După maxim urmează 5–6 exerciții, cu un set greu fiecare, la 6–15 repetări; poți face 2–3 seturi dacă preferi.","Același deadlift revine ca exercițiu de masă, cu greutate mai mică, la 6–10 repetări; tensiunea mecanică din repetările multe construiește mușchi.","Presa lucrează cvadricepșii fără grija echilibrului; flexiile completează femuralii, iar extensiile sunt doar un bonus."],"e":[["Trap bar deadlift","maxim de antrenament: 1 repetare la ~85%; apoi set de masă la 6–10 repetări"],["Leg press","cvadricepși, amplitudine mare"],["Leg curl","femurali, flexia genunchiului"],["Leg extension","izolare cvadricepși, „credit în plus”"],["Cable crunch","cu coardă, pentru abdomen"]],"c":["85% din 1RM","4–5 seturi de încălzire în rampă","pauză 2–3 minute înaintea repetării grele","5–6 exerciții suplimentare","6–15 repetări pe set de lucru","2–3 seturi opțional","6–10 repetări la deadlift de masă"]},{"v":"OKRYok3x7PY","k":"s","t":"3 days a week in the gym is plenty!","d":"03.11.2026","th":["program-si-split","volum-si-frecventa","cardio-si-pasi","mobilitate"],"i":["Trei zile grele pe săptămână ajung pentru majoritatea; în celelalte zile poți merge la sală pentru mobilitate, cardio ușor, abdomene sau flexibilitate.","Nu recomandă 6 zile x 2 ore, pentru că cei care dau acest sfat sunt, după el, pe steroizi; 3 zile sunt un punct de plecare solid."],"e":[],"c":["3 zile grele pe săptămână","10.000-20.000 de pași pe bandă înclinată (exemplu)","6 zile x 2 ore (criticat)"]},{"v":"UhuopEQ8QT8","k":"s","t":"How Fast Should You Gain Weight When Bulking?","d":"02.11.2026","th":["masa-musculara","nutritie"],"i":["La un lean bulk, ~2 lbs pe lună (jumătate de pound pe săptămână) e un ritm bun; grăbirea aduce mai ales grăsime.","Pornește cu 100-200 de calorii peste menținere și urmărește atent."],"e":[],"c":["2 lbs pe lună","0,5 lb pe săptămână","100-200 kcal peste menținere"]},{"v":"JTYsvbXwRkM","k":"s","t":"Mike Mentzer Was Right About Building Muscle All Along","d":"01.11.2026","th":["mike-mentzer","incepatori","volum-si-frecventa","failure-si-progresie"],"i":["Autorul crede că ar fi avut un fizic mai bun, cu jumătate din timp și mai puține dureri, dacă ar fi început cu un set la eșec în loc de 6-7 zile pe săptămână.","Totuși nu recomandă un set la eșec începătorilor, care au de învățat execuția; pentru ei sugerează 2-3 seturi, apoi trecerea la eșec când forma e bună."],"e":[],"c":["1 set la eșec (nu pentru începători)","2-3 seturi pentru începători","6-7 zile x 2 ore (trecutul autorului)","10 ani"]},{"v":"RgleDMQpIXc","k":"s","t":"This exercise will smoke your forearms!","d":"31.10.2026","th":["antebrate"],"i":["Wrist roller-ul antrenează și flexorii, și extensorii încheieturii; fără accesoriu folosești capătul unei bare cu o bandă elastică și un disc.","Îl face la finalul antrenamentului, un set la failure; se pot face și 2-3 seturi."],"e":[["wrist roller","la final, un set la failure, opțional 2-3 seturi; alternativă: capăt de bară cu bandă elastică și disc"]],"c":["1 set la failure","2-3 seturi"]},{"v":"xM9_9tb-8cA","k":"l","t":"Jacked & Strong Workout Routine (Day 1 of 3)","d":"30.10.2026","th":["program-si-split","piept","incalzire","umeri"],"i":["Fiecare antrenament începe cu un maxim de antrenament pentru forță, apoi exerciții pentru masă; în ziua 1 e împinsul la bancă plată, o repetare la ~85%.","Încălzire: bara goală pentru câteva repetări, apoi seturi în rampă, ca să te pregătești pentru repetarea grea fără oboseală inutilă.","La primul exercițiu de masă încălzește-te mai mult: un set ușor la ~50% din greutatea de lucru și încă unul-două dacă simți nevoia.","Ordinea după maxim: împins la aparat înclinat (piept sus), fluturări, extensii triceps, ridicări laterale pentru umeri, apoi wrist roller pentru antebrațe și priză.","După maxim faci 4–5 exerciții, de obicei un singur set greu fiecare; poți urca la 2–3 seturi."],"e":[["Flat barbell bench press","training max: 1 repetare la ~85% din 1RM"],["Incline machine press","accent pe pieptul de sus, plus umeri și triceps"],["Chest fly","piept, fără ca tricepsul să limiteze"],["Tricep push down","triceps"],["Lateral raise","deltoid lateral"],["Wrist roller","flexori și extensori ai antebrațului, forță de priză"]],"c":["85% din maximul pentru o repetare","4–5 exerciții după maxim","~50% din greutatea de lucru la încălzirea primului exercițiu de masă","2–3 seturi opțional"]},{"v":"BtYS7WT1aqk","k":"s","t":"You Don’t Need to Work Out as Much as You Think","d":"30.10.2026","th":["volum-si-frecventa","failure-si-progresie","principii-antrenament"],"i":["Autorul nu mai numără frecvența sau seturile: săptămâna e reușită dacă a lovit fiecare grupă mare cu cel puțin un set direct foarte greu și a progresat.","Concentrează-te pe forță în interval moderat de repetări, într-un program dovedit; restul e zgomot."],"e":[],"c":["un set direct la eșec pe grupă pe săptămână","3, 5, 6 ani"]},{"v":"Sm6Wiwopgek","k":"s","t":"Should You Lose Fat or Build Muscle First?","d":"28.10.2026","th":["slabit","masa-musculara","nutritie"],"i":["La 25-30% grăsime corporală se recomandă să slăbești întâi, pentru sănătate, până la 10-12%, chiar dacă pari slab.","Apoi alternezi faze de creștere și de tăiere, an după an, până ajungi musculos."],"e":[],"c":["25-30% grăsime","10-12% grăsime"]},{"v":"g-w7CTmHpEc","k":"s","t":"Why I Don't Recommend Full Body Workouts","d":"27.10.2026","th":["program-si-split","accidentari-si-articulatii","volum-si-frecventa"],"i":["Autorul recomandă full body doar începătorilor; la avansați, cu greutăți mari, tendoanele și articulațiile nu au timp de refacere.","El antrenează fiecare grupă o dată pe săptămână, cu push, legs, pull și zile de pauză, într-un interval moderat de repetări."],"e":[],"c":["squat 400-500 lbs","deadlift 500 lbs","bench 200-300 lbs","o dată pe săptămână"]},{"v":"75F_fBrqbE0","k":"l","t":"How to Build Muscle While Working a Physical Job","d":"26.10.2026","th":["program-si-split","nutritie","recuperare-si-somn","masa-musculara"],"i":["Cu o muncă fizică lungă, antrenează-te dimineața devreme, înainte de serviciu, când încă nu ești epuizat; autorul s-a trezit la 4 ca să reușească.","Antrenamente scurte: 3 zile pe săptămână cu zi liberă între ele, 4–5 exerciții, un set (2–3 pentru începători), 6–20 repetări, circa 45 de minute.","Pregătește mâncarea dinainte: 2–3 mese simple, fiecare cu proteină, carbohidrați și grăsimi din alimente întregi care îți plac.","Exemplu de zi: smoothie proteic dimineața, fructe pe parcurs, la prânz carne tocată cu cartof dulce; pentru calorii în plus, proteină cu lapte în cooler.","Planifică în avans când poți antrena și în ce zile gătești; de exemplu gătești pentru primele 3–4 zile și pregătești restul la mijlocul săptămânii.","Autorul spune că diferența dintre cei care progresează și ceilalți e pregătirea; cine improvizează rar ajunge la rezultate."],"e":[],"c":["8–12 ore pe picioare în ziua de muncă","trezire la 4:00 pentru antrenament înainte de serviciu","3 zile pe săptămână","4–5 exerciții","1 set (2–3 pentru începători)","6–20 repetări","antrenament de circa 45 de minute","smoothie: ~10 oz lapte de cocos sau lapte integral","prânz: 6–8 oz carne de vită tocată","energy drink de 300 mg cafeină, dat ca greșeală care i-a stricat somnul"]},{"v":"WGoSTMap1kY","k":"s","t":"Struggling to Gain Weight? Drink This.","d":"26.10.2026","th":["nutritie","masa-musculara"],"i":["Shake de masă: 10-12 oz lapte integral, ½ cană ovăz mărunțit, 1 lingură unt de nuci, 1 lingură miere, 1 scoop whey; ~700-1.000 kcal, ~40 g proteine.","Smoothie 2: ~10 oz lapte de cocos, 1-2 scoop-uri proteină, miere, unt de migdale, 2 curmale, ~1 cană fructe congelate; ajustezi caloriile după nevoie."],"e":[],"c":["10-12 oz lapte","½ cană ovăz","700-1.000 kcal","~40 g proteine","10 oz lapte de cocos","1 cană fructe congelate"]},{"v":"rsjLRvOrXCg","k":"s","t":"Bicep hack to double your arm size?","d":"24.10.2026","th":["brate","principii-antrenament","accidentari-si-articulatii"],"i":["Nu îți dublezi brațul cu o răsucire la curl; videoclipurile cu hack-uri sunt clickbait și mai multe variații duc la tendinită la cot.","Brațul crește când crești forța: de la 20 lbs la 40 lbs în 10 repetări în doi ani, la un singur exercițiu bun."],"e":[["incline dumbbell curl"],["standing curl"],["hammer curl"],["barbell curl"]],"c":["braț 12-13 inch","de la 20 lbs la 40 lbs în 10 repetări în 2 ani","ganteră 55 lbs"]},{"v":"e0DBQ7ZZNRM","k":"l","t":"3 Day Workout Routine to Build Muscle & Strength","d":"23.10.2026","th":["program-si-split","failure-si-progresie","incalzire","principii-antrenament"],"i":["Program pe 3 zile pentru oameni cu bază de antrenament: piept-umeri-triceps, picioare, spate-biceps, cu zi liberă între ele și două zile libere după ultima.","Fiecare zi începe cu un „maxim de antrenament” la ~85% din maximul real, apoi exerciții de masă; alternezi săptămânal bancă/overhead press și squat/trap bar.","Încălzire pentru maxim: împarți greutatea țintă în patru trepte și urci treptat, cu repetări tot mai puține pe măsură ce greutatea crește.","Exercițiile de masă: un set greu până la eșec sau progres, la 6–15 repetări; dacă vrei mai mult volum faci 2–3 seturi.","Maxim: dacă reușești, crești data viitoare cu cel mai mic pas; dacă eșuezi, repeți greutatea; dacă eșuezi de două ori, scazi 10% și urci din nou.","La exercițiile de masă: urci repetările cu câte una pe antrenament (ex. 6 la 10), apoi crești puțin greutatea și reiei de la 6."],"e":[["Flat barbell bench press","training max ziua 1, alternat cu overhead press"],["Overhead press","training max în săptămânile alternative"],["Incline machine press"],["Pec deck"],["Tricep push down"],["Lateral raise"],["Barbell squat","training max ziua 2, alternat cu trap bar deadlift"],["Trap bar deadlift"],["Leg press"],["Leg curl"],["Leg extension"],["Calf raise"],["Cable crunch"],["Weighted pull-up","training max ziua 3"],["Lat pull down"],["Chest supported row"],["Barbell curl"],["Rear delt fly"],["Neck curl"],["Incline dumbbell press","exemplu de progresie: 60 lb în fiecare mână, 6 la 10 repetări"]],"c":["3 zile pe săptămână","~85% din maximul pentru o repetare","4 trepte de încălzire (ex. 200 lb: bara, ~100, ~150, apoi 200)","6–15 repetări pe setul de masă","2–3 seturi opțional","sărituri: 5 lb la corp superior (2,5 lb pe parte), ~10 lb la squat și trap bar","scădere 10% după două eșecuri la aceeași greutate","6 la 10 repetări înainte de creșterea greutății"]},{"v":"nnQY2iYN4hg","k":"s","t":"The Only Exercise You Need for a Six-Pack","d":"22.10.2026","th":[],"i":[],"e":[],"c":[]},{"v":"6t4ivt0p9Vs","k":"s","t":"The Simplest Way to Build Muscle (That Actually Works)","d":"21.10.2026","th":["failure-si-progresie","principii-antrenament","masa-musculara","incepatori"],"i":["Alege 1-2 exerciții bune pentru fiecare grupă, învață execuția corectă și devino mai puternic la ele în ani; notează exercițiul, greutatea și seturile/repetările.","Exemplu: 6 repetări la tracțiuni azi, ținta 7 data viitoare, până la 10-12, apoi adaugi greutate și reiei de la 6; folosește hârtie, notițe sau o aplicație."],"e":[["pull-ups","6 repetări curate, apoi 7, până la 10-12, apoi se adaugă greutate și se revine la 6"]],"c":["6 repetări, ținta 7, apoi 10-12","3 ani de progres"]},{"v":"KZdr0-tmNs4","k":"l","t":"These 2 Shakes Make Bulking So Much Easier","d":"20.10.2026","th":["nutritie","masa-musculara","suplimente"],"i":["Dacă îți e greu să mănânci destul, adaugă un shake la ce mănânci deja și urmărește greutatea, în loc să-ți schimbi toată dieta.","Shake de zi cu zi: lapte integral, ovăz mărunțit în blender ca să iasă fin, unt de migdale sau arahide, miere și o măsură de proteină.","Smoothie-ul preferat: lapte de cocos, 1–2 măsuri de proteină, miere, unt de migdale, două curmale și fructe congelate.","Reglezi caloriile după nevoie: mai mult unt de nuci, ovăz sau proteină, sau lapte integral în loc de cocos; sau faci un shake mai mic.","Autorul spune că nu e nevoie de surplus mare: contează să mănânci constant puțin peste ce arzi; caloriile lichide se beau repede."],"e":[],"c":["shake 1: 10–12 oz lapte integral, 1/2 cană ovăz, 1 lingură unt de migdale, 1 lingură miere, 1 măsură proteină","shake 1: ~700 kcal până la ~1.000 kcal, ~40 g proteină","shake 2: ~10 oz lapte de cocos, 1–2 măsuri proteină, 1 lingură miere, 1 lingură unt de migdale, 2 curmale, ~1 cană fructe congelate","smoothie făcut de autor de peste 4 ani"]},{"v":"V6MsrLnbQTU","k":"s","t":"The Best Workout Split for Building Muscle","d":"19.10.2026","th":["program-si-split","volum-si-frecventa"],"i":["Splitul bun e cel care te ferește de accidentări, îți place și te ține consecvent; full body, upper/lower sau push/pull/legs pot merge.","Autorul susține ferm push/pull/legs, o dată pe săptămână, un set la failure, după 10 ani."],"e":[],"c":["3 zile","1 set la failure","o dată pe săptămână","10 ani"]},{"v":"dfLJjmJVZxM","k":"s","t":"How to Get Jacked Without Overcomplicating Everything","d":"18.10.2026","th":["principii-antrenament","program-si-split"],"i":["Cinci-șase exerciții care acoperă tot corpul, 2-3 zile pe săptămână și triplarea cifrelor în 5 ani te fac musculos fără alt conținut."],"e":[],"c":["5-6 exerciții","2-3 zile pe săptămână","triplarea cifrelor în 5 ani"]},{"v":"clwWwSr4gPI","k":"s","t":"Trap Bar Deadlift (Avoid These Mistakes)","d":"17.10.2026","th":["tehnica","spate","picioare"],"i":["Trap bar deadlift: stai ușor mai îngust decât umerii, așază-te ca într-un squat, scoate toată slăbiciunea din bară și îndreaptă spatele, fără smucitură.","Împinge prin călcâie, respiră adânc și coboară controlat."],"e":[["trap bar deadlift","stanță ușor mai îngustă decât umerii, spate drept, fără smucitură, împins prin călcâie"]],"c":[]},{"v":"gbIZRqg1xW8","k":"s","t":"80% of Fitness Advice Is a Waste of Time","d":"16.10.2026","th":["principii-antrenament","volum-si-frecventa","nutritie","recuperare-si-somn"],"i":["Principiul 80/20: lucruri cu randament mic sunt splitul perfect, detaliile (ex. unghiul), volumul perfect, timpul meselor, suplimentele și conținutul în exces.","Contează progresia, antrenamentul aproape de failure, recuperarea, mâncarea întreagă, 7-9 ore de somn și mersul zilnic."],"e":[["incline dumbbell press","exemplu de progresie de la 45 la 90 lbs pe ganteră"]],"c":["4-6 seturi pe mușchi pe săptămână","7-9 ore somn","de la 45 la 90 lbs"]},{"v":"Fs6RYD5h_bM","k":"l","t":"How to Get JACKED (Without Steroids)","d":"15.10.2026","th":["principii-antrenament","masa-musculara","mentalitate","varsta"],"i":["Patru ținte cu bara pentru un fizic remarcabil natural: overhead press 135 lb, bench 225, squat 315, deadlift 405, la o repetare cu formă bună.","Forța și mărimea mușchilor sunt legate, iar aceste patru exerciții antrenează aproape toate grupele mari.","Împerechează forța cu 10–15% grăsime corporală; prea multă grăsime acoperă mușchiul construit.","Nu ai nevoie de 250 lb sau de 500 lb la bancă; rețelele sociale îți strică reperul, iar majoritatea oamenilor nu se antrenează deloc.","Autorul preferă acum gantere și aparate, dar merită testată forța la aceste patru ținte de câteva ori pe an; au aceeași valoare în orice sală.","Vârsta și înălțimea schimbă ritmul: poți ajunge și așa, dar cu așteptări ajustate și mai mult timp."],"e":[["Overhead press","țintă 135 lb, o repetare"],["Bench press","țintă 225 lb, o repetare"],["Squat","țintă 315 lb, o repetare"],["Deadlift","țintă 405 lb, o repetare"]],"c":["135 lb overhead press (1 disc)","225 lb bench press (2 discuri)","315 lb squat (3 discuri)","405 lb deadlift (4 discuri)","10–15% grăsime corporală"]},{"v":"0AahBSFSKWU","k":"s","t":"Fitness Influencers Are Killing Your Gains","d":"15.10.2026","th":["mentalitate","principii-antrenament"],"i":["Regula «unei singure surse»: alege un autor cu filosofie coerentă și rezultate dovedite și urmează-l pe el, fără să amesteci metode.","Cine consumă prea mult conținut de la mulți influenceri se încurcă, pentru că metodele lor se contrazic, și ajunge să stagneze din prea multă gândire."],"e":[],"c":[]},{"v":"rnSPcwVEhA0","k":"s","t":"Stop Looking in the Mirror After Every Workout","d":"14.10.2026","th":["mentalitate","incepatori"],"i":["Nu te uita în oglindă după fiecare antrenament; schimbările se văd după 6 luni sau un an de non-negociabile (antrenament, mâncare, recuperare).","E ca o sămânță: nu vezi ce se întâmplă sub pământ."],"e":[],"c":["6 luni până la un an"]},{"v":"kplz6NqDEYk","k":"s","t":"The Biggest Mistake I Made Building Muscle","d":"13.10.2026","th":["mentalitate","incepatori"],"i":["Consumul excesiv de conținut este o capcană; întreabă-te dacă ești consecvent cu ce știi deja că contează.","Diferența o fac cei care repetă câteva lucruri de bază ani la rând, nu strategiile avansate."],"e":[],"c":["5 ani","10+ ani"]},{"v":"-uqGgp7EpPU","k":"s","t":"Stuck at the Same Weight? Do This.","d":"12.10.2026","th":["failure-si-progresie","principii-antrenament","mentalitate","recuperare-si-somn"],"i":["Când stagnezi, nu adăuga neapărat volum: poate ai nevoie de deload, de o schimbare de exerciții sau de o săptămână mai ușoară, pentru că articulațiile pot fi obosite.","Autorul spune că nu trebuie să te compari cu cei dopați; la 12 repetări cu 45 lbs la bicepși ești deja puternic, deci fii mândru de progres."],"e":[["twist curls","55 lbs, 9 repetări; la a 10-a începe să balanseze și o perfecționează înainte de a trece la 11"]],"c":["12 repetări cu 45 lbs","55 lbs x 9 repetări"]},{"v":"vUEQjy1a4ts","k":"l","t":"I Wish I Knew This About Building Muscle 10 Years Ago","d":"10.10.2026","th":["principii-antrenament","failure-si-progresie","volum-si-frecventa","mentalitate"],"i":["Mușchiul crește când un set greu, aproape de eșec, creează tensiune mecanică mare, iar apoi te recuperezi; tehnicile sofisticate nu contează.","Alege 1–2 exerciții eficiente pentru fiecare grupă, învață-le corect și pune toată energia în a deveni mult mai puternic la ele în câțiva ani.","Notează trei lucruri: exercițiul, greutatea, seturile și repetările; pe hârtie, în caiet sau în telefon, nu în minte.","Exemplu: 6 tracțiuni curate azi, țintă 7 data viitoare, apoi 10–12; după aceea adaugi greutate și reiei de la 6.","Un fizic bun se poate construi cu 3 zile pe săptămână, sub o oră, 4–6 exerciții și puține seturi.","Nu vei bate recordul la fiecare antrenament; urmărești o tendință ascendentă în timp."],"e":[["Pull-up","exemplu de progresie: 6 repetări curate, apoi 7, până la 10–12, apoi adaugi greutate"]],"c":["3 zile pe săptămână","4–6 exerciții pe antrenament","sub o oră","trei lucruri de notat: exercițiu, greutate, seturi și repetări","exemplu: de la 135 lb la 315 lb la bench în câțiva ani"]},{"v":"GHUiiq6WK4M","k":"s","t":"If you work out but still look the same, Watch this","d":"09.10.2026","th":["failure-si-progresie","principii-antrenament"],"i":["Dacă arăți la fel de mult timp, verifică dacă ridici aceleași greutăți pentru aceleași repetări de un an.","Notează antrenamentele (caiet sau telefon); nu trebuie să crești la fiecare antrenament, doar să faci mult mai mult după 6 luni sau un an."],"e":[],"c":["6 luni - 1 an"]},{"v":"cuDppRxClS4","k":"s","t":"Full Body Workouts Are Overrated","d":"08.10.2026","th":["program-si-split","accidentari-si-articulatii","volum-si-frecventa"],"i":["Full body de trei ori pe săptămână e potrivit pentru începători; la avansați, cu greutăți mari, tendoanele și articulațiile nu se recuperează.","Alege un program pe care îl poți ține și care te ferește de accidentări."],"e":[],"c":["squat 400+ lbs","deadlift 500 lbs","3 ori pe săptămână"]},{"v":"yMdcDFVSYuk","k":"s","t":"Building Muscle Is Simple, Seriously","d":"05.10.2026","th":["program-si-split","nutritie","principii-antrenament"],"i":["Bază simplă: 3 zile în sală (push, picioare, pull), 4-5 exerciții pe ședință, 3-4 mese din alimente întregi, mișcare zilnică afară.","Supraîncărcare progresivă: la fiecare antrenament adaugi o repetare sau greutate; ține cont de ținta forței peste 3-5 ani."],"e":[],"c":["3 zile pe săptămână","4-5 exerciții","3-4 mese","3-5 ani"]},{"v":"2XHGW1q_OWI","k":"l","t":"The Only Exercises You Need to Build Muscle (No Matter Your Equipment)","d":"04.10.2026","th":["principii-antrenament","sala-acasa","piept","spate"],"i":["Contează tiparul de mișcare, nu exercițiul anume: alege varianta potrivită echipamentului tău, atâta timp cât antrenezi aceeași mișcare.","Piept: împingere orizontală (bancă, gantere, aparat, flotări, dips). Spate: tragere verticală (helcometru, tracțiuni) și orizontală (ramat).","Umeri: împingere verticală și ridicări laterale. Biceps: orice curl. Triceps: orice extensie a cotului (push-down, extensii deasupra capului).","Cvadricepși: mișcare dominată de genunchi (presă, squat, fandări). Femurali și fesieri: hip hinge (RDL, deadlift) plus flexie de genunchi (leg curl, Nordic).","Alege mișcări care îți plac, pe care le poți face constant și care te țin fără accidentări; ignoră influencerii care spun „nu mai face X”."],"e":[["Incline dumbbell press"],["Barbell bench press"],["Chest press machine"],["Push-up"],["Dips"],["Lat pull down"],["Pull-up"],["Assisted pull-up"],["Band pull-up"],["Chest supported row"],["Cable row"],["Dumbbell row"],["Barbell row"],["Inverted row"],["Lateral raise"],["Dumbbell curl"],["Barbell curl"],["Cable curl"],["Preacher curl"],["Cable push down"],["Overhead extension"],["Hack squat"],["Pendulum squat"],["Leg press"],["Barbell squat"],["Bulgarian split squat"],["Reverse lunge","dacă ai doar greutatea corpului"],["Barbell Romanian deadlift"],["Dumbbell RDL"],["Conventional deadlift"],["Trap bar deadlift"],["Good morning"],["Leg curl machine"],["Nordic curl","fără acces la aparate"]],"c":["peste 10 ani și mii de antrenamente de experiență (afirmat de autor)"]},{"v":"kgZJG14B41E","k":"s","t":"Mike Mentzer Was the Black Sheep of the Fitness Industry","d":"02.10.2026","th":["mike-mentzer","principii-antrenament","failure-si-progresie"],"i":["Ideile lui Mentzer: antrenament rar cu recuperare, antrenament greu (o ganteră de 5 lbs la 30-40 de repetări nu dă semnal), progresie la aproape fiecare antrenament.","Un set la failure e partea controversată; autorul spune că logic are sens, e mai puternic după 10 ani și fără dureri constante. Alege ce te ține consecvent."],"e":[],"c":["ganteră 5 lbs, 30-40 repetări","ganteră 55 lbs","10 ani","5% câștig în plus (ipotetic)"]},{"v":"yuNdjkl6Ytc","k":"l","t":"You Only Need 4 Exercises for Legs","d":"01.10.2026","th":["picioare","program-si-split","failure-si-progresie"],"i":["Picioare simplu: deadlift cu trap bar și presă ca exerciții compuse, apoi leg curl și leg extension ca „bonus”; gambele și abdomenele sunt opționale.","Trap bar-ul e mai ușor de învățat pentru începători și mai blând cu spatele decât deadliftul clasic sau sumo.","Fără presă de picioare poți face squat cu bara, fandări inverse sau split squat bulgar.","Gambele se pot lucra la Smith, cu gantere sau cu bara și vârfurile ridicate; cablul pentru abdomen e opțional dacă faci multe compuse.","Interval 6–20 repetări; la capătul de sus mărești greutatea și cobori la baza intervalului (ex. trap bar 6 la 10 repetări, apoi +5 lb); pauze 1–3 minute."],"e":[["Trap bar deadlift","exercițiu compus, mai ușor pentru începători"],["Leg press","amplitudinea depinde de aparat"],["Leg curl machine","pad-ul trebuie să stea pe coapse"],["Leg extension machine"],["Calf raise","Smith, gantere sau bară cu picioarele ridicate"],["Cable crunch","opțional"],["Barbell squat","alternativă la presă"],["Reverse lunge","alternativă la presă"],["Bulgarian split squat","alternativă la presă"]],"c":["6–20 repetări","pauze 1–3 minute","exemplu trap bar: 400+ lb, 6 repetări spre 10 cu 405 sau 410 lb, apoi +5 lb","4 exerciții de bază, 6 cu gambe și abdomene"]},{"v":"L7vM1bry5xY","k":"s","t":"How to Build Muscle Without Living in the Gym","d":"30.09.2026","th":["program-si-split","incepatori","failure-si-progresie","nutritie"],"i":["Cea mai mare parte a celor care ridică greutăți vor doar să arate că se antrenează: 3 zile push-legs-pull, o zi liberă între ele, 4-5 exerciții, alese să-ți placă.","Compuse 6-10 repetări, izolări 8-15; notează greutățile (ex. 185 lbs x 7, apoi 8, 9, 10), apoi adaugi greutate; 7-9 ore de somn și mișcare și în zilele libere."],"e":[],"c":["3 zile pe săptămână","4-5 exerciții","6-10 repetări la compuse, 8-15 la izolări","185 lbs x 7 repetări (exemplu)","7-9 ore de somn"]},{"v":"umnStUj2Myk","k":"s","t":"Under 200 lbs is victim weight","d":"30.09.2026","th":["masa-musculara","mentalitate","suplimente"],"i":["Eticheta „victim weight” sub 200 lb vine de la oameni care vor să fie cât mai mari și folosesc substanțe; standardele lor nu sunt ale tale.","Autorul preferă destul mușchi cât să se vadă că ridică, slăbiciune relativă, forță și atletism real, fără antrenament 6-7 zile pe săptămână."],"e":[],"c":["6 picioare înălțime","aproximativ 190 lb","10-12% grăsime corporală","sub 200 lb"]},{"v":"VUDgsJImouk","k":"l","t":"You Only Need 4 Exercises for Chest, Shoulders, And Triceps","d":"29.09.2026","th":[],"i":[],"e":[],"c":[]},{"v":"O6XGuj8qOqA","k":"s","t":"1 set to failure only works if you do this","d":"29.09.2026","th":["failure-si-progresie","tehnica"],"i":["Un singur set la eșec funcționează doar dacă pui concentrare totală pe fiecare repetare, până nu mai poți face încă una cu formă bună.","Nu bifa o căsuță: cu un singur set trebuie să activezi mușchiul și să dai tot."],"e":[],"c":[]},{"v":"ErlBDk2ujgk","k":"l","t":"You Only Need 4 Exercises for Back & Biceps","d":"28.09.2026","th":["spate","brate","program-si-split","tehnica"],"i":["Spate și biceps din patru exerciții: tragere verticală, tragere orizontală, un curl și fluturări pentru deltoidul posterior, câte un set până la eșec.","Gândește în tipare de mișcare: acasă cu bară de tracțiuni faci tracțiuni (cu greutate), iar pentru ramatul orizontal merge și ramatul cu bara sau inversat.","Dacă ești începător (câțiva ani de sală), fă 2–3 seturi pe exercițiu: 6–10 repetări la compuse, 8–15 la ultimele două.","Încălzirile sunt doar practică a mișcării și semnal către corp, nu stimul de creștere; nu te gândi prea mult la ele.","Autorul nu numără tempoul repetării: se întreabă doar dacă și-a controlat forma și simte mușchiul.","La curl pe bancă înclinată reglezi unghiul după preferință (îl poți măsura cu telefonul); la fluturări scoți jocul din aparat înainte de set."],"e":[["Cable lat pull down","tragere verticală; alternativă: tracțiuni sau tracțiuni cu greutate"],["Cable row","tragere orizontală; alternative: barbell row, inverted row"],["Incline dumbbell curl","set de lucru de circa 50, cu gantere de 25, braț ușor în spatele corpului, coate lipite"],["Rear delt fly","aparat cu înclinare în față, priză standard, elimini jocul înainte de set"],["Hammer curl","opțional, al cincilea exercițiu"]],"c":["4 exerciții","1 set până la eșec","2–3 seturi pentru începători","6–10 repetări la compuse","8–15 repetări la ultimele două","unghi bancă 45° sau 30° (preferințe)"]},{"v":"hL_IAtK-bzM","k":"s","t":"Is 3 days per week in the gym enough?","d":"27.09.2026","th":["volum-si-frecventa","program-si-split","accidentari-si-articulatii","incepatori"],"i":["Regula unei singure surse: alege un influencer în care ai încredere, urmează-i splitul și ignoră restul.","Alege metoda care te face puternic într-un interval moderat de repetări, constant, fără accidentări; cu accidentare pierzi mai mult decât câștigi."],"e":[],"c":["10-20 seturi pe săptămână pe mușchi (recomandare științifică menționată)","3 zile pe săptămână push/legs/pull","5% câștig suplimentar (ipotetic)"]},{"v":"b3-b2SrLS6E","k":"s","t":"The Muscle Almost Nobody Trains","d":"26.09.2026","th":["gat","antebrate","accidentari-si-articulatii"],"i":["Gâtul și antebrațele se văd mereu, iar un gât subțire strică aspectul; antrenarea gâtului ajută și la prevenirea accidentărilor.","Autorul amintește un ideal: brațul aproape cât gâtul; dacă ai bicepsul la 16 inch și gâtul de 13-14 inch, gâtul rămâne în urmă."],"e":[],"c":["biceps 16 inch","gât 13-14 inch"]},{"v":"W1CD8IrHz_0","k":"l","t":"How To Build Muscle Without Training Like A Bodybuilder","d":"25.09.2026","th":["principii-antrenament","program-si-split","mentalitate","masa-musculara"],"i":["Definește ținta: destul mușchi cât să se vadă clar că ridici, rămânând relativ slab, puternic și atletic, nu mărimea maximă a culturiștilor.","Standardele de greutate din rețele cresc fără oprire (de la 175 la 200, la 220 lb) și nu sunt o normă pentru un fizic bun.","Split push-picioare-pull de 3 zile pe săptămână, cu zi liberă între ele, 4–5 exerciții și mișcări de bază pe care le poți repeta ani la rând.","Repetări: 6–10 la compusele mari, 8–15 la izolări, ghid general 6–20; contează efortul și progresia, nu un interval magic.","Notează ce ridici: 185 lb × 7 azi înseamnă țintă 8, 9, 10; la capăt crești puțin greutatea și reiei.","Afară din sală: alimente mai ales întregi, destulă proteină, calorii după scop, 7–9 ore de somn și activitate și în zilele libere."],"e":[["Squat"],["Bench press"],["Deadlift"],["Cable lateral raise"],["Dumbbell curl"]],"c":["autorul: 6 ft, ~190 lb, 10–12% grăsime","3 zile pe săptămână","4–5 exerciții","6–10 repetări la compuse","8–15 repetări la izolări","ghid general 6–20","bench 185 lb × 7 apoi 8, 9, 10","7–9 ore de somn"]},{"v":"JoxF1Q0W1wM","k":"s","t":"How To Lose Your Dad Bod","d":"25.09.2026","th":["slabit","nutritie"],"i":["Dacă faci sport și nu slăbești, în general ești în exces caloric: urmărește ce mănânci cu o aplicație și cântar de bucătărie.","Verifică uleiurile, sursele de grăsime și porțiile; autorul estimează că în 3-6 luni de urmărire dispare burta de «dad bod»."],"e":[],"c":["3-6 luni"]},{"v":"zzUMtWxMLpo","k":"s","t":"You Don’t Need Much Equipment to Build Muscle","d":"23.09.2026","th":["sala-acasa","principii-antrenament"],"i":["Nu ai nevoie de echipament scump; corpul înțelege doar rezistență și tensiune, deci provoacă mușchiul și devii mai puternic la aceeași mișcare.","Autorul a construit mare parte din fizic cu greutăți libere într-un rack pentru genuflexiuni, aproape 5 ani într-un dormitor liber."],"e":[],"c":["aproape 5 ani de antrenament în dormitor"]},{"v":"zTjDkYhb9Bk","k":"s","t":"Unfortunately, Building Muscle Is Incredibly Simple","d":"22.09.2026","th":["masa-musculara","failure-si-progresie","principii-antrenament"],"i":["Cei cu fizic impresionant sunt aproape mereu foarte puternici la exercițiile lor; dacă nu ai rezultate, de obicei ești slab sau nu i-ai dat destul timp.","Concentrează-te pe forță într-un interval moderat de repetări și dă-i timp."],"e":[["wide grip lat pulldown"],["pull-ups"],["weighted pull-ups"],["squat"],["leg press"]],"c":[]},{"v":"Aw617z0_Jwk","k":"l","t":"The ONLY supplements worth taking to build muscle","d":"21.09.2026","th":["suplimente","nutritie","masa-musculara"],"i":["Suplimentele sunt „credit în plus”: mai întâi contează mâncarea întreagă, proteina, antrenamentul cu progresie, somnul.","Creatina: circa 5 g pe zi, luată constant; momentul nu contează. Dă puțin mai multă energie în seturile grele și, spune autorul, ar avea și beneficii cognitive.","Pudra de proteină e doar comoditate; dacă ajungi la proteină din mâncare s-ar putea să nu ai nevoie. Autorul ia ~2 măsuri pe zi pentru că are poftă mică.","Pre-workout-ul e util mai ales pentru cofeină (150–200 mg la autor); e opțional, iar cafeaua neagră e o alternativă; sari peste el dacă îți strică somnul.","Citește eticheta: ingrediente puține, doze transparente, fără îndulcitori artificiali, coloranți sau umpluturi.","Fără buget, nu cheltui sute ca să compensezi somnul, dieta sau antrenamentul slab."],"e":[],"c":["creatină ~5 g/zi","~2 măsuri whey pe zi, ~50–60 g proteină","cofeină ~150–200 mg din pre-workout"]},{"v":"ZbGPcfYOa0I","k":"s","t":"If You Feel This Before a Set, You’re Doing It Right","d":"21.09.2026","th":["mentalitate","tehnica"],"i":["Anxietatea înainte de un set greu e normală, semn că încerci ceva nou; canaliz-o în execuție.","Autorul, după 10 ani, urmărește aproape la fiecare exercițiu un nou record personal."],"e":[],"c":["10 ani de antrenament"]},{"v":"OfxF0BXjYVU","k":"s","t":"The Simplest Diet to Build Muscle","d":"20.09.2026","th":["nutritie","masa-musculara","suplimente"],"i":["Pentru masă: greutatea în lbs x 16-18 ca punct de plecare pentru calorii; trei mese principale cu proteină, carbohidrați și grăsimi, plus fructe și shake-uri.","Cântărește-te des și urmărește media săptămânală: ținta e circa 0,5 lb pe săptămână; dacă nu se mișcă după 1-2 săptămâni, adaugă 100-200 kcal."],"e":[],"c":["greutatea în lbs x 16-18","6 ft, 194 lbs, țintă 200 lbs","0,5 lb pe săptămână","+100-200 kcal","3 zile de antrenament","10-12 oz shake cu lapte integral","6-8 oz carne 85/15","200 g orez gătit"]},{"v":"-lZQG-dVS2E","k":"l","t":"After 10+ Years of Training, I’d Only Do These 6 Things","d":"18.09.2026","th":["principii-antrenament","program-si-split","volum-si-frecventa","failure-si-progresie"],"i":["Autorul a progresat abia când a renunțat la pompă și trucuri și a început să urmărească forța într-un interval moderat de repetări, la aceleași exerciții.","Mușchiul crește ca adaptare la o cerință tot mai mare; în sală îi dai corpului un motiv să se adapteze, de ex. gantere de 60 lb spre 90 lb în câțiva ani.","Șase reguli: 3 zile pe săptămână cu zi liberă între; 4–6 exerciții; nu schimba exercițiile; notează fiecare antrenament; mai puțin volum; restul vieții simplu.","Notează greutatea și repetările ultimei date; la capătul intervalului adaugi greutate și reiei de jos.","Autorul face un singur set greu până la eșec, dar începătorilor le recomandă 2–3 seturi; contează stimulul, nu numărul de seturi.","Afară din sală: calorii potrivite scopului, destulă proteină, somn, activitate în zilele libere."],"e":[["Incline dumbbell press","exemplu de progresie: de la 60 lb la 90 lb"]],"c":["3 zile pe săptămână","4–6 exerciții","1 set greu la autor","2–3 seturi pentru începători","somn: 7 până la ~9 ore (transcrierea e neclară)","înainte: 5 seturi pe exercițiu, 2 ore la sală aproape zilnic"]},{"v":"5qYOMywutrY","k":"s","t":"Why I Only Train Each Muscle 1x Per Week","d":"17.09.2026","th":["volum-si-frecventa","program-si-split","principii-antrenament"],"i":["Autorul antrenează fiecare grupă mare o dată pe săptămână, intens, cu puține seturi; de două ori poate fi optim pe hârtie, dar costă zile, exerciții și oboseală.","Dacă vrei doar un fizic vizibil, data viitoare încerci să depășești ce ai făcut; dacă îți place sala 5-6 zile și te recuperezi, continuă."],"e":[],"c":["o dată pe săptămână pe grupă","program de 3 zile, 45-60 minute"]},{"v":"DAuRFLrOZyU","k":"s","t":"Can You Get Jacked Working Out at Home?","d":"17.09.2026","th":["sala-acasa","principii-antrenament","incepatori"],"i":["Poți deveni musculos acasă, chiar fără echipament, cu calistenie; corpul simte doar tensiunea progresivă.","Alege exerciții de bază și crește repetările sau greutatea; ținta e să fii de 2-3 ori mai puternic în 3-4 ani."],"e":[["push-ups","exemplu: de la 20 la 40, 60, 80 de repetări"]],"c":["de la 20 la 40-60-80 de flotări","3-4 ani"]},{"v":"-Y-f69Tidds","k":"s","t":"Stop Losing Weight. You Need to Build Muscle.","d":"16.09.2026","th":["slabit","masa-musculara","nutritie"],"i":["Dacă ai slăbit deja mult și ești pe la 15-17% grăsime, nu mai slăbi: treci la menținere sau recompoziție.","În recompoziție mănânci caloriile de întreținere și te concentrezi pe progresie la antrenament."],"e":[],"c":["20-40 lbs pierdute (exemplu)","15-17% grăsime corporală"]},{"v":"Fc-PP2DI7QM","k":"s","t":"How To Build Muscle With A Physical Job?","d":"15.09.2026","th":["program-si-split","nutritie","recuperare-si-somn"],"i":["Cu un job fizic greu, corpul se obișnuiește cu efortul, dar caloriile trebuie să fie la punct; dacă mănânci și te hidratezi prea puțin, rămâi mereu în urmă.","Autorul antrenează simplu, 3 zile pe săptămână, dimineața devreme înainte de muncă, și își pregătește mâncarea din timp."],"e":[],"c":["3 zile pe săptămână","zile de muncă de 10-12 ore (exemplu)"]},{"v":"prlPEyBYx8k","k":"l","t":"What I Eat Every Day to Build Muscle (Simple)","d":"14.09.2026","th":["nutritie","masa-musculara"],"i":["Pentru a lua în greutate, înmulțește greutatea în lb cu 16–18 ca să afli un interval de calorii de pornire; la 194 lb ies 3.100–3.500 kcal.","Mesele autorului: ~3.300 kcal, ~160 g proteină, ~400 g carbohidrați, ~120 g grăsimi, din alimente simple pe care le repetă.","Construiește dieta din 3 mese principale cu proteină, carbohidrați și grăsimi din ce îți place; completează cu fructe și shake-uri.","Cântărește-te des și urmărește media săptămânală; urcarea de ~½ lb pe săptămână e ok, mai repede înseamnă mai multă grăsime, deci scazi caloriile.","Dacă greutatea nu se mișcă după 1–2 săptămâni, adaugă 100–200 kcal și repetă procesul.","Caloriile lichide (smoothie, lapte) ajută dacă îți e greu să mănânci mai mult."],"e":[],"c":["6 ft, ~194 lb, țintă 200 lb","~3.300 kcal","~160 g proteină","~400 g carbohidrați","~120 g grăsimi","multiplicator 16–18 × greutatea în lb","interval pornire 3.100–3.500 kcal","~½ lb pe săptămână","+100–200 kcal dacă stagnează 1–2 săptămâni","200 g orez fiert, 6–8 oz carne tocată 85/15","trezire ~4:30"]},{"v":"Jq9ceQWUpfo","k":"s","t":"How Often Should You Change Your Workout Routine?","d":"14.09.2026","th":["program-si-split","mentalitate"],"i":["Recomandă să alegi un program dovedit și să-l urmezi un an fără modificări, mai ales dacă ai tendința să sari între programe.","Schimbi prea multe variabile deodată dacă treci des de la full body la upper/lower sau bro split; construiește baza întâi."],"e":[],"c":["un an fără schimbări"]},{"v":"sKwDk-aXAts","k":"s","t":"if you're skinny fat and don't want to be, watch this","d":"13.09.2026","th":["slabit","masa-musculara","program-si-split","nutritie"],"i":["Pentru cineva „skinny fat” cu greutate mică, autorul recomandă recompoziție (masă musculară pe loc, grăsime pierdută lent), nu o tăiere agresivă.","Țintă de pornire pentru recompoziție: greutatea în lbs înmulțită cu 13, ajustată după cum scade sau crește greutatea. Plan: 3 zile pe săptămână, pași pe zilele libere."],"e":[],"c":["greutate în lbs x 13 = calorii de pornire","3 zile pe săptămână de antrenament","primele 3-6 luni la greutatea curentă","exemplu: 163-165 lbs"]},{"v":"zYdN2NMGPZQ","k":"s","t":"The Simplest Way to Know If You’re Building Muscle","d":"13.09.2026","th":["failure-si-progresie","principii-antrenament"],"i":["Notează antrenamentele (caiet sau telefon) ca să știi ce ai de depășit; poate ridici de un an aceleași greutăți la aceleași repetări.","Nu trebuie să crești la fiecare antrenament; contează să faci mult mai mult după 6 luni, un an sau câțiva ani."],"e":[],"c":["6 luni, un an sau câțiva ani"]},{"v":"Um16MYNaHSc","k":"l","t":"You DON'T Need to Train Every Muscle Twice a Week","d":"11.09.2026","th":["volum-si-frecventa","principii-antrenament","failure-si-progresie","accidentari-si-articulatii"],"i":["De două ori pe săptămână pe mușchi poate fi optim pe hârtie, dar nu e necesar ca să fii puternic și să arăți bine; frecvența e doar o variabilă.","Costul frecvenței mai mari: zile în plus, exerciții, seturi și oboseală, plus risc de suprasolicitare; recuperarea include și țesutul conjunctiv și sistemul nervos.","Autorul antrenează fiecare grupă mare greu o dată pe săptămână, cu puține exerciții și seturi serioase, și încearcă mereu să-și bată antrenamentul precedent.","Test simplu: devii mai puternic într-un interval moderat de repetări? Dacă da, funcționează, de exemplu gantere înclinate de la 60 la 90 lb.","Se poate crește cu frecvența o dată, de două sau de trei ori pe săptămână; autorul nu spune că varianta lui e singura."],"e":[["Incline dumbbell press","exemplu de progres: de la 60 lb la 90 lb"],["Pull-up","exemplu: de la 5 repetări cu greutatea corpului la repetări cu greutate adăugată"]],"c":["programul lui durează 45 de minute până la o oră","mușchi antrenat o dată pe săptămână (fiecare grupă mare)","alternativă citată: 48–72 de ore între antrenamente pe același mușchi"]},{"v":"gtBCYgcB7Ms","k":"s","t":"You’re Not Building Muscle Because You Keep Doing This","d":"10.09.2026","th":["mentalitate","principii-antrenament","masa-musculara"],"i":["Cei fără masă sunt de obicei slabi la forță, pentru că schimbă programul des, schimbă exerciții și nu notează nimic.","Urmează un plan dovedit, mănâncă, dormi, hidratează-te și dă-i un an."],"e":[],"c":["un an"]},{"v":"oBa7_l9Pu6o","k":"s","t":"If you're natural and want to build muscle, follow this","d":"10.09.2026","th":["failure-si-progresie","principii-antrenament","incepatori"],"i":["Povestea lui Milo din Crotona (poartă un vițel care crește) explică progresia: începe cu ceva care te provoacă ușor și crește treptat.","Alege mișcări fundamentale, învață-le corect, notează și devino mai puternic în timp; nu număra zilele, exercițiile, seturile sau pompa."],"e":[],"c":["6-7 zile pe săptămână (greșeala autorului)"]},{"v":"H_1Wlszwn64","k":"s","t":"How to Finally Get Consistent in the Gym","d":"09.09.2026","th":["mentalitate"],"i":["Pentru consecvență, intenția singură nu ajunge: fă o listă zilnică de lucruri nenegociabile și deschide-o la finalul zilei.","Stabilește obiectivul, deduci acțiunile, le faci, iar atingerea obiectivului devine inevitabilă."],"e":[],"c":[]},{"v":"etEDym7TORQ","k":"s","t":"Do you have to track calories to get in shape?","d":"09.09.2026","th":["nutritie","incepatori","slabit"],"i":["Începătorii ar trebui să numere calorii o perioadă, ca să învețe să estimeze din ochi; nu trebuie pe vecie.","Cu un obiectiv serios, urmărirea unor ținte zilnice face ajungerea aproape inevitabilă."],"e":[],"c":["5-6 oz pui","200 g orez"]},{"v":"eQ9WsoP7pfQ","k":"l","t":"If You’re Struggling to Get In Shape, Watch This","d":"07.09.2026","th":["mentalitate"],"i":["„Mijlocul dezordonat” e etapa în care ești mult mai bine decât la început, dar departe de țintă; rezistența apare tocmai înainte ca îmbunătățirile să se acumuleze.","Rezistența (idee preluată din cărți) e tendința corpului și minții de a rămâne la statu quo: îndoială, anxietate, tentații; e normală și nu înseamnă că greșești.","O ajută o viziune clară: ce ai pierde dacă renunți (anti-viziunea) și cum arată viața pe care o vrei; autorul se trezește la 4 de doi ani.","Concentrează-te pe acțiunile de azi: mese, antrenament, somn, program; la finalul zilei întreabă-te dacă ai făcut ce trebuia, nu doar ținta îndepărtată.","Dacă faci acțiunile, dar rezultatul întârzie, nu te judeca: după progresul rapid de începător, ritmul scade și durează ani.","Atenție la anturaj: oamenii care țin de vechile obiceiuri cresc tentația; nu tai legăturile, dar ai nevoie de disciplină."],"e":[],"c":["trezire la 4:00 de ~2 ani (autorul)"]},{"v":"c3cVA3A7Yoc","k":"s","t":"Why You Still Don’t Have the Physique You Want","d":"07.09.2026","th":["mentalitate","recuperare-si-somn"],"i":["Înainte să judeci rezultatele, verifică dacă ai fost consecvent și la antrenament, și la somn; nu un somn haotic.","Consecvența se măsoară în ani; dacă faci un pas înapoi, fă zece înainte."],"e":[],"c":[]},{"v":"EHDnCWkiH2s","k":"l","t":"If You Don’t Know If You Should Bulk or Cut, Watch This","d":"06.09.2026","th":["slabit","masa-musculara","nutritie","principii-antrenament"],"i":["Cadru în trei pași: stabilește unde vrei să ajungi, vezi unde ești și repară cel mai mare decalaj dintre ele.","Țintă orientativă pentru 6 ft după ani de antrenament: 185–195 lb la 10–12% grăsime; ±5 lb pentru fiecare inch peste sau sub 6 ft; nu sunt greutăți magice.","Estimează grăsimea corporală dintr-un grafic; precizia nu contează, doar dacă ești slab, la mijloc sau cu mult surplus.","Dacă ai mult surplus de grăsime (ex. 210 lb, ~25%), începe cu slăbitul până spre low-mid teens, apoi treci la o fază de masă.","La skinny fat, autorul recomandă mai întâi slăbitul, chiar dacă pari mai mic; feedbackul vine repede, iar începătorii pot construi mușchi în timp ce slăbesc.","Bulk, cut și menținere sunt faze, nu decizii permanente; în ani ajungi la aceeași siluetă lean cu o greutate mai mare."],"e":[],"c":["185–195 lb la 10–12% grăsime pentru 6 ft","±5 lb pentru fiecare inch","5 ft 10: 175–185 lb","6 ft 2: 195–205 lb","exemplu: 210 lb la ~25% grăsime","low-mid teens ca punct de reevaluare"]},{"v":"B4YT98ugQ3c","k":"s","t":"You're Wasting 80% of Your Time in the Gym","d":"05.09.2026","th":["principii-antrenament","program-si-split","volum-si-frecventa","suplimente"],"i":["Mult timp se pierde pe programul perfect, unghiul exact la bancă, numărul ideal de seturi, suplimente și momentul meselor; alege un plan dovedit și rămâi cu el.","Contează tensiunea crescândă în timp, câteva seturi grele pe grupă pe săptămână, caloriile atinse până seara în 3-4 mese, somn; suplimentele sunt ultimele 5%."],"e":[],"c":["80% timp irosit","3-4 mese pe zi","suplimente = ultimele 5%","10 ani de antrenament"]},{"v":"PIhU4fmjGMc","k":"s","t":"The Real Reason You Should Get In Shape","d":"04.09.2026","th":["mentalitate","varsta"],"i":["Autorul spune că antrenamentul nu e doar pentru estetică, ci pentru o viață mai bună: să fii puternic și prezent pentru cei care au nevoie de tine.","Consideră că randamentul cel mai mare e investiția în sănătate."],"e":[],"c":[]},{"v":"xC7oyqP931g","k":"s","t":"The Only Supplements I Take To Build Muscle","d":"03.09.2026","th":["suplimente","nutritie"],"i":["Autorul ia doar pudră de proteine (pentru că are apetit mic), creatină, studiată mult, și un pre-workout curat doar pentru cofeină.","Suplimentele sunt doar comoditate; dacă îi place cafeaua neagră, ia cafea pentru cofeină."],"e":[],"c":[]},{"v":"v4bPSHs5Sgg","k":"l","t":"Building Muscle Is Much Simpler Than You Think","d":"02.09.2026","th":["principii-antrenament","failure-si-progresie","incepatori"],"i":["Povestea lui Milo și a vițelului: sarcina crește puțin în fiecare zi, iar corpul se adaptează; asta e supraîncărcarea progresivă în forma ei cea mai simplă.","Autorul număra zile, exerciții, seturi și pompa, nu dacă devine mai puternic; poți merge ani la sală și arăta la fel dacă ridici aceleași greutăți.","Exemplu pentru începător: 135 lb × 6 azi, apoi 7, 8, 9, 10; la 10 repetări curate adaugi puțină greutate și reiei de jos.","Nu trebuie să progresezi la fiecare antrenament sau cu salturi mari; contează ce poți face peste 6 luni, un an sau mai mulți ani.","Notează ce ai făcut ultima dată (caiet, telefon, aplicație); fără asta nu știi ce ai de depășit.","Înainte să schimbi programul, verifică dacă în ultimul an ai ridicat cu adevărat mai mult; adesea explicația stagnării e că nu."],"e":[["Bench press","exemplu: 135 lb × 6, apoi 7, 8, 9, 10"]],"c":["135 lb × 6 la bench, apoi până la 10 repetări","5 zile pe săptămână sau mai mult fără progres (exemplu negativ)","autorul a făcut 6–7 zile pe săptămână, mai multe ore, la început"]},{"v":"xpL6DzUItSs","k":"s","t":"The Most Overlooked Way to Build Muscle","d":"02.09.2026","th":["incepatori","brate","principii-antrenament"],"i":["Dacă nu poți ridica decât gantere de 20 lb la biceps, nu ai nevoie de mai mult lucru direct, ci de forță mai mare la câteva mișcări.","De cele mai multe ori nu izolezi nimic, ci devii mai puternic la câteva exerciții în loc de 15 la care ești slab."],"e":[["curl cu bară","135 lb cu 45 pe fiecare parte, ca exemplu de forță țintă"]],"c":["gantere de 20 lb","55 lb","135 lb cu discuri de 45"]},{"v":"jrfKmlpme2g","k":"s","t":"Mike Mentzer Was Right About Training Less","d":"01.09.2026","th":["mike-mentzer","volum-si-frecventa","failure-si-progresie"],"i":["Mentzer: un set la failure pe 4-5 exerciții, antrenament la 72 de ore sau mai rar, 20-30 de minute; adaugi repetări sau greutate de fiecare dată și te recuperezi afară.","Autorul a trecut de la 6-7 zile la acest stil și îl folosește de peste un an."],"e":[],"c":["1 set la failure","4-5 exerciții","72 de ore","20-30 de minute","peste un an"]},{"v":"IM183WSvPpA","k":"l","t":"Unfortunately, Getting in Shape Really Is This Simple","d":"31.08.2026","th":["principii-antrenament","mentalitate","volum-si-frecventa","failure-si-progresie"],"i":["Planta e puținul care contează (notat, seturi grele, exerciții-cheie, consecvență, recuperare, progresie); buruienile sunt tot ce te distrage.","Săritul între programe și retușarea continuă te împiedică să vezi creșterea, ca și cum ai dezgropa planta să verifici dacă a prins rădăcini.","Buruieni: trucurile influencerilor, durerea musculară, pompa, mai multe zile de sală și complexitatea; progresul se vede în forță, nu în dureri.","Un mușchi rămas în urmă nu cere neapărat zile în plus: mai întâi întreabă cât de puternic ești la exercițiul principal, adesea problema e forța mică.","Mai multe zile aduc oboseală și mai multă presiune pe articulații, nu rezultate; baza e 3 zile, iar pentru un avansat chiar și două pot ajunge.","Alege un program și un autor în care ai încredere și rămâi la el; amestecarea metodelor e ca un puzzle din piese diferite."],"e":[["Dumbbell curl","exemplu strict, cu puțin impuls: de la 25 lb la 55 lb"],["Lat pull down","exemplu: 190 lb pentru 6 repetări, apoi țintă 7"]],"c":["3 zile pe săptămână ca bază (4 pentru începători, 2 pentru avansați)","un set până la eșec sau progres într-un interval fixat de repetări","190 lb × 6 la lat pull down, apoi 190 × 7"]},{"v":"JOx4U5GfpL0","k":"s","t":"How to Actually Stick to Your Fitness Goals","d":"31.08.2026","th":["mentalitate"],"i":["Scrie obiectivul, stabilește intenția, dar ai nevoie și de un plan clar și de un mod de a-ți cere socoteală.","Fără acțiunile potrivite zilnice, intenția rămâne doar o dorință; fie că ești la definire sau la masă, angajează-te la acțiuni."],"e":[],"c":[]},{"v":"iCDZHxEmgQg","k":"s","t":"How long should you bulk and cut?","d":"29.08.2026","th":["slabit","masa-musculara","nutritie"],"i":["Durata fazelor depinde de punctul de plecare; supraponderal: taie spre 10-12% grăsime, cu pauze la menținere dacă somnul, energia sau libidoul scad.","Apoi menținere, bulk de 4-6 luni; când ajungi la 15-16% și abdomenul se estompează, taie înapoi la 12%."],"e":[],"c":["10-12% grăsime","un an pentru 100 pounds","o săptămână la menținere","bulk 4-6 luni","15-16% grăsime"]},{"v":"I-8rwwBZS3E","k":"s","t":"Stop overthinking your workout split!","d":"28.08.2026","th":["program-si-split","mentalitate"],"i":["Orice split funcționează (full body, upper/lower, bro split, chiar kettlebell sau calistenie), dacă îl poți urma, îți place și rămâi fără accidentări.","Contează consecvența; alege unul și rămâi cu el."],"e":[],"c":[]},{"v":"0tecDBJz2Mg","k":"s","t":"At Least Get in Shape Once in Your Life","d":"27.08.2026","th":["mentalitate","slabit","masa-musculara"],"i":["Autorul spune că poți să ai genetică excelentă și să n-o afli niciodată dacă nu încerci cu adevărat și nu mănânci ca să vezi definiția.","Dacă ai grăsime mare sau n-ai construit mușchi, merită să te prezinți zi de zi și să nu mai amâni; nu știi ce poți obține."],"e":[],"c":[]},{"v":"f34RCE783lU","k":"l","t":"If You're Skinny But Want To Be Muscular, Do This","d":"26.08.2026","th":["masa-musculara","nutritie","incepatori","program-si-split"],"i":["Alege o țintă clară (greutate și procent de grăsime) ca să știi cât ai de urcat; de la 135 la 185 lb e un proces de ani, nu de 3–6 luni.","Calorii de start: greutatea în lb × 16–18 (ex. 145–150 lb dau ~2.400–2.700 kcal); proteină ~1 g/lb din greutatea țintă, sau 0,7–0,8 × greutatea țintă.","Cântărește-te des și urmărește media săptămânală; țintă ~1 lb pe săptămână; dacă stagnezi, +100–200 kcal; dacă urci 2–3 lb pe săptămână, scazi.","Antrenament: 3 zile pe săptămână, 45 de minute până la o oră, orice program simplu (full body, push/pull/legs, upper/lower); contează să notezi și să devii mai puternic.","Dacă nu poți mânca destul, bea calorii (lapte integral, proteină, unt de migdale, banană, ovăz), ~600–1.000 kcal; urmărește ce mănânci, poți fi sub nevoie.","Dacă acumulezi prea multă grăsime, fă un cut scurt și controlat și revino la masă; un fizic natural impresionant durează ani."],"e":[],"c":["multiplicator 16–18 × greutatea în lb","145–150 lb → ~2.400–2.700 kcal","~1 g proteină pe lb din greutatea țintă (180 g la 180 lb)","alternativ 0,7–0,8 × greutatea țintă","~1 lb pe săptămână (4 lb pe lună)","+100–200 kcal dacă nu se mișcă","2.800–2.900 kcal exemplu, 2–3 lb pe săptămână = prea repede","3 zile, 45 min–1 oră","shake 600–1.000 kcal","exemplu: 3.200 kcal necesari, 2.700 mâncate = 500 sub","135 lb → 185 lb: ani, nu 3 sau 6 luni"]},{"v":"cZp_s3Y8Jdc","k":"s","t":"You Don’t Need to Keep Getting Stronger Forever.","d":"25.08.2026","th":["failure-si-progresie","accidentari-si-articulatii","varsta"],"i":["Nu trebuie să crești greutatea la infinit; la un nivel de forță ridicat poți încerca o variantă mai grea sau doar menține.","Menținerea mușchiului costă puțin: un set la failure cu ganteră mai ușoară (25-30 lbs) nu te face să pierzi volum."],"e":[["dumbbell curls","exemplu: 55 lbs, 12-15 repetări; 60 lbs cu durere de cot sau umăr"],["incline curls","variantă mai grea"]],"c":["55 lbs, 12-15 repetări","60 lbs","10+ ani","25-30 lbs pentru menținere"]},{"v":"v93wiouVoYA","k":"s","t":"Can’t Add Weight on Isolation Exercises? Do This","d":"24.08.2026","th":["failure-si-progresie","tehnica","umeri"],"i":["La exerciții de izolare mărește intervalul de repetări (de exemplu de la 6-10 la 6-15, apoi 20) înainte să crești greutatea.","Execuție mai bună și conexiune minte-mușchi înseamnă tot tensiune în plus; pentru salturi mici poți atașa o greutate de 2,5 lb la stiva scripetelui.","Nu vei crește greutatea la nesfârșit la izolare; ajungi la un nivel puternic, apoi încetinești execuția."],"e":[["cable lateral raise","crește repetările de la 6-10 la 6-15, apoi 20, în loc să forțezi greutatea"]],"c":["15 lb la ridicări laterale","6-10 apoi 6-15 apoi 20 repetări","plăcuță de 2,5 lb","ținta: 30-40 lb la izolare"]},{"v":"VwuWli9zgw8","k":"s","t":"How To Build Muscle Without Obsessing","d":"23.08.2026","th":["principii-antrenament","mentalitate","program-si-split","cardio-si-pasi"],"i":["Judecă antrenamentele după progres, nu după cât faci; trei antrenamente grele pe săptămână ajung pentru majoritatea natural-ilor.","Simplifică mâncarea (câteva mese preferate), mergi 8.000-10.000 de pași și gândește în ani, nu în săptămâni."],"e":[],"c":["3 antrenamente grele pe săptămână","8.000-10.000 de pași","6 luni sau un an cu aceleași greutăți","10 ani de antrenament"]},{"v":"qWYd5OUH-_s","k":"l","t":"The Problem With Training To Failure","d":"22.08.2026","th":["failure-si-progresie","principii-antrenament","mentalitate","recuperare-si-somn"],"i":["Antrenarea până la limită nu e de ajuns: efortul e subiectiv, progresul e obiectiv; fără notițe nu știi dacă ai dat corpului un stimul nou.","Diferența dintre a face exerciții și a te antrena: antrenamentul are intenție și țintă, de exemplu 35 lb × 8 săptămâna trecută și 35 × 9 acum.","Mușchiul crește din ceva nou pentru corp (greutate sau repetări), nu din pompă, volum sau trucuri.","Autorul crede că doar un procent foarte mic scapă fără notițe, de obicei cu somn, stres, mâncare și hidratare impecabile.","Când stagnezi, notițele te lasă să cauți cauza: somn, calorii, hidratare, stres; apoi repari ce nu merge.","După un efort lung (ex. surf), un set poate părea la eșec cu 70–80% din greutatea obișnuită: muncă grea, dar stimul vechi."],"e":[["Dumbbell curl","exemplu de țintă: 35 lb × 8, apoi 35 lb × 9"],["Incline machine","exemplu: două discuri de 45 lb pentru 10 repetări în mod obișnuit"]],"c":["~1% din oameni scapă fără notițe (afirmația autorului)","70–80% din greutatea obișnuită după un efort lung","antrenament 6–7 zile și 2 ore, în trecut, fără plan"]},{"v":"l5QGU5fAf2k","k":"s","t":"What I Eat Every Week to Stay in Shape","d":"21.08.2026","th":["nutritie","altceva"],"i":["Pregătirea meselor 3-4 zile odată elimină deciziile când ești obosit; dimineața pui, orez, ardei; la prânz carne tocată, orez, fasole verde; seara pui, orez.","Folosește inox, fontă și recipiente de sticlă; legume și avocado se adaugă la masă."],"e":[],"c":["pregătire 3-4 zile odată"]},{"v":"S7gwSl8ALB0","k":"s","t":"Stuck at the Same Weight and Reps?","d":"20.08.2026","th":["failure-si-progresie","principii-antrenament"],"i":["Progresul nu e liniar la intermediari; dacă ai egalat repetările, verifică dacă execuția a fost mai curată.","Când stagnezi, caută cauza (hidratare, stres, somn, ultimul deload) și schimbă o singură variabilă odată."],"e":[],"c":["10 lbs pe bench press la fiecare antrenament (la începători)","de la 6 la 7 repetări"]},{"v":"kCAf02K1pzc","k":"s","t":"How Many Reps Should You Do?","d":"19.08.2026","th":["volum-si-frecventa","failure-si-progresie"],"i":["Recomandare generală: 6-10, 8-12 sau 8-15 repetări, după exercițiu, oriunde între 6 și 20; la repetări foarte multe, cardio încarcă mai mult decât forța.","Contează să devii mai puternic progresiv."],"e":[],"c":["6-10, 8-12, 8-15 repetări","6-20 repetări"]},{"v":"4XtKPXrOfeY","k":"s","t":"3 Days a Week Is Better Than 6","d":"18.08.2026","th":["volum-si-frecventa","recuperare-si-somn","program-si-split","mentalitate"],"i":["Trei zile pe săptămână, sub o oră, îți dau recuperare suficientă și poți antrena foarte intens; mai ales dacă ești natural, mai multe zile aduc oboseală și dureri.","Un beneficiu neglijat: cu 3 zile îți place și aștepți antrenamentele, pe când la 6-7 zile autorul a ajuns să se teamă de ele."],"e":[],"c":["2-3 zile pe săptămână","antrenamente sub o oră","6-7 zile pe săptămână (trecutul autorului)"]},{"v":"muF7RTPUtnY","k":"l","t":"How To Build An Impressive Physique Without Obsessing","d":"16.08.2026","th":["principii-antrenament","volum-si-frecventa","nutritie","cardio-si-pasi"],"i":["Judecă antrenamentul după progres, nu după cât faci: 8 exerciții și multe seturi obosesc, dar nu produc nimic dacă ridici aceleași greutăți luni la rând.","Exemplu: gantere la înclinat de la 50 lb la 80 lb pentru 6 repetări cu formă bună, în 1–2 ani, duc probabil la un piept mai mare.","Trei sesiuni grele pe săptămână sunt de ajuns pentru majoritatea celor naturali; mai multe zile adaugă doar oboseală; split-ul nu e partea magică.","Nutriție simplă: 3 mese și gustări din alimente cu un singur ingredient (vită, pui, orez, cartofi, fructe, legume), repetate ca să nu mai decizi zilnic.","Activitate: plimbări, 8.000–10.000 de pași pe zi; cardio de zona 2 sau sprinturi sunt opționale; nu transforma zilele libere în alte antrenamente.","Când știi deja ce trebuie, nu mai căuta scurtături; gândește în ani, un fizic impresionant durează."],"e":[["Incline dumbbell press","exemplu de progres: 50 lb → 80 lb, 6 repetări"]],"c":["2–3 zile de ridicat pe săptămână, sub o oră (autorul)","3 sesiuni grele pe săptămână","3 mese pe zi","8.000–10.000 de pași pe zi"]},{"v":"W1Tv7nmlQko","k":"s","t":"Most Guys Don’t Need to Lose More Weight","d":"15.08.2026","th":["masa-musculara","slabit"],"i":["Mulți nu au nevoie să slăbească mai mult, ci să construiască mușchi; fără mușchi construiți în ani, după slăbire rămâi tot cu grăsime moale."],"e":[],"c":[]},{"v":"-00SlScAgDw","k":"s","t":"The Most Overlooked Muscle You’re Not Training","d":"14.08.2026","th":["gat","tehnica","principii-antrenament"],"i":["Gâtul e, după autor, cel mai ignorat mușchi; contează pentru aspect și pentru prevenirea accidentărilor, ca la luptători și fotbaliști.","Începe cu neck curls cu greutatea corpului, la final de antrenament, până la eșec; adaugă rotiri și extensii, un set fiecare, apoi un disc mic."],"e":[["neck curls","cu greutatea corpului, la finalul zilei, fără mișcare de crunch, până la eșec; apoi twists și extensions, un set fiecare; ulterior un disc cu un prosop sau căciulă îndoită ca protecție"]],"c":["disc de 45 lbs în demonstrație","disc de start 2,5 lbs sau 5 lbs","un set din fiecare variantă la început"]},{"v":"7H8H5u-Y8rw","k":"s","t":"You’ll Never Get Jacked If You Keep Doing This","d":"14.08.2026","th":["failure-si-progresie","program-si-split","mentalitate"],"i":["Mulți sunt slabi pentru că sar de la CrossFit la kettlebell, calisthenics și înapoi, deci nu au nicio bază de la care să urmărească progresul.","Alege un program dovedit cu exerciții de bază, notează progresul și nu-l schimba la fiecare câteva săptămâni."],"e":[],"c":["schimbare la fiecare 2 săptămâni (criticat)"]},{"v":"6di4J3K45QE","k":"l","t":"If You're Overweight but Want to Be in Shape, Watch This","d":"13.08.2026","th":["slabit","nutritie","program-si-split","mentalitate"],"i":["Exemplu pentru un bărbat supraponderal cu probleme de consecvență: o țintă concretă (240 lb la 200 lb în 365 de zile) și motivul din spate ca să reziste.","Program pe 3 zile (luni piept-umeri-triceps, miercuri picioare, vineri spate-biceps) plus pași și activitate în rest; întrebarea e ce poți ține ani, nu ce e optim.","Slăbit: deficit caloric cu cea mai mare cantitate de mâncare cu care pierzi constant grăsime; start de ~11–12 kcal × greutatea în lb (aici ~2.600) și ~180 g proteină.","Planifică și weekendul: pregătește mâncare pentru el; 3 mese principale plus o gustare sau shake, fiecare masă cu proteină, carbohidrat și legume.","Urmărește media săptămânală a greutății, talia, pozele și antrenamentele; 1–2 lb pe săptămână e rezonabil la 240 lb, iar dacă merg bine nu schimbi nimic.","Gândește în ani: ~¾ lb pe săptămână înseamnă aproape 40 lb într-un an, iar timpul trece oricum, deci mai bine ești constant."],"e":[],"c":["240 lb → 200 lb în 365 zile","multiplicator 11–12 × greutatea în lb pentru slăbit","~2.600 kcal de start","~180 g proteină pe zi","3 zile de lift pe săptămână","~8.000 pași pe zi (media din exemplu)","1–2 lb pe săptămână la 240 lb","~¾ lb pe săptămână ≈ aproape 40 lb într-un an","patru lucruri de urmărit: greutate, talie, poze, antrenamente"]},{"v":"JZnC4Z_NAcc","k":"s","t":"How to Actually Stick to Your Diet","d":"12.08.2026","th":["nutritie","slabit","mentalitate"],"i":["Cinci pași pentru dietă: ia o decizie reală, schimbă mediul (casa fără junk), construiește o dietă realistă, nu te opri după o masă proastă și repetă.","Un singur eșec nu șterge progresul; cu repetiție îți schimbi identitatea și devii cel care mănâncă așa."],"e":[],"c":["5 pași"]},{"v":"FZxtY3H9rDs","k":"s","t":"My Simple 3-Day Workout Program","d":"11.08.2026","th":["program-si-split","failure-si-progresie","incalzire","piept"],"i":["Metoda 1x4: 3 zile pe săptămână, 4 exerciții pe antrenament, fiecare cu un set de încălzire la 50% și un set de lucru la eșec; ziua a patra e opțională.","Alege o greutate pentru 6-10 repetări; dacă ai făcut 8, ținta e 9; la 10 repetări crești greutatea și revii la capătul de jos al intervalului."],"e":[["incline dumbbell press","ziua 1; apoi chest fly, cable lateral raises, cable pushdown cu bară dreaptă"],["leg press","ziua 2; apoi Romanian deadlift, leg extensions, leg curls"],["wide grip lat pulldown","ziua 3; apoi chest supported horizontal row, rear delts, incline dumbbell curl"],["neck curls","ziua 4 accesorii; apoi wrist rollers, cable crunches, calf raises la leg press"],["sprint","după încălzire dinamică de 15 minute, un singur sprint de circa 15 secunde"]],"c":["1 set de lucru la eșec, 4 exerciții","încălzire 1 set la 50% din greutatea de lucru","6-10 repetări","încălzire 15 minute înainte de sprint","un sprint de ~15 secunde"]},{"v":"88o5if4xIOg","k":"s","t":"The Power of Writing Down Your Goals","d":"10.08.2026","th":["mentalitate"],"i":["Autorul spune că scrisul de mână al obiectivelor le imprimă în subconștient și că el și-a atins toate obiectivele scrise în 2025.","Presupune că scrisul lent și rostit în minte te ajută; el spune că nu trebuie să-l crezi pe cuvânt, ci să încerci."],"e":[],"c":[]},{"v":"4jUUv_-gveo","k":"l","t":"If You Can Only Work Out 2 Days a Week, Do This","d":"09.08.2026","th":["program-si-split","volum-si-frecventa","failure-si-progresie","principii-antrenament"],"i":["Cu două zile pe săptămână: upper/lower (ex. luni sus, joi jos) sau full body; pauză de câteva zile între ele pentru recuperare.","Upper: incline press, pec deck, helcometru sau tracțiuni, ramat, apoi ridicări laterale, curl și push-down; dacă e prea mult, reduci seturile sau izolările.","Lower: presă sau squat, trap bar deadlift sau RDL, leg extension, leg curl sau Nordic curl, abdomene; opțional wrist roller, neck curl și gambe.","Majoritatea fac bine cu 2–3 seturi de lucru pe exercițiu, la 6–15 repetări: 6–10 la compuse, 8–15 la izolări.","Progresia dublă: alege o greutate cu ~2 repetări în rezervă la 6; urci repetările spre 10 în ambele seturi, apoi adaugi puțină greutate și reiei de jos.","Un antrenament pe mușchi pe săptămână poate ajunge dacă antrenezi tare, progresezi, mănânci și te recuperezi ani la rând."],"e":[["Incline press","exemplu de progresie: 135 lb, 6/6, apoi 7/6, 7/7, până la 10/10, apoi +5 lb"],["Pec deck"],["Dumbbell fly"],["Wide grip lat pull down"],["Pull-up"],["T-bar row"],["Barbell row"],["Cable lateral raise"],["Barbell curl"],["Dumbbell curl"],["Tricep straight bar push down"],["Leg press"],["Barbell squat"],["Trap bar deadlift"],["Trap bar Romanian deadlift"],["Leg extension"],["Seated leg curl"],["Nordic curl"],["Cable crunch"],["Wrist roller","opțional"],["Neck curl","opțional"]],"c":["2 zile pe săptămână","2–3 seturi de lucru","6–15 repetări","6–10 la compuse","8–15 la izolări","~2 repetări în rezervă la început","135 lb → 140 lb (sau 137,5 lb cu discuri mici)","pauză de câteva zile între antrenamente","cele 7 exerciții upper, 4–5 exerciții lower"]},{"v":"WfJxlgXaV5w","k":"s","t":"Once You Start Eating Clean, Junk Food Isn’t Worth It","d":"08.08.2026","th":["nutritie","mentalitate"],"i":["După ce mănânci alimente întregi, junk food-ul nu mai merită; când apare pofta, înlocuiește cu miere crudă cu lapte, curmale sau fructe."],"e":[],"c":[]},{"v":"ft95b8Yv_Zc","k":"s","t":"Not gaining muscle? This is probably why","d":"08.08.2026","th":["failure-si-progresie","recuperare-si-somn","spate"],"i":["Dacă ești natural și greutatea, repetările și forma sunt identice, probabil nu crești; platoul vine adesea din subrecuperare (calorii, somn, hidratare, stres).","Poate fi momentul unui deload sau al schimbării priza: de la wide grip pulldown la underhand."],"e":[["wide grip pulldown","poți trece la priză underhand"]],"c":[]},{"v":"2hvjiZhW2V4","k":"s","t":"Do This Every Morning If You Sit All Day","d":"07.08.2026","th":["mobilitate","umeri","recuperare-si-somn"],"i":["Dead hang zilnic, dimineața, contracarează statul jos: la lățimea umerilor, relaxat, fără tensiune.","Pornește de la ce reziști (ex. 5 secunde) și bate ziua precedentă, până la 60 de secunde sau 2 minute; autorul spune că îți ajută postura și mobilitatea."],"e":[["dead hang","priză la lățimea umerilor, fără tensiune musculară, zilnic sau la două zile; ținta crește treptat de la 5 s spre 60 s - 2 min"]],"c":["start 5 secunde","țintă 60 secunde sau 2 minute","bară de ușă ~15 dolari"]},{"v":"PeRywgqUOrk","k":"s","t":"Skinny Fat? Watch This","d":"06.08.2026","th":["slabit","masa-musculara","nutritie","incepatori"],"i":["Pentru skinny fat: definește obiectivul, alege recompoziția, calorii de pornire = greutatea în lbs x 13, cântărire zilnică și media săptămânală.","Dacă greutatea e stabilă și devii mai puternic, ești pe drumul bun; antrenează toate grupele în săptămână aproape de eșec, apoi 3 mese și 1-2 gustări."],"e":[],"c":["greutatea în lbs x 13","3 mese + 1-2 gustări"]},{"v":"FQzZewNal1o","k":"l","t":"Why 2-3 Workouts a Week Are All You Need","d":"05.08.2026","th":["volum-si-frecventa","principii-antrenament","recuperare-si-somn","failure-si-progresie"],"i":["Autorul ridică 2–3 ori pe săptămână, 30–45 de minute; mușchiul crește ca adaptare la o cerință fizică pentru care nu ești pregătit, nu pentru că stai 2 ore sau ai pompă.","Înainte să adaugi o zi, verifică dacă toate grupele mari au primit seturi grele în săptămână; dacă da, nu presupune că mai ai nevoie de o sesiune.","Un set greu până la eșec per exercițiu trimite semnalul de creștere; repetarea lui în mai multe seturi n-ar adăuga mult.","Progresia: în timp trebuie să ridici mai multă greutate, să faci mai multe repetări sau să-ți îmbunătățești tehnica.","Recuperarea face parte din antrenament; dacă ești mereu obosit, te dor articulațiile și performanța scade, corpul îți dă feedback.","Zilele libere pot fi active sau de mobilitate; nu trebuie să ridici zilnic."],"e":[["Dumbbell curl","exemplu: set la eșec cu 55 lb"]],"c":["2–3 antrenamente de forță pe săptămână, 30–45 de minute","1 set greu pe exercițiu","55 lb dumbbell curl (exemplu)"]},{"v":"L2LBks-Vc3c","k":"s","t":"Want More Muscle? Stop Overthinking It.","d":"04.08.2026","th":["principii-antrenament","failure-si-progresie","spate","mentalitate"],"i":["Înainte de trucuri pentru spate, treci de la 5 la 20 de tracțiuni cu greutatea corpului; gândește în 52 sau 100 de săptămâni, nu 18.","Scopul este ca un exercițiu să ajungă să aibă cu 100 lbs mai mult; e o chestiune de timp."],"e":[["bodyweight pull-ups","de la 5 la 20 de repetări"]],"c":["5 tracțiuni apoi 20","52 sau 100 de săptămâni","+100 lbs"]},{"v":"AHy7ARspuI8","k":"s","t":"If You're Working Out But Not Gaining Muscle, Watch This","d":"03.08.2026","th":["masa-musculara","failure-si-progresie","nutritie","recuperare-si-somn"],"i":["Patru întrebări dacă nu crești: devii mai puternic? Mănânci pentru obiectiv (calorii, proteine)? Te recuperezi (somn, stres)? Ai fost consecvent destul?","Mulți schimbă antrenamentul la câteva săptămâni și dieta lunar; autorul spune că drumul cel mai scurt e să accepți că durează mult."],"e":[],"c":["6 luni - 1 an fără progres la greutăți"]},{"v":"gFlY6IeZbIA","k":"s","t":"Strength Standards Every Man Should Aim For","d":"02.08.2026","th":["principii-antrenament","masa-musculara"],"i":["Ținte pentru un bărbat sănătos, ca orientare: bench 225 lbs, squat 315, deadlift 405, 15-20 pull-ups, overhead press ~150.","Variază cu proporțiile corpului; mulți pot mai mult decât cred și dau vina pe genetică."],"e":[["bench press"],["squat"],["deadlift"],["pull-ups"],["overhead press"]],"c":["bench 225 lbs","squat 315 lbs","deadlift 405 lbs","pull-ups 15-20","overhead press ~150 lbs"]},{"v":"hhTPtNsqS5o","k":"l","t":"The Only 2 Movements You Need To Grow Your Triceps","d":"01.08.2026","th":["brate","tehnica","principii-antrenament"],"i":["Două tipare de mișcare pentru triceps: extensia deasupra capului (întinde capul lung) și push-down-ul (brațele pe lângă corp); împreună antrenează cele trei capete.","Presele (incline, overhead, dips) antrenează indirect tricepsul, deci nu ai nevoie de mai multe exerciții de triceps.","Gândește în tipare, nu în exerciții: cablu, aparat, gantere sau bandă merg la fel; alege ce simți bine, ce-ți place și ce poți încărca progresiv ani la rând.","Extensie: bară dreaptă la cablu pentru stabilitate, brațele superioare fixe, stretch adânc jos, pauză, extinzi complet; reiei cu control.","Push-down: bară dreaptă, coatele lipite, apeși drept în jos, fără să ajuți cu tot corpul; controlezi revenirea.","Progresie la izolări: 8–15 repetări; adaugi o repetare pe antrenament, iar la 15 crești puțin greutatea și reiei."],"e":[["Straight bar cable overhead extension","brațe superioare fixe, stretch adânc, pauză jos, extensie completă"],["Cable press down","bară dreaptă, coate lipite, apăsare în jos, control la revenire"],["Rope push down","varianta populară, fără a fi rău"],["Overhead press","indirect"],["Incline press","indirect"],["Dip","indirect"]],"c":["8–15 repetări","+1 repetare pe antrenament","15 repetări = moment de a crește greutatea"]},{"v":"7xQm507XKWE","k":"s","t":"The Truth About Getting a Six Pack","d":"01.08.2026","th":["abdomen","slabit","nutritie"],"i":["Cubulețele se arată în bucătărie: printr-un deficit caloric și pierdere de grăsime, nu prin roata pentru abdomen sau mașina de abdomene.","Dacă vrei muncă directă, autorul menționează cable crunch și hanging knee raises; abdomenul se antrenează și indirect în orice exercițiu."],"e":[["cable crunch"],["hanging knee raises"]],"c":[]},{"v":"IXkXSmFjgko","k":"s","t":"Getting In Shape Isn't Hard Forever","d":"31.07.2026","th":["mentalitate","incepatori","volum-si-frecventa"],"i":["Să ajungi în formă e greu doar prima dată; apoi menținerea cere mult mai puțin.","Poți păstra un fizic impresionant cu 2-3 antrenamente bune pe săptămână."],"e":[],"c":["2-3 antrenamente pe săptămână","6 zile x 2 ore (nu e necesar)"]},{"v":"TW6koHrlqp0","k":"s","t":"Grow Your Forearms (2 Exercises)","d":"31.07.2026","th":["antebrate","brate"],"i":["Pentru antebrațe: wrist roller (antebraț aproape întreg și priză) și hammer curl (un mușchi mare al antebrațului).","Concentrează-te să devii mai puternic la ele, în paralel cu un program bun."],"e":[["wrist roller"],["hammer curl"]],"c":[]},{"v":"8ZPboN46wZg","k":"s","t":"Building Muscle Is Really This Simple","d":"30.07.2026","th":["masa-musculara","nutritie","recuperare-si-somn","principii-antrenament"],"i":["Mușchiul se construiește din hidratare, dietă bogată în nutrienți cu destule calorii, somn, lumină naturală, progres constant, fără exagerări; apoi îi dai timp.","Autorul spune că procesul e lent: sunt necesari 2-3 ani, iar el lucrează la asta de 10."],"e":[],"c":["2-3 ani","10 ani"]},{"v":"smJDNLy6xSM","k":"s","t":"How To Do Tricep Pushdowns","d":"30.07.2026","th":["brate","tehnica"],"i":["Tricepși la scripete: bară dreaptă sus, priză de sus la lățimea umerilor, coate lipite de corp, picioare fixate, abdomen încordat, piept ridicat.","Împingi până la extensie completă fără să miști brațele de sus, apoi revii lent până când antebrațele sunt puțin peste 90°. Fără elan."],"e":[["triceps pushdown","bară dreaptă la scripete sus, priză de sus la lățimea umerilor, coate lipite, extensie completă, revenire lentă până puțin peste 90°"]],"c":["antebrațe puțin peste 90° la revenire"]},{"v":"-ch1zQ3RoH0","k":"l","t":"This Diet To Get Lean Feels Like Cheating","d":"29.07.2026","th":["nutritie","slabit"],"i":["Cadru simplu pentru a rămâne slab: trei mese din alimente întregi, fiecare cu proteină, carbohidrat și grăsime; iei trei decizii pe zi, nu zece.","Surse flexibile: proteină (vită, pui, curcan, ouă, iaurt), carbohidrați (orez, cartofi, ovăz, fructe), grăsimi (avocado, unt de nuci, carne 80/20).","Gustări: fructe proaspete sau uscate ori un shake proteic; fructele au fibre și apă și sunt greu de mâncat în exces.","Băuturi: mai ales apă (90%) și uneori apă de cocos; multe calorii vin din sucuri, ceai dulce și cafele aromate.","Dacă mâncarea întreagă ți se pare fadă, e din cauza obișnuinței cu produse procesate; gustul se adaptează în timp.","Planifică mesele din timp și ajustează porțiile după scop: mai puțin ca să slăbești, mai mult din aceleași alimente ca să iei în greutate."],"e":[],"c":["3 mese pe zi","90% din băuturi: apă","grăsime din carne 80/20 menționată ca sursă"]},{"v":"XxPnmbSBSZo","k":"s","t":"How To Do Weighted Pull Ups","d":"29.07.2026","th":["spate","tehnica"],"i":["Weighted pull-up: disc atașat la centură, priză overhand cam la lățimea umerilor, umeri jos și înapoi, abdomen încordat, bărbia peste bară.","Evită balansul și elanul; coboară controlat până la brațe întinse."],"e":[["weighted pull-up","disc la centură, priză overhand lățimea umerilor, bărbia peste bară, coborâre lentă, expiri sus"]],"c":[]},{"v":"_g8ZbKAOKcg","k":"s","t":"Stop Doing Your Reps Like This","d":"28.07.2026","th":["tehnica","brate","principii-antrenament"],"i":["Nu face repetările doar ca să bifezi 10; elanul scade tensiunea mecanică, motorul creșterii.","Dacă te balansezi, scade greutatea și fă fiecare repetare controlat."],"e":[["hammer curls","demonstrat cu gantere de 55 lbs"]],"c":["10 repetări","gantere de 55 lbs"]},{"v":"fSheXgJp5sw","k":"s","t":"Try this if your biceps aren’t growing","d":"28.07.2026","th":["brate","tehnica"],"i":["Dacă bicepșii nu cresc, gândește-te să strângi bicepsul ca să îndoi brațul, nu să ridici ganteră; reduce elanul și ține tensiunea unde trebuie."],"e":[["curl","cu gantere, cu accent pe conexiunea minte-mușchi"]],"c":[]},{"v":"Nl3ovrTxEtY","k":"s","t":"The Diet Change That Made Fat Loss Easy","d":"27.07.2026","th":["slabit","nutritie"],"i":["Cu o dietă bazată pe carne, fructe, cartofi, miere și legume, mănânci mai puțin fără să te simți restricționat, pentru că te saturi mai bine.","Autorul crede că mâncarea procesată e făcută să încurajeze supraalimentarea, deci calitatea mâncării contează mult."],"e":[],"c":[]},{"v":"fsLV7JlKhI4","k":"s","t":"The Muscle Building Lesson I Wish I Learned Sooner","d":"26.07.2026","th":["incepatori","failure-si-progresie"],"i":["La început aproape orice funcționează, dar progresul încetinește și apare platoul.","Progresia e cheia creșterii: de fiecare dată dă corpului un motiv să se adapteze, cu mai multă greutate, mai multe repetări sau execuție mai bună."],"e":[],"c":[]},{"v":"bu8AL6KcxWU","k":"l","t":"Why I Pause Every Rep","d":"25.07.2026","th":["tehnica","failure-si-progresie","principii-antrenament"],"i":["Pauza la fiecare repetare standardizează mișcarea, deci vezi clar dacă ai devenit mai puternic; fără ea poți „progresa” prin recul sau amplitudine mai mică.","Beneficii: elimină impulsul (pornești din oprire), îmbunătățește controlul și conexiunea cu mușchiul și, după autor, ajută să rămâi sănătos pe termen lung.","Autorul consideră că tensiunea constantă e supraestimată: un set aproape de eșec creează tensiune mecanică și cu o pauză de ~jumătate de secundă.","Contează consecvența: dacă pauzezi azi, pauzezi și săptămâna viitoare, ca să știi că o repetare în plus sau 2,5–5 lb înseamnă progres real.","Nu pretinde că pauza are o proprietate magică pentru mușchi; ideea e să elimini variabilele ca să rămână doar forța.","La bench nu sări bara de piept, la deadlift nu o bate de podea, la presă nu folosi recul; sunt trucuri pentru ego."],"e":[["Bench press","pauză ~jumătate de secundă pe piept, fără a sări bara"],["Deadlift","menționat ca exemplu de recul de la podea"],["Leg press","menționat ca exemplu de recul"]],"c":["pauză de ~jumătate de secundă","+1 repetare; +1, +3 sau +5 lb ca pași de progres","+2,5 sau +5 lb pe bară"]},{"v":"GkefyWBkOik","k":"s","t":"You Don't Need Specific Exercises to Build Muscle","d":"24.07.2026","th":["tehnica","principii-antrenament","spate"],"i":["Nu te lega de un exercițiu anume: în loc de lat pulldown poți face tracțiuni cu priză largă, chest supported row, landmine row, T-bar row sau barbell row.","Important e să imiți tiparul de mișcare, pentru că corpul nu cunoaște exercițiile."],"e":[["lat pulldown, wide grip pull-ups, chest supported row, landmine row, T-bar row, barbell row","alternative pentru același tipar"]],"c":[]},{"v":"eNnrZex3s1w","k":"s","t":"Why You Keep Restarting Your Fitness Journey","d":"24.07.2026","th":["mentalitate"],"i":["Ai nevoie de un ancoră adâncă (motiv, scop) ca viața să nu te scoată din drum; dacă pierzi elanul, revino imediat."],"e":[],"c":[]},{"v":"lEqHr1xFNrk","k":"s","t":"How To Build Muscle (simple)","d":"23.07.2026","th":["principii-antrenament","masa-musculara","recuperare-si-somn"],"i":["Antrenamentul greu dă semnal de adaptare; mușchiul se reface mai mare cu somn, calorii și proteine destule.","Dacă te adaptezi, nu mai ai motiv să crești: fă puțin mai mult în timp (repetare, greutate, formă)."],"e":[],"c":[]},{"v":"eKk5xaFID4w","k":"l","t":"If You're Skinny Fat, Watch This","d":"22.07.2026","th":["slabit","masa-musculara","nutritie","program-si-split"],"i":["La skinny fat, o recompoziție (mușchi în plus, greutate aproape fixă) are sens înaintea unui cut agresiv, mai ales dacă n-ai antrenat consecvent.","Definește fizicul-țintă concret (ex. zvelt și musculos, 10-12% grăsime) și o greutate-țintă; astfel vezi dacă ai nevoie de mușchi, nu de pierdere de kilograme.","Start de calorii la recompoziție: greutatea în lbs x 13. Te cântărești zilnic, urmărești media săptămânală și ajustezi mâncarea în sus sau în jos.","Primele 3-6 luni ții greutatea, antrenezi 3 zile pe săptămână și urmărești forța; apoi reevaluezi și treci la lean bulk cu 200-300 kcal în plus.","Macro de plecare: proteine, carbohidrați și grăsimi împărțite în trei mese și una-două gustări, fiecare masă cu proteină, carbohidrat și grăsime sănătoasă."],"e":[],"c":["Exemplu: 163 lbs, 5'10, țintă 170 lbs (jacked și lean la 5'10: 170-180 lbs)","Calorii recompoziție: greutatea în lbs x 13, adică ~2.120 kcal/zi în exemplu","~160 g proteine, ~210 g carbohidrați, ~70 g grăsimi","Recompoziție 3-6 luni, reevaluare după ~6 luni","Lean bulk: +200-300 kcal/zi","Antrenament 3 zile pe săptămână (3-4 zile maxim)"]},{"v":"EgfDOKTZc2A","k":"s","t":"Why I Don't Eat Junk Food","d":"22.07.2026","th":["nutritie","mentalitate"],"i":["Autorul crede că o bucată de tort cu 50 g de zahăr adăugat poate cauza inflamație și afecta dopamina; el compară asta cu motorul pe benzină în care pui motorină.","Este părerea lui că starea proastă a multora vine din mâncare procesată; recomandă alimente cu un singur ingredient, dense în nutrienți."],"e":[],"c":["50 g zahăr adăugat într-o felie de tort"]},{"v":"OQ2KQLjaXRA","k":"s","t":"How To Actually Get Six Pack Abs","d":"20.07.2026","th":["abdomen","slabit","nutritie"],"i":["Abdomenul e deja acolo, dar acoperit de grăsime: mănâncă puțin mai puțin decât arzi, ia destule proteine și ridică greutăți.","Nu ai nevoie de abdomene directe, pentru că se lucrează la exercițiile compuse, decât dacă vrei abdomene mai groase; abdomenul se face în bucătărie."],"e":[],"c":[]},{"v":"yawtsSeFnVU","k":"s","t":"The Mobility Exercise Most People Desperately Need","d":"19.07.2026","th":["mobilitate","accidentari-si-articulatii","incepatori"],"i":["Atârnatul pe bară (dead hang) e exercițiul de mobilitate propus pentru cei care stau mult: dimineața, bate-ți timpul anterior, țintă un minut.","Începător: la două zile sau de trei ori pe săptămână, oprește-te când se duce priza, ușurează cu picioarele pe pământ. Durerea ascuțită sau ciupirea nu sunt normale."],"e":[["dead hang","cu bară de tracțiuni, dimineața; dacă e greu, picioarele ating ușor solul sau un scaun; oprire când cedează priza"]],"c":["începe de la 5 secunde, apoi 6","țintă: un minut","zilnic, sau la două zile ori de 3 ori pe săptămână"]},{"v":"8VhUvd2KAPY","k":"l","t":"This Workout Program Feels Like Cheating","d":"17.07.2026","th":["program-si-split","principii-antrenament","volum-si-frecventa","failure-si-progresie"],"i":["Metoda cu trei versiuni (3x4, 2x4, 1x4): primul număr = seturi de lucru pe exercițiu, 4 = exerciții de bază pe antrenament; versiunea depinde de anii de antrenament.","Consecvența contează mai mult decât anii de abonament; 2 ani de progres focalizat bat 5 ani de schimbat programe. Nu trebuie să treci la versiunea următoare.","Trei zile pe săptămână: piept-umeri-triceps, picioare, spate-biceps, cu o zi liberă între ele. Ziua opțională adaugă sprint, gât, antebrațe, abdomen, gambe.","Progresie: pornești din partea de jos a intervalului de repetări, adaugi o repetare pe săptămână, iar la capăt crești puțin greutatea și revii jos.","Încălzire: ~10 minute mers pe înclinare, apoi seturi de rampă cu 25%, 50% și 75% din greutatea de lucru, înainte de setul de lucru."],"e":[],"c":["3x4 începători (primii 0-2 ani), 2x4 pentru 2-3+ ani, 1x4 avansați (3+ ani)","4 exerciții per antrenament","3 zile pe săptămână, a patra opțională","6-10 repetări la compuse, 8-15 la izolări","Pauze: 2-3 minute la compuse, 1-2 minute la izolări","Creștere de greutate: 1-2 până la 5 lbs","~10 minute mers pe înclinare; seturi de rampă la 25%, 50%, 75%"]},{"v":"fnuvWThH_M4","k":"s","t":"What is a good workout split to build muscle?","d":"16.07.2026","th":["program-si-split","principii-antrenament"],"i":["Un split bun antrenează fiecare grupă într-o săptămână, permite recuperarea, se potrivește programului, te ferește de accidentări și îți permite să urmărești progresul.","Full body, upper/lower, push/pull/legs și bro split pot funcționa; alege unul și nu mai căuta unul perfect."],"e":[],"c":["5 criterii"]},{"v":"hoI88DObYt8","k":"s","t":"Why Most People Stop Building Muscle","d":"16.07.2026","th":["failure-si-progresie","tehnica","accidentari-si-articulatii"],"i":["Salturile mari de greutate degradează tehnica, îngreunează recuperarea și duc la accidentări; fă cel mai mic salt posibil sau doar o repetare în plus.","Discurile mici (micro plates, 2,5 lbs) permit progresul după ce au trecut câștigurile ușoare de începător."],"e":[],"c":["disc de 2,5 lbs","1-2 lbs pe fiecare parte a barei","salt de 10-20 lbs (greșeala începătorilor)"]},{"v":"5_vs8uHtuxM","k":"s","t":"How to prevent bicep tears","d":"15.07.2026","th":["accidentari-si-articulatii","tehnica","recuperare-si-somn","brate"],"i":["Părerea autorului: rupturile de biceps apar mai ales la cei pe steroizi, supraantrenați, cu amplitudini parțiale și deadlift cu priză mixtă la greutăți foarte mari.","Prevenție: recuperare, fără ego lifting sloppy; el a renunțat la priza mixtă la deadlift și folosește priza dublă pronată."],"e":[["conventional deadlift","autorul folosește priză dublă pronată, nu mixtă"]],"c":["500-600 lbs (exemplu de greutate la care se rupe)"]},{"v":"zCcNkYPjCM4","k":"s","t":"How To Build Muscle (Simplified)","d":"14.07.2026","th":["program-si-split","nutritie","recuperare-si-somn","masa-musculara"],"i":["Plan: 3 zile pe săptămână (upper/lower sau push/pull/legs), 4-5 exerciții, 2-3 seturi grele la 6-15 repetări, notezi tot, depășești o performanță pe săptămână.","Mâncare mai ales întreagă, proteină = greutatea țintă în lbs x 0,8, somn minim 7 ore, mers sau activitate afară."],"e":[],"c":["3 zile pe săptămână","4-5 exerciții","2-3 seturi pe exercițiu","6-15 repetări","greutatea țintă în lbs x 0,8 = proteină zilnică","somn minim 7 ore"]},{"v":"YqVNxuYVIow","k":"l","t":"The Only 2 Movements You Need To Grow Your Biceps","d":"13.07.2026","th":["brate","tehnica","principii-antrenament","failure-si-progresie"],"i":["Bicepsul din două mișcări: un curl cu stretch (brațele în spatele corpului) și unul cu priză neutră, care îngroașă și mușchii de sub biceps și de pe antebraț.","Gândește pe tipar de mișcare: corpul nu știe numele exercițiului, deci bară, cablu, preacher, ganteră, coardă sau aparat sunt înlocuibile.","Alege varianta care nu supără articulațiile, îți place și la care poți crește în siguranță ani la rând.","Evită balansul: controlează greutatea, fă o pauză scurtă jos ca să scoți avântul și strânge bicepsul.","Progresie: 8-15 repetări; dacă azi ai făcut 10, ținta e 11; la 15 curate crești puțin greutatea și reiei de jos."],"e":[["incline dumbbell curl","varianta preferată cu stretch; pauză scurtă jos, controlat, 8-15 repetări"],["hammer curl","curl cu priză neutră, controlat, stretch complet jos, 8-15 repetări; merge cu gantere, coardă sau aparat"],["barbell curl, straight bar cable curl, preacher curl","date ca alternative pentru același tipar"]],"c":["8-15 repetări","+1 repetare per antrenament","+1-2 lbs după 15 repetări curate","peste 10 ani de antrenament"]},{"v":"i7S2ydHNyA8","k":"s","t":"Best time of the day to workout?","d":"12.07.2026","th":["mentalitate","recuperare-si-somn"],"i":["Cel mai bun moment de antrenament este cel la care poți fi consecvent.","Dacă nu ești om de dimineață, culcă-te la 20:00 vreo 2 săptămâni și trezirea devine mai ușoară."],"e":[],"c":["culcare la 20:00","2 săptămâni","7-8 ore de somn"]},{"v":"L4-puJMoDwA","k":"s","t":"Eat These 10 Foods to Build Muscle!","d":"11.07.2026","th":["nutritie","masa-musculara"],"i":["Alimente de bază ale autorului: vită 80/20, pulpe de pui, proteină pudră simplă, orez jasmine, cartofi, fructe, miere, avocado, uleiuri de avocado/cocos, lapte integral.","Proteina pudră nu e magie și nu e obligatorie, dar ușurează ținta de proteine; laptele integral adaugă simplu calorii și proteine."],"e":[],"c":["10 alimente"]},{"v":"_ICq8t6zr5k","k":"s","t":"Why Getting Lean Changes Everything","d":"09.07.2026","th":["slabit","masa-musculara"],"i":["La multe fizice, procentul scăzut de grăsime face cea mai mare parte din impresia vizuală; mulți sunt mai aproape de un asemenea fizic, dar nu destul de definiți."],"e":[],"c":[]},{"v":"hJiCTV65MjU","k":"l","t":"The Only 2 Movements You Need To Grow Your Shoulders","d":"08.07.2026","th":["umeri","tehnica","principii-antrenament","failure-si-progresie"],"i":["Umerii din două mișcări: ridicări laterale (lățime, V-taper) și rear delt fly (spatele umărului, aspect rotunjit și postură mai bună).","Deltoidul frontal nu primește muncă directă: e deja solicitat la bench, înclinat, overhead press și flotări, iar după părerea lui limitele sunt lateralii și posteriorii.","Ridicare laterală: cablul ține tensiune pe tot parcursul; fără avânt, ridici controlat, cobori controlat și faci o pauză jos cu stretch.","La rear delt alegi reverse pec deck (stabil, ușor de progresat), cablu sau gantere aplecat; poți merge aproape de eșec fără probleme de echilibru.","Progresie: 8-15 repetări; dacă azi ai făcut 10, ținta e 11; la 15 curate crești puțin greutatea și reiei de la 8."],"e":[["lateral raise","cable lateral raise preferat; alternative: gantere, bandă, discuri; un set de lucru, 8-15 repetări, pauză jos"],["rear delt fly","reverse pec deck preferat; alternative: cablu, gantere aplecat (folosit acasă); 8-15 repetări"]],"c":["8-15 repetări","1 set de lucru la ridicări laterale","+1 repetare per antrenament","peste 10 ani de antrenament"]},{"v":"cBbcY8WsMQ4","k":"s","t":"What Rep Range To Build Muscle?","d":"08.07.2026","th":["volum-si-frecventa","varsta"],"i":["Autorul consideră moderat 6-15 repetări; peste 15 devine mai mult cardio.","Pe măsură ce îmbătrânește, probabil va trece de la 6-10 la repetări mai multe, pentru sănătatea inimii și menținerea forței."],"e":[],"c":["6-15 repetări","peste 15 repetări","6-10 repetări"]},{"v":"sYxXsJkT6Fk","k":"s","t":"Simple Leg Workout To Build Muscle (5 Exercises)","d":"07.07.2026","th":["picioare","program-si-split"],"i":["Zi de picioare simplă, cinci mișcări, fiecare cu un singur set de lucru real la eșec: presă, extensii, îndreptări cu bară hexagonală, flexii și gambe.","Presa încarcă cvadricepșii mult fără oboseală sistemică în plus; bara hexagonală lucrează lanțul posterior cu mai puțină solicitare pe spate decât îndreptarea clasică."],"e":[["leg press"],["leg extensions"],["trap bar deadlift"],["seated leg curls"],["Smith machine calf raises","repetări foarte multe, cu extra amplitudine de pe un bloc"]],"c":["5 exerciții","un set de lucru la eșec pe exercițiu"]},{"v":"IPQPldW5wuc","k":"l","t":"The Only 2 Movements You Need To Grow Your Back","d":"06.07.2026","th":["spate","tehnica","principii-antrenament","failure-si-progresie"],"i":["Spatele din două mișcări: o tracțiune verticală pentru lățime (lați) și una orizontală (ramat) pentru adâncime și grosime în spatele mijlociu și superior.","Poți înlocui exercițiul în același tipar: tracțiuni, pulldown cu altă priză sau cu bandă, ramat la cablu, aparat sau bară, după echipament și ce te supără.","Evită ego lifting-ul: alege greutate controlabilă, lasă lații să se întindă sus și gândește coatele spre corp, nu trage cu mâinile.","Ramatul cu piept sprijinit dă stabilitate și permite eșec fără ca spatele jos sau picioarele să limiteze; stretch complet jos.","Progresie: 6-10 repetări, un set; +1 repetare pe săptămână, iar la 10 curate crești greutatea și cobori la 6. Poți roti exercițiile la câteva luni."],"e":[["wide grip lat pulldown","tracțiunea verticală preferată; coatele spre corp, stretch controlat sus, 6-10 repetări, un set"],["chest supported T-bar row","ramatul preferat; stretch complet jos, 6-10 repetări, un set"],["wide grip pull-up, chin-up, neutral grip pulldown, assisted pull-up cu bandă, single arm pulldown, cable row, machine row, barbell row, inverted row","alternative pentru aceleași tipare"]],"c":["6-10 repetări","1 set de lucru","+1 repetare per antrenament","exemplu: 7 repetări azi, 8 săptămâna viitoare","peste 10 ani de antrenament"]},{"v":"MVQWoflvdro","k":"s","t":"The Physique Most Men Actually Want","d":"06.07.2026","th":["mentalitate","masa-musculara"],"i":["Autorul spune că fizicul pe care îl vrea majoritatea este cel echilibrat, cu talie îngustă, abdomene vizibile și umeri buni, nu un monstru de masă.","Ideea e să arăți bine și în haine, și fără tricou, fără să trăiești în sală."],"e":[],"c":[]},{"v":"Ijb2DRP2Ozg","k":"s","t":"If I Could Only Pick 2 Exercises for Bigger Biceps","d":"04.07.2026","th":["brate","tehnica","antebrate"],"i":["Incline dumbbell curl: brațele pornesc în spatele corpului, deci bicepsul e mai întins. Dumbbell hammer curl: lucrează și mușchii de sub biceps și antebrațul.","Devino puternic la ele în interval moderat de repetări, cu supraîncărcare progresivă; alege 2-3 exerciții în loc de 10."],"e":[["incline dumbbell curl","întindere mare a bicepsului la început"],["dumbbell hammer curl","antrenează și brahialul și antebrațul"]],"c":[]},{"v":"KsT4v8OEt98","k":"s","t":"I Wasted Years Looking for the Perfect Workout","d":"04.07.2026","th":["program-si-split","principii-antrenament","mentalitate"],"i":["Un split e ca un traseu GPS: push-pull-legs, upper/lower sau full body duc la aceeași destinație; important e să se potrivească vieții tale.","Trei întrebări: mă recuperez și devin mai puternic? rămân fără dureri? lovesc fiecare grupă cel puțin o dată în 7 zile?"],"e":[],"c":["fiecare grupă cel puțin o dată în 7 zile"]},{"v":"t6KWcIbchmc","k":"s","t":"Losing More Weight Won't Fix Your Physique","d":"03.07.2026","th":["slabit","masa-musculara"],"i":["Dacă ești încă moale după ce ai slăbit, poate nu îți trebuie mai multă dietă, ci mai multă masă musculară construită.","Fizicul dorit apare când ai destul mușchi încât, la definire, arăți cum te aștepți; nu din pierderea unor mici cantități de grăsime."],"e":[],"c":[]},{"v":"vtmY4_1s1_k","k":"s","t":"Older Guys Can Still Build Muscle","d":"03.07.2026","th":["varsta","masa-musculara","principii-antrenament"],"i":["Legea creșterii musculare nu depinde de vârstă: antrenament greu și greutăți mai mari în timp, deci se poate construi masă și la 46 de ani.","Alege exerciții fundamentale și devino mai puternic la ele, odihnește-te bine, fără să te pierzi în tempo și trucuri."],"e":[],"c":["46 de ani","3 ani până la schimbare vizibilă"]},{"v":"DLwdwe_1ECk","k":"s","t":"Less Training = More Muscle?","d":"02.07.2026","th":["volum-si-frecventa","varsta","recuperare-si-somn","mentalitate"],"i":["Bodybuilderii cu volum foarte mare ajung adesea la 50-70 de ani să abia se miște; autorul antrenează pentru longevitate, ca să poată face asta toată viața.","El spune că după 10 ani încă face recorduri, e la cea mai bună formă, cu 30-40 de minute de trei ori pe săptămână."],"e":[],"c":["6-7 zile, 20-30 seturi pe grupă (criticat)","30-40 de minute, de 3 ori pe săptămână","10 ani"]},{"v":"QSr5pxHjL2Y","k":"l","t":"The ONLY 2 Movements You Need To Grow Your Chest","d":"01.07.2026","th":["piept","tehnica","principii-antrenament","failure-si-progresie"],"i":["Pieptul din două mișcări: o împingere (cea mai bună pentru încărcare progresivă) și un fly (amplitudine mai mare, conexiune mușchi-minte). Nu pune două împingeri.","Alegi exercițiul după trei criterii: nu supără articulațiile, îți place și poți progresa în siguranță ani. Altfel înlocuiești cu aparat, gantere sau Smith.","Autorul preferă înclinat (aparat convergent sau gantere), pentru partea superioară a pieptului, des neglijată, care antrenează bine și restul pieptului.","Fără bounce: coboară controlat până la un stretch adânc, pauză foarte scurtă, apoi împinge cu atenția pe piept; repetările să arate la fel.","Progresie: împingere 6-10 repetări, un set, +1 repetare pe săptămână; fly 8-12 (uneori 15); la capătul intervalului crești puțin greutatea."],"e":[["converging incline machine press / incline dumbbell press","împingerea preferată; alternative: machine press, gantere, Smith machine; 6-10 repetări, un set"],["chest fly (pec deck, cable, dumbbell, machine)","8-12 repetări, uneori 15; stretch adânc și strângere sus"]],"c":["6-10 repetări la împingere","8-12 (uneori 15) la fly","1 set per exercițiu","+1 repetare pe săptămână"]},{"v":"BsVjlUb0Ax4","k":"s","t":"The Workout Split Myth","d":"30.06.2026","th":["program-si-split","principii-antrenament","accidentari-si-articulatii"],"i":["În loc să cauți split-ul perfect, întreabă-te: mă recuperez și devin mai puternic? rămân fără dureri? lovesc fiecare grupă cel puțin o dată în 7 zile?","Dacă răspunzi da la toate trei, autorul crede că e suficient și că asta i-a dat rezultatele."],"e":[],"c":["fiecare grupă cel puțin o dată în 7 zile"]},{"v":"E8bmNNi5-TI","k":"s","t":"Why Getting Leaner Won't Make You Look Muscular","d":"30.06.2026","th":["slabit","masa-musculara","failure-si-progresie","nutritie"],"i":["Dacă ești deja la 12-15% grăsime și nu arăți atletic, nu mai slăbi: problema e lipsa de mușchi.","Autorul ar mânca 6-12 luni la menținere și ar urmări progres real la greutăți și repetări, notând antrenamentele."],"e":[],"c":["12-15% grăsime corporală","6-12 luni la menținere"]},{"v":"K2EfOas8xkE","k":"s","t":"Mike Mentzer Was Right About Muscle Growth","d":"29.06.2026","th":["mike-mentzer","principii-antrenament","failure-si-progresie"],"i":["Autorul a observat că vechii culturiști subliniau aceleași lucruri: seturi la eșec sau aproape, greutate sau repetări în plus, zile de odihnă și consecvență.","Creșterea vine din stimul, recuperare, progresie și consecvență în timp, nu din antrenamente aleatorii sau trucuri."],"e":[],"c":[]},{"v":"xrGCzDJWZKQ","k":"s","t":"Stop Waiting to Feel Motivated","d":"29.06.2026","th":["mentalitate"],"i":["Uită de motivație: disciplina înseamnă să faci antrenamentul indiferent de dispoziție, ca sportivii de top.","Claritatea scopului și a acțiunilor de făcut face rezultatele inevitabile; autorul zice că se trezește la 4:00-4:30 fără să fie motivat."],"e":[],"c":["trezire la 4:00-4:30"]},{"v":"w_fkIHPJdU0","k":"l","t":"You're Probably Wasting 80% of Your Time in the Gym","d":"28.06.2026","th":["principii-antrenament","program-si-split","volum-si-frecventa","suplimente"],"i":["Regula 80/20: câteva acțiuni dau cea mai mare parte a rezultatului; restul (split perfect, unghiuri, calcule fine) e zgomot. Problema nu e splitul, ci lipsa progresiei.","Alege un program dovedit care îți place, te ține fără accidentări și pe care îl poți urma; toate sunt rute diferite spre același fizic.","Mai important decât unghiul exact al băncii e să crești greutatea, de pildă de la gantere de 15 la 30 lbs la laterale.","Volum: pentru început cam 6 seturi grele pe grupă pe săptămână, apoi ajustezi; autorul face mai puțin, fiindcă după el calitatea setului contează mai mult.","Suplimentele sunt ultimii 5%, nu primii 95%, iar timingul mesei nu e critic: atinge caloriile până seara, în 3-4 mese."],"e":[],"c":["~6 seturi grele per grupă pe săptămână","3-4 mese pe zi","suplimente: ultimii 5%","exemplu laterale: 15 lbs -> 30 lbs","peste 10 ani de antrenament"]},{"v":"6zvXjgjwq0c","k":"s","t":"Stop Looking for the Perfect Workout Split","d":"28.06.2026","th":["principii-antrenament","program-si-split","recuperare-si-somn"],"i":["Principiile care stimulează creșterea sunt universale, dar aplicarea diferă cu viața fiecăruia: muncă fizică, somn de 6 ore și stres scad capacitatea de recuperare.","Mai valoros decât a copia rutine e să înțelegi motivele; un program e bun dacă antrenezi destul de greu, te recuperezi și revii mai puternic."],"e":[],"c":["somn 6 ore (exemplu)"]},{"v":"x_EQ7T8NYSI","k":"s","t":"If You Keep Falling Off Your Workout and Diet, Watch This","d":"27.06.2026","th":["mentalitate","principii-antrenament"],"i":["Dacă luni schimbi tot și miercuri ești înapoi, îți lipsește un plan; nu face o întoarcere de 180° dintr-odată, pentru că obiceiurile de ani nu se rescriu peste noapte."],"e":[],"c":[]},{"v":"sZjRLpk-SHQ","k":"s","t":"The Fastest Way To Get In Shape","d":"26.06.2026","th":["mentalitate","principii-antrenament","incepatori"],"i":["Forma bună se construiește în ani, nu în săptămâni; provocările de 30 de zile promit rezultate nerealiste.","Cu un plan dovedit și supraîncărcare progresivă, calea cea mai lungă, răbdătoare, se dovedește cea mai rapidă."],"e":[],"c":["provocări de 30 de zile și 6 săptămâni date ca exemplu de promisiuni false"]},{"v":"FqeZjz_UVhw","k":"s","t":"4 Mobility Exercises That Fix 95% Of Your Problems","d":"25.06.2026","th":["mobilitate","umeri","spate"],"i":["Rutina zilnică de mobilitate din 4 exerciții (circa 5 minute): dead hang, assisted deep squat hold, banded shoulder dislocates și band pull-aparts.","Ideea e să lucrezi în sens opus față de statul pe scaun, cu umerii și pieptul adunat în față."],"e":[["dead hang"],["assisted deep squat hold"],["banded shoulder dislocates","priză destul de largă, banda peste cap și în spate, lent și controlat"],["band pull-aparts","banda ținută în față, tragi în lateral deschizând pieptul, cu spatele de sus și rear delts"]],"c":["4 exerciții","circa 5 minute"]},{"v":"bcyRumJVHIM","k":"l","t":"Normalize It Taking Years To Get In Shape, Not Weeks","d":"24.06.2026","th":["mentalitate","principii-antrenament","masa-musculara","altceva"],"i":["Mulți renunță pentru că așteptările sunt distorsionate de rețelele sociale, nu din cauza genelor sau a programului; fizicul admirat se construiește de obicei în ani.","După autor, cei cu transformări uluitoare rapide sunt excepții genetice, folosesc substanțe nespuse sau antrenează de mai mult timp decât recunosc.","Într-un an poți pierde multă grăsime dacă ești supraponderal sau poți câștiga vizibil mușchi dacă ești slab, dar fizicul dorit complet cere mai mult.","Progresul vine din lucruri plictisitoare repetate: aceleași alimente întregi, 3-4 zile de antrenament, forță în creștere și culcat la timp, ani la rând.","Dacă ești mai puternic decât anul trecut și ai obiceiuri mai bune, progresezi; nu schimba programul la câteva luni și nu cumpăra suplimente."],"e":[],"c":["3-4 zile de antrenament pe săptămână","peste 10 ani de antrenament"]},{"v":"lf4nTLIdfwY","k":"s","t":"Why I Eat Mostly Whole Foods","d":"24.06.2026","th":["nutritie"],"i":["Mănâncă mai ales mâncare întreagă (carne, fructe, legume, miere, apă) și eviți alimentele proiectate ca să creeze dependență."],"e":[],"c":[]},{"v":"E_VBVAD-gYY","k":"s","t":"Missed A Week In The Gym? Watch This.","d":"23.06.2026","th":["mentalitate","recuperare-si-somn"],"i":["Dacă ai ratat o săptămână din cauza bolii sau a programărilor, nu renunța și nu te demoraliza: revino imediat.","Autorul spune să tragi învățăminte (mai multă disciplină, mai multă pregătire) și să te raportezi la motivul tău."],"e":[],"c":[]},{"v":"d2LcxWKnGVM","k":"s","t":"I Built More Muscle By Doing Less","d":"23.06.2026","th":["volum-si-frecventa","failure-si-progresie"],"i":["Autorul spune că a progresat mai repede cu un set la failure, folosind regula: egalează sau depășește repetările anterioare cu una.","La intermediari și avansați cu antrenament stagnant: măcar un set la failure păstrează masa musculară."],"e":[],"c":["1 set la failure","+1 repetare"]},{"v":"zYG0TB4YHeQ","k":"s","t":"3 days vs 5 days a week in the gym?","d":"22.06.2026","th":["volum-si-frecventa","accidentari-si-articulatii","program-si-split","incepatori"],"i":["Autorul recomandă 3-4 zile pe săptămână, dar spune că e părerea lui; mai mult de atât înseamnă, după el, că faci ceva greșit.","A început cu 6-7 zile, a stagnat, s-a ars și a avut dureri la coate și umeri; acum, cu 3 zile de 30-40 de minute, e cel mai puternic."],"e":[],"c":["3-4 zile pe săptămână","6-7 zile la început","antrenament de 30-40 de minute"]},{"v":"8y45XSPCSLo","k":"l","t":"Mike Mentzer's Advice Doesn't Work","d":"21.06.2026","th":["mike-mentzer","failure-si-progresie","volum-si-frecventa","principii-antrenament"],"i":["Autorul crede că ar fi ajuns la același fizic cu un set până la eșec de la început, dar spune că mulți au construit fizicuri excelente cu volum mare.","Esența lui Mentzer: antrenament rar (la 72 de ore sau mai mult), progres de greutate sau repetări, jurnal, eșec muscular și un set de lucru pe 4-5 exerciții.","Dacă un set foarte greu aproape de eșec dă aproape tot stimulul, întrebarea e dacă beneficiul rămas merită timpul, oboseala și uzura articulațiilor și tendoanelor.","Mai mult volum cere mai multă recuperare și complexitate; pentru cine nu urcă pe scenă, câștigul suplimentar poate fi mic, în părerea autorului.","În experiența lui: recuperare mai bună, articulații mai bune și mai mult timp pentru alte hobby-uri; nu cere nimănui să facă la fel."],"e":[],"c":["72 de ore între antrenamente sau mai mult","1 set de lucru la eșec pe 4-5 exerciții","înainte: 6-7 zile pe săptămână, câte 2 ore","peste 10 ani de antrenament"]},{"v":"a0Lr9vx1qyo","k":"s","t":"Pause reps will get you jacked","d":"21.06.2026","th":["tehnica","piept"],"i":["Pauza la piept la bench elimină elanul și construiește forță în poziția de jos, cu amplitudine completă.","Autorul spune că seamănă mai mult cu ridicarea unei greutăți din repaus în viața reală."],"e":[["bench press cu pauză","pauză de o secundă jos"]],"c":["pauză de o secundă"]},{"v":"LVjooloBATE","k":"s","t":"4 Days A Week Is Enough To Get Jacked","d":"20.06.2026","th":["volum-si-frecventa","accidentari-si-articulatii"],"i":["Autorul spune că nu antrenezi mai mult de 4 zile pe săptămână, pentru că altfel riști accidentări dacă nu ai stilul de viață pentru recuperare.","Câștigul în plus ar fi de 1-3%, în schimb vin mai multe ore, mai mult stres articular și dureri."],"e":[],"c":["max 4 zile pe săptămână","1-3% câștig suplimentar"]},{"v":"GA6HRl2yjk4","k":"s","t":"The Biggest Fitness Mistake Nobody Talks About","d":"19.06.2026","th":["mentalitate","program-si-split"],"i":["Autorul compară fitnessul cu o carieră: nu te schimbi la fiecare câteva luni de job, ci rămâi, faci repetări, greșești și devii mai bun.","Cei care sar de la un antrenament la altul se învârt pe loc ani la rând."],"e":[],"c":[]},{"v":"XEY263yPYbM","k":"s","t":"Getting in shape isn't complicated","d":"19.06.2026","th":["principii-antrenament","nutritie","recuperare-si-somn","mentalitate"],"i":["Fitness-ul nu e complicat: antrenează-te greu de câteva ori pe săptămână, progresează, mănâncă mâncare reală, dormi bine și ieși zilnic la soare.","Complexitatea e profitabilă pentru industrie, care vinde protocoale și suplimente."],"e":[],"c":[]},{"v":"Ste8ZJZSmFk","k":"s","t":"The mistake most beginners in the gym make","d":"18.06.2026","th":["incepatori","program-si-split"],"i":["Începătorii se încurcă învățând de la toți deodată; mai multe abordări funcționează, dar fundamentele contează mai mult decât sistemul.","Nu amesteca metode până nu ai experiență și o bază musculară."],"e":[],"c":["3 zile pe săptămână"]},{"v":"Zt2QTAlVAQw","k":"s","t":"Your Reps Don't Need To Look Perfect","d":"17.06.2026","th":["tehnica","failure-si-progresie"],"i":["Repetările nu trebuie să fie perfecte spre record, dar rămâi în control; forma se mai strică puțin la failure, fără să arunci greutatea.","Împinge-te, dar nu fi neglijent."],"e":[],"c":["10-11 repetări"]},{"v":"cefFxDOfMVI","k":"l","t":"My Home Gym Setup For Chest, Shoulders, and Triceps","d":"16.06.2026","th":["sala-acasa","piept","umeri","brate"],"i":["Echipamentul scump nu e necesar: corpul răspunde la rezistență și tensiune. Autorul a antrenat aproape 5 ani într-o cameră liberă, mai ales cu greutăți libere și rack.","Ziua 1 din split-ul de 3 zile: piept, umeri, triceps; urmează zi liberă, picioare, zi liberă, spate-biceps și două zile libere.","A ales un aparat convergent cu plăci din motive de cost: gantere grele până la 120 lbs în perechi ar costa cam 3.000 de dolari, iar mișcarea imită ganterele.","Fly-ul se asociază cu împingerea; aparatul ieftin ales nu are reverse fly pentru deltoizii posteriori, așa că ar recomanda mai degrabă un pec deck cu reverse fly.","Alternative acasă: gantere înclinate, dips, bară înclinată, flyuri cu gantere sau cablu, laterale cu gantere, bandă sau discuri, extensii pentru triceps."],"e":[["incline press pe 3-in-1 converging chest press","aparat cu plăci; alternative: incline dumbbell press, dips cu greutate, incline barbell press"],["chest fly machine","alternative: dumbbell fly înclinat sau plat, pec deck, low to high cable fly"],["cable lateral raise","alternative: gantere, bandă, discuri"],["straight bar triceps pushdown","la turn de cablu; alternative: overhead dumbbell extension, skull crushers"]],"c":["3 zile pe săptămână","~55 lbs gantere inițial; perechi până la 120 lbs ≈ 3.000 de dolari","aparat fly sub 300 de dolari","aproape 5 ani de antrenament acasă"]},{"v":"Zq10DBIyDWo","k":"s","t":"The Biggest Lie About Staying Lean","d":"15.06.2026","th":["slabit","mentalitate","recuperare-si-somn"],"i":["Cei care rămân definiți tot anul nu fac lucruri extreme, ci repetă zilnic aceleași acțiuni; sala trebuie să-ți îmbunătățească viața, nu să o consume.","Pe scurt: 3 zile de antrenament greu, mâncare întreagă, mers zilnic și cât mai mult somn."],"e":[],"c":["3 zile pe săptămână"]},{"v":"e0hrZDpdrsI","k":"s","t":"Mike Mentzer's Advice Doesn't Work?","d":"15.06.2026","th":["mike-mentzer","failure-si-progresie"],"i":["Mușchiul crește dacă pornești mecanismul cu un set la failure, te recuperezi și revii cu ceva mai bine.","Autorul face patru exerciții cu patru seturi și simte aceeași pompă ca pe vremea antrenamentelor de 7 zile pe săptămână."],"e":[],"c":["4 exerciții","4 seturi","7 zile pe săptămână, 2 ore (înainte)"]},{"v":"oZv5qnmAH0I","k":"s","t":"Getting Jacked Is Simpler Than You Think","d":"14.06.2026","th":["principii-antrenament","brate","mentalitate"],"i":["Nu hack-urile pentru biceps; alege câteva exerciții și întreabă-te dacă ești mai puternic decât săptămâna trecută."],"e":[],"c":[]},{"v":"L-QUyYo_XsI","k":"s","t":"You Will Never Diet Your Way To Looking Jacked","d":"13.06.2026","th":["masa-musculara","slabit","failure-si-progresie","mentalitate"],"i":["Nu poți slăbi până ajungi musculos: dieta și cardio-ul nu construiesc mușchi; trebuie supraîncărcare progresivă (repetări și greutate) timp de ani.","Exemple: bench de la 155 la 225 lbs sau dumbbell curl de la 25 la 45 lbs; altfel ajungi doar skinny fat."],"e":[],"c":["bench press 155 lbs la 225 lbs","dumbbell curl 25 lbs la 45 lbs","2-3 luni (promisiune criticată)","ani"]},{"v":"niRNSxLWHns","k":"l","t":"Why I Stopped Training To Failure","d":"12.06.2026","th":["failure-si-progresie","mike-mentzer","principii-antrenament","accidentari-si-articulatii"],"i":["Autorul nu mai face din eșec ținta, ci din progres: să faci mai mult decât data trecută, prin repetare în plus, mai multă greutate sau control mai bun.","Dacă ai trecut de la 8 la 9 repetări cu aceeași formă, ai creat deja noul stimul; repetările până la 11 adaugă oboseală de recuperat în articulații și țesut conjunctiv.","Întrebarea utilă: care e cel mai mic progres care te ține în mișcare? Așa ai un reset firesc când crește greutatea și o oboseală mai ușor de gestionat.","Începătorii pot crește mult de la o săptămână la alta; la nivel intermediar, 2,5 lbs sau o repetare sunt normale și suficiente.","Context: de peste un an aplică stilul Mentzer (un set la eșec pe 4-5 exerciții, antrenament la 72 de ore sau mai rar, 20-30 min) cu această ajustare."],"e":[["curl (exemplu)","25 lbs: 8 repetări într-o săptămână, 9 în următoarea"]],"c":["peste 10 ani, peste 2.000 de antrenamente","antrenament la 72 de ore sau mai rar","1 set la eșec pe 4-5 exerciții, 20-30 min","începători: +5 lbs pe săptămână","intermediar: +2,5 lbs sau 1 repetare","exemplu: 25 lbs x 8 -> x 9"]},{"v":"8UAwTKLTpm8","k":"s","t":"The Simplest Advice to Build Muscle","d":"11.06.2026","th":["program-si-split","incepatori","failure-si-progresie","volum-si-frecventa"],"i":["3 zile pe săptămână, push / legs / pull cu o zi liberă între ele, 4-5 exerciții pe zi, 2-3 seturi fiecare, aproape de eșec, în general 6-15 repetări.","Notează greutatea și repetările; data viitoare bate fiecare set cu o repetare, iar la vârful intervalului (10, 12 sau 15) adaugi puțină greutate și reiei de la 6."],"e":[["incline press, fly, cable lateral raises, tricep pushdowns","exemplu de zi de push"]],"c":["3 zile pe săptămână","4-5 exerciții","2-3 seturi","6-15 repetări","reluare de la 6 repetări după adăugarea de greutate"]},{"v":"bIqpP8T2j48","k":"l","t":"Unfortunately, Building Muscle Really Is This Simple","d":"07.06.2026","th":["failure-si-progresie","principii-antrenament","masa-musculara","program-si-split"],"i":["Progresia e cheia: dai corpului un motiv să se adapteze, prin mai multă greutate, repetări sau execuție mai bună; la început merge automat, apoi apare platoul.","Salturile mari de greutate strică tehnica, îngreunează recuperarea și aduc accidentări; ținta e cel mai mic salt care încă înseamnă progres.","Micro-plăcile de 2,5 lbs permit pași mici și sustenabili, ca investițiile mici făcute constant; costă cam 10 dolari pe Amazon.","Exemplu: o repetare în plus pe săptămână; dacă azi ai făcut 6, ținta e 7 chiar dacă ai putea mai mult. La 10 adaugi 2,5 lbs și cobori la 6."],"e":[["incline chest machine","exemplu: 6 repetări azi, ținta 7 în săptămâna următoare"]],"c":["micro-placă de 2,5 lbs","~10 dolari","compuse 6-10 repetări, accesorii 8-12 sau 15","exemplu începător: curl 20 -> 25 -> 30 lbs; bench 135 -> 155 -> 165 lbs"]},{"v":"qUx8jZdxwsw","k":"s","t":"You don't need a second set!","d":"06.06.2026","th":["mike-mentzer","volum-si-frecventa","failure-si-progresie"],"i":["Mentzer: după un set dus la failure muscular momentan, nu mai e necesar un al doilea; ca un întrerupător, odată pornit mecanismul nu-l mai apeși."],"e":[],"c":["1 set la failure"]},{"v":"BZuePhPJ5sY","k":"s","t":"Nobody Wants To Hear This About Fitness","d":"05.06.2026","th":["mentalitate","principii-antrenament"],"i":["Maturizarea în sală e să accepți că fizicul dorit e la ani distanță; transformările de 12 săptămâni și «summer shred»-urile sunt, după autor, promisiuni false.","Fitnessul e maraton: repetă aceleași lucruri simple și lasă timpul să lucreze, fără să te obsedezi de viteză."],"e":[],"c":["12 săptămâni și 30 de zile (criticate)","10 ani de antrenament"]},{"v":"m-TZ9020jDg","k":"s","t":"Why I Only Do 1 Set To Failure","d":"05.06.2026","th":["volum-si-frecventa","failure-si-progresie"],"i":["Cu un singur set la failure, după încălzire, dai tot (aproape zero repetări în rezervă); înainte, cu mai multe seturi, se ținea în rezervă.","Poate ieși din sală în 30 de minute și rămâne cel mai puternic."],"e":[],"c":["1 set la failure","~0 repetări în rezervă","30 de minute"]},{"v":"JtS8_w30UuQ","k":"l","t":"How I Meal Prep Each Week To Stay Lean And Jacked","d":"03.06.2026","th":["nutritie","masa-musculara","slabit","altceva"],"i":["Un sistem bate voința: pregătești mâncarea dinainte, ca să nu decizi flămând și obosit. Autorul gătește de două ori pe săptămână pentru 3-4 zile.","Fiecare masă are proteină, carbohidrat și grăsime; exemple: ardei, ceapă și fasole verde cu orez gătit în supă de oase, pui, vită sau cârnăciori de pui.","Bulk: ~3 mese și gustări, două shake-uri proteice cu lapte integral și miere, seara smoothie cu lapte de cocos, proteină, miere, curmale, unt de migdale, fructe.","La slăbit structura rămâne, dar reduci porțiile și alimentele mai calorice (mai puțin orez și avocado, fără unt de migdale).","Cumpărături aproape fixe: carne, orez sau cartofi, legume, fructe, fără conservanți; mănâncă pentru a trăi, nu trăiește pentru a mânca."],"e":[],"c":["gătit 2 ori pe săptămână pentru 3-4 zile","3 mese pe zi plus gustări","2 shake-uri proteice cu lapte integral în bulk","pui la grătar ~20 de minute"]},{"v":"d3znfjqGvXw","k":"s","t":"Doing less in the gym helped me build more muscle","d":"02.06.2026","th":["volum-si-frecventa","mike-mentzer","recuperare-si-somn"],"i":["După accidentări și stagnare, autorul a trecut de la volum mare la un set la failure, inspirat de Mentzer.","Esențial: stimul, recuperare, progres; ține de luni și ani, nu de câteva săptămâni."],"e":[],"c":["1 set la failure"]},{"v":"qYz-7S-rxDw","k":"s","t":"My TOP 10 Exercises To Get Jacked","d":"02.06.2026","th":["program-si-split","piept","spate","picioare"],"i":["Cele 10 preferate: incline press, fluturare, lat pulldown, chest supported row, overhead press, laterale la cablu, trap bar deadlift, leg press, incline curl, neck curl.","Câțiva ani de progres pe ele bat schimbarea constantă a exercițiilor."],"e":[["incline dumbbell press"],["chest fly"],["wide grip lat pulldown"],["chest supported row"],["barbell overhead press"],["cable lateral raises"],["trap bar deadlift"],["leg press"],["incline dumbbell curls"],["neck curls"]],"c":["10 exerciții","3 ani"]},{"v":"5OFcm6naGfk","k":"l","t":"The Best Workout Routine Doesn't Exist","d":"31.05.2026","th":["principii-antrenament","program-si-split","mike-mentzer","failure-si-progresie"],"i":["Principii universale: antrenament suficient de greu (aproape de eșec), recuperare suficientă și progres în timp; organizarea depinde de job, somn și stres.","Splitul e secundar: full body, upper/lower sau push/pull/legs sunt rute diferite spre aceeași destinație; cel bun este cel la care poți rămâne.","Trei întrebări: te recuperezi și devii mai puternic, ești fără dureri persistente, lovești fiecare grupă măcar o dată în 7 zile? Trei de da înseamnă că ajunge.","Autorul într-o zi de push: patru exerciții după 1x4, singura țintă fiind o repetare în plus; în rest somn, lumină naturală, mers și mâncare densă în nutrienți.","Nu ridici greutăți zilnic; în zilele libere mergi înclinat sau faci mobilitate/core. Pentru majoritate, o dată pe săptămână pe grupă, în 3 zile, e potrivit, spune el."],"e":[],"c":["3 zile pe săptămână","1 dată pe săptămână per grupă","4 exerciții","aceeași zi de push la ~7 zile"]},{"v":"8Bz4lVc55Mk","k":"s","t":"How to Work Out When You Have No Motivation","d":"31.05.2026","th":["mentalitate"],"i":["Când nu ai chef, privește înapoi la versiunea de dinainte (anti-viața) pe care nu vrei s-o reiei și la care ai fi dezamăgit.","Apoi proiectează viziunea spre care mergi (casa, familia, stilul de viață dorit); motivația negativă și cea pozitivă se completează."],"e":[],"c":[]},{"v":"8KkXKHfMeDk","k":"s","t":"fitness really is simple","d":"30.05.2026","th":["principii-antrenament","incepatori","nutritie","recuperare-si-somn"],"i":["Rețeta autorului: 3 antrenamente pe săptămână, circa 10.000 de pași pe zi, mâncare reală, soare, 7+ ore de somn, hidratare și consecvență.","Cei care rămân în formă fac aceleași lucruri plictisitoare repetat; partea grea nu e să afli ce să faci, ci să o faci destul de mult."],"e":[],"c":["3 antrenamente pe săptămână","10.000 de pași pe zi","7+ ore de somn"]},{"v":"Xr6QKztf8zU","k":"s","t":"Mike Mentzer Was Right About Building Muscle","d":"28.05.2026","th":["mike-mentzer","volum-si-frecventa","principii-antrenament"],"i":["Construcția musculară se reduce la stimul și recuperare; splitul, numărul de seturi sau frecvența sunt detalii minore.","Întreabă-te dacă te antrenezi destul de greu pentru un stimul real și dacă te recuperezi."],"e":[],"c":[]},{"v":"I233qZbltas","k":"l","t":"Why You Still Look Soft Even After Losing Weight","d":"27.05.2026","th":["slabit","masa-musculara","failure-si-progresie","nutritie"],"i":["Dacă ești deja destul de slab (cam 12-15% grăsime) și tot nu arăți atletic, probabil îți lipsește masa musculară; a dieta mai mult te face doar mai mic.","Soluția lui: 6-12 luni la calorii de menținere și antrenament productiv, cu progres real în greutate și repetări la aceleași mișcări.","Exemple de țintă: de la gantere de 50 la 80 la înclinat pentru 8 repetări; de la 225 la 315 lbs la genuflexiune. Dacă ridicările nu cresc, nu construiești mușchi.","Notează antrenamentele într-un jurnal și într-o aplicație; a ține cifrele în cap aproape garantează lipsa progresului.","Fizicul dorit apare când ai destul mușchi încât, la slăbit, arăți cum ai vrut, nu din tot mai multe slăbiri."],"e":[["incline dumbbell press","exemplu de țintă: de la 50 la 80 lbs per ganteră, la 8 repetări"],["squat","exemplu de țintă: de la 225 la 315 lbs"]],"c":["12-15% grăsime","6-12 luni la calorii de menținere","gantere 50 -> 80 lbs la 8 repetări","genuflexiune 225 -> 315 lbs"]},{"v":"m22CSK1BeQo","k":"s","t":"Why I only train each muscle 1x a week","d":"27.05.2026","th":["volum-si-frecventa","recuperare-si-somn","accidentari-si-articulatii"],"i":["Autorul antrenează un mușchi o dată pe săptămână: recuperarea include articulații, țesut conjunctiv și sistem nervos, nu doar mușchiul.","Frecvența mai mare nu e greșită, doar nu e obligatorie; dacă ești mereu obosit, încearcă pauze mai lungi."],"e":[],"c":["o dată pe săptămână"]},{"v":"t261vAFaV8w","k":"s","t":"Building Muscle Takes Longer Than You Think","d":"27.05.2026","th":["mentalitate","masa-musculara"],"i":["Obiectivul poate dura ani, dar anii trec oricum; chiar făcut doar 60-70% corect, tot ajungi mult mai departe decât dacă nu încerci."],"e":[],"c":["60-70% respectarea planului","2-3 ani"]},{"v":"R1Wlezwn_tc","k":"s","t":"I Want To Be In Shape, Not Huge","d":"25.05.2026","th":["mentalitate","masa-musculara"],"i":["Autorul nu își dorește să fie cât mai mare: vrea să arate bine, să fie puternic în viața de zi cu zi și atletic (skate, surf, sprint).","Nu vrea să trăiască în sală 7 zile pe săptămână mâncând șase mese pe zi."],"e":[],"c":["10 ani de antrenament","7 zile și 6 mese pe zi (respins)"]},{"v":"SBO1xqNWS94","k":"s","t":"If You Want To Get Jacked, Do This Every Day","d":"25.05.2026","th":["mentalitate","principii-antrenament"],"i":["Repetă zilnic acțiuni simple: aceleași mese, programul de antrenament, mărirea constantă a greutății, indiferent de dispoziție."],"e":[],"c":[]},{"v":"iRdJk7dl2Tg","k":"l","t":"My Simple Daily Mobility Routine (4 Exercises)","d":"23.05.2026","th":["mobilitate","accidentari-si-articulatii","incepatori","altceva"],"i":["Rutină zilnică de patru mișcări, ~5 minute: dead hang, squat adânc cu sprijin, shoulder dislocates cu bandă și pull-aparts cu bandă.","Dead hang-ul deschide umerii în sus, opusul poziției de la birou și telefon; începi cu 5-10 secunde sau cu picioarele pe un taburet.","La squatul adânc te ții de ceva stabil, ca să nu lupți cu echilibrul și să lași șoldurile, genunchii și gleznele să se deschidă.","Dislocatele cu bandă se fac lent, cu prindere lată, atent la amplitudinea rar folosită; pull-apart-urile compensează postura rotunjită.","Începe cu o singură rundă, apoi 2-3; zilnic, la două zile sau 3 zile pe săptămână; rutina nu anulează lipsa generală de mișcare."],"e":[["dead hang","1-2 seturi; începători 5-10 secunde, cu picioarele pe un taburet dacă e prea greu"],["assisted deep squat hold","cu sprijin stabil, 30-60 secunde, cu mici balansuri laterale"],["banded shoulder dislocates","bandă ușoară, prindere lată, lent, 10-15 repetări"],["band pull-apart","10-15 repetări lente și controlate"]],"c":["4 exerciții, ~5 minute","dead hang 1-2 seturi","squat adânc 30-60 secunde","10-15 repetări la dislocate și pull-apart","1 rundă, apoi 2-3","zilnic, la două zile sau 3 zile pe săptămână"]},{"v":"bLVQxZHVGJA","k":"s","t":"Can You Keep Getting Stronger Forever?","d":"23.05.2026","th":["failure-si-progresie","accidentari-si-articulatii","varsta"],"i":["Nu trebuie să crești greutatea la infinit; după ani de antrenament, la un nivel de forță ridicat, poți încerca o variantă mai grea sau doar menține.","Menținerea mușchiului costă puțin: un set la failure cu ganteră mai ușoară (25-30 lbs) nu te face să pierzi volum."],"e":[["dumbbell curls","exemplu: 55 lbs, 12-15 repetări; 60 lbs cu durere de cot sau umăr"],["incline curls","variantă mai grea"]],"c":["55 lbs, 12-15 repetări","60 lbs","10+ ani","25-30 lbs pentru menținere"]},{"v":"4-ERnMonUGQ","k":"l","t":"The 1x4 Method - Legs","d":"22.05.2026","th":["picioare","incalzire","failure-si-progresie","tehnica"],"i":["Ziua de picioare 1x4: leg press, trap bar Romanian deadlift, extensii și curl; ~30 minute. Presa se poate înlocui cu squat, Bulgarian split squat sau SSB squat.","Pentru hamstrings combini o balans de șold (hip hinge) cu o flexie de genunchi; extensiile și curl-ul sunt muncă bonus.","Încălzire dinamică și un set la ~50% din greutatea de lucru, apoi direct setul de lucru.","Ținta e o repetare în plus, nu eșecul cu orice preț; uneori te oprești cu una în rezervă, iar salturile mici se adună fără să te epuizeze.","Autorul rotește variantele la 3-4 luni și lucrează acum unilateral (mai puțină oboseală sistemică, conexiune mai bună); bilateral economisește timp."],"e":[["leg press","acum single leg; un set de încălzire la ~50%, apoi setul de lucru"],["trap bar Romanian deadlift","accent pe hip hinge pentru hamstrings"],["leg extension","single leg; muncă directă pentru cvadricepși"],["leg curl","flexie de genunchi pentru partea cealaltă a hamstrings"]],"c":["4 exerciții, ~30 minute","un set de încălzire la ~50%","rotație variante la 3-4 luni","exemplu: leg press 350 lbs x 10 -> 400-420 lbs x 10 într-un an","încălzire: 10 pe fiecare picior"]},{"v":"GdWB5bxheQs","k":"s","t":"My best pieces of advice to get you jacked","d":"21.05.2026","th":["principii-antrenament","mentalitate","volum-si-frecventa","failure-si-progresie"],"i":["10 lecții după peste 10 ani: nu știi ce poți până nu ai antrenat și mâncat corect ani; majoritatea fac prea mult; nu te compara cu cei pe steroizi.","Nu schimba programul, rămâi ani la exerciții de bază; supraîncărcarea progresivă și notarea sunt obligatorii; gândește în ani, nu în săptămâni."],"e":[["incline bench, barbell rows, wide grip pull-ups, squats, deadlifts","exemplu de exerciții de bază de dezvoltat 3 ani"]],"c":["10 lecții","3 ani","8.000-10.000 de pași","3 antrenamente pe săptămână"]},{"v":"fX6aJxkKB4Y","k":"s","t":"The Best Workout Split Doesn’t Exist..","d":"21.05.2026","th":["program-si-split","accidentari-si-articulatii"],"i":["Full body, calisthenics, push/pull/legs, upper/lower sau bro split pot da rezultate dacă ești consecvent; alege ce îți place, ca să rămâi fără accidentări."],"e":[],"c":[]},{"v":"mIKHtae1zfQ","k":"s","t":"If you want to get lean, watch this","d":"21.05.2026","th":["slabit","nutritie"],"i":["Baza slăbitului e deficitul caloric: pornește de la greutatea ta ori 10 pentru calorii, notează tot într-o aplicație și cântărește-te zilnic dimineața.","După 14 zile compară media; dacă nu scade, taie 100 de calorii. Țintă: ~1 pound pe săptămână, menținând mușchiul."],"e":[],"c":["greutate × 10 = calorii de pornire","14 zile","-100 kcal","~1 pound pe săptămână"]},{"v":"72TB-Fe05nY","k":"l","t":"If You Can’t Stick To A Diet, Watch This","d":"20.05.2026","th":["nutritie","mentalitate","slabit","incepatori"],"i":["Dieta eșuează când nu schimbi sensul mâncării: autorul a ajuns să vadă junk food-ul ca un troc prost, 10 minute de plăcere contra inflamație și somn slab.","Pași: o decizie reală, nu discursul de duminică; mediu în care alegerea bună e ușoară; plan realist; o abatere nu anulează progresul; repetiție.","Fă un plan viabil, nu pui simplu cu legume: păstrezi preparatele preferate, dar schimbi ingredientele (burger, cartofi în ulei de avocado, ketchup fără zahăr).","Pentru poftă de dulce: mango uscat, fructe, miere crudă, curmale, apă de cocos, lapte integral cu miere și shake-uri proteice.","Dacă ai ieșit din plan, revino imediat: doar renunțarea e eșec."],"e":[],"c":[]},{"v":"NElCFHF2gyI","k":"s","t":"How Many Sets Do You REALLY Need to Build Muscle?","d":"19.05.2026","th":["volum-si-frecventa","principii-antrenament","accidentari-si-articulatii"],"i":["Autorul nu e de acord cu cele 10-20 de seturi pe grupă pe săptămână: randamentul scade mult; el antrenează fiecare grupă o dată pe săptămână, intens, apoi recuperează.","Preferă să se antreneze consecvent mai puțin și să fie sănătos peste 5 ani, decât 30 de seturi pe săptămână pentru 2-3% în plus."],"e":[],"c":["10-20 seturi pe grupă (criticat)","30 de seturi pe săptămână (criticat)","2-3% câștig în plus"]},{"v":"_Qw6Jwi5Ut8","k":"s","t":"Why I Pause My Reps","d":"18.05.2026","th":["tehnica","principii-antrenament"],"i":["Pauzele la piept la bench scot elanul și ego-ul, cer forță de la oprire completă și te fac mai puternic în pozițiile cele mai grele.","Tensiunea mecanică este motivul creșterii, iar săritul barei o reduce."],"e":[["bench press cu pauză","pauză pe piept, fără elan"]],"c":[]},{"v":"lNM7WP_Q8cQ","k":"s","t":"Why I stopped doing full body workouts","d":"18.05.2026","th":["program-si-split","accidentari-si-articulatii","volum-si-frecventa"],"i":["Autorul a renunțat la full body: sistemul nervos, articulațiile și țesutul conjunctiv se recuperează mai încet decât mușchii, iar rotirea intensității complică.","Folosește un split push/legs/pull de 3 zile pe săptămână, după ce le-a încercat pe toate."],"e":[],"c":["3 zile pe săptămână"]},{"v":"T22M8iHv_qw","k":"l","t":"The 1x4 Method - Back and Biceps","d":"17.05.2026","th":["spate","brate","program-si-split","incalzire"],"i":["Ziua spate-biceps la 1x4: pulldown cu priză largă, ramat cu piept sprijinit, rear delt fly și curl cu gantere; păstrează tiparul dacă schimbi exercițiile.","Încălzire cu bandă ușoară care mimează mișcările (curl, face pull, press, neck rolls), 10-15 repetări, 1-3 circuite; apoi un set la 50-60% și setul de lucru.","Notează fiecare antrenament, altfel nu ai ce bate data viitoare. Ținta e o repetare în plus (180 lbs x 7 -> x 8); dacă egalezi, e în regulă.","Dacă stagnezi, verifică somnul, recuperarea, nutriția și hidratarea; la slăbit prioritatea e grăsimea, nu forța.","Forma poate ceda puțin la ultimele repetări, dar rămâi în control; nu fugi de eșec. Pompa puternică înseamnă că nu mai trebuie al doilea set."],"e":[["wide grip lat pulldown","un set de încălzire la 50-60%, apoi setul de lucru; 7-10 repetări; stretch complet sus"],["chest supported T-bar row","pentru grosimea spatelui"],["rear delt fly","cu gantere aplecat, stretch complet"],["dumbbell bicep curl","exemplu cu gantere de 50 lbs; săptămâna trecută 10, ținta 11"]],"c":["180 lbs x 7 -> x 8 la lat pulldown","curl cu gantere de 50 lbs: 10 -> 11 repetări","încălzire cu bandă: 10-15 repetări","un set de încălzire la 50-60% din greutatea de lucru","7-10 repetări la pulldown","exemplu începător: 100 lbs x 6 -> 160 lbs x 10 în 12 luni"]},{"v":"D18iX55Q7yE","k":"s","t":"Machines vs Free Weights: Which Builds More Muscle?","d":"17.05.2026","th":["principii-antrenament","tehnica","masa-musculara"],"i":["Mașinile nu sunt inferioare greutăților libere: corpul simte doar tensiunea, nu sursa ei.","Ce contează e tensiunea aplicată constant, cu recuperare și supraîncărcare progresivă; gândește în tipare de mișcare (presă orizontală), nu în exerciții anume."],"e":[["machine chest press / dumbbell press","același tipar de apăsare orizontală"],["leg press, squat, hack squat","rezolvă o problemă similară"]],"c":[]},{"v":"LMWgz3B6oaU","k":"s","t":"Do You Train Differently When Cutting vs Bulking?","d":"16.05.2026","th":["failure-si-progresie","slabit","masa-musculara","principii-antrenament"],"i":["Antrenamentul rămâne construit pe progresie la aceleași exerciții cheie, indiferent dacă faci bulk sau cut; nu schimba tot split-ul când schimbi caloriile.","La cut nu adăuga zile, volum sau repetări mari: recuperarea e mai slabă, deci scopul e să-ți menții forța; dacă greutățile rămân la fel și corpul slăbește, ții mușchiul."],"e":[],"c":[]},{"v":"OcaOx-SPbo8","k":"s","t":"Unfortunately, Fitness is simple","d":"16.05.2026","th":["program-si-split","nutritie","recuperare-si-somn","cardio-si-pasi"],"i":["Cu 2-3 zile de sală pe săptămână, 30-45 de minute, mâncare reală, pași zilnici, somn bun și hidratare poți fi mai musculos decât 99% din oameni.","Autorul spune că minciuna bodybuilderilor (6-7 zile x 2 ore) nu e necesară fără steroizi: contează progresia și recuperarea."],"e":[],"c":["2-3 zile pe săptămână","30-45 minute","6-7 zile x 2 ore (criticat)"]},{"v":"uITwVBuL01E","k":"l","t":"This One Fitness Rule Will Save You Years Of Wasted Time In The Gym","d":"15.05.2026","th":["mentalitate","incepatori","principii-antrenament","program-si-split"],"i":["Regula unei singure surse: alege o sursă a cărei filosofie are logică și urmează-i sistemul exact 6-12 luni; abia apoi poți remixa.","Mai multe abordări funcționează; greșeala începătorilor e să amestece metode din surse diferite într-o rutină incoerentă și să schimbe programul la două săptămâni.","Fără angajament nu apare adaptare; e ca job hopping-ul, unde crești doar dacă rămâi, înveți și îți faci repetările.","Baza care contează: antrenament greu de câteva ori pe săptămână, progres simplu, alimente întregi, somn bun, lumină și mișcare, repetate ani."],"e":[],"c":["6-12 luni urmând un singur sistem","antrenament de câteva ori pe săptămână"]},{"v":"r6TEaKcNtn0","k":"s","t":"Why are you in the gym for 2 hours?","d":"14.05.2026","th":["volum-si-frecventa","program-si-split","mentalitate"],"i":["Nu ai nevoie de 2 ore în sală 5-7 zile; sesiuni de 30 de minute de 3 ori pe săptămână, iar timpul rămas pentru gătit și pregătit mâncarea.","Autorul se antrena 3-4 zile, 30-45 de minute, uneori o oră."],"e":[],"c":["2 ore, 5-7 zile (greșeala)","30 de minute de 3 ori pe săptămână","3-4 zile, 30-45 de minute"]},{"v":"wfGZFGDgoMo","k":"s","t":"Why I stopped wearing lifting belts and wrist straps","d":"13.05.2026","th":[],"i":[],"e":[],"c":[]},{"v":"7Ao2ofppMso","k":"s","t":"Scared to Go to the Gym? Watch This","d":"10.05.2026","th":["mentalitate","incepatori"],"i":["La sală, cei mai mulți cred că toți se uită la ei, dar în realitate nu îi pasă nimănui; nu te compara cu cineva aflat la capitolul 10.","Încrederea vine din expunere repetată, nu din evitare; nu aștepta să te simți pregătit, începe din starea în care ești."],"e":[],"c":[]},{"v":"Kq_izQSg7RY","k":"l","t":"Brad Pitt’s Fight Club Physique Would Be Called Small Today","d":"09.05.2026","th":["masa-musculara","slabit","program-si-split","mentalitate"],"i":["Fizicul din Fight Club (5'11, ~155 lbs) pare mic azi, dar aspectul vine mai ales din grăsime scăzută; mulți sunt mai aproape de el decât cred.","Plan: gândește în proporții și slăbire, nu în masă; 3-4 zile pe săptămână cu mișcări de bază progresive, plus brațe, gât și antebrațe, iar la picioare lucru unilateral.","Progres: devii mai puternic prin repetări și greutate notate într-o aplicație sau pe hârtie, nu ghicind.","În afara sălii: mers zilnic și mai puțin stat; dacă ești supraponderal, pierzi lent grăsime antrenând regulat și mâncând destulă proteină."],"e":[["incline press","mișcare de bază progresivă"],["chest supported row","mișcare de bază progresivă"],["wide grip lat pull","mișcare de bază progresivă"],["lateral raise","mișcare de bază progresivă"],["Bulgarian split squat / reverse lunge","variante unilaterale pentru picioare"]],"c":["Fight Club: 5'11, ~155 lbs","autorul: 6', 190 lbs, ~11-12% grăsime, peste 10 ani de antrenament","3-4 zile pe săptămână"]},{"v":"QaZJPcC3Ldc","k":"s","t":"how many days a week should you lift?","d":"08.05.2026","th":["volum-si-frecventa","program-si-split","varsta","accidentari-si-articulatii"],"i":["Autorul recomandă 3, maxim 4 zile de antrenament pe săptămână, la orice vârstă; 4 zile doar dacă ești începător și vrei să înveți mișcările.","La tineri sau la cei pe steroizi 5-6 zile par să meargă, dar în timp te toacă și ajungi să faci mai puțin din cauza accidentărilor; sala zilnică poate fi doar rutină."],"e":[],"c":["3, maxim 4 zile pe săptămână","5-6 zile (criticat)"]},{"v":"H-x21NmP1P8","k":"s","t":"Building muscle and strength while on a cut?","d":"07.05.2026","th":["slabit","failure-si-progresie","masa-musculara"],"i":["La definire scopul este să pierzi grăsime și să păstrezi mușchii, nu să bați recorduri; recuperarea și energia scad.","Întrebarea bună e dacă îți menții cea mai mare parte din forță în timp ce slăbești; dacă da, faci bine."],"e":[],"c":[]},{"v":"b9-67vAElkU","k":"s","t":"If you only did these 5 exercises, you'd be jacked","d":"06.05.2026","th":["principii-antrenament","program-si-split"],"i":["Cinci exerciții ar ajunge: bench, deadlift, overhead press, squat și un pull-up, făcute ani la rând.","Variația e bună dacă îți place și ca antrenamentul să nu devină plictisitor."],"e":[["bench press"],["deadlift"],["overhead press"],["squat"],["pull-up"]],"c":["5 exerciții","5 ani"]},{"v":"za5qnUph5Wk","k":"s","t":"You might not feel like working out…","d":"06.05.2026","th":["mentalitate"],"i":["Fă acțiunile în fiecare zi chiar dacă nu ai chef; rezultatele vin din fapte, nu din fixarea pe țintă.","Gândește-te la scop, dar întreabă-te zilnic ce poți face azi, ca un alpinist care se uită la pasul următor."],"e":[],"c":[]},{"v":"HFWyYhnhga8","k":"l","t":"If You Sit Most Of The Day, Watch This","d":"05.05.2026","th":["mobilitate","accidentari-si-articulatii","incepatori","altceva"],"i":["Dacă stai mult, începe cu dead hang zilnic, nu cu o rutină complicată; dimineața, sau la două zile ori de 3 ori pe săptămână dacă ești începător.","Bate timpul precedent (de la 5 secunde la 6 etc.) și țintește pe termen lung un minut; apoi poți adăuga greutate.","Mâinile ard și e normal; oprește setul când cedează priza. Dacă e prea greu, ține picioarele pe sol sau pe un taburet.","Ar trebui să simți un stretch prin umeri și decompresie în coloană; durere ascuțită sau ciupire = nu forța, schimbă priza sau folosește sprijin.","Alternativ, poți aduna 30 de secunde din mai multe seturi scurte."],"e":[["dead hang","un singur set în fiecare dimineață, cât poți; începător 5 secunde, +1 pe zi; ținta un minut; opțional cu greutate după aceea"]],"c":["start ~5 secunde, +1 pe zi","țintă 1 minut","1 set pe zi, sau la două zile ori 3 ori pe săptămână","total combinat 30 de secunde din seturi scurte"]},{"v":"AyqHsxN8z4E","k":"s","t":"Dead Hangs Will Change Your Life","d":"04.05.2026","th":["mobilitate","umeri","spate","antebrate"],"i":["Dead hang-ul decomprimă coloana, deschide umerii și pieptul și îți dezvoltă priza; autorul îl face în fiecare dimineață.","Începătorii pornesc de la 5-10 secunde, adaugă câte o secundă pe zi, cu țintă de un minut continuu; ajută postura, grip-ul și mobilitatea umerilor."],"e":[["dead hang","pe bara de tracțiuni, start de 5-10 secunde, apoi +1 secundă, țintă 1 minut; zilnic sau la două zile"]],"c":["start 5 sau 10 secunde","+1 secundă pe zi","țintă 1 minut"]},{"v":"EcGRYz_fGjA","k":"s","t":"You don’t need the ‘best exercises’ to build muscle","d":"03.05.2026","th":["tehnica","principii-antrenament","picioare"],"i":["Corpul înțelege tipare de mișcare, nu exerciții anume: pentru picioare poți alege squat cu bară, goblet squat, hack squat sau presă.","Alege varianta care ți se potrivește și o poți face fără accidentări, rămâi la ea și devino mai puternic."],"e":[["barbell squat, goblet squat, hack squat, leg press","toate acoperă tiparul de genuflexiune"]],"c":[]},{"v":"_O5Cq06Z0FM","k":"s","t":"Stop watching fitness content","d":"03.05.2026","th":["incepatori","principii-antrenament","mentalitate"],"i":["Ca începător, alege o singură sursă de informație și nu mai consuma restul conținutului.","Cu echipament limitat, 5-10 exerciții repetate un an, cu focus pe progresie, sunt de ajuns."],"e":[],"c":["5-10 exerciții"]},{"v":"nidOZfyTHuY","k":"l","t":"The 1x4 Method - Chest, Shoulders, and Triceps","d":"02.05.2026","th":["piept","umeri","brate","incalzire"],"i":["Ziua 1 la 1x4: press înclinat, fly, ridicări laterale la cablu și pushdown cu bară dreaptă; folosești gantere sau aparat dacă ai alt echipament.","Încălzire: mimezi mișcările cu bandă ușoară (press, curl, hammer, pushdown, pull-apart, fly jos-sus), 10-15 repetări; apoi un set la ~50% și setul de lucru.","La press pauză jos, fără bounce; ridici dintr-o oprire completă și scoți avântul. La laterale cu cablu, stretch bun și mișcare lentă.","Ultima repetare, cea de eșec, e cea care declanșează creșterea; poți adăuga drop set sau rest-pause strategic ca extra, dar nu e obligatoriu.","Progresie simplă: alege o greutate la care cedezi pe la 6 repetări și adaugi una pe antrenament. Metoda nu e pentru începători, care fac 2-3 seturi."],"e":[["incline machine chest press","single arm, un set de încălzire la ~50%, 8-10 repetări; setul de lucru la eșec"],["chest fly machine","un set de încălzire, apoi setul de lucru"],["cable lateral raise","pauză jos; stretch la cablu; un set de încălzire"],["straight bar tricep pushdown","un set de încălzire, apoi setul de lucru; săptămâna trecută 170 lbs x 11, acum greutate mai mare și 6 repetări"]],"c":["1 set de lucru, 4 exerciții","încălzire ~50% (în practică ~60%)","încălzire cu bandă: 10-15 repetări","170 lbs x ~11, apoi greutate mai mare și 6 repetări","5-7 zile între antrenamentele aceleiași grupe","începători: 2-3 seturi"]},{"v":"kh7uKFRGeGg","k":"s","t":"Upper Lower vs Push Pull Legs split","d":"01.05.2026","th":["program-si-split","volum-si-frecventa","mike-mentzer"],"i":["Autorul a trecut de la upper/lower de 4 zile la push/legs/pull de 3 zile; cu recul ar fi rămas la 3 zile, poate chiar la 2 (upper, lower).","Contează principiile, nu frecvența; muschiul se recuperează mai repede decât tendoanele, articulațiile și sistemul nervos, ceea ce duce la accidentări."],"e":[],"c":["4 zile upper/lower, apoi 3 zile push/legs/pull","48 de ore"]},{"v":"VbKD2j2-mNc","k":"s","t":"Why Mike Mentzer is the only bodybuilder I follow","d":"30.04.2026","th":["mike-mentzer","mentalitate"],"i":["Autorul îl urmează pe Mentzer pentru că acesta descuraja steroizii și avea o filozofie clară.","Nu lua sfaturi doar de la cineva musculos: întreabă care e filozofia lui; mulți își datorează rezultatele drogurilor."],"e":[],"c":[]},{"v":"S4S7TGkxxh0","k":"l","t":"How to Get To 10% Body Fat Enjoyably","d":"29.04.2026","th":["slabit","nutritie","cardio-si-pasi","mentalitate"],"i":["Nu forța slăbirea rapidă; gândește ce poți face constant 6 luni într-o viață normală: pași zilnici, 3 antrenamente, mese simple din alimente întregi, apă și somn.","Calitatea mâncării face deficitul mai ușor: alimentele reale (carne, fructe, cartofi, miere, legume) sățiază, iar cele procesate sunt făcute să fie mâncate în exces.","Mersul zilnic e subestimat: după mese, la pauza de prânz, dimineața sau în apeluri; 10-20 de minute adunate ajută și recuperarea.","Schimbările bruște pe toate planurile duc la foame, epuizare și abandon; obiceiurile de ani nu se inversează în câteva săptămâni."],"e":[],"c":["8.000-10.000 de pași pe zi ca exemplu","10-20 de minute de mers pe repriză","3 antrenamente pe săptămână","orizont de 6 luni"]},{"v":"-Oe2CTnFOfE","k":"s","t":"Warming up with 1 set to failure","d":"29.04.2026","th":["incalzire","failure-si-progresie","principii-antrenament"],"i":["Seturile de încălzire nu sunt făcute să obosească: servesc să repeți mișcarea, amplitudinea și unghiurile înainte de setul de lucru.","Autorul răspunde criticilor că nu face «un singur set la eșec»: setul de lucru e unul, încălzirea doar pregătește corpul."],"e":[],"c":[]},{"v":"tow9D6MjMR4","k":"s","t":"Why I Stopped Training Like a Bodybuilder","d":"29.04.2026","th":["program-si-split","varsta","mentalitate"],"i":["Autorul antrenează 3 zile (push, picioare, pull), 30-45 de minute, iar în zilele libere rămâne activ cu skateboard, surf și muncă în jurul casei.","În 2026 vrea să fie nu doar mare, ci și funcțional, ca să poată alerga, sări și face sprint pe măsură ce îmbătrânește."],"e":[],"c":["3 zile pe săptămână","30-45 de minute pe antrenament"]},{"v":"ihREYURzyTA","k":"s","t":"30 Min Dumbbell Only Workout Routine","d":"28.04.2026","th":["sala-acasa","program-si-split","failure-si-progresie"],"i":["Split push/legs/pull doar cu gantere, 3 zile, 2-3 seturi pe mișcare, pauză 1-2 minute; adaugă o repetare față de data trecută.","Când toate seturile ajung la 10 repetări, adaugă ~5 lbs (2,5 kg) și revino la 6."],"e":[["incline dumbbell press"],["incline dumbbell fly"],["seated dumbbell shoulder press"],["dumbbell lateral raises"],["overhead dumbbell tricep extensions"],["goblet squat"],["Bulgarian split squats"],["Romanian deadlift"],["calf raises"],["hanging knee raises"],["pull-ups","bară de ușă, ~15-20 USD"],["one arm dumbbell row"],["rear delt dumbbell fly"],["incline curls"],["hammer curls"]],"c":["3 zile","2-3 seturi","pauză 1-2 minute","6-10 repetări","+5 lbs sau 2,5 kg","bară de pull-up 15-20 USD"]},{"v":"tNeB_nycTvg","k":"s","t":"Stop trying to gain muscle and strength when cutting","d":"28.04.2026","th":["slabit","failure-si-progresie","mentalitate"],"i":["La tăiere ai un singur scop, pierderea în greutate; nu încerca în același timp volum mai mare, forță și masă.","E normal să nu bați recorduri pe deficit; câștigul e să-ți menții forța. Dacă pierzi forță, deficitul e probabil prea mare."],"e":[],"c":[]},{"v":"wLxBXNVa3hg","k":"s","t":"Morning pull-ups on the DIY pull up bar 💪","d":"27.04.2026","th":[],"i":[],"e":[],"c":[]},{"v":"0YP727tA_eQ","k":"s","t":"How to stay lean while bulking?","d":"26.04.2026","th":["masa-musculara","nutritie","slabit"],"i":["La bulking, dacă te îngrași prea repede, ai crescut caloriile prea mult; nu adăuga mese de fast food și sute de kcal în plus.","Mănâncă aceleași alimente și mărește doar porțiile unora; dacă greutatea crește vizibil de la o zi la alta, câștigi prea repede."],"e":[],"c":["+2.000 calorii (dat ca exemplu greșit)"]},{"v":"jgtmPL1zGEo","k":"s","t":"Is 1x a week per muscle group enough?","d":"26.04.2026","th":["volum-si-frecventa","program-si-split","accidentari-si-articulatii"],"i":["Autorul spune că a construit fizicul și la 2 ori pe săptămână, dar nu însemna că făcea bine; părere proprie, fără cercetări.","Preferă 2-3 zile pe săptămână push/legs/pull la failure, cardio în zilele libere, sprinturi și mișcare; tendoanele și sistemul nervos contează."],"e":[],"c":["2-3 zile pe săptămână","10 ani"]},{"v":"FdqsrOh-4_4","k":"l","t":"The 1x4 Method (The Simplest Workout Program to Get Jacked)","d":"25.04.2026","th":["program-si-split","failure-si-progresie","principii-antrenament","volum-si-frecventa"],"i":["1x4: un set la eșec pe 4 exerciții, 3 zile pe săptămână plus o zi opțională; pentru cine știe bazele și poate merge în siguranță la eșec, nu pentru începători.","Fiecare exercițiu are un set de încălzire la 50% din greutatea de lucru și un set de lucru la eșec cu formă bună; contează tiparul de mișcare, nu exercițiul exact.","Zilele: piept-umeri-triceps; picioare; spate-biceps; ziua 4 opțională cu gât, antebrațe, abdomen, gambe și un sprint. Poți adăuga o săptămâna 2 cu variante.","Progresie: alege o greutate pentru 6-10 repetări, adaugi una pe săptămână, iar la 10 crești greutatea și cobori la capătul de jos.","Ziua 4: ~15 minute de încălzire (lungeuri, sărituri), 3 sprinturi de rampă, apoi un sprint maxim de ~15 secunde."],"e":[["incline dumbbell press","ziua 1, apoi fly"],["chest fly","ziua 1"],["cable lateral raise","ziua 1"],["cable pushdown cu bară dreaptă","ziua 1"],["leg press","ziua 2"],["Romanian deadlift (trap bar)","ziua 2"],["leg extension","ziua 2"],["leg curl","ziua 2"],["wide grip lat pulldown","ziua 3"],["chest supported row","ziua 3"],["rear delt fly","ziua 3"],["incline dumbbell curl","ziua 3"],["neck curl","ziua 4; fără greutate la început, apoi +5 lbs odată; prosop pliat pe frunte"],["wrist roller","ziua 4"],["cable crunch","ziua 4"],["calf raise","ziua 4; la leg press sau Smith machine"]],"c":["1 set de lucru, 4 exerciții","3 zile pe săptămână plus ziua 4 opțională","1 set de încălzire la 50% din greutatea de lucru","6-10 repetări","+5 lbs la gât odată","sprint total ~15 secunde, încălzire ~15 minute"]},{"v":"i7gUsDY6qvA","k":"s","t":"If you want to get jacked, do the boring work","d":"24.04.2026","th":["mentalitate","principii-antrenament"],"i":["Programul plictisitor și repetitiv, cu aceleași exerciții și greutăți, dă rezultate dacă îi dai destul timp; efectul se adună în timp."],"e":[],"c":[]},{"v":"94GwBmWR8ZQ","k":"s","t":"My \"extreme\" way of eating to stay lean, healthy, and jacked.","d":"21.04.2026","th":["nutritie","mentalitate"],"i":["Autorul mănâncă aproape numai alimente întregi (vită, fructe, legume), fără procesate și fără cheat meals; spune că te satură mai bine și reduc poftele.","Susține că zahărul în cantități mari duce la inflamație, ceață mentală, anxietate și energie scăzută; e convingerea lui."],"e":[],"c":[]},{"v":"BRYiAn5SoyU","k":"s","t":"Every workout you do is a down payment on an easier life later","d":"20.04.2026","th":["mentalitate"],"i":["Gândește-te în avans: cum vei arăta peste 3 sau 5 ani dacă nu faci acțiunile zilnice pe care le știi.","Autorul spune că fiecare antrenament e un avans pentru o viață mai ușoară mai târziu."],"e":[],"c":["3 ani, 5 ani"]},{"v":"VKhiEDYrfME","k":"s","t":"Sprinting will change your life","d":"19.04.2026","th":["cardio-si-pasi","incalzire","accidentari-si-articulatii"],"i":["Sprintul se introduce treptat: 1-2 săptămâni de mers rapid, apoi jogging ușor, apoi seturi progresive de la 25% la 85% efort; din prima zi la maxim riști o ruptură.","Rutina: mers 10-15 minute, încălzire dinamică, rampe la 25/50/75%, pauză 2-3 minute, sprinturi, cooldown 5-10 minute; o sesiune pe săptămână."],"e":[["sprint","rampă la 25%, 50%, 75% efort, apoi sprinturi cu pauză de 2-3 minute"],["butt kicks"],["high knees"],["lunges"],["reverse lunges"],["skips for height"],["skips for distance"]],"c":["20-30 minute mers","2-3 sesiuni jogging pe săptămână","20-30 minute jogging","25%, 50%, 75%, 85% efort","pauză 2-3 minute","cooldown 5-10 minute","o sesiune pe săptămână"]},{"v":"OjH9KRPmHCE","k":"s","t":"1 Set To Failure Explained","d":"18.04.2026","th":["failure-si-progresie","volum-si-frecventa","mike-mentzer","principii-antrenament"],"i":["Un set la eșec înseamnă un set de lucru pe exercițiu, nu un set pe antrenament: circa 4-5 exerciții pe sesiune, de regulă 2 pe grupă.","Alege greutatea ca eșecul să vină între 6 și 10 repetări; la 15-20 e prea ușoară. Eșecul e când nu mai finalizezi corect o repetare; partea grea e mintală."],"e":[],"c":["un an de experiment","4-5 exerciții pe sesiune","2 exerciții pe grupă","6-10 repetări","15-20 repetări = prea ușor"]},{"v":"c98R5tp7vzE","k":"l","t":"The problem with full body workouts...","d":"16.04.2026","th":["program-si-split","accidentari-si-articulatii","volum-si-frecventa","failure-si-progresie"],"i":["A părăsit full body (spune că funcționează): sistemul nervos, articulațiile și tendoanele se recuperează mai lent decât mușchiul, iar antrenatul frecvent poate da dureri.","Dacă ai dureri la antrenament (cot, umăr, lombar), e semn că ceva nu e în regulă; nu continua forțat de teama de a pierde mușchi.","Vechii culturiști aveau o viață aranjată pentru recuperare; cu un job full-time și stres ai nevoie de mai puțin.","Full body cere gestionarea oboselii (ce prioritizezi, intensitate variată); autorul preferă să lovească o grupă pe săptămână și să urmărească doar o repetare în plus.","Când atingi vârful intervalului, cobori repetările și adaugi puțină greutate; la câteva luni face o săptămână de deload."],"e":[],"c":["2-3 zile pe săptămână, 30-45 minute","split push/pull/legs de 3 zile","1 dată pe săptămână per grupă","deload la câteva luni"]},{"v":"MKVN0MWo1q0","k":"s","t":"How to build the GREEK GOD physique step by step","d":"15.04.2026","th":["slabit","masa-musculara","nutritie","program-si-split"],"i":["Faza 1: ajungi la 10-12% grăsime (alimente întregi, deficit de 300-500 kcal, 2-3 plimbări de 45 min). Faza 2: construiești V-taper, piept sus, gât, antebrațe, abdomen.","Faza 3: surplus controlat de 200-300 kcal peste întreținere, până la ~15% grăsime, apoi reiei faza 1; autorul antrenează fiecare mușchi o dată pe săptămână."],"e":[],"c":["10-12% grăsime","deficit 300-500 kcal","2-3 plimbări de 45 minute pe săptămână","surplus 200-300 kcal","pas la ~15% grăsime","3 zile pe săptămână"]},{"v":"qEcFYwynvGs","k":"s","t":"How to pick your starting weight as a beginner lifter","d":"15.04.2026","th":["incepatori","tehnica"],"i":["Ca începător alege cea mai ușoară greutate (de ex. gantere de 5-10 lbs la incline press), exersează și urcă data viitoare până ajungi la 6-10 repetări.","Dacă ai ales greșit greutatea, mergi la failure și ajustezi data viitoare, nu te oprești la un număr arbitrar."],"e":[["incline dumbbell press","începători: gantere de 5 sau 10 lbs, apoi 15 lbs"],["chest fly","exemplu: țintă 8-12, mergi la failure"]],"c":["gantere de 5-10 lbs","15 lbs","6-10 repetări","8-12 repetări"]},{"v":"L-UIadt2VJU","k":"l","t":"If You’re Still Not Lean After Years… Here’s Why","d":"13.04.2026","th":["slabit","nutritie","mentalitate","altceva"],"i":["Legea de bază: dacă greutatea nu scade în timp, nu ești în deficit real; nu contează rutina, calitatea mâncării sau anii de sală.","Start: greutatea în lbs x 10 = calorii pe zi; urmărești tot într-o aplicație (inclusiv uleiul), te cântărești zilnic dimineața 14 zile și compari media săptămânală.","Dacă media nu scade, tai 100 kcal; ținta e ~1 lb pe săptămână, iar dacă pierzi mai multe lbs pe săptămână după câteva săptămâni, adaugă 100 kcal.","Pentru 5'11 natural, greutatea ideală pentru un fizic slab dar musculos e cam 180-190 lbs; cel care a comentat probabil își subestimează grăsimea."],"e":[],"c":["calorii de start: greutatea în lbs x 10 (ex. 240 lbs -> 2.400 kcal)","cântărire zilnică 14 zile","-100 kcal dacă media nu scade","ținta ~1 lb pe săptămână","5'11: ideal 180-190 lbs"]},{"v":"k7dliBm4QGQ","k":"s","t":"My 10% body fat diet (simple)","d":"12.04.2026","th":["nutritie","slabit"],"i":["Exemplu de zi pentru ~10% grăsime: preworkout cu 150 mg cafeină și miere, apoi lapte cu proteină, smoothie, burgeri de vită, pui, orez, avocado și cartofi.","Ia-l ca model personal: ajustează porțiile după înălțime, greutate, activitate și țel."],"e":[],"c":["~10% grăsime","150 mg cafeină","1-2 linguri miere","10-12 oz lapte","10 oz lapte de cocos","2 hamburgeri de 4 oz 80/20"]},{"v":"fxZpOw-UAuU","k":"s","t":"This will save you years of wasted time in the gym","d":"11.04.2026","th":["principii-antrenament","recuperare-si-somn","mentalitate"],"i":["Cinci lecții: planifică, ține jurnal, gândește pe tipare de mișcare și nu schimba des exercițiile, recuperarea e individuală, compară-te doar cu antrenamentul tău trecut.","Mai mult nu e mereu mai bine; autorul a progresat trecând de la 6 la 3 zile pe săptămână."],"e":[],"c":["peste 10 ani de antrenament","peste 1.000 de antrenamente","de la 6 la 3 zile"]},{"v":"rFNPSQCBc9o","k":"l","t":"Dumbbell Only Workout To Get Jacked (Simple)","d":"09.04.2026","th":["sala-acasa","program-si-split","failure-si-progresie","volum-si-frecventa"],"i":["Cu doar gantere poți construi mușchi: push/legs/pull în 3 zile (luni, miercuri, vineri), cu zile libere active și mers de 30-45 minute.","Pentru majoritate, 2-3 seturi pe mișcare și pauze de 1-2 minute; autorul face un set la eșec, dar îl recomandă doar intermediarilor și avansaților.","Prima sesiune: ajungi la 6 repetări cu două în rezervă, ca să înveți mișcarea; nu începe prea greu din ego.","Progresie: bate data trecută cu o repetare pe set; la vârful intervalului (ex. 10) adaugi ~5 lbs (2,5 kg) și cobori la 6; cu gantere ușoare folosești 15-20+."],"e":[["incline dumbbell press","ziua push"],["incline dumbbell fly","ziua push"],["seated dumbbell shoulder press","ziua push"],["dumbbell lateral raise","ziua push"],["overhead dumbbell tricep extension","ziua push"],["goblet squat","ziua de picioare"],["Bulgarian split squat","ziua de picioare"],["Romanian deadlift","ziua de picioare"],["calf raise","ziua de picioare"],["hanging knee raise","ziua de picioare"],["pull-up","cu bară de ușă de ~15-20 dolari"],["one arm dumbbell row","ziua pull"],["rear delt dumbbell fly","ziua pull"],["incline curl","ziua pull"],["hammer curl","ziua pull"]],"c":["3 zile pe săptămână","2-3 seturi pe mișcare","pauze 1-2 minute","interval 6-10 repetări, sau 15-20+ cu gantere ușoare","+5 lbs sau 2,5 kg","mers 30-45 minute","bară de ușă ~15-20 dolari"]},{"v":"QcZBrIibXo8","k":"s","t":"If your goal is to get jacked, watch this video","d":"09.04.2026","th":["failure-si-progresie","principii-antrenament","program-si-split"],"i":["Nu ai nevoie de rutină nouă, ci să devii mai puternic la exercițiile pe care le faci deja; cei mai musculoși sunt de obicei puternici.","Mușchiul se construiește mai ales prin tensiune mecanică, care crește cu greutatea; rămâi ani la același split și aceleași mișcări."],"e":[],"c":["peste 10 ani de antrenament"]},{"v":"0224JKaK8Xc","k":"s","t":"Simple Leg Workout (Only 4 Exercises)","d":"08.04.2026","th":[],"i":[],"e":[],"c":[]},{"v":"euJsP8OG8FY","k":"s","t":"Is one set to failure enough to build muscle?","d":"08.04.2026","th":["volum-si-frecventa","failure-si-progresie","piept"],"i":["Un set la failure ajunge pentru stimulul de creștere; folosește mai multe exerciții doar ca să acoperi toate zonele mușchiului.","La piept: o variantă incline și o fluturare, ambele la failure; mai multe seturi doar te țin mai mult pentru același rezultat."],"e":[["incline press","un set la failure"],["fly","un set la failure"]],"c":["6 repetări","1 set la failure"]},{"v":"_cMhbaTY1bM","k":"s","t":"Simple Push Workout (Only 4 Exercises)","d":"07.04.2026","th":[],"i":[],"e":[],"c":[]},{"v":"ExeJX2Ds2E8","k":"s","t":"Healthy kitchen swaps to get you jacked","d":"06.04.2026","th":["nutritie","altceva"],"i":["Autorul gătește în fontă și inox și folosește sticlă (borcane) și paie din inox, din cauza microplasticelor.","Dacă începi să gătești acasă din alimente întregi, merită o tigaie bună, pentru că o folosești zilnic."],"e":[],"c":[]},{"v":"4Ho5_GLpgaE","k":"l","t":"The Most Overlooked Exercise to Get Jacked","d":"05.04.2026","th":["cardio-si-pasi","incalzire","accidentari-si-articulatii","varsta"],"i":["Dacă ești sedentar de ani, nu sprinta la efort maxim din prima zi: riști o ruptură de hamstring. Construiește baza în faze, în 3-4 săptămâni.","Faza 1: mers rapid zilnic; faza 2: alergare ușoară la un ritm la care poți vorbi; faza 3: serii progresive, accelerând treptat din mișcare.","Sesiunea de sprint începe cu mers, încălzire dinamică și serii de pregătire la efort crescător, apoi o pauză lungă înainte de primul sprint.","Autorul pornește din jogging ușor și accelerează la maxim, nu din start de pe loc; a urcat de la 1 la 3 sprinturi și vrea să ajungă la 5, apoi doar să le facă mai rapide.","Un sprint pe săptămână ajunge, fiindcă solicită sistemul nervos, mai ales dacă ridici deja greutăți; lasă 5-6 zile între sesiuni, apoi mers de răcire."],"e":[["sprints","ramping sets la 25%, 50%, 75% efort, apoi sprinturi la maxim; până la 5 serii de lucru"],["butt kicks, high knees, lunges, reverse lunges, skips, hops","încălzire dinamică, una după alta, odihnă doar dacă e nevoie"],["brisk walking","20-30 minute zilnic în faza 1"],["light jogging","2-3 sesiuni pe săptămână, 20-30 minute, ritm de conversație"]],"c":["Faza 1: 1-2 săptămâni, 20-30 min de mers zilnic","Faza 2: 2-3 sesiuni/săptămână, 20-30 min jogging","Total faze: 3-4 săptămâni","Ramping: 25%, 50%, 75%, uneori 85% efort","Mers înainte de sprint: 10-15 min","Pauză înainte de primul sprint: 2-3 min","Obiectiv: 5 serii de sprint","Un sprint pe săptămână, 5-6 zile între sesiuni","Mers de răcire: 5-10 min","Autorul ridică greutăți 3-4 zile pe săptămână"]},{"v":"DelpEXC3xvQ","k":"s","t":"Why I don't workout 6 days a week","d":"03.04.2026","th":["volum-si-frecventa","accidentari-si-articulatii","varsta"],"i":["Antrenamentul 6 zile pe săptămână nu e necesar în 99% din cazuri și e aproape mereu contraproductiv; ce merge la 16-20 de ani te ajunge la 25-30+.","Dureri de umăr sau lombare și recuperare mai slabă apar după ani de volum mare; autorul avertizează să nu continui să forțezi fără să schimbi nimic."],"e":[],"c":["6 zile pe săptămână (criticat)","10 ani de antrenament"]},{"v":"fKxZnzT62mU","k":"s","t":"Don't worry about rep tempo","d":"03.04.2026","th":["tehnica"],"i":["Nu te complica cu tempoul: formă bună, lent și controlat, întindere completă sus și coborâre explozivă.","Nu numără secunde; întreabă-te dacă fiecare repetare a fost cât de bună ai putut."],"e":[],"c":[]},{"v":"UWqmz_mmVP0","k":"l","t":"My Simple Diet To Stay 10% Body Fat Year Round","d":"02.04.2026","th":["nutritie","slabit","suplimente"],"i":["Autorul mănâncă mai ales alimente întregi (carne de vită, fructe, legume), fără dulciuri procesate și fără mese libere; spune că sățiază mai bine decât junk food-ul.","Mănâncă aproape aceleași mese zilnic și le consideră o schemă personală: porțiile trebuie ajustate la înălțime, greutate, activitate și obiectiv.","Înainte de antrenament ia un pre-workout curat cu cofeină și puțină miere; în zilele de odihnă sare mierea și stă pe stomacul gol.","Pudra proteică o folosește doar ca să atingă mai ușor ținta de proteină; spune că nu e necesară și că se poate crește muscular și doar din mâncare.","Verifică etichetele sosurilor, de exemplu ketchupul, pentru zahăr adăugat și arome artificiale; dieta singură nu face fizicul, trebuie și antrenament structurat."],"e":[],"c":["Trezire în jur de 4:00","Pre-workout cu aproximativ 150 mg cofeină și 1-2 linguri de miere, cu 30 min înainte","Lapte integral 10-12 oz după antrenament, cu o măsură de proteină","Mic dejun în jur de 9:00","Smoothie: 10 oz lapte de cocos, 3 curmale, 1 lingură unt de migdale, 2 linguri de miere","Două burgeri de vită de 4 oz, 80/20","Peste 60 g zahăr adăugat în vechiul mic dejun (gogoși, lapte cu ciocolată, energizant)","Aproximativ 10% grăsime corporală tot anul","Smoothie băut zilnic de peste 4 ani"]},{"v":"Uyc3ckbLcaI","k":"s","t":"Here’s what I do on rest days","d":"02.04.2026","th":["cardio-si-pasi","recuperare-si-somn"],"i":["În zilele de pauză rămâi activ: mers lung și 10.000 de pași, uneori skateboard, surf sau drumeție; contează mișcarea, nu un protocol de cardio.","O dată pe săptămână face ceva mai intens (sprinturi), uneori și câteva jogging-uri zona 2 de 45 de minute."],"e":[["sprint session","o dată pe săptămână"],["zone 2 jog","45 de minute, de câteva ori în unele săptămâni"]],"c":["10.000 de pași pe zi","45 de minute zona 2","o sesiune intensă pe săptămână"]},{"v":"-AUq2yVc-0Q","k":"s","t":"Why I think Push, Legs, Pull Split 3x a Week Is Best","d":"01.04.2026","th":["program-si-split","volum-si-frecventa","recuperare-si-somn"],"i":["Autorul preferă push-legs-pull de 3 ori pe săptămână față de push-pull-legs, pentru că între zilele de partea superioară intercalezi o zi de picioare.","Astfel are mai multă recuperare: după ziua de pull urmează două zile libere complete înainte de a relua ciclul."],"e":[],"c":["3 zile pe săptămână","2 zile de odihnă după ultimul antrenament"]},{"v":"4IutvZTTBmQ","k":"s","t":"This PULL workout will get you Jacked!","d":"31.03.2026","th":["spate","brate","umeri","program-si-split"],"i":["Ziua de pull: lat pulldown cu priză largă (lățime), chest-supported T-bar row (grosime), rear delt fly, incline dumbbell curl și hammer curls.","Controlează greutatea, nu te preocupa de tempo sau negative numărate; rear delts directe ajută la prevenirea accidentărilor de umăr la cei care presează mult."],"e":[["wide grip lat pulldown","pentru lățimea spatelui, cu formă controlată"],["chest supported T-bar row","pentru grosime, fără a limita picioarele sau lombarele"],["rear delt fly / reverse pec deck","umeri posteriori"],["incline dumbbell curl","bicepsul în poziție de întindere"],["hammer curls","pentru antebrațe și grosimea brațului"]],"c":[]},{"v":"089tcB2iEbs","k":"s","t":"1 set to failure is all you need!","d":"30.03.2026","th":["volum-si-frecventa","failure-si-progresie","mike-mentzer"],"i":["Trecerea de la un set la două înseamnă 100% mai mult volum, iar asta consumă și din capacitatea de recuperare.","Chiar dacă al doilea set ar aduce un stimul în plus, creșterea de volum l-ar anula prin încărcarea recuperării (argument în stil Mentzer)."],"e":[],"c":["de la 1 la 2 seturi = +100% volum"]},{"v":"ULe39j3WZ48","k":"s","t":"This advice will help you get jacked","d":"30.03.2026","th":["mentalitate"],"i":["Stabilește ce e non-negociabil pentru ziua respectivă, fă-le și înșiră zilele; consecvența bate „hack-urile” și gratificarea instantanee."],"e":[],"c":[]},{"v":"to86cyUmoYE","k":"s","t":"Stop trying to get jacked fast","d":"30.03.2026","th":["mentalitate","incepatori"],"i":["Mulți subestimează cât durează să construiești masă vizibilă; primul an e în mare parte învățarea tehnicii și a constanței.","După 6 luni în sală ești tot la început; fizicurile impresionante se construiesc în ani."],"e":[],"c":["6 luni = încă început","primul an: tehnică și constanță"]},{"v":"p3vf2rpAjng","k":"l","t":"The Exact 3-Step Plan To Get The Greek God Physique","d":"27.03.2026","th":["masa-musculara","slabit","umeri","incepatori"],"i":["Primul pas pentru aspectul atletic e să slăbești destul cât să se vadă mușchii; fără asta, un an de sală poate să arate aproape la fel.","Țintă pentru majoritatea bărbaților: 10-12% grăsime corporală, cu mâncare reală, 3-4 mese pe zi, deficit moderat și 2-3 plimbări rapide pe săptămână.","Aspectul se construiește prin umeri largi, spate lat, piept superior, gât, antebrațe și abdomen; autorul antrenează fiecare grupă o dată pe săptămână.","După slăbire, urmează un surplus mic și controlat, ca să crești mușchi fără să te îngrași; apoi repeți ciclul când ajungi la aproximativ 15% grăsime.","Antrenamentul dă semnalul de creștere, iar mâncarea e materialul: antrenat din greu dar mâncând prea puțin, nu progresezi."],"e":[["cable lateral raises","pentru umeri"],["reverse pec deck","pentru deltoizii posteriori"],["wide grip lat pulldowns","pentru lățimea spatelui"],["T-bar rows","pentru grosimea spatelui"],["seated cable rows","pentru grosimea spatelui"],["incline press","la mașină, cu gantere sau cu bara; prioritate pentru pieptul superior"],["pec deck","variație pentru piept"],["cable fly","variație pentru piept"],["neck curl","cu un disc"],["wrist roller","pentru antebrațe"],["cable crunches","cu coarda; singurul exercițiu de abdomen al autorului"]],"c":["Țintă 10-12% grăsime corporală","Deficit de 300-500 calorii sub menținere","3-4 mese echilibrate pe zi","2-3 plimbări rapide de 45 min pe săptămână","Surplus de 200-300 calorii peste menținere","Revenire la faza de slăbire la aproximativ 15% grăsime","Split push/pull/legs, 3 zile pe săptămână, fiecare grupă o dată pe săptămână"]},{"v":"6zbpkUno5bo","k":"s","t":"This One Thing Decides If You Get Jacked","d":"26.03.2026","th":["failure-si-progresie","principii-antrenament"],"i":["Notează-ți antrenamentele: majoritatea oamenilor nu țin minte ce au făcut data trecută și intră în sală fără plan.","O singură repetare în plus, adunată în timp, decide dacă progresezi; fără notițe nu știi dacă ai făcut 7 sau 8."],"e":[],"c":[]},{"v":"BdNOtap177A","k":"s","t":"Why I don't have cheat meals or cheat days","d":"26.03.2026","th":["nutritie","mentalitate"],"i":["Autorul nu mai face cheat meals sau cheat days: după ce și-a schimbat complet dieta, nu mai are poftă de ele.","Spune că un cheat meal îi strică digestia și îi dă ceață mentală a doua zi, deci nu merită."],"e":[],"c":[]},{"v":"1a8cYxByZOo","k":"s","t":"Best Workout Split For a Beginner?","d":"25.03.2026","th":["incepatori","program-si-split","failure-si-progresie","masa-musculara"],"i":["Pentru primul an, autorul recomandă upper/lower de 3-4 zile sau push-legs-pull de 3 zile; mai important decât split-ul sunt consecvența și supraîncărcarea progresivă.","Notează antrenamentele și încearcă să adaugi o repetare sau greutate la fiecare sesiune; dacă ești slab, învață caloriile zilnice și cum faci bulking."],"e":[],"c":["3-4 zile pe săptămână, upper/lower","3 zile pe săptămână, push-legs-pull"]},{"v":"2xMrYnh-1YM","k":"s","t":"1 set to failure is all you need to get jacked?","d":"25.03.2026","th":["failure-si-progresie","volum-si-frecventa","mike-mentzer"],"i":["Un singur set la eșec ajunge, spune autorul, dar nu pentru începători, ci pentru cei din intermediar târziu sau avansat timpuriu.","Dacă împingi la eșec real, un al doilea sau al treilea set nu mai adaugă nimic; e ca un întrerupător care e deja pornit."],"e":[],"c":[]},{"v":"STBdKolVZuA","k":"s","t":"How To Build A Thicker Neck","d":"25.03.2026","th":["gat","tehnica"],"i":["La neck curls autorul nu depășește 45 lbs și face în jur de 30 de repetări.","Începătorii pot lucra cu greutatea corpului până la ~50 de repetări, apoi un disc de 5 lbs, 10 repetări, crescând spre 20-30."],"e":[["neck curls","autorul: ~30 de repetări cu 45 lbs; începători: corp liber până la 50 de repetări, apoi disc de 5 lbs"],["side to sides","50 de repetări cu greutatea corpului"]],"c":["45 lbs maxim","30 de repetări","50 de repetări","disc de 5 lbs, 10 apoi 20-30 repetări"]},{"v":"nJ2pX_KcsHU","k":"s","t":"Mike Mentzer's realest advice on fat loss","d":"23.03.2026","th":["mike-mentzer","slabit","abdomen"],"i":["Mentzer: nu există slăbire localizată; abdomenele nu topesc grăsimea de pe abdomen.","Pierderea de grăsime depinde în principal de calorii: dacă mănânci sub menținere, corpul folosește rezervele."],"e":[["sit-ups","menționat ca ineficient pentru topirea grăsimii"]],"c":[]},{"v":"rz7Thz1M9qY","k":"s","t":"This might be why you haven’t built muscle ￼","d":"23.03.2026","th":["mentalitate","principii-antrenament"],"i":["Cei care fac totul bine, dar nu văd încă schimbare mare, se pierd în detalii (alt split, 5-6 zile, mai multe seturi); de obicei e doar nerăbdare."],"e":[],"c":[]},{"v":"wu12RyDzpsI","k":"l","t":"Beginner's Guide To 1 Set To Failure","d":"22.03.2026","th":["failure-si-progresie","mike-mentzer","volum-si-frecventa","program-si-split"],"i":["Un set de lucru până la cedare pe exercițiu e, după autor, aproape tot stimulul necesar; seturile suplimentare aduc un câștig mic pentru oboseala și timpul în plus.","Nu e recomandat începătorilor, care încă nu știu ce e cedarea; ei fac mai bine 2-3 seturi pe exercițiu și urmăresc forța de la o săptămână la alta.","Cedarea înseamnă că la încercarea unei repetări noi corpul nu o mai termină corect; disconfortul apare înainte, iar partea grea e mintală.","Alege o greutate la care cedezi între 6 și 10 repetări; în prima mișcare faci 3 seturi de încălzire progresive, la următoarele doar unul la 50%.","Progresie: bate repetările sesiunii trecute, fără să forțezi peste țintă; la circa 10 repetări adaugi 5 lbs și cobori la 6. Așa autoreglezi oboseala."],"e":[["chest press","exemplu de set până la cedare, 6-10 repetări"],["fly variation","un set la cedare, alături de o variantă de press pentru piept"]],"c":["Un set de lucru la cedare per exercițiu","Aproximativ 4-5 exerciții pe sesiune","De obicei 2 exerciții pe grupă musculară","Cedare între 6 și 10 repetări, uneori până la 15","Încălzire pe primul exercițiu: 25%, apoi 50-60%, apoi 75-85% din greutatea de lucru","Pauză 1-2 minute după ultima încălzire","La exercițiile următoare: o încălzire la 50%","La aproximativ 10 repetări se adaugă 5 lbs și se revine la 6","Autorul a redus antrenamentele de la 6-7 la 3 zile pe săptămână și face asta de aproape un an"]},{"v":"7hKa-TdBuWE","k":"s","t":"This PUSH Workout Will Get You Jacked","d":"21.03.2026","th":["piept","umeri","brate","incalzire"],"i":["Zi de push: incline dumbbell press (accent pe pieptul de sus), pec deck, cable lateral raises, tricep pushdown cu bară dreaptă sau V; alternezi cu overhead extensions.","Încălzire: 5-10 minute de bandă și 5 minute cu bandă elastică; un set de lucru la eșec, ținta fiind greutate sau o repetare în plus săptămâna viitoare."],"e":[["incline dumbbell press","primul exercițiu al zilei"],["pec deck / chest fly","menține tensiunea pe tot parcursul amplitudinii, până la eșec"],["cable lateral raises","tensiune constantă"],["tricep pushdowns","cu bară dreaptă sau V; săptămâna următoare se alternează cu overhead tricep extensions"]],"c":["5-10 minute treadmill","5 minute bandă elastică","4-5 exerciții, 30-45 minute","un set de lucru la eșec"]},{"v":"D3hIVMR2djg","k":"s","t":"Why I’m doing cheat reps and half reps","d":"20.03.2026","th":["failure-si-progresie","tehnica"],"i":["Autorul a început să facă cheat reps și half reps după repetările curate, ca să epuizeze complet mușchiul.","Numără și notează doar repetările curate; cele trișate sunt extra și nu intră în jurnal."],"e":[],"c":[]},{"v":"uFjxLXzpbUA","k":"s","t":"From ego lifting to longevity","d":"19.03.2026","th":["varsta","mentalitate","accidentari-si-articulatii"],"i":["Cu cât te gândești mai devreme la longevitate, cu atât poți antrena mai mult timp; autorul își schimbă accentul de la 22 la 32 de ani."],"e":[],"c":["22 și 32 de ani"]},{"v":"hEE1FkYMQss","k":"l","t":"I Wasted Years in the Gym Until I Learned This","d":"18.03.2026","th":["principii-antrenament","failure-si-progresie","recuperare-si-somn","mentalitate"],"i":["Mușchiul crește doar când are un motiv: nu te baza pe pompă sau pe senzația zilei, ci pe un plan și pe progres măsurabil de la o sesiune la alta.","Ține un jurnal de antrenament (hârtie sau aplicație), nu doar în minte; dacă greutățile și repetările nu cresc în timp, schimbă programul, somnul sau alimentația.","Nu te teme dacă nu bați un record la fiecare antrenament; contează tendința ascendentă, iar câștigurile rapide de la început se vor încetini.","Corpul răspunde la tipare de mișcare, nu la exerciții anume: genuflexiunea merge cu bară, goblet, hack squat sau leg press. Alege varianta fără durere.","Recuperarea e individuală: nu copia programele influencerilor sau ale celor care folosesc steroizi. Autorul a progresat mai mult trecând de la 6 la 3 zile pe săptămână.","Compară-te doar cu antrenamentul tău anterior; pozele de pe rețele sunt editate și cu lumină bună, iar un fizic bun se face în ani."],"e":[["barbell squat","exemplu de tipar de genuflexiune"],["goblet squat","cu kettlebell, alternativă la genuflexiune"],["hack squat machine","alternativă la genuflexiune"],["leg press","alternativă la genuflexiune"],["bench press","menționat ca nefiind obligatoriu pentru piept"],["deadlift","menționat ca parte din big three, nu obligatoriu"]],"c":["Peste un deceniu de antrenament și peste o mie de antrenamente","Exemplu: 10 repetări cu ganterele de 30 lb săptămâna trecută, 8 în sesiunea următoare, la efort egal, indică recuperare insuficientă","Înainte antrena 6 zile pe săptămână, cu un split pe grupe","Trecere de la 6 la 3 zile pe săptămână"]},{"v":"VW8k13v1DAI","k":"s","t":"Mike Mentzer’s gold advice to Dorian Yates","d":"17.03.2026","th":["mike-mentzer","principii-antrenament"],"i":["Mentzer: contează intensitatea, nu volumul; trebuie întâi semnalul, apoi recuperarea, apoi supracompensarea, în această ordine."],"e":[],"c":[]},{"v":"mDe7PvSZhWg","k":"s","t":"Simple Leg Workout To Get Jacked","d":"17.03.2026","th":[],"i":[],"e":[],"c":[]},{"v":"Zo2oK_kK3v4","k":"s","t":"Should you bulk or cut first?","d":"16.03.2026","th":["slabit","masa-musculara","mentalitate"],"i":["Stabilește-ți mai întâi scopul; de regulă, de la 14% grăsime în sus, taie până la 10-12%, apoi fă lean bulk.","Când adaugi prea multă grăsime, fă un mini cut și repetă ciclul, fără să schimbi direcția la fiecare câteva săptămâni."],"e":[],"c":["peste 14% grăsime","10-12% grăsime"]},{"v":"ZFwDddMSKNA","k":"s","t":"My 3 day workout split to get jacked","d":"15.03.2026","th":["program-si-split","cardio-si-pasi","failure-si-progresie"],"i":["Splitul autorului: duminică push, luni cardio, marți picioare, miercuri cardio, joi pull, vineri sprint, sâmbătă ruck sau drumeție ușoară.","4-5 mișcări pe antrenament, un set de încălzire și un set la failure, 6-15 repetări; sub 45 de minute. Cardio zona 2: jogging sau mers înclinat."],"e":[["zone 2 cardio","jogging sau incline walk, 30-45 minute"]],"c":["4-5 mișcări pe antrenament","1 set la failure","6-15 repetări","sub 45 de minute","30-45 minute zona 2","10 ani de antrenament"]},{"v":"tem5qbLH_yU","k":"s","t":"My simple fitness routine you can follow","d":"14.03.2026","th":["program-si-split","cardio-si-pasi","principii-antrenament"],"i":["Rutină completă în aproximativ 6-7 ore pe săptămână: trei ședințe de forță, un sprint, mersuri zona 2 și o drumeție lungă.","Autorul susține că asta acoperă forța, inima, rezistența și claritatea mentală, adică cam 6% din săptămână."],"e":[["sprint"],["zone 2 walks or jogs"],["hike or ruck"]],"c":["168 de ore pe săptămână","3 ședințe de forță a câte 45 de minute","un sprint de 30 de minute pe săptămână","2-3 mersuri zona 2 de 30-45 de minute","o drumeție de 1-1,5 ore","6-7 ore pe săptămână în total","aproximativ 6% din săptămână"]},{"v":"jSHvhQ8OJJs","k":"l","t":"If You Want To Get Jacked, Get Strong","d":"13.03.2026","th":["principii-antrenament","failure-si-progresie","masa-musculara"],"i":["De cele mai multe ori nu ai nevoie de un program nou, ci să devii mai puternic la exercițiile pe care le faci deja; schimbatul constant de rutine e zgomot.","Mușchiul se construiește mai ales prin tensiune mecanică, iar tensiunea crește cu greutatea; cine ridică ani de zile tot mai mult își schimbă fizicul.","Obiecția că cineva e puternic dar mic nu contrazice regula: și el e mai mare decât înainte să devină puternic, genetica doar diferă de la om la om.","Întreabă-te cât de puternic poți deveni, fără durere, la mișcările pe care le placi: înclinat cu gantere, tracțiuni, leg press sau genuflexiuni, în greutate sau repetări.","Rămâi la același split și aceleași mișcări suficient de mult ca să progresezi la ele, cu dieta în ordine, în loc să cauți trucuri de la influenceri."],"e":[["bench press","exemplu de progres de la 135 la 225 lbs, cu repetări pe pauză"],["pull-ups","exemplu de progres de la 5 la 20 de repetări cu greutatea corpului"],["incline dumbbell press","exemplu: de la gantere de 50 la 90"],["leg press"],["squats"],["curls","menționat ca exercițiu la care se adaugă greutate în timp"],["lateral raises","menționat ca exercițiu la care se adaugă greutate în timp"]],"c":["Peste 10 ani de ridicat greutăți","Exemplu: bench de la 135 la 225 lbs","Exemplu: de la 5 la 20 de tracțiuni","Exemplu: ganterele de la 50 la 90","Autorul are 32 de ani"]},{"v":"84JfCstu7vs","k":"s","t":"Mike Mentzer - 3 reasons why you’re not building muscle","d":"13.03.2026","th":["mike-mentzer","principii-antrenament","volum-si-frecventa"],"i":["Dacă nu progresezi, încalci un principiu al antrenamentului de înaltă intensitate (citat din Mentzer): intensitate mică, prea multe seturi sau prea multe antrenamente.","Antrenamentele trebuie să fie scurte și rare, ca să lase corpul să producă creșterea stimulată."],"e":[],"c":[]},{"v":"CtkJwe5K3YY","k":"s","t":"Copy This EXACT Pull Workout To Get Jacked","d":"13.03.2026","th":[],"i":[],"e":[],"c":[]},{"v":"PzSoRFzZvps","k":"s","t":"Will you lose muscle if you get sick?","d":"12.03.2026","th":["recuperare-si-somn","masa-musculara","accidentari-si-articulatii"],"i":["Mușchiul nu se pierde în câteva zile sau 2 săptămâni; pierderea vizibilă apare după circa 3 săptămâni de inactivitate completă.","Revino ușor: la prima sau a doua sesiune scade intensitatea, fără record personal; după pauze mai lungi, poți coborî la jumătate din greutate și reveni într-o lună."],"e":[],"c":["circa 3 săptămâni până la pierdere de mușchi","jumătate din greutate după pauză lungă","o săptămână de revenire"]},{"v":"Hv1-LP17xcI","k":"l","t":"My Simple Grocery List to Stay Lean and Jacked","d":"11.03.2026","th":["nutritie","masa-musculara","suplimente"],"i":["Autorul își bazează mesele pe lapte integral, carne de vită și pui, fructe, legume, cartofi, orez și avocado, cu puține condimente simple.","Citește etichetele: laptele de cocos, cârnații, ketchupul și bulionul pot ascunde gume, zaharuri sau aditivi; bulionul trebuie să fie de oase, nu apă aromată.","Spune că mâncarea de calitate costă mai mult, dar o vede ca investiție în sănătate; propune să muți bani de la lucruri inutile spre mâncare bună.","Nu se teme de fructe și susține o dietă echilibrată cu legume, fructe, carne de calitate și grăsimi sănătoase, nu extreme precum keto, carnivore sau vegan.","Preferă produse organice ca să reducă pesticidele (preferință personală) și poate mânca burger sau cartofi, dar fără ingrediente de umplutură."],"e":[],"c":["Aproximativ 5 lbs de carne tocată 80/20 la 4-5 zile, adică circa 1 lb pe zi","O ceașcă de bulion de oase are 8 g proteină","3/4 sau 1 ceașcă de bulion la 180 g orez uscat","Ribeye o dată pe săptămână","Aproximativ 6 condimente folosite","Pudra proteică costă aproximativ 60 de dolari"]},{"v":"hgGkEi8Otho","k":"s","t":"You don't have to live in the gym to get Jacked","d":"11.03.2026","th":["mentalitate","recuperare-si-somn"],"i":["Nu trebuie să trăiești în sală: un program complet pentru toți indicatorii de sănătate înseamnă cam 6% din săptămână.","Miza e să trăiești sănătos până târziu, nu să ajungi gras și bolnav, cu medicamente."],"e":[],"c":["6% din săptămână"]},{"v":"ClJzeSnf76Y","k":"s","t":"The Gym Won’t Make You Lean?","d":"10.03.2026","th":["slabit","nutritie","cardio-si-pasi","masa-musculara"],"i":["Sala nu e instrumentul principal de slăbit: repetări multe, pauze scurte și drop sets nu ard grăsime mai bine; slăbitul se face în afara ei.","Deficit caloric, mâncare întreagă și 8.000-10.000 de pași pe zi contează mai mult decât intervalul de repetări; în sală construiești mușchi."],"e":[],"c":["8.000-10.000 de pași pe zi"]},{"v":"hffnQfY2fUQ","k":"s","t":"Copy This Exact PUSH Workout To Get Jacked!","d":"09.03.2026","th":[],"i":[],"e":[],"c":[]},{"v":"sNGEvHVAzWE","k":"s","t":"Mike Mentzer could’ve done more sets…","d":"08.03.2026","th":["mike-mentzer","failure-si-progresie","volum-si-frecventa"],"i":["Argumentul „un set la eșec merge doar cu steroizi” nu invalidează metoda: steroizii cresc recuperarea, deci acei sportivi puteau face mai mult volum, dar au ales puțin.","Pentru cei fără ajutor chimic, recuperarea e mai mică, deci principiul intensității mari și volumului mic contează și mai mult."],"e":[],"c":["un set la eșec, cu aproximativ 80% mai puțin volum decât concurenții (după autor)"]},{"v":"cBriDXhva_M","k":"l","t":"30 Min Pull Workout To Get Jacked","d":"07.03.2026","th":["spate","brate","umeri","program-si-split"],"i":["Ziua de spate în 30-45 de minute: o tragere verticală, una orizontală, deltoid posterior și biceps; contează progresia, nu oboseala.","Primul exercițiu primește seturi progresive de încălzire (de exemplu bara goală, apoi 95 și 115 lbs pentru o lucrare de 135); dacă obosești la încălzire, ai exagerat.","După primul exercițiu: o încălzire și un set de lucru la cedare, cu circa 2 minute pauză; începătorii fac 2-3 seturi, fiindcă încă nu știu ce e cedarea.","Rear delts și face pulls pot preveni multe probleme de umăr la cei care apasă mult; lucrul direct pe deltoidul posterior ține umerii sănătoși și dă aspect 3D.","Pentru biceps, curl înclinat pune mușchiul în întindere jos și mărește tensiunea; hammer curl adaugă grosime brațului și lucru pentru antebrațe."],"e":[["wide grip lat pulldowns","se lasă în întindere sus, formă controlată, fără tempo numărat; construiește lățimea spatelui"],["chest supported T-bar row","variantă orizontală pentru grosime, fără să intervină picioarele sau lombarele"],["rear delt flies / reverse pec deck","lucru direct pentru deltoidul posterior"],["incline dumbbell curl","controlat, mușchiul în întindere la capătul de jos"],["hammer curls","pentru grosime și antebrațe"],["face pulls","menționat pentru prevenirea problemelor de umăr"]],"c":["Antrenament de 30-45 minute, de 3 ori pe săptămână","Încălzire cu 5-10 minute de mers și câteva minute cu bandă elastică","Seturi progresive: 45 lbs, 95 lbs, 115 lbs, apoi set de lucru la 135 lbs, 6-10 repetări la încălzire","Un set de lucru la cedare pe exercițiu, 4-5 exerciții","Pauză de aproximativ 2 minute între mișcări","Partea de ridicat durează în jur de 20 de minute","Începătorii: 2-3 seturi pe mișcare","Autorul antrenează 2-3 zile pe săptămână"]},{"v":"7PqA1e8tLXo","k":"s","t":"The Single Greatest Habit You Can Build Is Getting Jacked","d":"05.03.2026","th":["principii-antrenament","incepatori","mentalitate"],"i":["După 10 ani, autorul a revenit la bază: antrenament simplu, dietă simplă și consecvență, după ani de antrenamente aleatorii și sfaturi de la oameni pe steroizi.","El susține că forma fizică este obiceiul cu cea mai bună rentabilitate și că îmbunătățește celelalte aspecte ale vieții."],"e":[],"c":["peste 10 ani de antrenament"]},{"v":"_M6CMqw9PXo","k":"s","t":"Simple advice that will get you jacked","d":"04.03.2026","th":["principii-antrenament","masa-musculara","recuperare-si-somn"],"i":["Mușchiul vine din patru lucruri: antrenament destul de greu, creșterea forței, mâncare suficientă și somn.","Greutatea care te provoacă îi transmite corpului că trebuie să se adapteze."],"e":[],"c":["4 factori"]},{"v":"WWhFU1FCm1I","k":"s","t":"The problem with training to failure","d":"03.03.2026","th":["failure-si-progresie"],"i":["Failure nu e o măsurătoare, e o senzație; poți merge la failure fără să progresezi.","Notează antrenamentele ca să știi dacă devii mai puternic și dacă problema e antrenamentul, somnul sau mâncarea."],"e":[],"c":[]},{"v":"ss0n8IeU87k","k":"l","t":"30 Minute Leg Workout To Get Jacked","d":"02.03.2026","th":["picioare","principii-antrenament","program-si-split","failure-si-progresie"],"i":["Mușchiul se construiește prin calitatea stimulului și prin capacitatea de a te recupera, nu prin ore în sală; mulți influenceri care fac volum mare folosesc steroizi.","Filtrul zilei de picioare: progres la câteva exerciții cheie, un set cu adevărat greu la cedare, apoi ieșit din sală și recuperat.","Leg press îi permite să încarce cvadricepșii greu fără oboseală sistemică în plus; leg extension urmează ca izolare, alternând periodic între un picior și două.","Trap bar deadlift acoperă mișcarea de balans din șold cu mai puțină cerere pe lombare decât deadlift-ul clasic; urmează seated leg curl pentru flexia genunchiului.","Cu un singur set per exercițiu, fiecare set trebuie să conteze; comprimând sesiunea și tăind inutilul, trei zile pe săptămână sunt suficiente."],"e":[["leg press","compus greu pentru cvadricepși, un set la cedare"],["leg extensions","izolare; la 3-4 luni alternează între un picior și două"],["trap bar deadlift","șold în balans, mai puțină cerere pe lombare; alternativ Romanian deadlift cu trap bar"],["seated leg curls","flexie de genunchi pentru ischiogambieri"],["Smith machine calf raises","repetări multe, pe un bloc pentru mai multă amplitudine"],["barbell squat","făcut ani de zile, dar nu mai e folosit acum"],["pendulum squat","menționat ca variantă încercată în trecut"]],"c":["Antrenament de 30-45 minute","5 mișcări pe ziua de picioare","Un set de lucru la cedare pe exercițiu","Trei zile pe săptămână","Peste 10 ani de experiență"]},{"v":"7Di7tWFCHdY","k":"s","t":"Mike Mentzer Was Right","d":"02.03.2026","th":["mike-mentzer","principii-antrenament","volum-si-frecventa","recuperare-si-somn"],"i":["Construcția musculară ține de stimul și recuperare; seturile, exercițiile și split-ul sunt detalii minore (viziunea lui Mentzer, adoptată de autor).","Ca o sămânță: stimulezi cu un set greu, apoi dai timp și nutrienți și n-o scoți a doua zi; mulți se ceartă pe 4 vs 5 seturi și ignoră stimulul."],"e":[],"c":["antrenamente de 6-7 zile pe săptămână, 2 ore, uneori de 2-3 ori pe zi (era lui Arnold)"]},{"v":"B215EX4av-Y","k":"s","t":"Sugar is killing your gains?","d":"02.03.2026","th":["nutritie","mentalitate"],"i":["Pentru dependența de zahăr, privește pe termen lung: cum vei arăta și te vei simți peste 3, 5 sau 10 ani dacă continui.","Autorul leagă zahărul de ceață mentală, anxietate, schimbări de dispoziție și inflamație, și recomandă mâncare plină de micronutrienți."],"e":[],"c":["3, 5, 10 ani"]},{"v":"lqR_eEOSq7g","k":"s","t":"Do you really need supplements?","d":"01.03.2026","th":["suplimente"],"i":["Nicio supliment nu repară dieta proastă, somnul slab sau antrenamentul haotic; autorul crede că 99% din ele sunt exagerate și scumpe.","Atenție la influenceri plătiți cu comision; după el, rezultatele lor vin din steroizi, nu din suplimente."],"e":[],"c":["99% exagerat"]},{"v":"4fWA0Epctbk","k":"l","t":"30 Minute Push Workout to Get Jacked","d":"28.02.2026","th":["piept","program-si-split","volum-si-frecventa","umeri"],"i":["Autorul face push/picioare/pull în 3 zile pe săptămână; mușchiul se reface în 48 de ore, dar tendoanele, articulațiile și sistemul nervos, spune el, nu.","Spune că mai multă frecvență poate aduce un câștig, dar se întreabă cât de mare e față de efortul și uzura acumulate; e părerea lui, nu o regulă generală.","Sesiunea de 30-45 de minute vine din 10-15 minute de încălzire, apoi 4-5 exerciții de 4-5 minute fiecare: un set la cedare de 60-90 secunde și circa 2 minute pauză.","Ziua de push: incline cu gantere pentru pieptul superior, apoi pec deck sau fly pentru tensiune pe toată amplitudinea, lateral raises la cablu și extensii pentru triceps.","Rotește variantele de press la câteva luni ca să eviți suprasolicitarea; nu e nevoie de 15 seturi de piept, fiindcă oboseala în plus nu înseamnă creștere."],"e":[["incline dumbbell press","primul exercițiu, ținta e pieptul superior; amplitudine mai mare decât la bară"],["pec deck / chest fly","tensiune pe toată amplitudinea, permite cedare fără probleme de echilibru"],["cable lateral raises","tensiune constantă; merg și cu gantere"],["tricep push downs","cu bară dreaptă sau în V, pentru capul lateral și medial"],["overhead tricep extensions","se rotesc în săptămâna următoare"]],"c":["Antrenament de 30-45 minute","Treadmill 5-10 minute și bandă elastică circa 5 minute","Un set de lucru la cedare, 60-90 secunde de lucru","Pauză de circa 2 minute între exerciții","4-5 exerciții pe sesiune","Push/picioare/pull, 3 zile pe săptămână","Autorul are 32 de ani","Peste 10 ani de testat metode"]},{"v":"PyUWVf5sT-E","k":"s","t":"Should you workout if you're still sore?","d":"27.02.2026","th":["recuperare-si-somn","accidentari-si-articulatii","incepatori"],"i":["Febra musculară de 3 zile e normală, mai ales pentru începători; diferă de durere, care e ascuțită, localizată și crește la mișcare.","Întreabă-te dacă te poți mișca bine și antrena cu formă bună la aceeași greutate; dacă febra e mică, poți merge, iar dacă șchiopătezi, mai așteaptă 1-2 zile."],"e":[],"c":["3 zile de febră musculară","1-2 zile în plus de pauză"]},{"v":"c8DdCFc0DOQ","k":"s","t":"is one set enough to get jacked?","d":"27.02.2026","th":["volum-si-frecventa","failure-si-progresie","incepatori"],"i":["Un set dur pe exercițiu e potrivit pentru cei cu bază de cel puțin un an; avantaje: antrenamente de 25-45 de minute, recuperare bună, mai puține accidentări.","Dezavantaje: trebuie să mergi cu adevărat la failure, iar nu exersezi mișcarea; nu e pentru începători."],"e":[],"c":["1 set la failure","25-45 de minute","peste 10 ani de antrenament"]},{"v":"SoksGDK0g80","k":"s","t":"Best Split For Max Muscle Growth?","d":"26.02.2026","th":["program-si-split","principii-antrenament"],"i":["Cel mai bun split e cel pe care îl poți respecta; contează seturile grele, progresia și recuperarea.","Programele sunt ca mașinile: toate te duc la destinație, important e care ți se potrivește."],"e":[],"c":[]},{"v":"FN6p6adz_tE","k":"l","t":"You're Using The Gym Wrong","d":"25.02.2026","th":["slabit","cardio-si-pasi","principii-antrenament","mentalitate"],"i":["Mulți aleg repetări multe, pauze scurte, drop seturi sau supersets ca să ardă grăsime; autorul zice că sala servește mai ales construirii mușchiului.","Grăsimea se pierde în afara sălii, prin deficit caloric, mese reale și mișcare; după autor, 8-10.000 de pași contează mai mult decât intervalul de repetări.","Semnalul de creștere vine din progresie: adaugi treptat greutate sau repetări, pe săptămâni și luni.","Nu confunda transpirația, pulsul ridicat sau epuizarea cu creșterea musculară; contează progresul în sală, mâncatul, somnul și hidratarea.","Împarte rolurile: ridicatul construiește forță și mușchi, mișcarea și cardio mențin sănătatea inimii, mâncarea controlează grăsimea, iar recuperarea te ține consecvent."],"e":[["lat pulldowns","exemplu al unui om care făcea repetări foarte multe și avea nevoie de ajutor din cauza prinderii"]],"c":["8.000-10.000 de pași pe zi","Deficit caloric mic pentru slăbit","Progresie treptată pe săptămâni și luni"]},{"v":"fG3xwrFEZdE","k":"s","t":"Dorian Yates said it best...","d":"24.02.2026","th":["mike-mentzer","volum-si-frecventa","failure-si-progresie"],"i":["Dorian Yates: mergi la failure real, destul cât să stimulezi, dar nu mai mult, pentru că trebuie să te și recuperezi.","Spune că 45 de minute de două ori pe săptămână și o dietă bună pot schimba o viață; lipsa timpului nu e scuză."],"e":[],"c":["45 de minute de două ori pe săptămână"]},{"v":"emdDtstpdhQ","k":"l","t":"THE BIGGEST LIE ABOUT GETTING JACKED","d":"23.02.2026","th":["mentalitate","cardio-si-pasi","program-si-split","varsta"],"i":["Nu ai nevoie de o viață construită în jurul sălii pentru a fi în formă; amânarea nu elimină costul, doar îl mută în sănătate, energie și încredere, mai târziu.","Rutina completă descrisă: 3 antrenamente de 45 de minute, un sprint de 30 de minute, 2-3 plimbări sau jogging lent de 30-45 de minute și o drumeție sau ruck lungă.","Autorul adună rutina la 6-7 ore pe săptămână, circa 10 cu drumul și schimbatul, adică aproximativ 6% din timpul unei săptămâni.","Dacă viața e aglomerată, minimul este 3 zile de ridicat greutăți și mers zilnic sau la două zile, care tot aduc beneficii.","Dacă amâni, spune autorul, nu ai o problemă de timp, ci de priorități; făcând din formă o prioritate te scoate din blocaj."],"e":[["ruck","o drumeție lungă pe săptămână, de o oră până la o oră și jumătate"],["zone two walks or jogs","2-3 pe săptămână, 30-45 de minute"],["sprint session","una pe săptămână, circa 30 de minute"]],"c":["168 de ore pe săptămână","Muncă 40-50 de ore, somn 6-8 ore, în total circa 100","3 sesiuni de sală de 45 min, puțin peste 2 ore","Un sprint de 30 min","2-3 plimbări sau jogging zonă 2, 30-45 min, în jur de o oră și jumătate","O drumeție de 1-1,5 ore","6-7 ore pe săptămână în total, circa 10 cu drumul","Aproximativ 6% din săptămână","Autorul are 32 de ani"]},{"v":"NxvfThnOtXk","k":"s","t":"Creatine causes hair loss?","d":"23.02.2026","th":["suplimente"],"i":["Autorul a evitat creatina aproape zece ani de teama căderii părului, apoi a luat 5-8 g pe zi timp de un an fără probleme vizibile.","Părerea lui e că riscul de cădere a părului depinde mai ales de genetică și a fost exagerat; nu promite aceleași rezultate pentru toți."],"e":[],"c":["5-8 g creatină pe zi","un an de folosire"]},{"v":"_LHobqFvABc","k":"s","t":"These 7 things will get you Jacked!","d":"21.02.2026","th":["program-si-split","tehnica","picioare","spate"],"i":["Gândește pe tipare de mișcare, nu pe exerciții fixe: genuflexiune, hinge, împins orizontal și vertical, tras orizontal și vertical, plus un loc pentru carry/core.","Dacă nu poți sau nu vrei un exercițiu clasic, alegi alternative din același tipar."],"e":[["barbell squat","alternative: front squat, goblet squat, leg press, hack squat, split squat"],["Romanian deadlift","cu gantere sau trap bar; alternative hip thrust, good mornings, kettlebell"],["barbell bench press","alternative: incline dumbbell, Smith machine, machine press, push-ups, floor press"],["overhead press","bară, gantere sau mașină"],["barbell row","alternative: dumbbell row, T-bar, cable row, machine row"],["pull-ups","alternative: weighted pull-ups, chin-ups, lat pulldown, assisted"],["single arm farmers walk","pentru core, priză și stabilizatori"]],"c":["7 tipare de mișcare","10 ani de antrenament"]},{"v":"nxRI7jrxHTY","k":"s","t":"Want to build your dream body? Do this","d":"20.02.2026","th":["mentalitate"],"i":["Scrie-ți obiectivele pe hârtie în fiecare dimineață: îți dau claritate și îi dau creierului o țintă pentru zi."],"e":[],"c":[]},{"v":"NbFRi-yhEus","k":"s","t":"Stop doing squats, bench press, and the deadlift?","d":"19.02.2026","th":["tehnica","principii-antrenament","picioare","accidentari-si-articulatii"],"i":["Nu există exerciții obligatorii: corpul simte doar tensiunea; poți înlocui squatul cu split squat, Bulgarian split squat, leg press sau hack squat.","Dacă urăști un exercițiu sau îți doare articulațiile, alege varianta care îți place; consecvența pe termen lung te face musculos."],"e":[["squat, split squat, Bulgarian split squat, leg press, hack squat","toate dau tensiune asupra picioarelor"]],"c":[]},{"v":"X8whyQdJrT8","k":"s","t":"If you want to get jacked, focus on this","d":"18.02.2026","th":["sala-acasa","principii-antrenament","failure-si-progresie"],"i":["Mușchiul nu știe ce echipament folosești, ci doar stresul aplicat; important e să produci forță împotriva rezistenței și să progresezi.","Autorul a antrenat ani de zile într-o sală improvizată în dormitor, cu un rack ieftin și greutăți libere second-hand."],"e":[],"c":[]},{"v":"U27_hwmXcMU","k":"l","t":"I Only Do 1 Set Per Exercise To Failure (Here's Why)","d":"17.02.2026","th":["failure-si-progresie","mike-mentzer","volum-si-frecventa","principii-antrenament"],"i":["Creșterea musculară se reduce la stimul și recuperare; câte seturi, ce exerciții și cum împarți săptămâna sunt detalii minore, după autor.","Metafora semințe: antrenamentul greu e semănatul, iar somnul, mâncarea și hidratarea sunt apa; dacă dormi puțin, mănânci prost și antrenezi zilnic, nu progresezi.","Un stimul puternic cere apropierea de cedare; odată atins pe câteva exerciții care acoperă grupa, seturile în plus adaugă mai ales oboseală.","Autorul spune că steroizii cresc recuperarea, deci cei cu volum mic au ales asta deliberat; fără ajutor, precizia contează și mai mult.","Beneficii: sesiuni de 25-45 de minute, recuperare mai bună, concentrare pe un singur set. Costuri: efort mintal mare. Potrivit după circa un an de antrenament."],"e":[["incline dumbbell press","exemplu cu hantere de lucru de 95 lb: 8 repetări cu 45, 5 cu 70, apoi 1-3 cu 85-90 lb, 2 minute pauză"]],"c":["Peste 10 ani de antrenament","Trecere de la 6-7 la 3 zile pe săptămână","De la 20 de seturi pe mușchi pe săptămână la sub 10","Sesiuni de 25-45 de minute","Primul exercițiu: 2-3 seturi de încălzire progresive","Următoarele: o încălzire la 50% din greutatea de lucru","Pauză de 2 minute înainte de setul de lucru","Recomandat după cel puțin un an de antrenament"]},{"v":"O_XUat7LcNc","k":"s","t":"I only train each muscle 1x a week (here’s why)","d":"15.02.2026","th":["volum-si-frecventa","program-si-split","failure-si-progresie"],"i":["Autorul antrenează fiecare mușchi o dată pe săptămână, în push-legs-pull: sigur stimulezi creșterea și apoi ai o săptămână întreagă de recuperare.","Nu se concentrează pe volum sau frecvență, ci pe seturi grele aproape de eșec, recuperare și supraîncărcare progresivă într-un interval moderat de repetări."],"e":[],"c":["o dată pe săptămână pe grupă","peste 10 ani"]},{"v":"lKLT-dT4GV4","k":"l","t":"The Only 7 Exercises You Need To Get Jacked?","d":"13.02.2026","th":["tehnica","principii-antrenament","program-si-split","sala-acasa"],"i":["Gândește în tipare de mișcare, nu în exerciții obligatorii: dacă nu suporți squatul sau banca te doare la umeri, există alternative pentru aceiași mușchi.","Șase tipare: genuflexiune, balans din șold, împingere orizontală, împingere verticală, tragere orizontală și verticală; al șaptelea, opțional, e transportul încărcat.","Al șaptelea slot este transportul încărcat, de exemplu farmer's walk cu o singură mână, care cere rezistență la rotație și antrenează priza, stabilizatorii și core-ul.","Barele rămân o opțiune la fiecare tipar și pot fi folosite dacă îți merg; ideea e că nu există o singură variantă corectă, nu că trebuie evitate exercițiile grele.","Alege varianta care merge pentru corpul tău, antreneaz-o din greu și urmărește progresul prin greutăți și repetări adăugate în timp."],"e":[["back squat, front squat, goblet squat, leg press, hack squat, split squat","variante ale tiparului de genuflexiune"],["Romanian deadlift with dumbbells or trap bar, hip thrust, good morning, kettlebell work","variante ale tiparului de hinge; unele merg și cu benzi elastice"],["barbell bench press, incline dumbbell bench, Smith machine press, machine press, push-ups, floor press","împingere orizontală"],["barbell overhead press, dumbbell press, machine shoulder press","împingere verticală"],["barbell row, dumbbell row, chest supported T-bar row, cable row, machine row, inverted row","tragere orizontală"],["pull-ups, weighted pull-ups, chin-ups, lat pulldowns, assisted pull-ups","tragere verticală"],["single arm farmers walk","transport încărcat, ține postura dreaptă și nu te lasă într-o parte"],["walking lunges, Bulgarian split squats","menționate ca alternative pentru forță funcțională"]],"c":["Peste 10 ani de ridicat greutăți","Șase tipare principale și un al șaptelea opțional","Peste 100 de variante de împingere orizontală, după autor"]},{"v":"JN-H7WmqUC8","k":"s","t":"A simple workout routine to build muscle, and stay healthy","d":"12.02.2026","th":["program-si-split","cardio-si-pasi","recuperare-si-somn","varsta"],"i":["Rutina autorului la 32 de ani: push-legs-pull de 3 ori pe săptămână, 30-45 min, 4-5 exerciții; zone 2 de 2-3 ori pe săptămână și o zi de sprinturi (3-5, pauză completă).","Sprintul e riscant fără bază (rupturi de hamstring); pentru somn: lumină redusă seara, dormitor întunecat și răcoros, orar fix; sauna și baia rece sunt opționale."],"e":[],"c":["3 zile pe săptămână, 30-45 minute","4-5 exerciții","zone 2: 2-3 ori pe săptămână","sprint o zi pe săptămână, 3-5 sprinturi, 20-30 minute","încălzire 15 minute"]},{"v":"pC-jjoqZReM","k":"l","t":"You Don’t Need to Squat, Bench, or Deadlift to Get Jacked","d":"08.02.2026","th":["tehnica","sala-acasa","mentalitate","principii-antrenament"],"i":["Corpul nu știe ce e o genuflexiune sau o presă: reacționează la tensiune mecanică ridicată și la recuperare, deci exercițiul concret e doar o unealtă.","Nu te forța la mișcări pe care le urăști sau care îți strică articulațiile doar pentru că sunt considerate obligatorii; întreabă-te ce tipar vrei să antrenezi.","Un exercițiu își merită locul dacă îl simți în mușchiul vizat, îți place în cea mai mare parte, te poți recupera fără accidentări și poți progresa la el.","Autorul nu spune că genuflexiunea sau bara sunt rele; le consideră unelte excelente, dar a renunțat la ele și și-a făcut sală acasă cu mașini, cabluri și gantere.","Începătorii ar trebui să urmeze un program dovedit și să învețe bazele; abia după faza de novice poți experimenta cu variante care ți se potrivesc."],"e":[["squat, bench press, barbell deadlift","menționate ca exerciții pe care mulți le simt obligatorii"],["split squat, Bulgarian split squat, leg press, hack squat, pendulum squat","alternative pentru picioare"],["leg curl, leg extension, cable tower, leg press","echipamentele din sala de acasă a autorului"]],"c":["Peste 5 ani de antrenament într-o sală improvizată în dormitor, doar cu rack, bară și greutăți libere","Acum 7 ani autorul vorbea doar de squat, bench și deadlift"]},{"v":"cSKe9gyIQlU","k":"s","t":"If you’re Skinny fat, Do this","d":"08.02.2026","th":["slabit","masa-musculara","incepatori"],"i":["Pentru skinny fat: taie întâi la 10-12% grăsime, cu un deficit de ~300 kcal, apoi lean bulk.","La bulk antrenează-te 3-4 zile cu un split simplu și mănâncă simplu; efectele se văd în 6-12 luni."],"e":[],"c":["10-12% grăsime","deficit ~300 kcal","3-4 zile","6-12 luni"]},{"v":"btl1dt5MEhM","k":"s","t":"Do This To Increase Your Testosterone Naturally","d":"06.02.2026","th":["suplimente","cardio-si-pasi","recuperare-si-somn"],"i":["Autorul a aflat din analize testosteron la limita inferioară a mediei și vitamina D scăzută; recomandă soare zilnic.","Face în fiecare zi ceva afară (mers, surf, skateboard), ceea ce ajută vitamina D și ținerea la linie fără cardio plictisitor."],"e":[],"c":["vârsta 30 de ani"]},{"v":"uIzZlEQLEE8","k":"s","t":"One of Mike Mentzer's best pieces of advice","d":"05.02.2026","th":["mike-mentzer","principii-antrenament","volum-si-frecventa"],"i":["Antrenamentul de culturism nu e probă de rezistență; scopul e să declanșezi creșterea cu efortul necesar, apoi să pleci acasă și să te odihnești.","Dacă antrenamentul durează doar 20 de minute, nu e o problemă."],"e":[],"c":["antrenament de 20 de minute"]},{"v":"8y1egHz8Wfk","k":"l","t":"My Simple Approach To Working Out, Cardio, and Longevity","d":"04.02.2026","th":["program-si-split","cardio-si-pasi","recuperare-si-somn","varsta"],"i":["Programul pe viață are patru piloni: ridicat greutăți (3 zile, push/picioare/pull, 30-45 de minute, 4-5 exerciții), cardio simplu, mișcare zilnică și recuperare.","În zilele fără sală te miști cu activități ușoare, cu impact mic, plus cardio în zona 2 de 2-3 ori pe săptămână, la un ritm la care poți vorbi.","Un sprint pe săptămână, de 10-15 secunde la 85-95%, 3-5 repetări cu odihnă completă, după 15 minute de încălzire dinamică; începe treptat dacă n-ai alergat de ani.","Somnul e baza: reduci lumina vie seara, ecranul îl dai pe modul de noapte sau îl eviți, dormi în întuneric și la răcoare, la ore similare.","Sauna și cold plunge sunt opționale; autorul le folosește pe zile de odihnă, pentru relaxare și pentru beneficii mintale, și nu cere nimănui să se simtă obligat."],"e":[["incline walking, light jog, cycling","cardio zona 2, 30-45 de minute, respiri pe nas și poți vorbi"],["sprints","10-15 secunde la 85-95%, 3-5 repetări, încălzire de 15 minute cu skips, high knees, hops și exerciții ușoare"]],"c":["3 zile de sală pe săptămână, 30-45 minute","4-5 mișcări cheie pe sesiune","Zona 2: 2-3 ori pe săptămână, 30-45 minute","Sprint: o dată pe săptămână, 20-30 minute în total, 10-15 secunde, 85-95%, 3-5 repetări","Încălzire pentru sprint: circa 15 minute","Plan: luni push, marți cardio, miercuri picioare, joi cardio, vineri pull, sâmbătă sprint, duminică odihnă cu mișcare","Țintă citată: aproximativ 11 minute de expunere la frig și 57 minute de saună pe săptămână","Sesiune de saună 20-30 minute, cold plunge 2-3 minute","Cold plunge în mijlocul sau finalul anilor 40 F; sauna infraroșu 130 F","Autorul are 32 de ani"]},{"v":"VRWkYQsxp1g","k":"s","t":"This is why you look the same year after year","d":"01.02.2026","th":["failure-si-progresie","principii-antrenament"],"i":["Notează fiecare antrenament (exerciții, greutate, repetări, seturi) ca să poți progresa data viitoare; altfel doar faci mișcare, nu te antrenezi cu scop."],"e":[],"c":[]},{"v":"fbIrvzknGXY","k":"s","t":"My best advice to get you jacked","d":"31.01.2026","th":["principii-antrenament","program-si-split","nutritie","mentalitate"],"i":["15 lecții: nu schimba programul un an, progresie obligatorie, 3-4 antrenamente grele pe săptămână, jurnal, bulk lent, 3-4 mese reale, 10.000 de pași, 7+ ore somn.","Proteine: autorul zice că 0,6-1 g per pound ajunge; sfatul de a mânca mai mult poate ascunde un interes comercial."],"e":[],"c":["3-4 antrenamente pe săptămână","10.000 de pași","7+ ore somn","0,6-1 g proteine per pound","10 ani de antrenament"]},{"v":"UMgH-8VdWyk","k":"l","t":"The Problem With Fitness Influencers...","d":"30.01.2026","th":["mentalitate","principii-antrenament","altceva"],"i":["Industria fitness merge în valuri (diete, split-uri, antrenament hibrid, volum mare, minimalism); trendurile se schimbă, iar simplitatea e acum la modă pentru că vinde.","Fitness simplu: ridici greutăți câteva zile pe săptămână, devii mai puternic decât data trecută, mănânci dens în nutrienți și te recuperezi.","Alege pe cine urmezi după istoric, nu după mesaj: spune același lucru de ani? Are rezultate reale cu oameni reali? Predă un proces clar sau doar reacționează la trenduri?","Autorul susține că predă aceeași idee din 2017: un plan simplu, câteva exerciții cheie, accesorii pentru estetică, urmărirea cifrelor, progresie și consecvență."],"e":[],"c":["Autorul spune că predă aceeași idee din 2017"]},{"v":"Xj8V30MMAGs","k":"s","t":"1 set to failure doesn't work?","d":"30.01.2026","th":["volum-si-frecventa","principii-antrenament"],"i":["Începe cu un set per exercițiu; dacă nu merge, treci la două, apoi la trei, căutând doar cantitatea strict necesară."],"e":[],"c":["1 set, apoi 2, apoi 3"]},{"v":"fv5euHBYXoM","k":"l","t":"You Only Need 3 Days A Week In The Gym!","d":"29.01.2026","th":["volum-si-frecventa","failure-si-progresie","program-si-split","recuperare-si-somn"],"i":["Trei zile pe săptămână nu sunt o scurtătură: cu mai puține sesiuni, fiecare antrenament contează mai mult și nu mai ai plasa de siguranță a volumului mare.","Simplu nu înseamnă ușor. Cine trece la 3 zile fără să urmărească greutățile, să mănânce și să doarmă bine, apoi dă vina pe program, nu și-a schimbat execuția.","Ce a schimbat pentru autor a fost intensitatea: sesiunile vechilor culturiști cu volum mic erau grele, cu seturi duse la cedare, nu cu repetări lăsate în rezervă.","Cu 3 zile de ridicat, ce faci în afara sălii nu mai e opțional: tracking, nutriție, somn și recuperare trebuie să fie în ordine.","Dacă îți place să mergi zilnic la sală, ridici doar 3 zile, iar în rest pași, cardio sau mobilitate; șase zile de ridicat pot eroda recuperarea și articulațiile."],"e":[],"c":["Antrenează 3 zile pe săptămână de peste 5 ani","Sesiuni de circa 25-40 de minute","Un set greu pe exercițiu","Înainte: 6-7 zile pe săptămână","Normă obișnuită: peste 20 de seturi pe săptămână și 2 ore în sală, 6 zile","Peste 10 ani de antrenament"]},{"v":"iw0AklkkXDU","k":"l","t":"This Fitness Challenge Will Change Your Life","d":"26.01.2026","th":["mentalitate","incepatori","principii-antrenament","nutritie"],"i":["Autorul crede că oamenii nu sunt în formă din lipsă de consecvență, nu de lene: nu urmăresc nimic, deci nu progresează și nu văd îmbunătățiri care să motiveze.","Provocare de 75 de zile cu 10 reguli; dacă ratezi una, reiei de la ziua 1. Scopul e să înveți ce înseamnă consecvența și să vezi ce trebuie făcut pentru fizicul dorit.","Reguli de antrenament: scrie-ți obiectivele zilnic, ridică minim 3 zile pe săptămână, notează fiecare antrenament și adaugă greutate sau măcar o repetare la un set.","Reguli de stil de viață: minim 8.000 de pași, mâncare curată fără mese libere, doar apă, cafea neagră, ceai sau apă de cocos, o poză de progres pe săptămână.","Dormi minim 7 ore și bifează zilnic un tracker al regulilor; scrisul pe hârtie și urmărirea îți țin atenția pe țintă."],"e":[],"c":["75 de zile; ratezi o regulă și reiei de la ziua 1","10 reguli","Minim 3 zile de ridicat pe săptămână","Minim 8.000 de pași pe zi","Somn minim 7 ore","Fotografie de progres o dată pe săptămână","Autorul are peste 10 ani de antrenament"]},{"v":"luvVet_uhhY","k":"s","t":"Do THIS every single workout…","d":"26.01.2026","th":["failure-si-progresie","principii-antrenament"],"i":["La fiecare antrenament provoacă-te: vino cu plan, ține aceleași mișcări cheie în timp și încearcă să adaugi o repetare sau puțină greutate."],"e":[],"c":[]},{"v":"J0j90bDSKLs","k":"s","t":"Focus on this instead of getting a good pump","d":"24.01.2026","th":["failure-si-progresie","principii-antrenament"],"i":["Nu judeca antrenamentul după pump sau febra musculară, ci după cifre: dacă greutățile cresc într-un interval moderat de repetări, construiești mușchi.","Nu se vede neapărat în oglindă de la o săptămână la alta, dar în luni și ani corpul se schimbă."],"e":[],"c":[]},{"v":"PBcCsw-K1DY","k":"s","t":"POV: You built your dream home gym","d":"23.01.2026","th":[],"i":[],"e":[],"c":[]},{"v":"FYRiwDyXx8Q","k":"l","t":"I Built My Dream Home Gym...","d":"22.01.2026","th":["sala-acasa","altceva"],"i":["Pentru sala din șopron, în Florida, autorul a pus la tavan 2 inch de foam board sigilat cu bandă, fiindcă izolația veche de 1/2 inch lăsa goluri.","Pe pereți a pus OSB în loc de gips-carton: costă cam la fel, nu cere finisaje și rezistă mai bine la lovituri cu discuri sau bară, deși e greu și casant.","Ar evita: lipsa unui plan scris cu schiță și listă de materiale, mai multe drumuri la magazin, lipsa unei scări înalte sau a schelei; ar fi ales gips-carton.","Podeaua: covoare de cauciuc din magazin de bricolaj în loc de cele de grajd, care miroseau a chimicale; plăcile mai mari obligă la tăieturi și ușa trebuie ajustată.","A cumpărat oglinzi de sticlă ieftine, puse pe suport cu un cui provizoriu; spune că nu are parteneriate și a plătit echipamentul, în afară de gantere și bănci."],"e":[],"c":["Șopron de circa 20 pe 20","Trasee de circa 50 de picioare pentru cablu electric","Izolație 2 inch la tavan, 1 inch pe pereți","Aproximativ 7 prize","Mini split de 18.000 BTU","Oglinzi de 63 pe 24, câte două pe cutie","Lucrul a durat circa 6 zile pe schelet și 3 săptămâni până la sala gata","Sauna cumpărată second-hand cu aproximativ 500 de dolari"]},{"v":"OtqjSaag7bw","k":"s","t":"Working out is you vs you","d":"20.01.2026","th":["mentalitate","failure-si-progresie"],"i":["Nu te compara cu alții; singura competiție este versiunea ta din săptămâna trecută.","Dacă progresezi, chiar încet, faci bine; dacă nu, ajustează pe baza jurnalului de antrenament, nu a emoțiilor."],"e":[],"c":[]},{"v":"jWShh_oqKww","k":"s","t":"S Tier Arm Exercises To Get You Jacked","d":"19.01.2026","th":["brate"],"i":["Incline dumbbell curl: biceps în poziție de întindere, greu de trișat dacă pui pauză jos; urmat de barbell curl cu bară dreaptă.","Triceps: push-down și overhead extension, cu cabluri sau gantere; cele două acoperă tricepsul."],"e":[["incline dumbbell curls","pauză jos, tensiune în întindere"],["barbell curls","bară dreaptă"],["tricep push downs"],["overhead extension","cu V-bar, bară dreaptă sau gantere"]],"c":[]},{"v":"q2HOazl8f5o","k":"l","t":"This Will Save You Years Of Wasted Time In The Gym","d":"17.01.2026","th":["principii-antrenament","failure-si-progresie","nutritie","mentalitate"],"i":["Alege un program potrivit scopului și ține-l cel puțin un an; sari între programe și supraanaliza te costă ani, iar majoritatea programelor merg dacă rămâi consecvent.","Progresia nu e opțională: dacă greutățile sau repetările nu cresc în timp, nici fizicul nu va crește; nota progresul într-un jurnal și crede cifrele, nu pompa.","3-4 antrenamente serioase pe săptămână ajung pentru un sportiv natural, care are nevoie de mai multă recuperare și de forță în repetări moderate.","Pentru masă, mergi pe un surplus mic, de circa 200-300 de calorii; pentru slăbit, 3-4 mese reale, aproximativ 10.000 de pași și minimum 7 ore de somn.","Proteina: autorul spune că 0,6-1 g pe lb de greutate corporală ajunge. Forța și mărimea merg împreună, iar procesul e un maraton, nu o cursă de viteză."],"e":[["bench, squat, overhead press, deadlift","compuse recomandate pentru bază, cu variante precum incline, decline, front squat, overhead press cu gantere sau din șezut"]],"c":["Peste 10 ani de antrenament","Program ținut cel puțin un an","3-4 sesiuni pe săptămână","Surplus de aproximativ 200-300 calorii","Aproximativ 10.000 de pași pe zi","Somn minim 7 ore","Proteină 0,6-1 g pe lb de greutate corporală","Exemplu: bench de la 135 la 225 lbs","Exemplu: tracțiuni de la 5 repetări la 10 cu un disc de 45 lb"]},{"v":"-9tGTJbAAVY","k":"s","t":"If you want to get in shape, Try this.","d":"15.01.2026","th":["mentalitate","incepatori"],"i":["Scrie de ce fugi (anti-viziunea) și unde vrei să ajungi (viziunea pozitivă); când nu ai chef de sală, te întorci la ele.","Poți construi mușchi indiferent dacă acum ești gras sau slab; contează acțiunile zilnice și rutina."],"e":[],"c":[]},{"v":"dTG-Ld7A7YU","k":"l","t":"Building Muscle Is Not Rocket Science","d":"13.01.2026","th":["principii-antrenament","recuperare-si-somn","failure-si-progresie","incepatori"],"i":["Creșterea musculară cere trei lucruri: efort, recuperare și dovadă (jurnal). Dai corpului un motiv să se schimbe, apoi timp și combustibil ca să o facă.","Efort înseamnă plan și aceleași exerciții cheie ținute în timp; încearcă mereu să adaugi o repetare sau puțină greutate sau să faci aceeași greutate cu formă mai curată.","Mulți se blochează la recuperare, fiindcă copiază programe făcute pentru oameni pe steroizi; autorul recomandă 3-4 zile, somn, hidratare, mâncare bună și mers.","Dacă greutățile cresc încet în intervalul 6-12 repetări, volumul e bun; dacă stagnezi, verifică dacă faci prea mult, dormi puțin sau nu antrenezi destul de greu.","Cu cât intensitatea e mai mare, cu atât durata trebuie să scadă mult; poți antrena fie greu, fie mult, dar nu amândouă. Compară-te doar cu tine din săptămâna trecută."],"e":[],"c":["Începutul interesului pentru sală: 2011","Peste 10 ani de experiență","3-4 zile de antrenament pe săptămână","Repetări în jur de 6-12, uneori 15","Exemplu: omul care antrena 6-7 zile pe săptămână a redus numărul de zile"]},{"v":"5owXF7-Xc5g","k":"s","t":"Just start working out bro","d":"12.01.2026","th":["mentalitate","incepatori"],"i":["Dacă crezi că nu poți avea un fizic bun din cauza genelor, întreabă-te la ce te ajută gândul ăsta; poate e adevărat, dar nu te face să te miști.","Compară cu orice ai învățat să faci (șofatul): începi, exersezi, treci de pragul inițial și înfrunți rezistența."],"e":[],"c":[]},{"v":"xJHilbebyMo","k":"s","t":"S Tier Leg Exercises To Get You Jacked","d":"11.01.2026","th":["picioare","tehnica"],"i":["Pentru picioare: presă (sau genuflexiuni), extensii de picior, flexii pentru femurali plus o mișcare de îndreptare, gambe la aparat șezând sau la Smith.","Fără aparat de extensii, split squat cu gantere (bulgăresc) sau fandări inverse; pentru îndreptare, RDL sau trap bar, mai comodă pentru majoritatea."],"e":[["barbell squat"],["leg press","alternativă cu mai puțin stres pe zona lombară"],["pendulum squat"],["leg extensions"],["split squats","cu gantere, stil bulgăresc, sau fandări inverse"],["seated leg curl"],["lying leg curl","variantă de alternat"],["Romanian deadlift"],["trap bar deadlift"],["seated calf raise"],["Smith machine standing calf raise","lent și controlat"]],"c":[]},{"v":"C188NHVQpJg","k":"l","t":"Most Supplements Are a Waste of Money","d":"10.01.2026","th":["suplimente","nutritie","masa-musculara"],"i":["Autorul consideră că majoritatea suplimentelor sunt umflate și scumpe; dacă dieta, somnul și antrenamentul sunt slabe, niciun supliment nu le repară.","Folosește creatina (5-8 g pe zi) pentru forță, recuperare și, după el, beneficii pentru creier; temerea de căderea părului o consideră exagerată și depinzând de genetică.","Ia circa 150 mg cofeină dintr-o sursă naturală cu L-teanină, pentru concentrare, nu pentru mușchi; seara târziu sau în doze mari îi dădea anxietate.","A ales vitamina D cu K2, zinc, bor și magneziu glicinat după analize cu testosteron spre limita de jos; recomandă mai ales soare zilnic și mers afară.","Pudra proteică o ia doar fiindcă mănâncă greu suficient; dacă mâncarea ajunge, nu e nevoie. E părerea lui personală, nu sfat medical."],"e":[],"c":["Creatină 5-8 g pe zi, la circa o oră după trezire","Cofeină aproximativ 150 mg","Aproximativ o lingură de miere și puțină sare sau picături de electroliți înainte de antrenament","Antrenament la circa 45 minute după trezire","Proteină pudră adaugă aproape 1.000 de calorii lichide în smoothie","Circa 1 an de creatină fără probleme"]},{"v":"iHTHLTTqMKE","k":"s","t":"Please watch this if you're new to working out","d":"08.01.2026","th":["incepatori","mentalitate"],"i":["Începătorii nu văd rezultate în 3 săptămâni; înveți exercițiile, disciplina și obiceiurile, iar corpul nu se grăbește.","Timpul trece oricum; trebuie să accepți că durează."],"e":[],"c":["3 săptămâni"]},{"v":"kMitI9VpNAQ","k":"s","t":"These 2 Exercises Will Build Your Back","d":"07.01.2026","th":["spate"],"i":["Wide grip lat pulldown (sau weighted wide grip pull-ups acasă) pentru lățime; chest supported T-bar row pentru grosime, ca să nu preia lombarul.","Pull-up cu greutate: după 10 repetări curate, adaugi centură cu disc de 5-10 lbs; fără aparat de rând, inverted row sau barbell row."],"e":[["wide grip lat pulldown"],["weighted wide grip pull-ups","după 10 repetări cu greutatea corpului, centură cu disc de 5-10 lbs"],["chest supported T-bar row"],["inverted row","alternativă, cu vestă cu greutate"],["barbell rows"]],"c":["10 repetări","disc de 5-10 lbs"]},{"v":"w1EBPwnkBdI","k":"s","t":"The only 2 exercises I do for Abs","d":"06.01.2026","th":["abdomen","nutritie"],"i":["Pentru abdomen autorul alege fie cable crunch cu frânghie, fie ridicări de picioare din atârnat, deși nu i-a antrenat constant.","Crede că abdomenii se fac în bucătărie; mișcările compuse îi lucrează și ele."],"e":[["cable crunches","cu frânghie"],["hanging leg raises"]],"c":["10 ani fără antrenament constant pentru abdomen"]},{"v":"ZlrvdO16lzI","k":"s","t":"You don't need much protein to get jacked","d":"05.01.2026","th":["nutritie","masa-musculara"],"i":["Autorul spune că a crescut cu mai puține proteine decât recomandările (~140 g pe zi la 180-190 lbs); contează antrenamentul mai greu, consecvența și caloriile totale.","Prezintă accentul pe proteine ca marketing, dar e părerea lui."],"e":[],"c":["1 g per pound recomandat","~140 g proteine pe zi","180-190 lbs"]},{"v":"WjeC0oNh-PM","k":"s","t":"If you're confused in the gym, watch this video","d":"04.01.2026","th":["principii-antrenament","incepatori","program-si-split"],"i":["Dacă ești subdezvoltat, problema nu e alegerea exercițiilor, ci că n-ai rămas destul la un plan, n-ai mâncat și nu te-ai antrenat consecvent.","Nu specializa și nu adăuga exerciții înainte să ai o bază musculară."],"e":[],"c":[]},{"v":"MpEN_i7FH0E","k":"s","t":"These 2 Exercises Will Build Your Chest","d":"03.01.2026","th":["piept","tehnica","principii-antrenament"],"i":["Incline dumbbell press încarcă direct pieptul de sus, cu amplitudine mai mare decât barbell sau Smith; seated incline chest fly la mașină dă cea mai bună întindere.","Alternativa la mașină e incline dumbbell fly; presă și fly înclinate acoperă pieptul, nu ai nevoie de 5-6 exerciții."],"e":[["incline dumbbell press","pentru pieptul de sus, amplitudine mare"],["seated incline chest fly machine","întindere și conexiune musculară; alternativă: incline dumbbell fly"]],"c":[]},{"v":"QMI0qzsM6-E","k":"l","t":"How To Go From Fat To Jacked in 2026 (Just Copy This)","d":"01.01.2026","th":["slabit","nutritie","cardio-si-pasi","mentalitate"],"i":["Înainte de orice plan, scrie de ce vrei să slăbești, mai adânc de abdomene vizibile, și recitește motivul în zilele grele, inclusiv ce se întâmplă dacă nu schimbi nimic.","Scopul nu e doar scăderea în greutate, ci mușchi construit în timp ce slăbești; ridică greutăți 3-4 zile pe săptămână, circa 45 de minute.","Pentru cineva supraponderal, cel mai bun cardio e mersul: arde calorii, ajută apetitul și nu forțează articulațiile; urmărește 8.000-10.000 de pași, repartizați în zi.","Începe cu o săptămână de observare a mâncării (porții, gustări, mâncat de plictiseală sau stres), apoi înlocuiește mesele preferate cu versiuni mai bune, făcute acasă.","Mesele din alimente reale sațiază mai mult decât fast-food-ul; schimbările mici se adună și se mențin mai ușor decât un regim strict."],"e":[],"c":["3-4 zile de sală pe săptămână, circa 45 de minute","Împărțire sugerată: o zi de partea de sus, o zi de partea de jos, cu zi de odihnă între ele","8.000 de pași ca minim, 10.000 ca țintă","O săptămână de observare a mâncării"]},{"v":"msQ_TxypRII","k":"s","t":"These 4 Exercises Build Bigger Shoulders","d":"31.12.2025","th":["umeri","tehnica"],"i":["Overhead press în picioare cu bara, amplitudine completă, cu pauză și fără leg drive; laterale cu gantere sau cabluri pentru lățime.","Nu uita deltoidul posterior: face pull sau reverse pec deck; acasă, benzi elastice."],"e":[["standing barbell overhead press","amplitudine completă, pauză, fără leg drive"],["lateral raises","gantere sau cabluri"],["cable face pulls"],["reverse pec deck"]],"c":[]},{"v":"3eEAkoKpncA","k":"l","t":"The Most Underrated Muscle for Looking Jacked (And How to Build It)","d":"29.12.2025","th":["antebrate","accidentari-si-articulatii","brate","tehnica"],"i":["Antebrațele se văd mereu și țin de priză și de stabilitatea cotului; autorul le lucrează și ca să prevină cotul de tenisman sau de golfist.","Începătorii nu au nevoie de lucru direct pentru antebrațe: tracțiunile, ramele și deadlift-ul le cresc singure multă vreme.","Wrist roller antrenează flexia și extensia pe rând; crește numărul de rulări întâi și greutatea abia după ce poți face 4 seturi fără oprire.","Wrist curl și reverse wrist curl cu gantere, cu antebrațele ușor în afara băncii, merg ușor; autorul le vede mai ales pentru sănătatea cotului, nu pentru volum.","Trap bar deadlift e exercițiul preferat pentru antebrațe, fiindcă le ține sub tensiune izometrică; renunță la chingi. Adaugă 1-2 seturi de 8-15 repetări."],"e":[["wrist roller","o urcare și coborâre contează un set; când faci 4 seturi fără oprire, adaugi greutate"],["dumbbell wrist curls and reverse wrist curls","în genunchi, în spatele unei bănci, antebrațele ușor suspendate; pauză cam un minut între cele două"],["hammer curls","coate lipite de corp, ganterele urcă drept, nu peste corp; adaugă grosime brațului"],["trap bar deadlift","alternativ cu bara dreaptă; apuci și strângi mânerele continuu; fără chingi"]],"c":["8-15 repetări","1-2 seturi pe exercițiu","Adăugat la finalul unei zile de antrenament","4 seturi fără oprire la wrist roller înainte de a mări greutatea"]},{"v":"3WC9aezWGTE","k":"s","t":"The \"secret\" to getting jacked","d":"28.12.2025","th":["principii-antrenament","failure-si-progresie"],"i":["Nu există tempo magic, stil de repetări magic sau tehnică secretă ascunsă de influenceri.","Dacă ar exista un secret: alegi un mod de antrenament care îți place, lucrezi aproape de eșec sau la eșec, adaugi greutate și repetări când poți și rămâi consecvent."],"e":[],"c":[]},{"v":"tiF5QFD15fg","k":"l","t":"This Is the Workout Program I’d Use to Get Jacked in 2026","d":"26.12.2025","th":["incepatori","program-si-split","failure-si-progresie","nutritie"],"i":["Primul an de antrenament seamănă cu învățatul unei mașini cu cutie manuală: nu te aștepta la rezultate în trei săptămâni; construirea corpului nu se poate grăbi.","Mușchiul vine din patru lucruri: antrenament suficient de greu, forță crescândă, destulă mâncare și somn; execuția e simplă, nu pompa sau suplimentele.","Rutina pentru începători: upper/lower/upper în 3 zile sau upper/lower în 4; ziua de sus are 2 împingeri, 2 tragerii și izolare pentru umăr, triceps, biceps.","Ziua de jos: genuflexiune sau presă, izolare de cvadriceps, balans din șold, flexie de genunchi, gambe și opțional abdomen; 10-12 exerciții pe săptămână.","Alege un interval de repetări (de exemplu 6-10), crește treptat și adaugă greutate la 10 pe toate seturile, revenind la 6; ultimele repetări trebuie să fie grele."],"e":[["squat or press","mișcare principală în ziua de jos"],["leg extension","izolare pentru cvadriceps"],["hamstring hinge and hamstring knee flexion","pentru ischiogambieri în întregime"],["calves","după mișcările de ischiogambieri"]],"c":["3 zile pe săptămână: upper, lower, upper, cu zi de odihnă între antrenamente","4 zile: upper, lower, odihnă, upper, lower, odihnă, odihnă","Ziua de sus: 2 împingeri, 2 tragerii și câte o izolare pentru umăr, triceps și biceps","10-12 exerciții pe săptămână","Interval de repetări: 6-10, 8-12 sau 10-15; la început 3 seturi de 6, apoi 7 etc.","Pași: 8.000-10.000 pe zi","Somn: minim 7 ore","Termostat la aproximativ 66 F","Postește câteva ore după trezire, apoi 3-4 mese","Prima sau a doua săptămână: stabilirea greutății inițiale, fără efort maxim"]},{"v":"6UOCbzqtv_M","k":"s","t":"Do THIS if you want to get jacked","d":"24.12.2025","th":["failure-si-progresie","masa-musculara","mentalitate"],"i":["Dacă vrei să construiești mușchi, notează antrenamentele ca regulă fixă; tot antrenamentul se învârte în jurul întrebării dacă ai bătut săptămâna trecută.","Dacă nu mai vrei masă, sala rămâne un câștig pentru menținerea activității."],"e":[],"c":[]},{"v":"SFLRKbE0x1Y","k":"s","t":"You’re Making Fitness Harder Than It Is","d":"23.12.2025","th":["mentalitate","program-si-split","incepatori"],"i":["Rezultatele vin din bazele repetate mult timp, nu din multă informație; alege un plan simplu de 3-4 zile pe săptămână.","Mănâncă suficient, urmărește progresul și dă planului un an întreg înainte să decizi că ai nevoie de mai mult."],"e":[],"c":["plan de 3-4 zile","un an"]},{"v":"TYEkRRKcncg","k":"l","t":"My S-Tier Exercises for Getting Jacked","d":"21.12.2025","th":["program-si-split","piept","spate","picioare"],"i":["Pentru piept ajung două mișcări înclinate: o presă și un fly. Presa încarcă greu, flyul dă întinderea completă; adaugă greutate și repetări în timp.","Presa cu gantere pe înclinat e mișcarea lui preferată pentru partea de sus a pieptului: încarcă direct și permite o amplitudine mai mare decât Smith sau bara.","Spate: tracțiuni late cu priză largă pentru lățime, tras la T-bar cu sprijin la piept pentru grosime, fiindcă ține corpul stabil și lucrează spatele, nu lombarii.","Umeri și brațe: presă overhead cu bara, lateral raises, face pulls pentru deltoidul posterior; la biceps curl pe înclinat cu pauză jos, plus extensii pentru triceps.","Picioare: presa de picioare e o alternativă bună la genuflexiuni, cu mai puțin stres pe spate; adaugă leg extension, leg curl și un hinge (RDL sau trap bar).","Nu ai nevoie de sală scumpă: acasă înlocuiești cu gantere, benzi elastice, pull-up cu centură, rânduri inversate. Constanța contează mai mult decât exercițiile."],"e":[["Incline dumbbell press","mișcarea principală pentru piept, amplitudine mare"],["Seated incline chest fly machine","alternativă: incline dumbbell fly"],["Wide grip lat pulldown","acasă: weighted wide grip pull-ups, centură cu disc de 5-10 lb după 10 repetări curate cu greutatea corpului"],["Chest supported T-bar row","alternative: inverted row (cu vestă cu greutăți), barbell row, landmine row"],["Standing barbell overhead press","amplitudine completă, cu pauză, fără leg drive"],["Lateral raises","cu gantere sau cabluri"],["Cable face pulls / reverse pec deck","acasă: benzi elastice, începi ușor"],["Incline dumbbell curls","pauză la partea de jos; exemplu de progres de la 20 lb la 45 lb pentru 10 repetări"],["Barbell curls","preferă bara dreaptă"],["Triceps pushdowns","cu V-bar sau bară dreaptă"],["Overhead extension","cu V-bar sau bară dreaptă la cablu"],["Leg press"],["Barbell squat"],["Pendulum squat machine"],["Leg extension","fără aparat: split squat cu gantere, bulgarian sau reverse lunges"],["Seated leg curl","lying leg curl ca variație"],["Romanian deadlift","sau trap bar deadlift"],["Calf raise","la aparat șezând sau în picioare la Smith, lent și controlat"],["Cable crunch with rope","sau hanging leg raises"]],"c":["10 ani pe aceleași mișcări de bază","10 repetări curate cu greutatea corpului înainte de centura cu greutăți","disc de 5 sau 10 lb","de la 20 lb la 45 lb la incline dumbbell curl, pentru 10 repetări, în unul-doi ani"]},{"v":"IY3ZgO1p4RM","k":"s","t":"Why Most People Never Make Progress In The Gym","d":"20.12.2025","th":["failure-si-progresie","principii-antrenament","mike-mentzer"],"i":["Ține un grafic de progres exact: dacă antrenezi corect, devii mai puternic la fiecare antrenament sau aproape.","Mușchiul nu vine din efort singur, ci din efort cu îmbunătățire măsurabilă (citat din Mentzer)."],"e":[],"c":[]},{"v":"NsNFXs-gS6M","k":"s","t":"Mike Mentzer - You Only Need One Set!","d":"19.12.2025","th":["mike-mentzer","failure-si-progresie","volum-si-frecventa"],"i":["Citat din Mentzer: după un set dus la eșec muscular, nu mai e nevoie de un al doilea, ca la un întrerupător deja pornit.","Scopul este să declanșezi mecanismul de creștere cu un set până la eșec momentan."],"e":[],"c":[]},{"v":"RLKKQU6INkg","k":"s","t":"This Is All 99% of People Need to Get Jacked","d":"18.12.2025","th":["program-si-split","principii-antrenament","incepatori","nutritie"],"i":["Pentru 99% dintre oameni: un program simplu care îți place, 3-4 zile pe săptămână, câteva exerciții de bază și accesorii, antrenament greu, greutate adăugată când poți.","Adaugă mâncare reală și repetă destul timp; mai ales dacă te antrenezi ca să arăți mai bine și să fii puternic, nu pentru scena de culturism."],"e":[],"c":["3-4 zile pe săptămână"]},{"v":"DQ99fndbrRs","k":"l","t":"Is Your Workout Actually Enough to Build Muscle?","d":"17.12.2025","th":["principii-antrenament","incepatori","program-si-split","masa-musculara"],"i":["Dacă ești subdezvoltat, problema rareori e selecția exercițiilor: lipsesc mâncarea suficientă, constanța și timpul petrecut pe același program.","Rămâi pe un plan simplu de 3-4 zile pe săptămână, mănâncă în surplus caloric, urmărește progresul și dă-i un an întreg înainte să adaugi ceva.","Progresul vine din adăugat greutate și repetări în timp; variațiile se schimbă doar de câteva ori pe an, ca să eviți suprasolicitarea.","Greutatea țintă pentru un fizic slab și musculos: înălțimea în inci înmulțită cu 2,4-2,6 (5'11 dă aproximativ 185 lb); scazi sau adaugi 2-3 lb pe inch.","Cine se face mare repetă lucruri plictisitoare: aceleași alimente, aceleași mișcări, aceleași obiceiuri, zi de zi."],"e":[],"c":["3-4 zile pe săptămână","înălțime în inci x 2,4-2,6 = greutate țintă","5'11 (71 in) x 2,6 = aproximativ 185 lb","180-190 lb pentru 5'11 cu abdomenul vizibil","2-3 lb pentru fiecare inch în plus sau în minus","un an înainte de a schimba planul"]},{"v":"Zbr9-U7edWo","k":"s","t":"This One Mistake Makes You Think You’re Strong","d":"16.12.2025","th":["tehnica","failure-si-progresie"],"i":["Un record la bench în care bara sare de pe piept nu e un record real, ci unul de ego bazat pe elan."],"e":[["bench press"]],"c":[]},{"v":"U0tWTpAMNgA","k":"l","t":"I’ve Done 1,500 Workouts. This One Thing Matters Most For Getting Jacked","d":"14.12.2025","th":["failure-si-progresie","principii-antrenament","mike-mentzer","mentalitate"],"i":["Notează fiecare antrenament (caiet, aplicație sau jurnal): corpul crește doar la progres măsurabil, iar fără cifrele din săptămâna trecută nu ai țintă azi.","Chiar o repetare în plus la un set, cu aceeași formă curată, e un stimul nou; întrebarea de bază e dacă ai depășit săptămâna trecută.","Fără urmărire alegi calea ușoară, sari de la un program la altul și te iei după pump și febră musculară, care nu dovedesc creșterea.","Mike Mentzer insista pe un grafic exact al progresului, ca să știi că te îmbunătățești la fiecare antrenament sau cel puțin des.","Caiet ieftin sau aplicație pe telefon; autorul preferă caietul, fiindcă telefonul îl distrage în sală."],"e":[],"c":["bench 185 lb x 7 săptămâna trecută, 8 repetări săptămâna aceasta, ca exemplu de progres"]},{"v":"SPR9hx2sfLo","k":"s","t":"Don't look in the mirror after a workout","d":"12.12.2025","th":["mentalitate","incepatori"],"i":["Alege un program cu recenzii decente, urmează-l un an și abia apoi privește-te în oglindă; după două antrenamente nu se vede nimic.","Contează consecvența, nu programul anume."],"e":[],"c":["un an","10 ani de antrenament"]},{"v":"Lxvvx1xOh3Q","k":"s","t":"STOP listening to juiced up bodybuilders","d":"11.12.2025","th":["volum-si-frecventa","recuperare-si-somn","principii-antrenament"],"i":["Cei mai mulți nu cresc fiindcă fac prea mult (seturi, zile, exerciții) și nu se recuperează; mușchiul crește în recuperare.","Autorul spune că cei pe steroizi au recuperare mult mai mare, deci sfatul «mai mult e mai bine» de la ei poate fi periculos pentru tine."],"e":[],"c":[]},{"v":"U9B1qzmQ6Qw","k":"l","t":"Do This Warm-Up Before Every Workout","d":"10.12.2025","th":["incalzire","tehnica","mentalitate"],"i":["Începe cu 5-7 minute de mers pe bandă înclinată (10-12 în ziua de picioare), ușor; ridică temperatura corpului și pregătește articulațiile.","Mimează mișcările zilei cu o bandă elastică ușoară, în circuit lin: de exemplu overhead press, lateral raises, face pulls și pushdowns în ziua de împins.","La primul exercițiu fă 3-4 seturi crescătoare, cu pauze scurte și ultima aproape de greutatea de lucru, apoi 2 minute pauză înainte de setul real.","La exercițiile următoare ajunge un singur set de încălzire la aproximativ jumătate din greutatea de lucru, 5-8 repetări.","Încălzirea nu trebuie să obosească; 20 de minute de stretching plus foam rolling în plus sunt prea mult. E părerea lui, să găsești ce merge pentru tine."],"e":[["Incline walk","5-7 minute, 10-12 în ziua de picioare, ritm ușor"],["Band circuit","overhead shoulder press, single arm lateral raise, face pulls, tricep pushdowns, ușor și controlat"],["Lat pulldown ramp up","greutate de lucru 170 lb: 70 lb x 8, 100 lb x 5, 130 lb x 3, 160 lb x 1; pauze 30-45 secunde, apoi 2 minute"],["T-bar row","un set de încălzire 70 lb x 5-8, apoi 140 lb ca set de lucru"]],"c":["5-7 minute incline walk","10-12 minute în ziua de picioare","170 lb greutate de lucru la pulldown","70 lb x 8, 100 lb x 5, 130 lb x 3, 160 lb x 1","pauze 30-45 secunde între seturile de încălzire","2 minute înainte de primul set de lucru","un set la aproximativ jumătate din greutate, 5-8 repetări, la exercițiile următoare","70 lb înainte de 140 lb la T-bar row"]},{"v":"bAV1lT7mP1g","k":"s","t":"The Simple System I Use To Stay Lean Year Round","d":"09.12.2025","th":["nutritie","slabit","cardio-si-pasi"],"i":["Sistemul autorului pentru a rămâne definit: obiective citite zilnic, mâncare reală, cafeină în prima oră, câteva ore de post dimineața, plimbare."],"e":[],"c":[]},{"v":"T30dF_NOpz4","k":"s","t":"You don't need that much protein to build muscle","d":"08.12.2025","th":["nutritie","masa-musculara"],"i":["Nu ai nevoie de cantități uriașe de proteine: în jur de 0,6-0,8 g pe pound de greutate corporală e suficient, peste asta diferența e mică."],"e":[],"c":["0,6-0,8 g proteine per pound de greutate"]},{"v":"q4Wx_ebZtDM","k":"l","t":"The Hidden Rep Method That Got Me Jacked","d":"07.12.2025","th":["tehnica","failure-si-progresie","principii-antrenament"],"i":["Pauza completă după fiecare repetare elimină elanul și orgoliul: mușchiul produce toată forța, fără săritură din jos și fără trișat prin punctul greu.","Tensiunea mecanică e motorul creșterii: seturi grele duse aproape de eșec sau la eșec, cu greutate crescută în timp. Arsura și pumpul sunt metaboliți, nu tensiune.","Spune că, după cercetări, tempoul exact contează puțin dacă efortul e acolo; pauză, repetări netede sau tensiune constantă dau creștere similară.","Pauzele întăresc poziția cea mai slabă, ceea ce se vede apoi în forță și în viața de zi cu zi.","Alege stilul pe care îl faci cu plăcere: dacă antrenamentul te enervează, renunți. Nu există tempo sau truc magic, doar antrenament greu, progres și răbdare."],"e":[],"c":["3-4 zile pe săptămână","aproape 100.000 de abonați"]},{"v":"ZGl98DESY9k","k":"s","t":"Stick to the plan. That’s how you get jacked.","d":"06.12.2025","th":["mentalitate"],"i":["Fă un program pe hârtie și respectă-l indiferent cum te simți; rămâi la plan și evită ce știi că nu e bun."],"e":[],"c":[]},{"v":"DD4JlZ4vQH4","k":"s","t":"How To Build Muscle With Just 4 Hours a Week","d":"05.12.2025","th":["program-si-split","volum-si-frecventa","picioare","incepatori"],"i":["Sub 4 ore pe săptămână: zi upper cu 2 exerciții de împingere, 2 de tragere și izolări; zi lower cu squat sau presă, cvadriceps, hamstring, gambe.","2-3 seturi, 6-10 repetări la compuse și 8-12 la accesorii, pauze 2-3 min și 1 min; la vârful intervalului pe toate seturile adaugi greutate."],"e":[],"c":["sub 4 ore pe săptămână","2-3 seturi","6-10 repetări compuse, 8-12 accesorii","pauze 2-3 minute și 1 minut"]},{"v":"aWsiy2crohU","k":"l","t":"The Biggest Lie In The Fitness Industry","d":"03.12.2025","th":["nutritie","suplimente","principii-antrenament","mike-mentzer"],"i":["Proteina e exagerat promovată de industrie; la el contează mai mult antrenamentul mai greu decât înainte, caloriile suficiente, somnul și constanța.","El însuși a mâncat sub un gram pe lb (în jur de 140 g la 180-190 lb) și a crescut și s-a întărit totuși.","Pentru o țintă simplă: greutatea dorită în lb înmulțită cu 0,6-0,8; la 185 lb ies aproximativ 140 g pe zi, nu trebuie să fie exact.","Un gram pe lb rămâne țintă comodă și ajută la sațietate, mai ales la slăbit, dar nu e obligatoriu.","Mike Mentzer ținea proteina la aproximativ 20-25% din calorii, iar el spune că ideea de bază nu s-a schimbat în 40 de ani.","Folosește pudră de proteină doar ca să adauge calorii în shake-ul zilnic, cu puține ingrediente."],"e":[],"c":["1 g pe lb de greutate corporală","aproximativ 140 g proteină pe zi la 180-190 lb","0,6-0,8 g pe lb","185 lb, aproximativ 140 g","20-25% din calorii din proteină la Mentzer","40 de ani"]},{"v":"wRqZlC2hkts","k":"s","t":"How many days a week should you workout?","d":"02.12.2025","th":["volum-si-frecventa","program-si-split","failure-si-progresie"],"i":["Pentru 99% din oameni 3-4 zile pe săptămână sunt de ajuns, iar 4 pot fi mai bune la început pentru mai multă practică.","Pe măsură ce avansezi, mai puține antrenamente, dar mai intense; mușchiul crește din forță într-un interval moderat, nu din pump sau rutine „shock”."],"e":[],"c":["3-4 zile pe săptămână pentru 99% din oameni"]},{"v":"GJ9ECfILL3g","k":"s","t":"This meal plan keeps me lean and jacked year round","d":"01.12.2025","th":["nutritie","masa-musculara"],"i":["Planul de mese al autorului: proteine de pui sau vită la micul dejun plus un smoothie zilnic (lapte de cocos, unt de migdale, miere, cacao nibs, curmale, afine, mango).","Apoi carne tocată de vită, cartofi la air fryer, fructe și un snack; la cină friptură sau pui cu orez ori cartofi dulci și legume."],"e":[],"c":["circa 9 oz lapte de cocos","1 lingură unt de migdale","1 lingură miere","3 curmale medjool","același smoothie de 4 ani"]},{"v":"JxTid8xETlg","k":"l","t":"The Best Workout Routine If You Don’t Want To Live In The Gym","d":"28.11.2025","th":["program-si-split","volum-si-frecventa","failure-si-progresie","recuperare-si-somn"],"i":["Poți construi un fizic bun în mai puțin de 4 ore pe săptămână; mulți nu progresează fiindcă fac prea multe seturi și zile și nu se recuperează.","Ziua de sus: două mișcări de împins, două de tras, plus câte o izolare pentru umeri, triceps și biceps. Nu ai nevoie de șapte unghiuri pentru piept.","Ziua de jos: genuflexiune sau presă, o mișcare pentru cvadriceps, un leg curl, un hinge, gambe și opțional abdomene, cu 2-3 seturi pe exercițiu.","Progresie simplă: când atingi limita de sus a intervalului de repetări la toate seturile, cu formă bună, crești greutatea săptămâna următoare; dacă nu, rămâi la aceeași.","Dacă mergi la eșec, fă mai puține seturi și urmărește doar să bați repetările din săptămâna trecută, nu să le egalezi (de exemplu 8 și 6, apoi 9 și 7).","Culturiștii cu steroizi suportă volum mare pentru că se recuperează mult mai bine; sfatul lor că mai mult înseamnă mai bine e riscant pentru restul."],"e":[["Dumbbell incline press","exemplu cu 70 lb pe mână: începi cu 6 repetări la toate seturile, apoi 7-6-6, până la 10, apoi crești greutatea cu 2,5-5 lb și revii la 6"]],"c":["sub 4 ore pe săptămână","3 sau 4 zile pe săptămână","2-3 seturi pe exercițiu","6-10 repetări la compuse","8-12 repetări la accesorii, uneori până la 15","pauză 2-3 minute la mișcările mari, 1 minut la cele mici","creștere de 2,5 sau 5 lb la atingerea a 10 repetări","bench de la 135 lb x 5 la 225 lb x 5, ca exemplu","10 ani de antrenament"]},{"v":"gArAISTLHNA","k":"s","t":"Getting in shape isn't complicated","d":"26.11.2025","th":["mentalitate","principii-antrenament"],"i":["Rămâi definit fără 6 zile pe săptămână, antrenamente de 2 ore, multe suplimente sau dietă extremă; industria câștigă din confuzie."],"e":[],"c":["6 zile pe săptămână","2 ore"]},{"v":"4XH3jADQF7c","k":"l","t":"Unfortunately, Fitness Really Is This Simple","d":"22.11.2025","th":["principii-antrenament","volum-si-frecventa","cardio-si-pasi","nutritie"],"i":["Pentru majoritatea oamenilor 3-4 zile de antrenament pe săptămână sunt suficiente; recuperarea permite să devii mai puternic de la o sesiune la alta.","Mușchiul se construiește mai ales devenind mai puternic într-un interval moderat de repetări, nu prin pump, trucuri gen 21s sau antrenamente de brațe de două ore.","Dacă greutățile nu cresc, fizicul nu se schimbă; mai bine 2-3 seturi de 6 repetări la curl, adaugi o repetare pe săptămână și apoi greutate.","Combină antrenamentul cu mers (10k pași), mâncare reală, lumină de dimineață în ochi, somn 7-9 ore, hidratare și, mai presus de toate, constanță pe luni și ani.","Mâncarea din alimente întregi (carne, ouă, fructe, miere, cartofi, orez, legume) îți reglează caloriile fără numărat obsesiv; după el, 3-4 mese sătură.","Somn 7-9 ore (la el cameră răcoroasă, ~66°F, draperii opace, fără ecrane târziu, magneziu glicinat) și apă: jumătate din greutatea corporală, în uncii pe zi."],"e":[["Incline dumbbell press","exemplu de progres de la 45 lb x 7 pe mână la 80 lb x 10 după un an"],["Barbell curl","2-3 seturi de 6 repetări, adaugi o repetare pe săptămână, apoi greutate"],["21s","dă doar pump, spune el"]],"c":["3-4 zile pe săptămână","99% din câștiguri cu 3-4 zile","10k pași pe zi","somn 7-9 ore","66° în cameră","jumătate din greutatea corporală, în uncii de apă pe zi","80% dintre spectatori nu leagă soarele de rezultate, spune el","45 lb x 7 devine 80 lb x 10 în an"]},{"v":"e5QQoVvz27s","k":"s","t":"You’re Training Too Much (Do This Instead To Grow)","d":"21.11.2025","th":["recuperare-si-somn","principii-antrenament"],"i":["Trei niveluri de deload: micro (scurtezi sesiunea unui mușchi), resetare de câteva zile (seturile și greutatea la jumătate) și deload complet de o săptămână.","La deload complet rămâi activ (mers, stretching, bandă, mobilitate); într-o săptămână nu pierzi mușchi."],"e":[],"c":["seturi și greutate la jumătate","o săptămână deload complet"]},{"v":"7NGuw1q58bc","k":"s","t":"Old school lifters looked better","d":"20.11.2025","th":["principii-antrenament","mentalitate"],"i":["Autorul se întreabă de ce fizicurile din vechea școală arată mai bine decât ale majorității de azi, deși aveau echipament mai slab și fără internet.","Clipul anunță pași pentru un look de școală veche, dar fragmentul nu îi detaliază."],"e":[],"c":[]},{"v":"n1Y-4fpw7wY","k":"l","t":"The Simple Diet That Gets You Lean and Keeps You Lean","d":"17.11.2025","th":["nutritie","slabit","suplimente"],"i":["Rămâne slab tot anul mâncând aproape numai alimente neprocesate, fără fast food și junk; spune că mesele lui sunt aproape aceleași în fiecare zi.","Mulți nu slăbesc fiindcă mâncarea procesată nu sătură; alimentele întregi fac să mănânci mai puțin și să atingi ținta calorică fără chin.","Autorul susține că suplimentele sunt vândute ca bază, deși ele doar astupă mici goluri; multe conțin ingrediente artificiale.","Plan-exemplu: shake de dimineață (lapte de cocos, proteină, miere, curmale, fructe), vită cu cartofi, fructe, apoi la cină friptură cu orez sau cartof dulce.","Susține că 3-4 mese, ajustate la înălțime, greutate și obiectiv, duc la slăbire; pofta de dulce o stinge cu fructe uscate sau apă de cocos.","Nu e de acord cu ideea că alimentele contează doar dacă încap în macros; spune că micronutrienții și calitatea mâncării contează."],"e":[],"c":["3-4 mese pe zi","același shake de 4 ani","aproximativ 9 uncii de lapte de cocos","1 lingură unt de migdale","1 lingură miere","3 curmale","carne tocată 80/20"]},{"v":"ZK5pnadjJRk","k":"s","t":"You'll get jacked if you listen to this advice...","d":"15.11.2025","th":["program-si-split","mentalitate","incepatori"],"i":["Alege un plan simplu și dovedit (3-4 zile pe săptămână), mărește lent repetările și greutatea, mănâncă mâncare reală și rămâi consecvent.","Ai nevoie de mai puține opțiuni, nu de mai multe informații."],"e":[],"c":["3-4 zile pe săptămână"]},{"v":"i8TzJo6HlbE","k":"s","t":"Getting jacked really is simple.","d":"15.11.2025","th":["mentalitate","nutritie"],"i":["Nu ai nevoie de pantofi speciali sau ceasuri smart; mișcă-ți corpul, antrenează-te și notează ce mănânci."],"e":[],"c":[]},{"v":"vfjwE3k3Rw0","k":"l","t":"The Two Muscles Guys Ignore That Make You Look 10x More Jacked","d":"13.11.2025","th":["gat","antebrate","accidentari-si-articulatii","mike-mentzer"],"i":["Gâtul și antebrațele se văd mereu în haine de zi cu zi; antrenate direct, schimbă rapid impresia generală.","Spune că un gât mai puternic amortizează șocurile și ajută la protecția capului; îl prezintă ca avantaj general, nu doar pentru luptători.","Antebrațe puternice dau priză mai bună, deci rânduri, îndreptări și curl-uri merg mai bine, și ar ajuta la coate dureroase (epicondilită).","Mentzer credea că gâtul și antebrațele cresc fără muncă directă dacă antrenezi greu cu compuse; autorul zice că nu pentru toți, mai ales dacă faci muncă de pompare.","În ziua de sus: 2-3 seturi de 10-15 repetări lente, moderate, pentru gât (flexie sau extensie) și curl de încheietură, o dată sau de două ori pe săptămână.","Măsoară gâtul înainte și după 6 luni ca să vezi diferența."],"e":[["Neck curl / neck extension","fără hamac, cu un disc pe frunte sau pe ceafă, cu căciulă groasă pentru amortizare; greutate moderată, lent"],["Dumbbell wrist curl","2-3 seturi de 10-15 repetări"],["Reverse wrist curl","2-3 seturi de 10-15 repetări"]],"c":["2-3 seturi de 10-15 repetări","1-2 ori pe săptămână","măsurători după 6 luni","split de 3 zile: push, legs, pull"]},{"v":"R9Fgko8w-ho","k":"s","t":"If you struggle with going to the gym, watch this","d":"12.11.2025","th":["mentalitate","incepatori"],"i":["Dacă nu ai obiective, începe cu durerile din viața ta: cum vei fi peste 5 ani dacă nu mergi la sală, ce fizic și ce stare mentală vei avea.","Cu cât listezi mai multe lucruri care îți fac rău, cu atât ai mai multe obiective de abordat."],"e":[],"c":["5 ani"]},{"v":"PvB9yObEaV0","k":"s","t":"The One Habit That Separates Average from Jacked.","d":"11.11.2025","th":["failure-si-progresie","altceva"],"i":["Autorul spune că cei mai mulți nu au rezultate pentru că nu își notează antrenamentele.","Anunță un jurnal propriu de planificare, dar fragmentul e în mare parte reclamă."],"e":[],"c":[]},{"v":"w7pXKCZY4Yg","k":"s","t":"If you're struggling to get jacked, watch this","d":"10.11.2025","th":["mentalitate","principii-antrenament","nutritie"],"i":["Cei cu fizic bun sunt constanți, își notează antrenamentele, antrenează destul de intens și își urmăresc mâncarea; dacă nu ai rezultate, compară-te cu ce fac ei."],"e":[],"c":[]},{"v":"3Z7qTgyH0V0","k":"l","t":"Most Guys Lift For Years And Still Look The Same... Here’s Why.","d":"09.11.2025","th":["principii-antrenament","mentalitate","program-si-split"],"i":["Mulți nu se schimbă în ani de sală fiindcă schimbă mereu programul și suplimentele; consecvența bate noutatea.","Modelul broaștei țestoase: 3-4 zile pe săptămână, seturi grele, aceleași mișcări de bază, notezi progresul și ai mese simple și repetabile.","Progresul se adună: adaugi cinci lb sau o repetare, luni și ani la rând, fără să renunți.","Ai grijă la plictiseală: aceleași exerciții și mese par plictisitoare, dar tocmai asta funcționează."],"e":[],"c":["3-4 zile pe săptămână","adaugi 5 lb sau o repetare","6 luni, 1 an, 3 ani"]},{"v":"XuELa_n-3Z8","k":"s","t":"This is how to get ahead of 99% of people in the gym","d":"09.11.2025","th":["mentalitate"],"i":["Disciplină în loc de motivație, amânarea recompensei și consecvență prin rutină: plan pentru antrenament și mese în fiecare zi.","Fitness-ul e un joc infinit: sau avansezi, sau regresezi."],"e":[],"c":[]},{"v":"-X5GcbKOYlw","k":"s","t":"If you've always wanted six pack abs, watch this","d":"07.11.2025","th":["slabit","nutritie","cardio-si-pasi","incepatori"],"i":["Începe prin a-ți scrie motivul (scopul), apoi stabilește acțiunile zilnice; dacă ai mult de slăbit, începe mic și fără diete extreme.","Bazează dieta pe alimente întregi (te saturi mai bine, mai puține pofte) și merge pe jos în loc să forțezi cardio complicat; ținta autorului: 10.000 de pași pe zi."],"e":[],"c":["10.000 de pași pe zi"]},{"v":"Uos9s0WIrg0","k":"l","t":"Old School Lifters Looked Better… Here’s Why.","d":"05.11.2025","th":["principii-antrenament","program-si-split","mike-mentzer","mentalitate"],"i":["Fizicurile de modă veche arătau echilibrat și sănătos, fără exces de definiție sau de volum, iar autorul vede în ele un reper realist.","Prea multă informație te lasă mai confuz; el a ales o singură sursă și un singur plan, apoi a antrenat mai puține zile și a progresat iar.","Rețetă veche: 3-4 zile pe săptămână, adaugi repetări și greutate încet, mănânci mâncare reală și rămâi suficient de slab tot anul.","Pentru aspectul clasic: presă pe înclinat pentru partea de sus a pieptului, presă overhead pentru umeri, spate cu priză largă (V-taper) și picioare puternice, nu uriașe.","Volum mai mic și intensitate mare, devenind mai puternic la aceleași mișcări în timp, fără să schimbi mereu exercițiile."],"e":[["Incline press","cu bara, gantere sau aparate, rotite la câteva luni"],["Overhead press","gantere, bară sau aparate"],["Wide grip back exercises","toate mișcările pentru spate cu priză largă"]],"c":["3-4 zile pe săptămână"]},{"v":"QyIGHG3bkAw","k":"s","t":"Scared of looking dumb in the gym? Watch this","d":"05.11.2025","th":["altceva"],"i":[],"e":[],"c":[]},{"v":"B33xzw1hGEw","k":"s","t":"Mike Mentzer was way ahead of his time","d":"04.11.2025","th":["mike-mentzer","volum-si-frecventa","failure-si-progresie","incepatori"],"i":["Trecând de la 3 seturi la 1 set pe exercițiu (stil Mentzer), autorul spune că a avut mai multă recuperare, prospețime, recorduri personale și timp liber.","Reproșuri: nu e potrivită începătorilor (nu știu ce e eșecul real), iar superseturile și static holds i s-au părut inutile."],"e":[],"c":["de la 3 seturi la 1 set pe exercițiu"]},{"v":"Q_Vrou61U7s","k":"l","t":"You’re Training Way Too Much","d":"01.11.2025","th":["recuperare-si-somn","accidentari-si-articulatii","volum-si-frecventa"],"i":["Accidentarea e, după el, ucigașul numărul unu al progresului; de obicei vine din acumulare (articulații, stres, recuperare slabă), nu dintr-o singură repetare proastă.","De aceea preferă 3-4 zile pe săptămână în loc de 5-6: mai puțină uzură și loc pentru alte activități, cum ar fi jiu-jitsu, alpinism sau surf.","Semne că ai nevoie de deload: lifturi mai slabe la 2-3 antrenamente la rând, aceeași greutate parcă mai grea, dureri de coate, genunchi, umeri, oboseală și lipsă de chef.","Micro deload: dacă un antrenament merge prost, scazi seturile sau greutatea pe restul sesiunii și te asiguri că somnul, mâncarea și apa sunt la punct.","Reset de câteva zile: seturile și greutatea la jumătate (4x8 devine 2x8 mai ușor). Deload complet: o săptămână fără antrenament greu, doar mers și mobilitate.","Nu pierzi mușchi într-o săptămână; mai probabil revii mai puternic."],"e":[],"c":["10 ani de antrenament","3-4 zile pe săptămână","somn de 7+ ore","seturi și greutate la jumătate","4x8 devine 2x8 cu 50% greutate","o săptămână deload complet"]},{"v":"KLs_LUNYpr0","k":"s","t":"The Fitness Industry Is Lying to You","d":"31.10.2025","th":["nutritie"],"i":["Macro-urile și caloriile contează, dar și din ce sunt făcute; poți atinge cifrele cu batoane, shake-uri și fast food, dar te vei simți rău.","Autorul susține că procesatele cu zaharuri adăugate, coloranți, arome și uleiuri de semințe afectează testosteronul, recuperarea și provoacă inflamație."],"e":[],"c":[]},{"v":"DD_N1OvKSQc","k":"s","t":"Seated Shoulder Press (How To | Form Tutorial)","d":"30.10.2025","th":["tehnica","umeri"],"i":["Seated shoulder press la mașină: reglează scaunul cu mânerele la nivelul umerilor sau puțin sub, lipește spatele de pernă și ține pieptul sus și abdomenul încordat.","Împinge controlat până aproape de extensie și coboară lent până când coatele ajung la circa 90 de grade sau puțin sub."],"e":[["seated shoulder press (machine)","priză pronată puțin în afara umerilor, coborâre până la ~90 de grade la coate"]],"c":["coate la ~90 de grade"]},{"v":"QFBjd8MRruI","k":"s","t":"Getting Jacked Will Change Your Life","d":"29.10.2025","th":["mentalitate","varsta"],"i":["Autorul spune că fizicul musculos înseamnă ani de disciplină, consecvență și răbdare, trăsături care se transferă în restul vieții.","Susține că obții mai multă energie, respect și longevitate, fără dezavantaje."],"e":[],"c":[]},{"v":"dWs6IbgzQok","k":"l","t":"Getting a Six Pack Is Easier Than You Think","d":"28.10.2025","th":["slabit","nutritie","cardio-si-pasi","mentalitate"],"i":["Scrie-ți scopul și motivul real și recitește-l în fiecare dimineață; obiceiurile și sistemele sunt marginile care te țin pe drum când viața se complică.","Bazează dieta pe alimente întregi (fructe, miere, vită, pui, ouă, cartofi, apă de cocos); mâncarea ultraprocesată e făcută să te facă să vrei mai mult și nu sătură.","Nu fa diete extreme, fiindcă nu le poți ține; dacă ai multă greutate de dat jos, începe mărunt, nu perfect.","La el: cofeină în 30-60 de minute după trezire (taie și pofta), apoi post de 3-4 ore până la prima masă; înainte de antrenament, o lingură de miere.","Mergi zilnic, iar el țintește 10.000 de pași; recomandă câteva plimbări, la prânz sau după muncă, în loc de cardio complicat."],"e":[],"c":["10 ani cu abdomenul vizibil, fără efort mare","cofeină în 30-60 de minute după trezire","3-4 ore de post dimineața","1 lingură de miere crudă cu 15-30 de minute înainte de antrenament","10.000 de pași pe zi"]},{"v":"yp9lDT0qWGU","k":"s","t":"My Simple Leg Day To Build Aesthetics/Get Jacked","d":"27.10.2025","th":["picioare","incalzire","program-si-split"],"i":["Zi de picioare: urcare pe înclinație sau stair master, încălzire cu mișcări similare, apoi presă cu seturi de ramp-up înaintea setului de lucru.","Apoi extensii, flexii pentru femurali plus eventual RDL cu gantere, o mișcare pentru gambe la eșec. 4-5 exerciții, pauze de 2-3 minute."],"e":[["leg press","2-4 seturi de ramp-up: 25% cu 10 repetări, 50% cu 8 sau 5, apoi 3 și 1, apoi setul de lucru"],["leg extensions"],["lying leg curls","sau șezând"],["dumbbell Romanian deadlift","al doilea exercițiu pentru femurali"],["bodyweight squats"],["bodyweight lunges"]],"c":["3 zile pe săptămână, push legs pull","25% x 10, 50% x 8 sau 5, apoi 3 și 1 repetări","4-5 exerciții","pauze de 2-3 minute"]},{"v":"ilm8sW_-WHE","k":"s","t":"This is how I would get jacked again if I had to start over","d":"26.10.2025","th":["program-si-split","principii-antrenament","recuperare-si-somn"],"i":["Formula de reluare: 3-4 zile, plan dovedit, execuție perfectă la intensitate maximă, fără sărit între programe.","Recuperare serioasă (7-9 ore somn, destule proteine, stres controlat) și urmărirea cifrelor."],"e":[],"c":["3-4 zile pe săptămână","7-9 ore somn"]},{"v":"d4wJ4YxQOOM","k":"s","t":"The only thing I focus on to get a jacked physique","d":"25.10.2025","th":["failure-si-progresie","mentalitate"],"i":["Singura țintă: să urci pinul pe stivă, adică să crești greutatea la aceleași repetări, an de an, fără trucuri.","Seturi drepte cu intensitate, încercând să-ți depășești săptămâna trecută."],"e":[],"c":["20-30 lbs în plus pe un an","100-200 lbs în plus pe un an la unele exerciții"]},{"v":"4sJClHODw_c","k":"s","t":"If you want to get Jacked, Do THIS!","d":"24.10.2025","th":["program-si-split","principii-antrenament","mentalitate"],"i":["Alege un program dovedit și rămâi cu el: contează mai mult că îl urmezi decât care e.","Autorul compară programele cu mașini: full body, upper/lower, bro split, push-pull-legs ajung toate la țintă, doar cu viteze diferite."],"e":[],"c":[]},{"v":"9wB0JQQ_-TM","k":"s","t":"Mike Mentzer Was Right All Along...","d":"23.10.2025","th":["mike-mentzer","failure-si-progresie","volum-si-frecventa"],"i":["Autorul își construiește rutina după ideea lui Mentzer: mușchiul e ca un întrerupător, după un set greu nu mai trebuie stimulat.","Cu un set la eșec, în 30-35 de minute, spune că bate recorduri personale la aproape fiecare antrenament și va documenta progresul."],"e":[],"c":["un set la eșec","30-35 minute","un PR la fiecare antrenament (afirmat)"]},{"v":"rpcAIjK_fpU","k":"l","t":"My LEG Day To Get Jacked (Step By Step)","d":"22.10.2025","th":["picioare","incalzire","failure-si-progresie","mike-mentzer"],"i":["Ziua de picioare: 4-5 exerciții, cu pauză 2-3 minute între ele; începe cu o presă sau genuflexiune, apoi leg extension, leg curl, hinge opțional și gambe.","Pentru fiecare mișcare principală încălzește-te mimând mișcarea (air squats, lunges) și apoi 2-4 seturi crescătoare, apoi 2-3 minute pauză înainte de setul de lucru.","Ca antrenament cu intensitate mare, gândit în stilul lui Mentzer, face puține seturi, puține zile și duce fiecare set la eșec brutal.","Dacă ești începător, începe cu 3-5 seturi mai ușoare pentru a învăța mișcările și treptat mergi spre greutate mai mare și mai puține seturi.","Alternează leg curl culcat și șezut la câteva săptămâni; la gambe merge până la eșec, chiar cu formă care cedează.","Sesiunile lui durează acum 25-35 de minute, după 10 ani de sală."],"e":[["Leg press","alternative: front squat, back squat, box squat, pendulum squat"],["Leg extension","set dus la eșec"],["Lying leg curl","alternativ seated leg curl"],["Romanian deadlift","cu gantere sau bară, opțional"],["Calf raise","1-2 exerciții, standing și seated, la eșec brutal"],["Incline walk / stair master","la începutul antrenamentului"]],"c":["split de 3 zile: push, legs, pull","4-5 exerciții","2-3 minute pauză între exerciții","ramp up: 25% x 10, 50% x 8 sau 5, apoi 3 și 1","2-4 seturi crescătoare","3-5 seturi pentru începători","25-35 de minute pe sesiune","10 ani în sală"]},{"v":"hwsdtVMKVRQ","k":"s","t":"How to Get Jacked (Fast)","d":"22.10.2025","th":["program-si-split","failure-si-progresie","nutritie","cardio-si-pasi"],"i":["Plan: 3-4 zile, 4-5 exerciții, 2-3 seturi aproape de failure; pornești de la o greutate pentru 6 repetări și adaugi câte o repetare pe săptămână.","La 10 repetări curate crești greutatea și reiei de la 6. Mâncare reală, 1 g proteine per pound de greutate țintă, 8.000 de pași, 7+ ore somn, minim 6 luni."],"e":[],"c":["3-4 zile pe săptămână","4-5 exerciții","2-3 seturi","pauză 2-3 minute la principale, ~1 minut la mici","6 repetări până la 10","1 g proteine per pound","8.000 de pași","7+ ore somn","6 luni"]},{"v":"BTW_dN2TN0s","k":"s","t":"The reason most bodybuilder advice doesn’t work for you.","d":"20.10.2025","th":["principii-antrenament","mentalitate"],"i":["Părerea autorului: sfaturile culturiștilor funcționează pentru ei din cauza steroizilor, care ține corpul în creștere constantă și le dau mult mai multă testosteron.","El se opune trucurilor ca drop sets și superseturi și avertizează că doar pump-ul cu repetări multe nu te va face «jacked»."],"e":[],"c":["de 2-3 ori mai multă testosteron la cei pe steroizi (afirmat)"]},{"v":"jUkfj1JFECA","k":"l","t":"Being Jacked Is Life's Ultimate Cheat Code","d":"19.10.2025","th":["mentalitate","principii-antrenament","altceva"],"i":["Părerea autorului: un fizic bun înseamnă ani de disciplină, răbdare și amânarea gratificării, trăsături care se transferă în restul vieții.","Sala devine pentru el terapie și meditație, iar motivele lui s-au mutat de la aspect la sănătate mintală, pasiune și longevitate.","Consideră că un corp format e unul dintre puținele lucruri care nu se pot cumpăra și aduce energie, respect și oportunități.","El antrenează mai puține zile, cu mai puține seturi și mai puțin timp decât mulți alții."],"e":[],"c":[]},{"v":"2HxEtDNIcZg","k":"s","t":"Jeff Nippard's New Workout Routine","d":"18.10.2025","th":["volum-si-frecventa","program-si-split","mentalitate"],"i":["Autorul spune că un antrenor cunoscut a ajuns și el la volum mai mic și intensitate mare, ceea ce confirmă ce susține el de ani.","Nu ai nevoie de 6-7 zile pe săptămână și seturi nesfârșite: alege un program care îți place, antrenează-te intens, progresează și rămâi consecvent."],"e":[],"c":["6-7 zile pe săptămână (criticat)","2 seturi (în clipul comentat)"]},{"v":"WvW7uQZmCEM","k":"s","t":"Getting Jacked Will Change Your Life","d":"18.10.2025","th":["mentalitate"],"i":["Antrenamentul îți formează caracterul, disciplina și încrederea; corpul e vehiculul care te duce prin viață, așa că pune-l pe primul loc."],"e":[],"c":[]},{"v":"UrNHfehVUgk","k":"s","t":"Do THIS and make the best gains of your life","d":"17.10.2025","th":["failure-si-progresie","mentalitate"],"i":["Progresia duce la creștere; chiar dacă faci o singură repetare în plus la un exercițiu, antrenamentul e o victorie."],"e":[],"c":["o repetare în plus"]},{"v":"TN7gReSHLYs","k":"l","t":"Jeff Nippard Just Proved What I’ve Been Saying for Years","d":"14.10.2025","th":["volum-si-frecventa","principii-antrenament","failure-si-progresie"],"i":["Un creator bazat pe știință a testat volumul mic și intensitatea mare, iar autorul zice că asta confirmă ce spune el de ani: nu trebuie 6-7 zile și seturi fără sfârșit.","Mai multe seturi și zile l-au dus la epuizare, dureri de articulații și accidentări; a revenit la câteva mișcări cheie, puține seturi grele și progres constant.","Aproape orice program funcționează dacă are progresie încorporată și acoperă bazele; contează să-l poți ține pe termen lung.","Rețeta lui: 3-4 zile pe săptămână, 4-5 exerciții pe sesiune, 1-3 seturi pe exercițiu, antrenează tare, progresează, recuperează-te și rămâi consecvent."],"e":[],"c":["3-4 zile pe săptămână","4-5 exerciții pe sesiune","1-3 seturi pe exercițiu","peste 80 de ani de cercetare","peste 10 programe diferite vândute de creatorul menționat"]},{"v":"hVCHA5bk5-g","k":"l","t":"Give Me 59 Seconds And I'll Teach You How To Get Jacked","d":"13.10.2025","th":["program-si-split","failure-si-progresie","nutritie","recuperare-si-somn"],"i":["Antrenează-te 3-4 zile pe săptămână, push/legs/pull sau upper/lower, și rămâi la unul fără să-l schimbi tot timpul.","Fă 4-5 exerciții pe sesiune, cu 2-3 seturi de lucru fiecare, aproape de eșec, cu pauze de 2-3 minute la cele mari și cam un minut la cele mici.","Începe cu o greutate de 6 repetări la toate seturile, adaugă o repetare săptămânal la cel puțin un set și, la 10 repetări bune, crești greutatea și revii la 6.","Mănâncă mâncare reală, un gram de proteină pe lb din greutatea țintă; surplus ușor pentru masă, la mentenanță sau puțin sub pentru slăbit.","Țintește 8.000 de pași pe zi și 7+ ore de somn, și ține planul 6 luni, ideal ani."],"e":[],"c":["3-4 zile pe săptămână","4-5 exerciții","2-3 seturi de lucru","6 repetări pe set, apoi 10","pauze 2-3 minute (mari) și circa 1 minut (mici)","1 g proteină pe lb din greutatea țintă","8.000 de pași","7+ ore de somn","6 luni fără schimbări"]},{"v":"MbBpLzna-88","k":"s","t":"If you're not seeing progress in the gym.. Watch this","d":"12.10.2025","th":["recuperare-si-somn","failure-si-progresie","nutritie"],"i":["Dacă nu progresezi săptămână de săptămână, probabil te recuperezi prea puțin: hidratare, mâncare, somn și stres; astupă «găurile din găleată».","Nu e nevoie de drop sets, superseturi sau periodizare complicată: cheia e o repetare în plus la un exercițiu față de data trecută."],"e":[],"c":[]},{"v":"MkgU9VkUT7E","k":"s","t":"This Is Why You’re Still Small After Years of Training","d":"11.10.2025","th":["failure-si-progresie","mentalitate"],"i":["Dacă ești avansat și seturile îți sunt ușoare, probabil nu te împingi destul: înainte de setul de lucru ar trebui să fii puțin neliniștit.","Pentru începători, care învață mișcările și urcă în greutăți, autorul nu recomandă să meargă la limita absolută."],"e":[],"c":[]},{"v":"uZ0tDUk69wA","k":"l","t":"Stop Chasing the Pump (Do This Instead to Actually Build Muscle)","d":"10.10.2025","th":["failure-si-progresie","principii-antrenament","tehnica"],"i":["Sfatul culturiștilor cu pump și repetări parțiale merge pentru ei fiindcă iau steroizi; autorul crede că la fel stau și mulți influenceri de azi.","Semnul lui că construiești mușchi: peste un an faci aceleași repetări cu 20-30 lb mai mult (uneori 100-200 lb, după exercițiu), adică mută cheia pe stiva de greutăți.","Seturi drepte cu intensitate, iar scopul e să-ți depășești săptămâna trecută; drop sets și super sets pot ajuta uneori la platouri, dar nu sunt baza.","Greșeală frecventă: greutăți prea mici, prea multe repetări și prea multe zile; mai bine greutate mai mare, 6-12 repetări și mai puține zile ca să te recuperezi."],"e":[["Cable stack progression","mutarea cheii pe stiva de greutăți ca indicator"]],"c":["6-12 repetări","20-30 lb sau mai mult într-un an","2-3 ori mai mult testosteron la cei care iau steroizi, spune el"]},{"v":"seyNXSFKRrs","k":"s","t":"Stop overthinking fitness, it's simple.","d":"08.10.2025","th":["principii-antrenament","mentalitate"],"i":["Nu complica fitnessul și nutriția; ai nevoie de un plan pe care îl poți ține, ca să nu te mai învârți în loc."],"e":[],"c":[]},{"v":"UmX_ZgN_38c","k":"s","t":"Push Workout To Get JACKED","d":"06.10.2025","th":["piept","umeri","program-si-split","failure-si-progresie"],"i":["Ziua de push a autorului: un set la failure pe exercițiu (incline press, fluturări, presă de umeri, laterale, push-down); sub o oră.","Începătorii nu ar trebui să copieze: să facă 2-5 seturi. Cu volum mic și intensitate mare trebuie să știi ce faci."],"e":[["incline dumbbell press","un set la failure"],["incline machine flies","pentru partea superioară a pieptului"],["shoulder press","la mașină; merge și cu gantere sau bară"],["lateral raises","merg cu gantere, mașină sau cabluri"],["tricep push downs","singurul exercițiu direct pentru triceps; opțional overhead extension"]],"c":["1 set la failure","2-5 seturi pentru începători","30-35 de minute"]},{"v":"QybSXBLvXhE","k":"s","t":"Mike Mentzer's Leg Day","d":"04.10.2025","th":["mike-mentzer","picioare","program-si-split"],"i":["Ziua de picioare după Mentzer: leg extensions 6-10 repetări la eșec, imediat fără pauză leg press sau squat 6-10 repetări la eșec (superset).","Apoi pauză scurtă, un set de leg curls și altă pauză scurtă."],"e":[["leg extensions","6-10 repetări la eșec, urmat imediat de superset"],["leg press sau squat","6-10 repetări la eșec, în superset"],["leg curls","un set după pauză scurtă"]],"c":["6-10 repetări"]},{"v":"xyqoBiAvdR8","k":"l","t":"How I Got Better Results Training Less","d":"03.10.2025","th":["volum-si-frecventa","failure-si-progresie","program-si-split","mike-mentzer"],"i":["Antrenează trei zile pe săptămână, push/legs/pull; în zilele libere se mișcă ușor, cu mers, treburi prin casă, surf sau skateboard.","Scop la fiecare sesiune: să-ți bați performanța anterioară, cu greutate sau repetări, notată în aplicație sau caiet; chiar o repetare în plus e un câștig.","Experiment personal: un set la eșec pe exercițiu (6-10 repetări, uneori 12-15), după întrerupătorul lui Mentzer: odată pornit stimulul, al doilea set nu mai e necesar.","Dacă nu mergi la eșec, ia 3x8, apoi 3x9, 3x10; crești greutatea cu 5 lb (sau 2 kg) doar când toate seturile ating ținta, apoi revii la 3x8 sau 3x6.","Începătorii să nu copieze setul unic: 10-12 seturi pe grupă pe săptămână, cu 1-3 repetări rezervă, sunt un punct de plecare bun.","O metaanaliză despre volum dă un interval de la 4 la 40 de seturi pe săptămână, iar la 40 randamentele scad mult; el crede că ar fi putut progresa și cu mai puțin."],"e":[["Incline dumbbell bench","un set la eșec, ziua de împins"],["Machine chest fly / pec deck","un set la eșec"],["Seated machine shoulder press / overhead press","un set la eșec"],["Lateral raises","un set la eșec"],["Overhead triceps extension / push down","un set la eșec"]],"c":["3 zile pe săptămână: marți, joi, duminică","un set la eșec, 6-10 repetări, uneori 12 și 15","4-5 exerciții pe zi","3x8, 3x9, 3x10, apoi +5 lb sau 2 kg","10-12 seturi pe grupă pe săptămână pentru începători","4-40 de seturi pe săptămână în metaanaliza menționată","mai mult de 10 ani de antrenament","înainte, 7 zile pe săptămână cu peste 20 de seturi pe sesiune"]},{"v":"KsvEM4QdNnA","k":"s","t":"Train Like This If You Actually Want to Grow","d":"02.10.2025","th":["failure-si-progresie","tehnica"],"i":["Clipul spune doar că seturile făcute într-un fel sunt cele care te mențin mic, iar cele împinse spre progresie dau creștere.","Din transcriere nu rezultă ce anume diferă între cele două moduri."],"e":[],"c":[]},{"v":"ioOwUgq9VyA","k":"s","t":"Mike Mentzer’s #1 chest, shoulders, and triceps exercise","d":"01.10.2025","th":["mike-mentzer","piept","umeri","brate"],"i":["Mentzer: dips sunt „squat-ul pentru partea superioară”, cel mai bun exercițiu pentru piept, umeri și triceps.","Se fac strict, controlat, 6-10 repetări; dacă poți mai mult de 10, adaugi greutate (textul se oprește aici)."],"e":[["dips","strict, controlat, 6-10 repetări"]],"c":["6-10 repetări"]},{"v":"xCCsW-z4-c0","k":"l","t":"The Exact Upper/Lower Split I Used To Go From Average to Jacked","d":"30.09.2025","th":["program-si-split","volum-si-frecventa","failure-si-progresie","principii-antrenament"],"i":["Upper/lower în 4 zile (luni, marți, joi, vineri): sus două împinse, două trase, umeri, triceps, biceps; jos presă sau genuflexiune, cvadriceps, leg curl, hinge, gambe.","Orice program dovedit merge (full body, bro split, upper/lower, PPL), ca mașini diferite spre aceeași destinație; important e să alegi unul și să rămâi pe el.","Regula de progres: când atingi limita de sus a repetărilor la toate seturile, crești greutatea cu 2,5-5 lb săptămâna următoare; altfel rămâi pe loc.","Greșeli: volum inutil (la început 2-3 seturi pe mișcarea principală, 1-2 la izolare), exerciții schimbate săptămânal (rămâi minim 12 săptămâni), efort departe de eșec.","Dacă la setul de lucru nu ai nici o emoție, probabil nu împingi destul; începătorii nu trebuie să ajungă la limită.","Cadrul lui: 10 seturi minim pe grupă pe săptămână, 6-15 repetări, pauze de 2-3 minute la principale și circa 1 minut la izolări. Acum antrenează mult mai puțin."],"e":[["Squat / leg press","ziua de jos"],["Bulgarian split squat / leg extension","cvadriceps"],["Lying leg curl / seated leg curl"],["Deadlift (hip hinge)","hinge pentru ischiogambieri"],["Seated calf raise / standing calf raise"]],"c":["4 zile: luni, marți, joi, vineri","3 zile dacă ești ocupat","2-3 seturi pe mișcare principală","1-2 seturi pe izolare","cel puțin 12 săptămâni pe aceleași exerciții","10-20 de seturi pe grupă pe săptămână în recomandările științifice","minim 10 seturi pe grupă pe săptămână","6-15 repetări","2-3 minute pauză la principale","circa 1 minut la izolări","creștere de 2,5-5 lb"]},{"v":"ATKrBBRdb30","k":"s","t":"The Secret Behind Every Jacked Physique","d":"29.09.2025","th":["failure-si-progresie","principii-antrenament"],"i":["Înainte să pleci din sală, întreabă-te: am depășit versiunea mea anterioară, sunt măcar cu 1% mai bun?","Dacă repetările și greutatea cresc în timp, în interval moderat, creșterea musculară trebuie să aibă loc, cu condiția să faci lucrurile corecte și în afara sălii."],"e":[],"c":["1% mai bun"]},{"v":"9YsNxVhzcls","k":"s","t":"How To Bulk Like A Pro (Step By Step)","d":"28.09.2025","th":["masa-musculara","nutritie","incepatori"],"i":["Bulk-ul e pentru cei slabi, nu pentru cei foarte supraponderali. Calorii de întreținere = greutatea în lbs x 15, plus 200-300 kcal pentru bulk.","Cântărește-te dimineața și fă media pe 7 zile; dacă media nu crește, adaugă 150 kcal, iar dacă urcă prea repede scade 150 kcal; țintă 0,5-1 lb pe săptămână."],"e":[],"c":["greutatea în lbs x 15 = întreținere","+200-300 kcal","+/-150 kcal ajustare","0,5-1 lb pe săptămână","2-4 lb pe lună"]},{"v":"-LsqJwdUHAc","k":"l","t":"My PUSH Day to Get Jacked (Step-by-Step)","d":"27.09.2025","th":["piept","umeri","failure-si-progresie","mike-mentzer"],"i":["Ziua de împins: două mișcări pentru partea de sus a pieptului (presă și fly pe înclinat), presă de umeri, lateral raises și pushdowns; tricepsul lucrează și indirect.","Începătorii nu copiază un set la eșec: ar trebui 2-5 seturi, mai multe seturi nu la eșec, fiindcă volumul mic și intensitatea mare cer experiență.","Se concentrează pe tensiune mecanică prin amplitudine completă și eșec muscular, chiar dacă lasă tensiunea la capătul mișcării, spre deosebire de tensiunea constantă.","Țintește aspect: umeri rotunzi, partea superioară a spatelui și a pieptului evidențiate, talie slabă, la 8-10% grăsime (uneori 12) în timp ce face lean bulk.","Fiecare antrenament durează 30-35 de minute; folosește mai multe aparate acum, după ce a antrenat înainte doar cu bară acasă."],"e":[["Incline dumbbell bench press","un set la eșec; începători 2-5 seturi"],["Incline machine flies","alternativ cu gantere pe bancă înclinată"],["Shoulder press","cu gantere, bară sau aparat"],["Lateral raises","gantere, aparat sau cabluri"],["Triceps push downs","opțional overhead extension"]],"c":["3 zile pe săptămână","un set la eșec","30-35 de minute pe sesiune","8-10% grăsime corporală, uneori 12%","începători 2-5 seturi"]},{"v":"M_6FqKTDNUk","k":"s","t":"Stop listening to most fitness influencers","d":"26.09.2025","th":["mentalitate","principii-antrenament"],"i":["Autorul crede că influencerii câștigă mai mult ținându-te în căutare decât dându-ți claritate, iar mai mult conținut aduce contradicții, nu cunoștințe.","Mulți au consumat sute de ore de conținut și arată la fel după ani."],"e":[],"c":["sute de ore de conținut"]},{"v":"_TfVrhHarIw","k":"s","t":"Workout Split To Get Jacked (3 days a week)","d":"25.09.2025","th":["program-si-split","mike-mentzer","failure-si-progresie"],"i":["Split push/legs/pull de 3 zile, inspirat de Mentzer: împins, fluturare, umeri, laterale, triceps; tras vertical și orizontal, 2 pentru deltoid posterior, biceps.","Câteva seturi de încălzire, apoi un set la failure, pauză de câteva minute; dacă revii mai puternic, mușchiul crește."],"e":[["hanging knee raises","opțional, pentru core"],["cable crunches","opțional, pentru core"]],"c":["3 zile pe săptămână","1 set la failure"]},{"v":"jx0xHNeaZC4","k":"s","t":"You’re not jacked yet because you’re still weak","d":"24.09.2025","th":["incepatori","principii-antrenament"],"i":["Dacă bench-ul e puțin peste 135 lbs sau faci abia 5 pull-ups, ești mic pentru că ești slab; urmează un sistem de încredere câțiva ani.","Abia după 2-3 ani de bază poți vorbi de rămâneri în urmă și de specializare."],"e":[["bench press"],["pull-ups"]],"c":["bench 135 lbs","5 pull-ups","2-3 ani"]},{"v":"ot-h46DlCfo","k":"l","t":"Do THIS One Thing and You’ll Finally Get Jacked","d":"23.09.2025","th":["failure-si-progresie","incepatori","principii-antrenament","mentalitate"],"i":["Întrebarea de bază după fiecare antrenament: mi-am depășit varianta de săptămâna trecută, măcar cu 1%? Fără asta, alegi exerciții la întâmplare și nu progresezi.","Seturile ușoare cu multe repetări, fără plan, sunt volum inutil; fără jurnal nu știi ce greutate sau câte repetări ai făcut data trecută.","Dacă urci repetările și greutatea într-un interval moderat și faci corect restul, mușchiul crește; nu te pierde în frecvență, tempo sau număr exact de seturi.","Cei cu fizic remarcabil aleg un plan, antrenează tare, notează progresul în jurnal sau aplicație și depășesc săptămâna trecută, ani la rând."],"e":[],"c":["intervalul orar 4-5 dimineața pentru antrenamentul lui"]},{"v":"ptW8cpCr_yk","k":"s","t":"Maturing in the gym is realizing...","d":"22.09.2025","th":[],"i":[],"e":[],"c":[]},{"v":"x8Hyc40M2Z4","k":"l","t":"How to Bulk Up and Get Jacked (Step By Step)","d":"20.09.2025","th":["masa-musculara","nutritie","program-si-split","suplimente"],"i":["Fă bulk doar dacă ești slab sau mediu; dacă ești deja supraponderal, taie întâi, ca să nu adaugi grăsime și să nu te simți mai rău.","Calorii de menținere: greutatea în lb x 15 (14 sedentar, 16 foarte activ), plus 200-300 kcal pentru lean bulk; la 190 lb și 6 ft ies circa 3.200 kcal.","Cântărește-te dimineața, fă media a 7 zile; dacă nu urcă, adaugă 150 kcal, iar dacă urcă prea repede, scade 150. Țintă: 0,5-1 lb pe săptămână.","Macros: 1 g proteină pe lb de greutate țintă, 25-30% grăsimi, restul carbohidrați; 3-4 mese simple, din alimente întregi, cu proteină, carbohidrat și puțină grăsime.","Antrenament: split upper/lower de 4 zile, fiecare grupă de două ori pe săptămână; alege un interval (8-12 sau 6-10) și crești 5 lb când atingi limita de sus.","Un bulk corect durează minim 6 luni; urmărești greutatea, forța și poze lunare. Suplimente simple: creatină 5-10 g, proteină la nevoie, cafeină înainte de antrenament."],"e":[],"c":["greutate în lb x 15 pentru calorii de întreținere","x 14 sedentar, x 16 foarte activ","+200-300 kcal","190 lb, 6 ft: circa 3.200 kcal","+150 kcal sau -150 kcal după media săptămânală","0,5-1 lb pe săptămână sau 2-4 lb pe lună","1 g proteină pe lb","25-30% grăsimi","3-4 mese pe zi","4 zile upper/lower","5 lb pe progres, 2,5 lb pe fiecare parte a barei","creatină 5-10 g pe zi","minimum 6 luni","somn 7-9 ore","la 6 ft, 130-140 lb în liceu","5'9 și 190-200 lb ar trebui întâi să slăbească spre 160-170 lb și 10% grăsime"]},{"v":"WkOy5dXdiYs","k":"s","t":"Do these exercises to build aesthetics","d":"20.09.2025","th":["piept","spate","brate","picioare"],"i":["Alegerile autorului: incline dumbbell press plus o fluturare pentru piept; lat pulldown și T-bar row pentru spate; laterale și reverse pec deck pentru umeri.","Brațe: curl-uri și push-down/overhead extension. Picioare: squat sau leg press, extensii, curl și un hip hinge. Abdomene: rar, cable crunch."],"e":[["incline dumbbell press"],["wide grip lat pulldown"],["chest supported T-bar row","pentru grosime"],["incline dumbbell curls"],["barbell curls"],["tricep push down"],["overhead extension"],["lateral raises"],["reverse pec deck","deltoid posterior"],["barbell squats"],["leg press"],["seated leg extensions"],["lying curls"],["seated curls"],["Romanian deadlift"],["trap bar deadlift"],["cable crunches"],["hanging leg raises"]],"c":[]},{"v":"u12UYhIY4bg","k":"s","t":"You can build muscle and lose fat at the same time","d":"18.09.2025","th":["slabit","masa-musculara","nutritie"],"i":["Recompoziția (mâncat în jur de menținere, proteină suficientă, accent pe forță) e mai lentă, dar eviți bulk-urile murdare și tăierile prea dure.","Nu iei 20-40 lbs de mușchi în 3 luni, dar progresezi lent și arăți bine tot anul, în loc să pierzi jumătate de an detestându-ți aspectul."],"e":[],"c":["nu 20 sau 40 lbs de mușchi în 3 luni"]},{"v":"DoZMGROx4mw","k":"l","t":"My Pull Day to Get Jacked (Step-by-Step)","d":"16.09.2025","th":["spate","incalzire","failure-si-progresie","accidentari-si-articulatii"],"i":["Ziua de tras: o tracțiune verticală, un rând orizontal, două mișcări pentru deltoidul posterior și un exercițiu pentru biceps; 4-5 exerciții pe sesiune, un set la eșec.","Încălzire: 5 minute pe bandă sau mers înclinat (uneori 10), apoi circuit cu bandă elastică; la primul exercițiu 2-3 seturi crescătoare, 2-3 minute pauză, apoi setul real.","La exercițiile următoare face doar un set de încălzire ușor sau fără greutate, ca să mimeze mișcarea.","Singurul obiectiv: să-ți bați varianta anterioară; dacă ai 3x10, treci la 3x11, 3x12, apoi la 3x8 cu 5 lb în plus. Pe un an privești o creștere clară a greutăților.","Nu umbla la program cât ești încă slab: cine nu are 135 lb la bench sau 5 tracțiuni are nevoie de forță. Urmează un sistem 2-3 ani, apoi lucrezi punctele slabe.","El a început să simtă inflamație la cotul exterior (tennis elbow), pe care o leagă de surf plus eșec; a trecut de la curl cu gantere pe înclinat la cablu."],"e":[["Wide grip lat pulldown","aproape 200 lb la setul de lucru; încălzire cu 2-3 seturi"],["Horizontal row","urcă de la 8 la 9 repetări"],["Reverse pec deck","130 lb x 8 data trecută, țintă 9; două mișcări de deltoid posterior"],["Cable curl","înlocuiește curl-ul cu gantere pe înclinat din cauza cotului"],["Band circuit","lateral raises, overhead press, curls, face pulls, 2-3 seturi"]],"c":["3 zile pe săptămână","un set la eșec","4-5 exerciții pe sesiune","5 minute pe bandă, uneori 10 minute incline walk","2-3 seturi crescătoare","2-3 minute pauză","pulldown aproape 200 lb","130 lb x 8 apoi 9","3x10, 3x11, 3x12, apoi 3x8 și +5 lb","bench 135 lb și 5 tracțiuni ca repere","40-50 lb în plus peste un an"]},{"v":"8aLmwbpaDKg","k":"s","t":"Mike Mentzer - this is the best bicep exercise in the world!","d":"15.09.2025","th":["brate","mike-mentzer","tehnica"],"i":["Tracțiunea la piept cu priză îngustă supinată e prezentată (în stil Mentzer) ca cel mai bun exercițiu de bicepși, mai bun decât orice flexie.","Argument: bicepsul lucrează peste cot și umăr, deci se contractă mai uniform, în loc să încarce doar partea de jos ca la flexii."],"e":[["close grip palms up pulldown","lucrează bicepsul peste două articulații, cot și umăr"]],"c":[]},{"v":"2PAEqnix-3c","k":"l","t":"Fitness Influencers Are Killing Your Gains","d":"13.09.2025","th":["principii-antrenament","mentalitate","program-si-split"],"i":["Pe măsură ce consumi mai mult conținut despre fitness, acumulezi contradicții, nu cunoștințe, iar fizicul nu se schimbă.","Regula unei singure surse: alege un program de la o persoană de încredere, urmează-l ani de zile fără ajustări și lasă progresul să se adune.","Bazele: mișcări compuse principale, accesorii pentru punctele slabe, 3-4 zile pe săptămână, progres în timp, proteină suficientă și recuperare, repetate ani la rând.","Mulți înlocuiesc antrenamentul cu discuții despre antrenament; disciplina și acțiunea contează mai mult decât informația în plus."],"e":[],"c":["3-4 zile pe săptămână","sub 4 ore pe săptămână în sală"]},{"v":"g2xupcEgBwQ","k":"s","t":"Leave the gym knowing you gave it everything","d":"12.09.2025","th":[],"i":[],"e":[],"c":[]},{"v":"oWs75O_hgvQ","k":"s","t":"Building muscle is boring 🤷‍♂️","d":"11.09.2025","th":["program-si-split","mentalitate","recuperare-si-somn"],"i":["Alege acum un program de 3-4 zile pe săptămână și nu mai schimba; urmărește progresul în fiecare antrenament.","În afara sălii aranjează somnul, mâncarea, hidratarea și stresul."],"e":[],"c":["3-4 zile pe săptămână"]},{"v":"B0hrQjo9V-A","k":"s","t":"Don’t let your body get old without seeing what it's capable of","d":"10.09.2025","th":["mentalitate","incepatori"],"i":["Nu ai nevoie de o rutină complicată: mișcă-te într-un fel care îți place și rămâi activ.","Autorul face surf, skate, 3 antrenamente pe săptămână și mers pe jos aproape zilnic."],"e":[],"c":["3 antrenamente pe săptămână"]},{"v":"W5LGNfps21Q","k":"l","t":"The Mike Mentzer Inspired Routine I’m Using to Get Jacked","d":"09.09.2025","th":["mike-mentzer","program-si-split","volum-si-frecventa","failure-si-progresie"],"i":["Rutina lui actuală, inspirată de Mentzer: un singur set la eșec complet pe exercițiu, apoi recuperare, în loc de cele 10-20 de seturi pe grupă recomandate de obicei.","Nu o recomandă începătorilor sau celor intermediari timpurii; fizicul lui s-a construit cu un upper/lower, iar asta e un experiment după 10 ani.","Split de 3 zile push, legs, pull (nu push, pull, legs), pentru mai mult repaus între zilele de sus; exemplu: marți push, joi legs, sâmbătă pull, apoi două zile libere.","Șablon: push = presă piept, fly, presă umeri, lateral raise, triceps; pull = tragere verticală și orizontală, 2 deltoid post., biceps; legs = presă, quad, curl, hinge.","Pe prima mișcare câteva seturi crescătoare, apoi un set total la eșec, cu pauză de câteva minute. Spune că a avut PR-uri aproape la fiecare mișcare, lună de lună.","Programul e un șablon: adaptează exercițiile la echipament, de exemplu tracțiuni cu greutăți dacă nu ai lat pulldown."],"e":[["Chest press / fly / shoulder press / lateral raise / triceps isolation","ziua de push"],["Vertical pull / horizontal pull / two rear delt movements / biceps isolation","ziua de pull"],["Main pressing movement / quad isolation / knee flexion / hip hinge","ziua de legs; uneori hanging knee raises sau cable crunches"],["Weighted pull-ups","alternativă la lat pulldown acasă"]],"c":["10-20 de seturi pe grupă pe săptămână, recomandarea standard","un set la eșec","3 zile: marți push, joi legs, sâmbătă pull","două zile libere","10 ani de antrenament"]},{"v":"V06J3GuJojA","k":"s","t":"Being Jacked Doesn’t Mean You’re Healthy","d":"08.09.2025","th":["recuperare-si-somn","accidentari-si-articulatii","nutritie"],"i":["Aspectul musculos nu înseamnă sănătate: antrenamentul excesiv, somnul puțin, cofeina, mâncarea procesată și stresul duc la accidentări și probleme.","Scopul antrenamentului nu e să arăți bine câțiva ani și apoi să cazi."],"e":[],"c":[]},{"v":"h0N3lCtXVLw","k":"s","t":"Want Better Gains? Start With These Health Swaps","d":"06.09.2025","th":["nutritie","altceva"],"i":["Schimbări pentru sănătate: filtru de apă cu osmoză inversă, vase din inox sau fontă în loc de cele cu înveliș, recipiente de sticlă, sticle din inox sau sticlă.","Argumentul autorului: reziduuri mici zilnic, ani de zile, pot afecta hormonii și digestia."],"e":[],"c":[]},{"v":"mzRvth4cvs0","k":"s","t":"Mike Mentzer - The BEST Chest Exercise of all time!","d":"05.09.2025","th":["mike-mentzer","piept","umeri","brate"],"i":["Mentzer: dips sunt cel mai bun exercițiu pentru piept, umeri și triceps; trei gimnaști la paralele aveau dezvoltare de culturiști avansați fără să ridice greutăți."],"e":[["dips"]],"c":["3 gimnaști"]},{"v":"gFXiGCz8oCo","k":"l","t":"How To Lose Fat And Build Muscle At The Same Time (Step By Step)","d":"04.09.2025","th":["slabit","masa-musculara","nutritie","recuperare-si-somn"],"i":["Recompoziția înseamnă să crești mușchi și să pierzi grăsime simultan, mâncând în jur de mentenanță; e mai lentă decât bulk sau cut, dar arăți bine tot anul.","Nu e pentru toți: foarte slab și începător are nevoie de lean bulk (300-500 kcal peste mentenanță); foarte supraponderal se concentrează pe deficit de 500 kcal.","Recomp e pentru cei din mijloc: exemplu cu 6 ft, 195 lb și 16-20% grăsime ajunge, în același cântar, la 10-12% grăsime.","Antrenamentul rămâne prioritar: intensitate și supraîncărcare progresivă; contestă ideea că rezultatele sunt 80% mâncare.","Mănâncă puțin peste mentenanță dacă ești slab și vrei mărime, puțin sub dacă ești mai moale; 1 g proteină pe lb din greutatea țintă și somn de 7-9 ore.","Nu vei câștiga 20-40 lb de mușchi în 3 luni, dar vei arăta bine tot anul."],"e":[],"c":["+300-500 kcal peste mentenanță pentru lean bulk","deficit de 500 kcal pentru foarte supraponderali","6 ft, 195 lb, 16-20% grăsime","10-12% grăsime la același cântar","1 g proteină pe lb din greutatea țintă","somn 7-9 ore","aproape 10 ani cu același fizic"]},{"v":"OdfMkfIic4s","k":"l","t":"My No BS Exercise Guide To Building An Aesthetic Body","d":"01.09.2025","th":["piept","spate","umeri","picioare"],"i":["Pentru un look estetic: slab, spate lat și proporții echilibrate, nu masă extremă; alege exerciții în funcție de ce vrei să țintești.","Piept: presa cu gantere pe înclinat (majoritatea au partea de sus rămasă în urmă) plus un fly, la aparat sau cu gantere.","Spate: un lat pulldown cu priză largă pentru lățime și un T-bar row cu sprijin la piept pentru grosime, cu alternative la rânduri.","Brațe: curl pe înclinat și cu bara, pushdown și extensii overhead cu V-bar. Umeri: lateral raises obligatorii, reverse pec deck pentru spate; rotești la câteva luni.","Picioare: genuflexiune sau presă, leg extension, leg curl și un hinge (RDL sau trap bar), pentru că ischiogambierii lucrează la șold și la genunchi.","Abdomenul nu l-a antrenat direct niciodată; dacă o face, cable crunch, uneori hanging leg raises. Spune că abdomenul se vede când ești suficient de slab."],"e":[["Incline dumbbell press","mișcarea principală de împins"],["Pec deck / dumbbell fly"],["Wide grip lat pulldown"],["Chest supported T-bar row"],["Incline dumbbell curls"],["Barbell curls"],["Triceps pushdowns","cu V-bar"],["Overhead extension","cu V-bar"],["Lateral raises","gantere, cabluri sau aparat"],["Reverse pec deck","deltoid posterior"],["Barbell squat","folosită mult; recent mai mult leg press"],["Leg press"],["Seated leg extension"],["Lying leg curl / seated curl"],["Romanian deadlift / trap bar deadlift","hinge"],["Cable crunch","hanging leg raises pentru mai mult volum"]],"c":["peste 10 ani în sală","aproximativ 100 de mișcări încercate"]},{"v":"vfCCfoH3yrs","k":"s","t":"10 Years of Lifting Advice In under 2 minutes.","d":"01.09.2025","th":["principii-antrenament","recuperare-si-somn","mentalitate"],"i":["Cinci lecții după 10 ani: stimulul de creștere e universal, recuperarea e individuală, caietul de antrenament arată adevărul, uneori mai puțin înseamnă mai mult.","Nu te compara cu alții; singurul adversar e performanța ta din săptămâna trecută din caiet."],"e":[],"c":["peste 10 ani de antrenament","5 lecții"]},{"v":"kMQBfkHgrUQ","k":"s","t":"Why You Shouldn’t Train Just to Get Huge","d":"30.08.2025","th":["mentalitate","accidentari-si-articulatii","varsta"],"i":["Obiectivul autorului nu e masa maximă, ci forță, estetică și longevitate: să rămână atletic și fără dureri cu vârsta.","Menține antrenamentul simplu, dar intens, ca să evite accidentările din supraantrenament."],"e":[],"c":["10 ani","~10% grăsime"]},{"v":"aADAMAAAjY4","k":"s","t":"This is why most guys stay average and never build their dream physique","d":"29.08.2025","th":["mentalitate","program-si-split","recuperare-si-somn"],"i":["Șablon zilnic: 3-4 antrenamente pe săptămână, peste 8.000 de pași, 3-4 mese cu proteine, 7-8 ore de somn, respectat cel puțin 6 luni.","Pune planul la vedere și bifează-l la sfârșitul fiecărei zile."],"e":[],"c":["3-4 antrenamente pe săptămână","8.000+ pași","3-4 mese cu proteine","7-8 ore somn","6 luni"]},{"v":"1xX6RbnD7sw","k":"s","t":"Maximizing Gains is Overrated (Here’s Why I Don’t Do It)","d":"28.08.2025","th":["mentalitate","principii-antrenament"],"i":["Autorul nu își maximizează câștigurile cu orice preț: nu renunță la skate, surf, ciclism sau excursii doar pentru încă ~5% mușchi.","Stilul bodybuilderului te leagă de sală și de mese controlate; el preferă un echilibru care lasă loc vieții."],"e":[],"c":["~5% mușchi în plus"]},{"v":"CUbYdJBj3YU","k":"l","t":"It Took Me 10 Years In The Gym To Learn What I’ll Teach You In 5 Minutes","d":"26.08.2025","th":["principii-antrenament","recuperare-si-somn","failure-si-progresie","mentalitate"],"i":["Stimulul de creștere e universal: împingi mușchiul peste capacitatea lui actuală, cu plan și intensitate mai mare decât data trecută, nu cu pump sau ore în sală.","Recuperarea e individuală: unii suportă 5 zile pe săptămână, alții mai puține. Începe cu 4 zile și întreabă-te dacă greutatea sau repetările au crescut măcar puțin.","Jurnalul de antrenament nu minte: forța într-un interval moderat de repetări e indicatorul principal al mărimii; nimeni nu a crescut fără să devină mai puternic.","Uneori mai puțin înseamnă mai mult; câteva progrese mari au venit după ce a scăzut volumul și a lăsat corpul să se adapteze.","Compară-te doar cu tine din jurnalul săptămânii trecute; chiar un progres lent înseamnă că mergi bine."],"e":[],"c":["peste 10 ani în sală","început de 4 zile pe săptămână","5 lecții"]},{"v":"SOANI6TeFvw","k":"s","t":"Mike Mentzer's workout routine - Day 3","d":"25.08.2025","th":["mike-mentzer","umeri","brate","failure-si-progresie"],"i":["Ziua 3 din rutina heavy duty a lui Mentzer: toate seturile la failure, 6-10 repetări, lente și controlate, bară dreaptă la curl.","Între push-down-uri și dips pauza e de 3-5 secunde; în total sunt doar cinci seturi."],"e":[["dumbbell lateral raises"],["reverse pec deck","pentru deltoidul posterior"],["barbell curls","bară dreaptă, nu easy bar, repetări lente"],["cable tricep push downs","cu V bar"],["dips","imediat după push-downs, pauză 3-5 secunde"]],"c":["6-10 repetări","5 seturi în total","pauză 3-5 secunde"]},{"v":"ugjgT0Cd5X4","k":"l","t":"Big Muscles Don’t Mean You’re Healthy","d":"24.08.2025","th":["recuperare-si-somn","nutritie","principii-antrenament","accidentari-si-articulatii"],"i":["Mușchii mari nu înseamnă sănătate; antrenamentul excesiv, somnul puțin, cafeina, energizantele și mâncarea procesată duc la accidentări și probleme.","Antrenează-te 3-4 zile pe săptămână cu compuse mari, intensitate și notarea progresului; în zilele libere cardio ușor sau abdomene, nu antrenament epuizant.","El vrea să rămână atletic cu vârsta, deci să facă skateboard și surf fără să-l doară articulațiile, nu să fie cât mai mare cu orice preț.","Contează și din ce sunt făcute caloriile: procesatele (zahăr adăugat, coloranți, uleiuri de semințe) i se par rele pentru energie și hormoni; zice că nu e sfat medical.","Schimbări sugerate: filtru de apă cu osmoză inversă, vase de inox sau fontă, recipiente de sticlă, sticle de inox sau sticlă; te îndeamnă să cercetezi singur."],"e":[],"c":["10 ani de antrenament","aproximativ 10% grăsime corporală","3-4 zile pe săptămână"]},{"v":"afR3tPH6y_g","k":"s","t":"Barbell Overhead Press (How To | Form Tutorial)","d":"22.08.2025","th":["umeri","tehnica"],"i":["Overhead press: stai cu picioarele la lățimea umerilor, abdomen și fese încordate, priză overhand puțin mai largă decât umerii, pauză pe piept, apoi împingi vertical.","Fixează sus bicepșii în dreptul urechilor, bara să nu se ducă înainte; fără leg drive, altfel devine push press."],"e":[["barbell overhead press","picioare la lățimea umerilor, priză puțin peste umeri, pauză scurtă pe piept, împins vertical, strict, fără leg drive"]],"c":[]},{"v":"b8WRWoCVeEI","k":"s","t":"Should you bulk or cut first?","d":"20.08.2025","th":["slabit","masa-musculara","nutritie"],"i":["Slab și fără grăsime: lean bulk cu surplus de ~300 kcal. Peste 20% grăsime: tai întâi, cu deficit mic.","Skinny fat: cele mai bune rezultate pe termen lung vin tăind întâi, apoi lean bulk."],"e":[],"c":["surplus 300 kcal","peste 20% grăsime"]},{"v":"DkmwOTYBrgE","k":"l","t":"The Truth About ‘Maximizing’ Gains (And Why It’s a Trap)","d":"19.08.2025","th":["volum-si-frecventa","principii-antrenament","mentalitate","nutritie"],"i":["Maximizarea înseamnă somn urmărit pe scoruri, mâncare cântărită și cronometrată, 6-7 zile de sală și renunțat la hobbyuri; poate dă câteva procente, pe seama libertății.","Trei sesiuni intense bat 6-7 mediocre. Nu ai nevoie de precizie la gram, doar proteină suficientă și calorii apropiate de țintă.","Antrenamentul de 3-4 zile merge dacă ai intensitate, exerciții alese bine, formă corectă, supraîncărcare progresivă, monitorizare și constanță.","Planul lui: trei sesiuni scurte și intense pe săptămână, compuse grele cu progres, accesorii pentru echilibru, mâncare reală, pași, soare și surf sau skateboard.","Dacă visul tău e să fii culturist, fă ce fac ei; majoritatea vor doar să arate bine, să fie puternici și să aibă o viață în afara sălii."],"e":[],"c":["3-4 zile pe săptămână","3 sesiuni intense pe săptămână","aproximativ 5% mai mult mușchi, ca exemplu al câștigului maxim"]},{"v":"FFZx1cpuwkw","k":"l","t":"I Trained Like Mike Mentzer For 30 Days","d":"16.08.2025","th":["mike-mentzer","failure-si-progresie","volum-si-frecventa","incepatori"],"i":["Experiment de 30 de zile după Mentzer: frecvență mică, intensitate mare, un singur set la eșec în loc de trei pe exercițiu.","Avantaje găsite: ideea de intensitate reală, mai multă recuperare, motivație mai mare, PR-uri la toate mișcările și mai mult timp pentru alte pasiuni.","Părerea lui despre dezavantaje: nu e pentru începători, care nu știu ce e eșecul real; fără intensitate maximă, volumul mic nu merge, iar ei au nevoie de mai mult volum.","Nu a fost de acord cu superseturile și static holds, plus pauza de 4-7 zile între antrenamente; consideră trucurile de felul acesta inutile.","Pentru intermediari târzii sau avansați curioși, încercarea nu strică; el s-a întors la split-ul de 3 zile push, legs, pull."],"e":[["Supersets","nu i-au plăcut"],["Static holds","nu i-au plăcut"]],"c":["30 de zile","de la 3 seturi pe exercițiu la 1 set","4 zile de pauză între antrenamente în varianta Mentzer, 6-7 la platou","7 zile pe săptămână la început","5 ani pe sistemul propriu","3 zile push, legs, pull"]},{"v":"YfhmAm7PnqA","k":"s","t":"The secret to building a jacked physique","d":"14.08.2025","th":["mentalitate","principii-antrenament"],"i":["Nu există secret la creșterea naturală: consecvență, efort și timp; antrenează-te greu și nu mai gândi excesiv."],"e":[],"c":[]},{"v":"d57ZJN61p8Q","k":"s","t":"Mike Mentzer's workout routine - Day 2","d":"13.08.2025","th":["mike-mentzer","picioare"],"i":["Ziua de picioare a lui Mentzer: leg extension, leg press, lying leg curl și standing calf raise, fiecare cu un singur set all-out.","El nu recomanda antrenarea picioarelor din nou 5-8 zile."],"e":[["leg extensions"],["seated leg press"],["lying leg curls","adăugat pentru că nu se face deadlift în ziua de spate"],["standing calf raises"]],"c":["4 exerciții","1 set all-out","5-8 zile pauză"]},{"v":"KKI_Kf6wFRw","k":"s","t":"Mike Mentzer's workout routine - Day 1","d":"12.08.2025","th":["mike-mentzer","program-si-split","piept","spate"],"i":["Ziua 1 din rutina de bază a lui Mentzer: pec deck 6-10 repetări, imediat (3-5 secunde) incline chest press la mașină 1-3 repetări, apoi pauză cât e nevoie.","Apoi underhand lat pulldown 6-10 repetări și conventional deadlift 5-10 repetări; patru exerciții la eșec total, singurul superset fiind fly + press."],"e":[["pec deck chest fly","6-10 repetări, apoi imediat superset"],["incline chest press machine","1-3 repetări, în 3-5 secunde după fly"],["underhand grip lat pulldown","6-10 repetări"],["conventional deadlift","5-10 repetări"]],"c":["6-10 repetări","1-3 repetări","3-5 secunde","5-10 repetări","4 exerciții"]},{"v":"YYnOi3kxnoU","k":"l","t":"Stop Overcomplicating How to Get Jacked","d":"10.08.2025","th":["volum-si-frecventa","program-si-split","recuperare-si-somn","nutritie"],"i":["Frecvența contează doar până la un punct: cu același volum săptămânal pe grupă rezultatele sunt apropiate; programul pe care îl ții bate un câștig de 1-3%.","La upper/lower ar alterna ordinea în a doua zi de sus, ca spatele sau pieptul să nu vină mereu la final, când ești obosit.","Somn 7-9 ore, minim 7. Cu un inel de somn a aflat că intra în somn adânc abia după 1-2 noaptea; limitează mâncatul târziu și ecranele înainte de culcare.","Standardele de forță sunt individuale; mai util să-ți propui să dublezi ce faci acum (de exemplu bench 135 lb în sus cu 100 lb) decât să urmărești 225/315/405.","Dacă te blochezi, verifică somnul, mâncarea, stresul și apa; apoi deload sau schimbă un exercițiu. La eșec seturile nu se potrivesc, dar bate măcar un set pe antrenament.","Mâncare simplă cu puține ingrediente: orez, cartofi, fructe, miere, vită, pui, avocado, ulei de măsline; mofturos sau nu, trebuie să treci peste."],"e":[["Upper/lower","alternează ordinea împins/tras între cele două zile de sus"]],"c":["3-4 zile pe săptămână","3-4 zile aduc 99% din câștiguri","7-9 ore de somn","bench 225, squat 315, deadlift 405, pull-ups 15-20, ca repere date","bench 135 lb plus 100 lb","8.000 de pași pe zi","30-45 minute de mers","1-2 repetări rezervă pentru începători","8-7-6 apoi 9-8-7 ca exemplu de progres la eșec","1-3% câștig în plus de la frecvență","4-5 zile pentru concurenți, spune el"]},{"v":"KuNi6rk_YqY","k":"l","t":"Why Less Training = More Muscle (Seriously)","d":"06.08.2025","th":["volum-si-frecventa","principii-antrenament","accidentari-si-articulatii","recuperare-si-somn"],"i":["Mai multe seturi, zile și trucuri (drop sets, superseturi, 30 de repetări) dau pump, nu progres; fără notare și progres în greutate sau repetări, creșterea se oprește.","Exemplu: cineva de peste 40 de ani, accidentat, a scăzut volumul și zilele și a simțit mai multă forță, mai puțină oboseală și aproape zero dureri în câteva săptămâni.","Nu există hack, ci un program ales și ținut: 3-4 zile pe săptămână, intensitate, progres măcar într-o formă la fiecare antrenament și recuperare bună.","Alege un program legitim și rămâi pe el: să-ți placă puțin și să fie sustenabil. El a construit fizicul pe un upper/lower de 4 zile.","Nu ai nevoie de metode complexe (drop sets, superseturi, rest pause, reverse pyramid); somn, mâncare, hidratare și stres contează pentru recuperare."],"e":[["6-second negatives","i-a fost întrebat; răspunsul lui: nu e un hack, ci mai puțin și mai intens cu progres"]],"c":["3 zile pe săptămână, sub o oră","3-4 zile recomandate","4 zile upper/lower, cum și-a construit fizicul","șase zile pe săptămână, 30 de repetări pe set și 8 exerciții, la cei doi observați","4:00 dimineața"]},{"v":"-zJay051lPE","k":"s","t":"Stop looking for shortcuts, it takes years to get jacked!","d":"04.08.2025","th":["mentalitate","incepatori","principii-antrenament"],"i":["Nu există scurtături: un fizic cu adevărat dezvoltat durează ani de antrenament constant, iar cei cu fizic de elită au 3, 5 sau peste 10 ani de sală.","Cine vinde un plan de 30 de zile pentru abdomene vrea să vândă ceva; acceptă drumul lung ca să nu mai pierzi timp cu minuni."],"e":[],"c":["3, 5 și peste 10 ani de antrenament constant","plan de 30 de zile (criticat)"]},{"v":"tq-WkxYtxt4","k":"l","t":"The Overthinker’s Guide to Getting Jacked (Follow This Exactly)","d":"02.08.2025","th":["program-si-split","failure-si-progresie","nutritie","mentalitate"],"i":["Alege un singur program și nu schimba nimic cel puțin 6 luni, ideal un an; schimbatul continuu te readuce la zero.","Antrenează upper/lower de 3 sau 4 ori pe săptămână, cu aceleași două zile repetate, ca să rămâi consecvent.","Începe fiecare exercițiu cu 3x6 la o greutate la care ai putea face 7-8; crești repetările până la 3x10, apoi adaugi greutate și revii la 6.","Treci mai departe doar când toate seturile au același număr de repetări, de exemplu 7-7-7 înainte de a urca la 8.","Setează reguli zilnice nenegociabile (antrenament, pași, mese cu proteine, somn) și bifează-le într-un tracker în fiecare seară."],"e":[["incline dumbbell press","zi upper, 6-10 repetări"],["wide grip lat pulldown","zi upper"],["machine or dumbbell chest fly","zi upper"],["T-bar row","zi upper"],["cable lateral raise","zi upper"],["incline dumbbell curl","zi upper"],["cable overhead tricep extension","zi upper"],["squat or leg press","zi lower"],["hamstring curl or Romanian deadlift","zi lower"],["leg extension","zi lower"],["trap bar deadlift","zi lower"],["calf raise","zi lower"],["hanging knee raise","zi lower"]],"c":["upper/lower de 3 sau 4 ori pe săptămână","6-10 repetări la toate exercițiile","pauză 2 minute la început, apoi 3 minute la compuse și 1-2 minute la izolări","start 3 seturi x 6 repetări, țintă 3 x 10","adaugi aproximativ 5 lbs (sau 2 kg) după 3x10","proteine: 1 g per pound de greutate țintă","bulking: greutate x 16-18 kcal; cutting: greutate x 12-14 kcal","surplus de 300 kcal la lean bulk","25-30% din calorii din grăsimi","8.000+ pași pe zi","3-4 mese cu proteine","somn 7-8 ore","peste 20% grăsime corporală: cut mai întâi"]},{"v":"QM7AhYdwbvo","k":"s","t":"What I've learned from Mike Mentzer...","d":"30.07.2025","th":["mike-mentzer","failure-si-progresie","volum-si-frecventa"],"i":["Autorul a trecut de la 3 seturi la 1 set la eșec pe exercițiu și spune că a bătut recorduri la fiecare antrenament în două luni, în 30-40 de minute.","Nu se consideră inventator: testează o altă cale, iar există mai multe moduri de a deveni musculos."],"e":[],"c":["de la 3 seturi la 1 set","30-40 minute","două luni","2 ore și fără zile libere (trecutul autorului)"]},{"v":"ccncKLw5pEE","k":"l","t":"Mike Mentzer's Ideal Routine - Day 3","d":"29.07.2025","th":["mike-mentzer","umeri","brate","failure-si-progresie"],"i":["Rutina Heavy Duty din ziua 3 are doar 5 seturi totale, toate duse la eșec absolut, în zona de 6-10 repetări.","Repetările se fac lent și controlat; la curl se folosește bară dreaptă, nu EZ, iar la tricepși bară dreaptă sau V, nu coardă.","Între tricepși la scripete și dips e singurul superset al rutinei, cu doar 3-5 secunde pauză.","Dacă faci peste 5 repetări la dips cu greutatea corpului, adaugi greutate cu centura.","Autorul experimentează stilul, dar spune că nu așa și-a construit fizicul; începătorii să nu schimbe programul ca să nu stagneze."],"e":[["dumbbell lateral raise","la eșec, 6-10 repetări, lent și controlat"],["reverse pec deck","înlocuiește bent over dumbbell flies recomandate de Mentzer; pentru deltoidul posterior"],["barbell curl","bară dreaptă, priză puțin mai largă"],["cable tricep pushdown","bară dreaptă sau V, superset imediat cu dips"],["dips","pauză 3-5 secunde după pushdown; cu centură dacă faci peste 5 repetări"]],"c":["5 seturi totale","6-10 repetări","pauză 3-5 secunde între pushdown și dips","încălzire: 5-10 minute treadmill înclinat, apoi 1-2 seturi crescătoare per exercițiu","autorul antrenează 2-3 zile pe săptămână cu 4-5 seturi pe antrenament"]},{"v":"3cF08ANMo2I","k":"s","t":"Mike Mentzer's Favorite Bicep Exercise Of All Time","d":"29.07.2025","th":["brate","mike-mentzer","tehnica"],"i":["Tracțiunea la piept cu priză îngustă supinată (close grip palms up pulldown) e prezentată ca cel mai bun exercițiu de bicepși, mai bun decât orice flexie.","Motivul: lucrează bicepsul peste două articulații (cot și umăr), deci mușchiul se contractă mai uniform, nu doar partea de jos ca la flexii."],"e":[["close grip palms up pulldown","priză îngustă, palmele spre tine; lucrează bicepsul peste cot și umăr"]],"c":[]},{"v":"eQjMgauy73o","k":"s","t":"You don't need a complicated meal plan to get jacked","d":"28.07.2025","th":["nutritie","masa-musculara"],"i":["Nu ai nevoie de plan complicat: 3-4 mese echilibrate din alimente întregi pe zi, repetate dacă ajută.","Dacă nu mănânci destul nu crești, iar fără regularitate nu te recuperezi."],"e":[],"c":["3-4 mese pe zi"]},{"v":"f8s0jUFvcqI","k":"l","t":"I Would’ve Stuck to My Diet Sooner If I Knew This","d":"27.07.2025","th":["nutritie","mentalitate","slabit"],"i":["Scrie-ți clar motivul pentru care ții dieta și citește-l în fiecare dimineață; el te ține în zilele fără chef.","Nu privi dieta ca pe o soluție de scurtă durată: pornește de la mesele tale curente, făcute mai curate și gătite acasă.","Evită dietele extreme (keto, carnivor, provocări de pe rețele); alege mâncare simplă, integrală, pe care o poți ține 6 luni.","Se poate mânca bine și slăbi sau defini, dacă controlezi cantitatea."],"e":[],"c":["plan de ținut cel puțin 6 luni"]},{"v":"q1xV4n5hKFY","k":"s","t":"Mike Mentzer - Heavy Duty (Legs)","d":"27.07.2025","th":["mike-mentzer","picioare"],"i":["Rutina de picioare Heavy Duty: leg extension la failure, apoi fără pauză leg press sau squat (superset), pauză scurtă, leg curl, pauză, un set de gambe.","Fiecare set în 6-10 repetări, la failure."],"e":[["leg extensions","6-10 repetări la failure"],["leg press sau squat","imediat după leg extension, superset, 6-10 repetări la failure"],["leg curls","după o pauză scurtă"],["calf raises","un set"]],"c":["6-10 repetări","1 set per exercițiu"]},{"v":"ZGjFuwj_FzM","k":"s","t":"This is killing your gains...","d":"26.07.2025","th":["mentalitate","principii-antrenament"],"i":["Consumul excesiv de conținut fitness te confuzează; alege un sistem care se potrivește vieții tale și rămâi la el."],"e":[],"c":[]},{"v":"qWbgVNn1wTg","k":"s","t":"This is why you're not gaining muscle...","d":"25.07.2025","th":["masa-musculara","principii-antrenament","recuperare-si-somn"],"i":["Dacă nu crești, rareori e genetica: verifică mâncatul, somnul, intensitatea, jurnalul, frecvența prea mare sau consecvența.","Găsește „gaura din găleată”, repar-o și creșterea pornește."],"e":[],"c":["6 cauze"]},{"v":"Bc8fhTiTBnI","k":"l","t":"Mike Mentzer's Ideal Routine - Day 1","d":"24.07.2025","th":["mike-mentzer","piept","spate","failure-si-progresie"],"i":["Ziua 1 din rutina Mentzer are doar 4 exerciții duse la eșec total; singurul superset e pec deck urmat imediat de împins la înclinat.","Între exerciții odihnești cât ai nevoie, dar nu mai mult decât e necesar; la deadlift poți înlocui cu un tip de ridicări de umeri (shrug) dacă ai probleme lombare.","Autorul spune că a progresat cel mai bine cu mai puțin volum, într-un split de 3-4 zile, iar acum face push/legs/pull de 3 ori pe săptămână.","Mergi la eșec complet doar când poți judeca bine eforturile; la prima încercare el a simțit că mai avea 1-2 repetări în rezervă."],"e":[["pec deck chest fly","6-10 repetări; alternativ dumbbell sau cable flies"],["incline chest press machine","1-3 repetări, imediat după fly (3-5 secunde); alternativ incline barbell sau Smith machine"],["underhand grip lat pulldown","6-10 repetări"],["conventional deadlift","5-10 repetări; poate fi înlocuit cu shrugs"]],"c":["4 exerciții","6-10 repetări la fly","1-3 repetări la incline press","3-5 secunde între fly și incline press","5-10 repetări la deadlift","antrenament actual: 3 zile pe săptămână"]},{"v":"02Qci1-0Aao","k":"s","t":"Wide Grip Lat Pulldown (How To | Form Tutorial)","d":"23.07.2025","th":["tehnica","spate"],"i":["La lat pulldown cu priză largă, fixează coapsele sub pernă și trage bara în linie dreaptă spre pieptul de sus, cu coatele în jos și înapoi.","Evită să te lași prea mult pe spate sau să folosești avânt; strânge latele jos și revino lent până la întindere completă."],"e":[["wide grip lat pulldown","priză pronată, puțin în afara lățimii umerilor; pornești din dead hang, bara la pieptul de sus, revenire lentă"]],"c":[]},{"v":"rAx_tf13V5k","k":"s","t":"Incline Dumbbell Curl (How To | Form Tutorial)","d":"22.07.2025","th":["brate","tehnica"],"i":["Incline dumbbell curl: bancă la 45-60 de grade, cap și umeri pe bancă, brațele atârnă cu palmele înainte, pornești din întindere completă, fără balans.","Ridici controlat strângând bicepsul și cobori lent la întindere completă."],"e":[["seated incline dumbbell curl","bancă la 45-60 de grade, palme înainte, întindere completă, fără elan"]],"c":["45-60 de grade"]},{"v":"y4uCrUu6VyM","k":"l","t":"Mike Mentzer's Ideal Routine - Day 2","d":"21.07.2025","th":["mike-mentzer","picioare","principii-antrenament","incepatori"],"i":["Ziua de picioare din rutina Mentzer are 4 exerciții, fiecare cu un singur set total până la eșec, apoi 5-8 zile de pauză pentru picioare.","Extensiile pentru cvadricepși se fac primele, ca la presa de picioare să limiteze cvadricepșii, nu fesierii sau ischiogambierii.","Flexiile culcat acoperă ischiogambierii când nu faci deadlift sau alte mișcări de tip hip hinge.","Autorul nu recomandă stilul unui începător: nu știe încă ce înseamnă eșecul real și profită de mai mult volum, care lasă loc de greșeli."],"e":[["leg extension","un singur set la eșec, primul în ordine"],["seated leg press","imediat după extensii, un set la eșec"],["lying leg curl","un singur set la eșec"],["standing calf raise","un singur set la eșec; autorul a folosit Smith machine cu discuri"]],"c":["4 exerciții, câte un set","5-8 zile până la următorul antrenament de picioare","autorul antrenează 3 zile pe săptămână"]},{"v":"bvHefkoO4hs","k":"s","t":"Focusing on Supplements? You're Doing It Backwards","d":"21.07.2025","th":["suplimente","incepatori","nutritie"],"i":["Suplimentele sunt cam 5% din ecuație; contează somnul, mâncarea nutritivă și antrenamentul consecvent.","Gândește-le ca punctaj extra, nu ca înlocuitor: un praf nu acoperă 5 ore de somn."],"e":[],"c":["5% din ecuație","5 ore de somn"]},{"v":"v7xpJJYUc_E","k":"s","t":"if it fits your macros is BS!","d":"17.07.2025","th":["nutritie","slabit"],"i":["„If it fits your macros” ignoră calitatea mâncării: sursa, uleiurile și prepararea contează, iar mâncarea influențează și creierul și starea generală.","Poți slăbi mâncând orice, dar asta nu înseamnă că ar trebui; autorul compară corpul cu o mașină frumoasă pe dinafară și ruginită în motor."],"e":[],"c":[]},{"v":"g0c_c7NER5s","k":"l","t":"What I’ve Learned From Mike Mentzer (After 10+ Years of Lifting)","d":"16.07.2025","th":["mike-mentzer","principii-antrenament","volum-si-frecventa","failure-si-progresie"],"i":["Autorul a scăzut de la 6 zile și peste 20 de seturi pe grupă la 2-3 zile și 4-6 seturi mai grele și spune că a bătut recorduri la fiecare antrenament.","Folosește câte un singur set la eșec complet pe exercițiu, cu 72 de ore pauză între push și pull și 48 între celelalte, ședințe de 30-40 de minute.","Susține că sfaturile din fitness sunt făcute pentru sportivi cu substanțe; naturalii recuperează mai greu și au nevoie de mai puțin volum.","Pune în discuție dacă 4-6 seturi pe săptămână dau cam 95% din câștig față de 10-20, cu mai puțin timp și uzură; prezentat ca părere proprie, nu ca regulă.","Nu există un singur program corect: contează ce te ține fără accidentări și constant."],"e":[["incline dumbbell bench","un set la eșec complet"],["machine chest fly","un set la eșec"],["chest press","un set la eșec"],["cable lateral raise","un set la eșec"],["overhead tricep extension","uneori, un set la eșec"]],"c":["de la 6 zile la 2-3 zile pe săptămână","de la peste 20 la 4-6 seturi pe grupă","de la 3 seturi la 1 set pe exercițiu","72 de ore între push și pull","48 de ore între celelalte zile","30-40 de minute pe antrenament","10-20 de seturi pe grupă (cercetarea citată)","95% din câștig (ipoteza autorului)"]},{"v":"Exc5Iey3X4E","k":"s","t":"Do THIS to get the best gains of your life","d":"15.07.2025","th":["failure-si-progresie","principii-antrenament"],"i":["La fiecare antrenament, bate cel puțin un set la un exercițiu; nu e nevoie de toate seturile, dar repetările și greutatea trebuie să crească în timp.","Antrenamentele nu ar trebui să fie ușoare; autorul recunoaște că uneori se teme de ele pentru că te scot din zona de confort."],"e":[],"c":["cel puțin un set bătut pe antrenament"]},{"v":"e8aJXIpQaec","k":"s","t":"Lifting 3 to 4 days a week is best for 99% of lifters","d":"10.07.2025","th":["volum-si-frecventa","program-si-split","recuperare-si-somn"],"i":["Cu efort real, naturalii pot face 3-4 sesiuni pe săptămână de 45-60 de minute; antrenamentul mai bun bate pe cel mai mult.","Mulți nu sunt supraantrenați, ci subrecuperați; mai puțin antrenament îți dă timpul înapoi."],"e":[],"c":["3-4 sesiuni pe săptămână","45-60 de minute"]},{"v":"nHu6o4IHp0A","k":"l","t":"You’ve Been Lied To About Getting Jacked","d":"09.07.2025","th":["mentalitate","principii-antrenament","suplimente","incepatori"],"i":["Progresul real durează ani; cine promite un plan de 30 de zile vinde ceva, deci alege un program simplu și ține-l fără să sari de la unul la altul.","Suplimentele sunt cam 5% din rezultat și nu compensează somnul slab sau mâncarea slabă; creatina și proteina în pudră pot ajuta după ce baza e pusă.","Notează fiecare antrenament (exerciții, repetări, greutăți) și crește constant încărcătura; fără progresie corpul rămâne la fel.","Dacă nu crești, caută gaura din găleată: mănânci prea puțin, dormi puțin, nu antrenezi destul de greu, nu notezi, antrenezi prea des sau nu ești consecvent.","Mănâncă 3-4 mese echilibrate din alimente întregi pe zi; 3 zile de antrenament bun bat 6 zile mediocre, cu seturi aproape sau la eșec."],"e":[],"c":["progres de ordinul anilor, 3, 5 sau chiar peste 10 ani","suplimentele: aproximativ 5% din ecuație","3-4 mese pe zi","antrenament 3-4 zile pe săptămână","exemplu dat: 5 ore de somn"]},{"v":"ropcEmqYLYM","k":"s","t":"How to Stay Jacked for Life (10 Simple Rules)","d":"08.07.2025","th":["mentalitate","program-si-split","cardio-si-pasi","nutritie"],"i":["10 reguli: planifică seara, obiective dimineața, 3-4 antrenamente, 10.000 de pași, 3-5 mese fixe, pregătire în bloc, fără junk în casă, notează antrenamentele.","Mai adaugă rutină de somn și întrebarea ce ar face acum versiunea ta cea mai concentrată."],"e":[],"c":["3-4 zile","10.000 de pași","3-5 mese","5 ore de somn (greșeala)"]},{"v":"w0FDzY-ilPU","k":"l","t":"If I Had to Start Over Skinny and Wanted to Get Jacked, This Is Exactly What I’d Do","d":"06.07.2025","th":["incepatori","masa-musculara","failure-si-progresie","nutritie"],"i":["Pentru masă musculară, autorul ar antrena 3-4 zile pe săptămână, cu 3-4 exerciții și 1-2 seturi duse la eșec adevărat, nu doar greu.","Un plan scris îți permite să urmărești progresul; evită să improvizezi antrenamentul pe loc cu aparatele libere.","Urmărește caloriile câteva săptămâni, află menținerea și mănâncă cu 300-500 peste; dacă nu iei în greutate, nu mănânci destul.","Ține un singur program cel puțin un an și notează fiecare ridicare; fără progresie nu crești.","Lasă orgoliul: alege o greutate grea în 6-10 repetări și execută curat fiecare repetare, fără formă slabă pentru impresie."],"e":[],"c":["3-4 zile pe săptămână","3-4 exerciții per antrenament","1-2 seturi la eșec","surplus de 300-500 kcal peste menținere","autorul era cu 500-1.000 kcal sub necesar când credea că mănâncă mult","un program cel puțin un an","6-10 repetări"]},{"v":"xJC5Rj2K9Kk","k":"l","t":"If I Wanted To Become Jacked in 2025, This Is What I'd Do [FULL BLUEPRINT]","d":"03.07.2025","th":["mentalitate","program-si-split","cardio-si-pasi","nutritie"],"i":["Planifică ziua în seara dinainte (haine de sală, ora antrenamentului, mese pregătite) și începe dimineața cu obiectivele scrise, nu cu telefonul.","Antrenează 3-4 zile pe săptămână și mergi pe jos zilnic; autorul face o plimbare de 30-45 de minute în zilele de sală și două în zilele libere.","Rotește 3-5 mese de bază pe care le repeți zilnic (proteină, carbohidrat, grăsime sănătoasă), evită ultraprocesatele și gătește în avans de 1-2 ori pe săptămână.","Scoate gustările și mâncarea procesată din casă, ca să pui o barieră între tine și impuls.","Notează fiecare sesiune și încearcă să progresezi; dormi 7-8 ore, fără ecrane înainte de culcare, cu draperii opace și cameră răcoroasă."],"e":[],"c":["3-4 zile de antrenament pe săptămână","10.000 de pași pe zi","plimbare 30-45 de minute în zilele de antrenament","2 plimbări pe zi în zilele libere","3-5 mese de bază","gătit în avans de 1-2 ori pe săptămână","somn 7-8 ore","ecrane oprite cu 1 oră înainte de somn","autorul a menținut definiția aproape 10 ani"]},{"v":"HTt1fsJpxSI","k":"l","t":"You Don’t Need to Train Every Day to Look Jacked. I Only Train 3 Days a Week.","d":"01.07.2025","th":["program-si-split","volum-si-frecventa","recuperare-si-somn","principii-antrenament"],"i":["Autorul consideră că 3-4 zile pe săptămână, cam 45-60 de minute, sunt cele mai potrivite pentru majoritatea naturalilor care chiar muncesc la intensitate.","Dacă antrenezi 6-7 zile și nu ești mulțumit de rezultate, schimbă ceva; el a obținut cele mai bune câștiguri scăzând la 3 zile, fără accidentări sau epuizare.","Cu mai puține zile ești nevoit să ai un plan și să tragi tare, iar recuperarea mai bună aduce mai multă creștere.","Spune că mulți nu sunt supraantrenați, ci prost recuperați; antrenamentul mai bun contează mai mult decât mai mult antrenament."],"e":[],"c":["3-4 sesiuni pe săptămână","45 de minute până la o oră pe sesiune","reducere de la 7 zile la 3 zile"]},{"v":"QRUaTRQ_M64","k":"s","t":"Rear Delt Cable Fly (How To | Form Tutorial)","d":"30.06.2025","th":["tehnica","umeri"],"i":["La rear delt cable fly: cablurile puțin deasupra nivelului ochilor, stai la mijloc, prinzi mânerele fără atașamente și faci pași în spate până simți tensiune.","Duci mâinile în jos și peste corp, pauză scurtă, revii controlat, cu cotul ușor îndoit și fără balans."],"e":[["rear delt cable fly","cabluri puțin peste nivelul ochilor, bile fără atașamente, mâinile în jos și peste corp, pauză scurtă jos, coate ușor îndoite"]],"c":[]},{"v":"Mlr-Lx-10HQ","k":"s","t":"Chest Supported T Bar Row (How To | Form Tutorial)","d":"28.06.2025","th":["tehnica","spate","umeri"],"i":["La chest supported T-bar row: pieptul lipit de pernă, platforma reglată să ai picioarele întinse, priză neutră sau pronată, tragi greutatea spre piept cu coatele lipite.","Controlează faza negativă și evită smucitul; exercițiul lucrează grosimea spatelui mijlociu și rear delts."],"e":[["chest supported T-bar row","priză neutră sau pronată, coatele aproape de corp, fără smucit"]],"c":[]},{"v":"5YC67yVpBGE","k":"s","t":"Underhand Lat Pulldown (How To | Form Tutorial)","d":"27.06.2025","th":["tehnica","spate","brate"],"i":["La underhand lat pulldown: priză supinată la lățimea umerilor sau puțin mai larg, piept sus, ușor înclinat, bara la pieptul de sus, coatele în jos și spre interior.","Controlează faza negativă și limitează balansul; exercițiul lucrează atât bicepșii, cât și latele."],"e":[["underhand lat pulldown","priză supinată, la lățimea umerilor sau puțin mai larg, bara la pieptul de sus"]],"c":[]},{"v":"_dky9gJuKzo","k":"l","t":"If You’re Not Gaining Muscle, It’s One of These 5 Things","d":"26.06.2025","th":["masa-musculara","failure-si-progresie","nutritie","recuperare-si-somn"],"i":["Dacă nu crești, de obicei lipsește unul din cinci lucruri: efort la sau aproape de eșec, progresie, calorii suficiente, somn și consecvență.","Notează antrenamentele și caută o tendință ascendentă în greutate și repetări; aceeași încărcătură în fiecare săptămână nu dă corpului motiv să se adapteze.","Măsoară ce mănânci, află menținerea și adaugă 300-500 kcal; fără material de construcție mușchiul nu se repară.","Somnul de 5 ore, stresul, cafeina târziu și lipsa zilelor de odihnă frânează câștigul.","Rezultatele întârzie; nu schimba programul la 3 săptămâni doar pentru că nu vezi încă schimbări."],"e":[],"c":["surplus de 300-500 kcal peste menținere","exemplu: somn de 5 ore pe noapte","exemplu: 3 săptămâni de efort înainte de renunțare"]},{"v":"_xUapZyUWIY","k":"s","t":"This is why you're not jacked yet...","d":"21.06.2025","th":["mentalitate","incepatori","failure-si-progresie"],"i":["Prea mulți influenceri și schimbarea scopului în fiecare săptămână duc la paralizie prin analiză.","Fără urmărirea progresiei nu există creștere; rămâi la un singur drum."],"e":[],"c":[]},{"v":"LvhzArVLMWA","k":"l","t":"What I Eat in a Day (For Skinny Guys Struggling to Gain Size)","d":"17.06.2025","th":["nutritie","masa-musculara","incepatori"],"i":["Autorul mănâncă alimente integrale puțin procesate (carne de vită, pui, fructe, uleiuri precum avocado sau cocos) și evită extremele precum keto sau carnivor.","Susține că \"if it fits your macros\" nu e suficient: contează și calitatea și proveniența mâncării, nu doar caloriile.","Gătește acasă, planifică mesele și, când mănâncă în oraș, alege friptură cu cartofi sau orez și legume, fără pâine și ultraprocesate.","Pentru masă folosește un surplus mic, 200-400 kcal, cu mese bogate în proteine; ziua arătată are în jur de 2.700-3.000 kcal.","Mesajul de bază e simplitatea și consecvența, nu o singură zi bună de mâncat."],"e":[],"c":["surplus de 200-400 kcal pe zi","aproximativ 2.700-3.000 kcal în ziua prezentată","bone broth cu 7 g proteine la 8 oz","8 oz carne de vită 80/20 la prânz","aproximativ 160 g de orez jasmine","10-11% grăsime corporală tot anul (declarat de autor)","creatină aproximativ 8-9 g în ziua respectivă","3-4 zile de sală pe săptămână"]},{"v":"7_mvDXIcPzM","k":"s","t":"Stop listening to juiced up bodybuilders","d":"16.06.2025","th":["volum-si-frecventa","program-si-split","suplimente","recuperare-si-somn"],"i":["Autorul spune că nu e nevoie de 6-7 zile pe săptămână ca să construiești mușchi; el antrenează 3 zile, natural, cu creatină ca singur supliment.","Înainte încercase tot felul de programe și rămânea epuizat, accidentat și blocat; acum filosofia lui e simplitate, consecvență și echilibru."],"e":[],"c":["3 zile pe săptămână","6-7 zile pe săptămână (criticat)"]},{"v":"xs7_fJY2OwQ","k":"s","t":"I only workout 3 days a week (Here's why)","d":"15.06.2025","th":["volum-si-frecventa","recuperare-si-somn","accidentari-si-articulatii","program-si-split"],"i":["Trei antrenamente pe săptămână aduc intensitate și concentrare mari, mai multă recuperare (mușchii cresc în odihnă) și un program realist, ușor de ținut tot anul.","Mai puține ședințe înseamnă mai puțină uzură a articulațiilor și ligamentelor, deci risc mai mic de accidentare."],"e":[],"c":["3 zile pe săptămână","6-7 zile date ca exemplu negativ"]},{"v":"x7hOr7fXnww","k":"s","t":"If you're 30, and out of shape. Watch this video","d":"14.06.2025","th":["varsta","program-si-split","cardio-si-pasi","recuperare-si-somn"],"i":["La 30 de ani și peste, cinci pași: antrenament 3-4 zile, 10.000 de pași pe zi, 3-4 mese cu mâncare reală, somn 7-8 ore și o rutină fixă.","Somnul e fundația; îl repari înainte să iei suplimente. Mersul e descris ca „cheat code” pentru slăbit."],"e":[],"c":["3-4 zile de antrenament pe săptămână","10.000 de pași pe zi","3-4 mese pe zi","somn 7-8 ore","3-4 ore alocate corpului"]},{"v":"0vwdiHwHfXk","k":"l","t":"You’ll Get More Jacked Than 99% of Lifters (If You Do This)","d":"12.06.2025","th":["mentalitate","program-si-split","failure-si-progresie","cardio-si-pasi"],"i":["Schimbatul constant al scopului și al programului îți șterge urma progresului; alege o țintă, un split upper/lower sau push/legs/pull de 3-4 zile și ține-te de el.","Împinge cel puțin un set din fiecare antrenament extrem de greu și caută să crești repetările și greutatea în timp; aceleași antrenamente dau aceleași rezultate.","Odihnește-te după antrenament, mănâncă alimente integrale dense în nutrienți și hidratează-te bine.","Nu complica cardio-ul: o plimbare de 30-45 de minute în zilele de sală și două plimbări în zilele libere.","Singurul secret e timpul: muncă plictisitoare, repetată ani de zile, nu zile sau luni."],"e":[],"c":["3-4 zile de antrenament pe săptămână","plimbare 30-45 de minute pe zi","două plimbări în zilele de odihnă","aproximativ jumătate până la un galon de apă pe zi"]},{"v":"6cOn6ANSf7M","k":"l","t":"Skinny Guys: You Only Need to Workout 3 Days a Week!","d":"10.06.2025","th":["volum-si-frecventa","masa-musculara","recuperare-si-somn","incepatori"],"i":["Pentru un tip slab natural, autorul recomandă doar 3 antrenamente pe săptămână, făcute cu efort maxim; volumul mare al sportivilor cu substanțe te epuizează.","Mușchii cresc în timpul odihnei, nu al antrenamentului; dacă ești slab, recuperarea și mâncatul contează mai mult decât încă o zi de sală.","Mai puține sesiuni înseamnă și mai puțină uzură a articulațiilor și mai puține accidentări, deci progres mai constant.","Volumul mic și frecvența mică merg doar dacă antrenezi greu și urmărești progresia, nu faci doar 'pompe' ușoare."],"e":[],"c":["3 antrenamente pe săptămână (3-4 zile la final)","fost 6-7 zile pe săptămână","10 ani de experimentare (declarat)"]},{"v":"Xh87J4eoEVE","k":"s","t":"Doing exercises like THIS is why you're not jacked yet","d":"08.06.2025","th":["principii-antrenament","program-si-split","incepatori"],"i":["Rezultatele vin din deficit caloric și antrenament, nu din exerciții trendy; mergi la sală 3-4 zile, greu, cu exerciții compuse cu bara și mașini.","Pe rețele sociale e multă „iarbă” făcută pentru vizualizări; nu complica."],"e":[["cable crunches","alternativă mai simplă"],["hanging knee raises","alternativă mai simplă"]],"c":["3-4 zile pe săptămână"]},{"v":"bpmJ07QkRoU","k":"s","t":"The Video I Wish I Had When I Was Skinny","d":"08.06.2025","th":["incepatori","masa-musculara","nutritie","failure-si-progresie"],"i":["Greșeli de slab: prea mult volum, mâncat prea puțin (urmărește mâncarea și adaugă 300-500 kcal peste bază), schimbat programul, fără jurnal, ego lifting.","Fă mai puțin volum, dar seturi mai intense, aproape de failure, și încearcă să-ți depășești cifrele în mai toate antrenamentele."],"e":[],"c":["300-500 kcal peste bază"]},{"v":"l_90Tkv5VzI","k":"l","t":"THIS Might Be Why You’re Not Building Muscle (Not What You Think)","d":"07.06.2025","th":["varsta","recuperare-si-somn","suplimente","nutritie"],"i":["Autorul crede că testosteronul scăzut poate frâna progresul și recomandă analize de sânge pentru un punct de plecare, cu mențiunea că nu e medic.","El spune că a ridicat valorile cu somn de 7-8 ore (cameră rece, întuneric, telefon departe), mâncare integrală, plimbări, cardio moderat și lumină solară.","A folosit vitamina D cu K2, magneziu glicinat, zinc și bor și a trecut la recipiente din sticlă; prezentat ca experiență proprie, nu sfat medical.","Înainte de TRT, taie alcoolul, fast-food-ul și sedentarismul și rezolvă bazele."],"e":[],"c":["somn 7-8 ore","cel puțin 30 de minute pe zi afară la soare","antrenament 3-4 zile pe săptămână","analize de sânge costat aproximativ 500 de dolari","câteva sesiuni de cardio moderat pe săptămână","un sprint ocazional"]},{"v":"3oaNKSzrMik","k":"s","t":"Do you have an average physique even though you've been working out for years?","d":"06.06.2025","th":["mentalitate","program-si-split","principii-antrenament"],"i":["Mulți au un fizic mediu după ani pentru că schimbă mereu programul când procesul devine plictisitor, în loc să persevereze.","Ce ajută: să te prezinți și când e repetitiv, să crești greutățile și repetările în săptămâni și să nu mai complici lucrurile."],"e":[],"c":[]},{"v":"582sBxlvftA","k":"l","t":"How To Get Jacked in your 30's!","d":"05.06.2025","th":["varsta","program-si-split","cardio-si-pasi","nutritie"],"i":["După 30 de ani recuperarea scade și stresul crește, deci ai nevoie de un plan clar: 3-4 ore pe săptămână pentru corp sunt, în ochii autorului, cea mai bună investiție.","Antrenează 3-4 zile cu mișcări mari (press înclinat, tracțiuni cu greutate, pulldown, ramat, trap bar deadlift, overhead press) plus accesorii; la 3 zile trage tare.","Mergi 10.000 de pași pe zi, inclusiv în zilele libere, pentru slăbire și recuperare.","Mănâncă 3-4 mese cu alimente reale și atinge proteina zilnică; dormi 7-8 ore și pune antrenamentul în calendar ca regulă fixă.","Înainte de TRT, pune la punct somnul, antrenamentul, mâncarea și lumina soarelui."],"e":[["incline press","mișcare mare de bază"],["weighted pull-up","mișcare mare de bază"],["wide grip lat pulldown","mișcare mare de bază"],["row","mișcare mare de bază"],["trap bar deadlift","mișcare mare de bază"],["overhead press","mișcare mare de bază"]],"c":["3-4 zile de antrenament pe săptămână","aproximativ o oră pe sesiune","10.000 de pași pe zi","3-4 mese pe zi","somn 7-8 ore","3-4 ore pe săptămână pentru corp din 168"]},{"v":"bNFX7Sv2HIo","k":"s","t":"More is NOT always better in the gym.","d":"05.06.2025","th":["volum-si-frecventa","recuperare-si-somn","program-si-split"],"i":["Mușchiul crește când te recuperezi, nu când te antrenezi; 6 zile pe săptămână fac recuperarea mai grea.","Autorul a făcut cele mai bune progrese cu 3-4 zile pe săptămână în ultimii 5 ani."],"e":[],"c":["6 zile pe săptămână","3-4 zile","5 ani"]},{"v":"Hf5epWiri74","k":"s","t":"Do these 5 things daily to get jacked","d":"31.05.2025","th":["principii-antrenament","nutritie","recuperare-si-somn","cardio-si-pasi"],"i":["Cinci lucruri zilnice: mișcă-te, ieși la soare, mănâncă mâncare reală (fără uleiuri de semințe, coloranți, îndulcitori), antrenează-te greu 3-4 zile pe săptămână.","Al cincilea: prioritizează recuperarea; autorul spune că fără somn progresul se oprește și mulți au deficit de vitamina D."],"e":[],"c":["3-4 zile pe săptămână, nu 6-7"]},{"v":"w2KYbPClDXQ","k":"s","t":"If you're skinny fat but want to get jacked... watch this","d":"30.05.2025","th":["masa-musculara","program-si-split","failure-si-progresie"],"i":["Skinny fat înseamnă prea puțin mușchi; bro split de 6 zile, prea mult cardio, mâncat puțin și antrenamente de pump fără progresie înrăutățesc situația.","Ai nevoie de antrenament mai greu, forță într-un interval moderat de repetări și seturi împinse tare, nu de mai mult volum."],"e":[],"c":["split de 6 zile dat ca greșeală"]},{"v":"kIkTxTLrf9k","k":"l","t":"How to Unf*ck Your Diet and Training (So You Actually Get Jacked)","d":"29.05.2025","th":["principii-antrenament","mentalitate","program-si-split","cardio-si-pasi"],"i":["Esența e simplă: stres pe mușchi, mâncare pentru refacere, somn și repetare constantă; mai multe stiluri de antrenament pot funcționa.","Fugi de promisiunile rapide (30 de zile, 15 zile, abdomene în 2 săptămâni); pentru naturali e un drum lung și are nevoie de răbdare și plan.","Alege un program dovedit, de preferat cu cel mult 4 zile pe săptămână, și o rutină zilnică fixă: aceeași oră de trezire, aceleași mese, aceleași zile de sală.","Concentrează-te pe progresie la câteva exerciții de bază, nu pe circuite sau zeci de repetări pe 15 exerciții.","În zilele libere rămâi activ: plimbări de aproximativ 45 de minute dimineața și seara, țintă 10.000 de pași, fără planuri complicate de cardio."],"e":[],"c":["program de 4 zile pe săptămână sau mai puțin","3-4 mese cu alimente integrale","3-4 zile de forță pe săptămână","10.000 de pași pe zi","2 plimbări de aproximativ 45 de minute în zilele libere"]},{"v":"WWEnEHV9tgA","k":"s","t":"Do THESE things daily to get jacked.","d":"28.05.2025","th":["mentalitate","principii-antrenament"],"i":["Nu există scurtături: apari, notezi antrenamentele și mâncarea, te antrenezi greu, te miști și repeți zilnic."],"e":[],"c":[]},{"v":"QE8KFdDG4jk","k":"l","t":"These 5 Mistakes Kept Me Skinny. Don’t Make Them.","d":"27.05.2025","th":["masa-musculara","incepatori","failure-si-progresie","nutritie"],"i":["Greșeala 1: antrenament de avansat, 6 zile și mult volum de pompare; mai bine mai puțin volum, seturi aproape de eșec și bătut de cifre aproape la fiecare ședință.","Greșeala 2: mâncat curat, dar prea puțin; urmărește ce mănânci, află baza și adaugă 300-500 kcal pentru un lean bulk.","Greșeala 3: schimbatul programului de plictiseală; ține unul dovedit și nu-l modifica.","Greșeala 4: lipsa dovezilor; notează-ți ridicările și caută o tendință ascendentă.","Greșeala 5: orgoliul cu formă slabă; accidentarea oprește câștigurile, deci compară-te doar cu tine."],"e":[],"c":["surplus de 300-500 kcal peste bază","pompa e aproximativ 10% din ecuație (părerea autorului)","începătorii pot adăuga greutate în fiecare antrenament, intermediarii săptămânal","autorul a antrenat 6 zile pe săptămână la început"]},{"v":"kj3kwmLKOWM","k":"s","t":"STOP following so many fitness influencers","d":"26.05.2025","th":["incepatori","mentalitate","program-si-split"],"i":["Regula unei singure surse: nu amesteca planuri din 10 surse, ca piese de puzzle din cutii diferite; alege un drum.","Autorul spune că după ce a tăiat zgomotul a crescut în forță și fizic."],"e":[],"c":[]},{"v":"51udd2HqLFI","k":"s","t":"My Top Exercises To Build A Jacked Physique!","d":"25.05.2025","th":["program-si-split","piept","spate","umeri"],"i":["Autorul folosește azi doar 22 de exerciții, alese pentru că funcționează, nu pentru că sunt la modă.","Piept: incline barbell/dumbbell press, cable fly, machine press. Spate: tracțiuni, pulldown, T-bar și barbell rows. Umeri, brațe și picioare au câte 4-5 exerciții."],"e":[["incline barbell bench press"],["incline dumbbell press"],["low to high cable fly"],["machine chest press"],["incline machine fly","sau dumbbells"],["wide grip pull-ups"],["wide grip lat pulldowns"],["chest supported T-bar row","sau T-bar row simplu"],["barbell rows"],["overhead press","barbell sau dumbbell"],["cable lateral raises"],["machine rear delt fly","sau cable rear delt fly (katanas)"],["incline dumbbell curls"],["cable curls"],["overhead cable tricep extensions"],["strict barbell curls"],["barbell squat","sau pendulum squat"],["Romanian deadlifts","barbell sau dumbbell"],["seated leg curl"],["lying leg curl"],["reverse lunges / Bulgarian split squats","cu barbell sau dumbbell"],["leg extensions"]],"c":["22 de exerciții","10 ani de încercări"]},{"v":"pZHHFGN_zxQ","k":"l","t":"Copy My Exact Plan To Get Jacked In 180 Days","d":"24.05.2025","th":["program-si-split","volum-si-frecventa","failure-si-progresie","piept"],"i":["Plan de 180 de zile cu două variante: upper/lower în 4 zile sau push/legs/pull în 3 zile; dacă ai prea multe variante ajungi să te pierzi.","Ziua upper: două exerciții de piept, două de spate, unul de umeri, unul de triceps și unul de biceps, 2-3 seturi fiecare, dar cu intensitate mare.","Ziua lower: două exerciții pentru cvadricepși, unul de flexie a genunchiului și unul de hip hinge pentru ischiogambieri, plus gambe și, opțional, abdomene.","Progresia: pornește cu o greutate de 8 repetări, adaugă o repetare pe săptămână, la 12 pe toate seturile crești 2,5-5 lbs și revii la 8.","În zilele libere fă două plimbări de 30-45 de minute; scrie-ți motivul și citește-l în fiecare dimineață."],"e":[["incline barbell bench press","piept"],["incline dumbbell press","piept"],["low to high cable fly","piept"],["incline machine chest press","piept"],["incline machine fly or dumbbell fly","piept"],["wide grip pull-up","spate"],["wide grip lat pulldown","spate"],["chest supported T-bar row","spate"],["barbell row","spate"],["barbell overhead press","umeri; alternativ mașină sau gantere"],["cable lateral raise","umeri"],["machine rear delt fly","umeri"],["cable rear delt fly","umeri"],["incline dumbbell curl","brațe"],["cable curl","brațe"],["overhead cable tricep extension","brațe"],["barbell curl","brațe"],["back squat","picioare"],["pendulum squat","picioare"],["Romanian deadlift","hip hinge pentru ischiogambieri"],["seated or lying leg curl","flexie de genunchi"],["reverse lunge","barbell sau dumbbell"],["leg extension","picioare"],["seated or standing calf raise","gambe"],["trap bar deadlift or standard deadlift","picioare"],["hanging knee raise","abdomene"],["cable crunch","abdomene"]],"c":["upper/lower 4 zile sau push/legs/pull 3 zile","2-3 seturi per exercițiu","start 8 repetări, 12 la final","creștere de 2,5 până la 5 lbs","pauză 2-3 minute la compuse și 1 minut 30 la accesorii","încălzire: 10 minute treadmill, 3-4 seturi crescătoare","exemplu de ramping: 20s x 5-6, 40s x 5-6, 60s x 2-3 pentru țintă 80 lb","două plimbări de 30-45 de minute în zilele libere","plan de 180 de zile"]},{"v":"u8uor1_OBzU","k":"s","t":"Simple Pull Day Routine to Build Muscle (3-Day A Week Workout Plan)","d":"23.05.2025","th":["spate","brate","umeri","program-si-split"],"i":["Zi de pull simplă: lat pulldown la priză largă, T-bar cu suport pe piept, fluturări pentru deltoidul posterior, apoi două exerciții de biceps.","Progresie: 3 seturi pe exercițiu, începi la 8 repetări, urci la 12 la toate seturile, apoi crești greutatea și cobori din nou."],"e":[["wide grip lat pulldown","priză largă, amplitudine completă, pauză în stretch sus, coborâre explozivă"],["chest supported T-bar row","pentru grosimea mijlocului spatelui și trapez"],["rear delt flies","pentru estetică și postură"],["incline dumbbell curl","exercițiul favorit pentru biceps"],["cable curls","în spatele corpului, pentru tensiune"]],"c":["3 seturi pe exercițiu","8 până la 12 repetări","3 zile pe săptămână"]},{"v":"xC6nviHk-Hk","k":"l","t":"I Would've Gotten Jacked Sooner If I Knew THIS","d":"21.05.2025","th":["principii-antrenament","program-si-split","nutritie","recuperare-si-somn"],"i":["Muscularea se reduce la patru pași repetați: stresezi mușchiul, îl hrănești, îl lași să se refacă, iar corpul se adaptează; nu complica cu detalii de unghi sau tempo.","Alege upper/lower în 3-4 zile sau push/legs/pull; peste 4 zile pentru un natural nu e necesar și aduce poate 1-5% în plus cu mai multă uzură.","După antrenament mănâncă 3-4 mese cu mâncare integrală, echilibrate cu proteină, grăsime și carbohidrat, și dormi suficient.","Pentru hormoni, autorul recomandă stil de viață sănătos: ieși zilnic afară, 10.000 de pași, soare, hidratare și somn; nu TRT.","Ai deja destulă informație; ce lipsește sunt execuția și timpul."],"e":[],"c":["upper/lower 3-4 zile sau push/legs/pull","maximum 4 zile de antrenament pe săptămână","1-5% câștig în plus la 6-7 zile (părerea autorului)","3-4 mese pe zi","10.000 de pași pe zi"]},{"v":"dqOprOM719U","k":"s","t":"Simple Leg Day Routine to Build Muscle (3-Day Workout Plan)","d":"20.05.2025","th":["picioare","program-si-split","incalzire","failure-si-progresie"],"i":["Ziua de picioare: pendulum squat, RDL cu gantere, leg curl, leg extension, opțional gambe și abdomen; 3 seturi pe mișcare.","Progresie: începi la 8 repetări; când toate 3 seturi ies curate, adaugi repetări; la 12 pe toate seturile mărești greutatea și reiei de la început."],"e":[["pendulum squats"],["dumbbell Romanian deadlifts","strict, fără a transforma în mișcare de spate"],["seated or lying leg curls"],["leg extensions"],["seated calf raises","opțional"],["cable crunches","opțional"],["hanging knee raises","opțional"],["bodyweight squats","încălzire"],["lunges","încălzire"],["bodyweight RDL","încălzire"]],"c":["10 minute mers înclinat","3 seturi pe mișcare","8 repetări","12 repetări"]},{"v":"3m0G0LoOGLA","k":"s","t":"Simple Push Day Routine to Build Muscle (3-Day Workout Plan)","d":"19.05.2025","th":["piept","umeri","brate","program-si-split"],"i":["Ziua de push: incline dumbbell bench pentru partea de sus a pieptului, apoi flies la cablu (de jos în sus), lateral raises la cablu și extensii pentru triceps la cablu.","Pornește de la 3 seturi de 8; când faci 8 la toate, crești repetările până la 12 la toate seturile, apoi adaugi greutate și cobori la 8."],"e":[["incline dumbbell bench","exercițiul principal pentru piept, pentru partea de sus"],["machine chest fly / low to high cable fly","unghiul cablului contează: de jos în sus"],["cable lateral raise","pentru umeri"],["tricep cable extensions","pentru triceps"]],"c":["3 seturi x 8 repetări","creștere până la 12 repetări, apoi adaugi greutate și revii la 8"]},{"v":"I4MV7IATdB8","k":"l","t":"There Are 20,000 Exercises, But You Only Need These 22 To Get Jacked","d":"18.05.2025","th":["tehnica","piept","spate","umeri"],"i":["Programele de forță cu mișcări compuse te fac mai puternic, dar pot lăsa pieptul și brațele în urmă; pentru aspect ai nevoie de alegerea mișcărilor.","Autorul folosește circa 22 de exerciții și crește greutatea constant, nu zeci de variante.","La piept accent pe partea superioară (înclinat); la spate priză largă pentru V; la umeri press plus ridicări laterale și posterioare; la brațe doar mișcări stricte.","Preferințele lui de top: incline dumbbell press și incline machine fly pentru piept, wide grip pulldown și T-bar row pentru spate."],"e":[["incline barbell bench press","piept"],["incline dumbbell press","piept, una din cele două alegeri de top"],["low to high cable fly","piept"],["machine chest press","piept"],["incline machine fly","piept, alternativ gantere; una din cele două alegeri de top"],["wide grip pull-up","spate"],["wide grip lat pulldown","spate, una din cele două alegeri de top"],["wide grip chest supported T-bar row","spate; T-bar row simplu dacă nu ai suport; una din cele două alegeri de top"],["barbell row","spate"],["barbell or dumbbell overhead press","umeri"],["cable lateral raise","umeri"],["machine rear delt fly","umeri"],["cable rear delt fly","umeri"],["incline dumbbell curl","brațe"],["cable curl","brațe"],["overhead cable tricep extension","brațe"],["strict barbell curl","brațe"],["barbell squat or pendulum squat","picioare"],["Romanian deadlift","barbell sau dumbbell"],["seated and lying leg curl","picioare"],["reverse lunge or Bulgarian split squat","barbell sau dumbbell"],["leg extension","picioare"]],"c":["aproximativ 22 de exerciții","experiență de peste 10 ani (declarat)"]},{"v":"xmYG3zKH2b4","k":"s","t":"If you're new to the gym, stop looking in the mirror everyday!","d":"16.05.2025","th":["incepatori","mentalitate","failure-si-progresie"],"i":["Începător: nu te mai uita zilnic în oglindă, urmărește progresia în greutate sau repetări.","Schimbările vizibile iau timp; după 6 luni sau un an vei fi surprins."],"e":[],"c":["6 luni până la un an"]},{"v":"Adn_n2FqKzM","k":"l","t":"Getting Jacked Is a Superpower.","d":"15.05.2025","th":["mentalitate"],"i":["Autorul susține că transformarea fizică aduce și încredere și disciplină; ține de a face ce ai spus când nu te vede nimeni.","Spune că a fi în formă aduce respect și oportunități; prezentat ca părere proprie.","Corpul e baza pe care construiești restul, deci pune-l înaintea lucrurilor materiale."],"e":[],"c":[]},{"v":"FQ7NqW3krG0","k":"s","t":"Most guys overcomplicate building muscle","d":"14.05.2025","th":["program-si-split","volum-si-frecventa","incepatori"],"i":["Mulți complică inutil: nu e nevoie de 6 zile, antrenamente de peste 2 ore sau un split absurd.","Cu consecvență și structura potrivită se poate progresa serios cu doar 3 zile pe săptămână."],"e":[],"c":["3 zile pe săptămână","6 zile și 2+ ore (criticat)"]},{"v":"9l_6xX_EiZY","k":"l","t":"These 5 Habits Took Me From Average to Jacked","d":"13.05.2025","th":["mentalitate","cardio-si-pasi","nutritie","recuperare-si-somn"],"i":["Cinci reguli zilnice: mișcă-te zilnic, ieși la soare, mănâncă mâncare reală, antrenează-te serios 3-4 zile și prioritizează recuperarea.","Autorul face o plimbare în zilele de antrenament și două de 45 de minute în zilele libere; spune că așa rămâne slab fără urmărire detaliată.","Pentru somn: oră fixă de culcare, cameră rece și întunecată, termostat în jur de 66 F, telefon pe airplane mode și fără ecrane cu o oră înainte.","Ia magneziu glicinat cu aproximativ o oră înainte de somn; antrenează 3 zile (marți, joi, sâmbătă), cu efort mare."],"e":[],"c":["3-4 zile de antrenament pe săptămână","o plimbare în zilele de sală","2 plimbări de 45 de minute în zilele libere","somn minimum 7 ore","termostat în jur de 66 F","fără ecrane 1 oră înainte de somn","magneziu glicinat cu 1 oră înainte de somn"]},{"v":"GIoEFzWRz-c","k":"l","t":"The REAL Reason You're Not Jacked Yet.","d":"11.05.2025","th":["mentalitate","incepatori"],"i":["Împarte ținta mare în pași zilnici mici: nu te uita la vârful muntelui, ci la ce faci azi.","Gândește ca un om în formă: își face antrenamentele, își notează ridicările, mănâncă la timp, doarme și se prezintă oricum.","Un fizic bun se construiește cu cărămizi mici, plictisitoare, repetate; schimbatul programului și căutarea unei soluții rapide te țin pe loc.","Întreabă-te zilnic: am antrenat, mi-am atins mâncarea, am dormit, am mers?"],"e":[],"c":[]},{"v":"UGqGhpPUkXI","k":"s","t":"If you want to get jacked, stop looking for secrets!","d":"10.05.2025","th":["mentalitate","principii-antrenament"],"i":["Nu căuta secrete; fă bine fundamentele care nu se schimbă și fă-le automate, zi de zi, ani de zile."],"e":[],"c":[]},{"v":"ewmskw53SNo","k":"s","t":"This is what keeps guys from getting jacked!","d":"09.05.2025","th":["failure-si-progresie","mentalitate"],"i":["Majoritatea nu merg destul de aproape de failure; fă încă o repetare când mintea vrea să renunțe, dar fără să te accidentezi."],"e":[],"c":["99% nu se antrenează la failure"]},{"v":"8r-lqewUNUY","k":"l","t":"My Pull Day Explained (Simple 3-Day Workout Routine)","d":"08.05.2025","th":["spate","brate","umeri","failure-si-progresie"],"i":["Ziua de pull a autorului: 5 exerciții pentru spate, deltoid posterior și biceps, câte 3 seturi, cu progresie de la 8 la 12 repetări.","Lat pulldown cu priză largă, amplitudine completă și pauză în întindere sus; fără aparat folosești benzi sau tracțiuni asistate.","Pentru grosimea spatelui folosește un rând orizontal (T-bar cu suport, gantere, bară sau mașină) și rămâi la el ca să crești în forță.","La biceps, curl înclinat cu brațele în spatele corpului pentru întindere maximă, apoi cable curl cu cablul în spate.","Pentru naturali contează progresia, nu pompa, recuperarea, nu volumul infinit, și execuția, nu variația continuă."],"e":[["wide grip lat pulldown","amplitudine completă, pauză în întindere sus; alternativ assisted pull-up cu benzi sau pull-up"],["chest supported T-bar row","pentru grosimea spatelui mijlociu și trapez; alternativ dumbbell, barbell sau machine row"],["rear delt fly","mașină sau cablu încrucișat (katana); alternativ benzi sau face pulls"],["incline dumbbell curl","stai înclinat, brațele atârnă în spatele corpului, execuție controlată"],["cable curl","cu cablul în spatele corpului sau standard; ultima mișcare"]],"c":["3 seturi per exercițiu","start 8 repetări, țintă 12, apoi crești greutatea și revii la 8","antrenează 3-4 zile pe săptămână de 5 ani"]},{"v":"5oNhGYGHxnc","k":"s","t":"Want a jacked physique? Focus on THESE things.","d":"07.05.2025","th":["principii-antrenament","incepatori","program-si-split","nutritie"],"i":["Autorul spune că rutina lui nu e revoluționară: 3-4 antrenamente grele pe săptămână, scopul fiind să adaugi măcar o repetare la un set în fiecare sesiune.","Pe lângă antrenament: mâncare reală, fără procesate, mișcare zilnică, lumină de soare, 8 ore de somn și rutină zilnică."],"e":[],"c":["3-4 antrenamente pe săptămână","8 ore de somn","cel puțin o repetare în plus pe sesiune"]},{"v":"R8BRgzRE7yU","k":"l","t":"My Leg Day Explained (Simple 3-Day Routine)","d":"06.05.2025","th":["picioare","abdomen","failure-si-progresie","program-si-split"],"i":["Ziua de picioare: un compus pentru cvadricepși, un hip hinge, un leg curl, extensii și opțional gambe și abdomene, câte 3 seturi.","Include atât RDL (hip hinge), cât și leg curl (flexia genunchiului) pentru dezvoltare completă a ischiogambierilor.","Începe cu o greutate cu care ai 8 repetări curate și poți face încă 2 dacă ți se cere; crești repetările până la 12, apoi greutatea.","Autorul urmează regula unei singure surse: alegi un creator cu fizicul dorit și îi urmezi planul exact; schimbatul continuu te blochează.","Încălzire: 10 minute pe treadmill înclinat, apoi mișcări cu greutatea corpului (genuflexiuni, fandări, RDL)."],"e":[["pendulum squat","3 seturi; alternativ barbell squat sau hack squat"],["dumbbell Romanian deadlift","strict, controlează faza negativă, fără să încarci lombarul"],["seated or lying leg curl","flexia genunchiului; poți alterna săptămânal"],["leg extension","pentru cvadricepși, cu accent pe conexiunea minte-mușchi"],["seated calf raise","opțional, până la eșec"],["cable crunch","abdomene, opțional"],["hanging knee raise","abdomene, opțional"]],"c":["3 seturi per exercițiu","start 8 repetări, 12 țintă","încălzire 10 minute treadmill","aproximativ 80% din greutate la început","train 3 zile pe săptămână"]},{"v":"lVDrlOw3gcQ","k":"l","t":"My Push Day Explained (Simple 3-Day Routine)","d":"04.05.2025","th":["piept","umeri","brate","program-si-split"],"i":["Ziua de push a autorului: cinci exerciții, câte 3 seturi drepte, cu 8 repetări la început și 12 ca țintă înainte de a urca greutatea.","Înclinatul construiește partea superioară a pieptului; cablurile low-to-high adaugă volum pentru aceeași zonă.","Autorul nu folosește superseturi sau drop seturi și spune că a clădit fizicul pe simplitate.","Trei zile pe săptămână, aproximativ o oră pe sesiune, cardio ușor în afara sălii; mai puțină uzură pentru articulații și mai puține accidentări."],"e":[["incline dumbbell bench","3 seturi, 8 repetări la început"],["machine chest fly","alternativ dumbbell flies"],["low to high cable fly","scripete setat la nivel jos, pentru partea superioară a pieptului"],["cable lateral raise","alternativ gantere"],["tricep cable extension","coardă sau bară dreaptă, extensie completă și control"]],"c":["3 seturi per exercițiu","start 8 repetări, țintă 12","încălzire 10-15 minute incline walk","aproximativ 8-9 seturi de piept pe săptămână","antrenament de aproximativ o oră","3 zile pe săptămână"]},{"v":"DEHJxlh4ejw","k":"s","t":"How to get ahead of 99% of people in the gym","d":"03.05.2025","th":["principii-antrenament","mentalitate","nutritie","recuperare-si-somn"],"i":["Nu crești în sală, ci din obiceiurile din afara ei: mese gătite când ești obosit, somn și disciplină când motivația lipsește.","Alege un plan dovedit, nu amesteca sfaturi de la 10 influenceri, antrenează-te foarte greu la fiecare set, mănâncă alimente întregi, hidratează-te și dormi 7+ ore."],"e":[],"c":["7+ ore de somn"]},{"v":"pBs-N1O9nKQ","k":"s","t":"If You’re Injured from Lifting, Don’t Skip This","d":"02.05.2025","th":["accidentari-si-articulatii","volum-si-frecventa"],"i":["Dacă ai accidentări ușoare, întâi scade ușor numărul de zile, apoi numărul total de seturi și repetări pe săptămână.","Nu trebuie să te antrenezi zilnic ca să ai un fizic estetic."],"e":[],"c":[]},{"v":"Er6iiQ7KxJk","k":"l","t":"I Studied 1,000 Lifters. This Is Why Most Never Build Muscle.","d":"01.05.2025","th":["program-si-split","mentalitate","failure-si-progresie"],"i":["Regula unei singure surse: alege o persoană, un plan și o filosofie; amestecul de sfaturi din zece surse e ca piesele de puzzle din cutii diferite.","Schimbatul constant al programului e ca scoaterea banilor de pe piață în fiecare săptămână: nu lași nimic să se acumuleze.","Scopul antrenamentului e să progresezi săptămânal în greutate sau repetări, iar schimbările dese fac progresia dificilă.","Autorul spune că a învățat mult urmărind creatori, dar fizicul nu s-a schimbat până nu a tăiat zgomotul și a urmat un singur plan."],"e":[],"c":[]},{"v":"1_-CC_6_eeo","k":"s","t":"The REAL First Step to Getting Jacked","d":"01.05.2025","th":["mentalitate","incepatori"],"i":["Primul pas în fitness este să afli de ce o faci: un motiv profund la care să te întorci când motivația scade.","Vor fi zile în care nu ai chef; motivul tău (partener, încredere, sănătate pentru copii) te ține pe drum."],"e":[],"c":[]},{"v":"pgWPFALMfFM","k":"l","t":"I Would’ve Gotten Jacked Sooner If I Trained Like This","d":"29.04.2025","th":["tehnica","spate","umeri","piept"],"i":["Programele de forță (full body, 5x5) cresc ridicările, dar nu construiesc neapărat forma dorită: talie îngustă, umeri lați, spate gros, piept superior.","Pentru aspect alege mișcări țintite: priză largă pentru forma de V, T-bar sau ramat pentru grosime, ridicări laterale și posterioare pentru umeri rotunzi.","Pentru piept, accent pe înclinat (press și fly) ca partea superioară să fie mai plină; autorul folosește mai ales gantere și bară.","Nu sări peste picioare, iar la brațe mulțumește-te cu trei mișcări; curl pentru gât îl consideră util pentru un aspect puternic.","Rezultatul vine în ani, nu în 90 de zile; important e să rămâi în plan și să faci progresie."],"e":[["wide grip pull-ups or lat pulldowns","pentru forma de V a spatelui"],["T-bar row or wide grip barbell row","grosimea spatelui"],["neck curl","pentru gât"],["lateral raise","umeri"],["rear delt fly or face pull","umeri"],["barbell overhead press","umeri și trapez superior"],["incline press","piept superior"],["incline machine or dumbbell fly","piept superior"],["squat","picioare"],["pendulum squat","picioare"],["Romanian deadlift","picioare"],["Nordic curl","picioare"],["Bulgarian split squat","picioare"],["reverse lunge","picioare"],["incline dumbbell curl","brațe"],["barbell curl","brațe"],["cable curl","brațe"]],"c":["3 mișcări de brațe","2 ani sau un an pentru schimbări vizibile (părerea autorului)"]},{"v":"IlLKfPVRSSU","k":"s","t":"The Truth You Need to Hear if You Want to Get Jacked","d":"28.04.2025","th":["mentalitate","principii-antrenament"],"i":["Singurul secret al autorului după peste 10 ani: nu a renunțat, a mers la sală și obosit, a notat antrenamentele și a fost atent la mâncare.","Nu e nevoie de aplicații, echipament, accesorii, split de 7 zile sau o grămadă de suplimente."],"e":[],"c":["peste 10 ani","split de 7 zile (criticat)"]},{"v":"IAvjnHHQKTk","k":"l","t":"The Brutal Truth About Your Average Physique","d":"27.04.2025","th":["mentalitate","incepatori"],"i":["Programul nu e problema; când devine repetitiv sau greu, mulți caută alt plan în loc să continue.","Rezistența la plictiseală și la repetiție e partea grea, iar cine nu renunță începe să crească constant în greutate și repetări.","Un fizic puternic se construiește cu disciplină în zilele fără aplauze; nu există gratificare instantanee în aspect.","Autorul leagă antrenamentul de disciplină și mentalitate care se transferă în alte domenii."],"e":[],"c":["10 ani de antrenament (declarat)"]},{"v":"CP_sd0A1biM","k":"s","t":"The #1 Killer of Your Gains (Nobody Talks About This)","d":"26.04.2025","th":["accidentari-si-articulatii","volum-si-frecventa","program-si-split"],"i":["Accidentarea e ce îți distruge cel mai sigur câștigurile; antrenamentele zilnice cu volum mare nu merită pentru majoritatea.","După părerea autorului, 3 zile pe săptămână dau cam 95% din câștiguri, iar a patra zi aproape 99%; cei care promovează 6-7 zile sunt pe steroizi."],"e":[],"c":["3 zile = ~95% din câștiguri","4 zile = ~99%","6-7 zile (criticat)"]},{"v":"Tc5obg_jTMc","k":"l","t":"If Fitness Is THIS Simple, Why Aren’t You Jacked Yet?","d":"25.04.2025","th":["mentalitate","program-si-split","cardio-si-pasi","principii-antrenament"],"i":["Simplu nu înseamnă ușor: planul e clar, dar mulți renunță la partea plictisitoare care funcționează; social media creează iluzia că toată lumea e în formă.","Ce a mers pentru autor: split upper/lower de 4 zile (acum 3), o mișcare compusă grea la început și apoi accesorii pentru aspect, aceleași mese zilnice și 10.000 de pași.","Succesul vine din câteva lucruri esențiale repetate de mii de ori, nu din 100 de lucruri făcute o dată.","Întreabă-te dacă ai urmat un plan 6 luni neîntrerupt, ți-ai notat ridicările, ai dormit și ai mâncat constant; dacă nu, acolo e problema, nu în genetică sau vârstă."],"e":[["overhead press","exemplu de mișcare aleasă"],["incline fly","exemplu de mișcare aleasă"],["wide grip pulldown","exemplu de mișcare aleasă"],["row","exemplu de mișcare aleasă"],["incline curl","exemplu de mișcare aleasă"]],"c":["3-4 antrenamente pe săptămână","10.000 de pași pe zi","un plan urmat cel puțin 6 luni","upper/lower 4 zile, acum 3 zile"]},{"v":"i2xwqBmJM1U","k":"s","t":"If You Want to Be Jacked… BE THIS GUY","d":"25.04.2025","th":["mentalitate"],"i":["Fii cel care nu ratează o zi și care face munca chiar când nu se uită nimeni; nimic nu se schimbă dacă nu schimbi nimic."],"e":[],"c":[]},{"v":"WgEOC3twfHE","k":"s","t":"There’s no hack to getting JACKED! 💪","d":"24.04.2025","th":["mentalitate","principii-antrenament"],"i":["Nu există scurtături: apari, notezi antrenamentele și mâncarea, te antrenezi greu și te miști în fiecare zi."],"e":[],"c":[]},{"v":"vx0VnWyKQvY","k":"l","t":"The Problem With Working Out 6 Days A Week...","d":"23.04.2025","th":["volum-si-frecventa","recuperare-si-somn","accidentari-si-articulatii","program-si-split"],"i":["Antrenamentul de 6 zile pe săptămână poate frâna creșterea pentru un natural, pentru că mușchii se refac în afara sălii, iar aceleași grupe se suprapun între zile.","Somnul slab, stresul și mâncarea proastă adăugate la frecvența mare duc la oboseală, dureri articulare, accidentări și forță blocată.","Autorul antrenează 3-4 zile pe săptămână de 5 ani și spune că a avut cele mai bune câștiguri, cu sesiuni mai intense și fără exerciții de umplutură.","Pentru cei cu serviciu și viață personală, mai puțin e mai bine; contează antrenamentul greu, progresia de la o săptămână la alta și recuperarea."],"e":[],"c":["3-4 zile de antrenament pe săptămână de 5 ani","comparație: 6 zile pe săptămână"]},{"v":"wGXrDepnR-E","k":"s","t":"How to Make More Progress in 1 Year Than Most Guys Do in 5 at the Gym","d":"23.04.2025","th":["principii-antrenament","program-si-split","recuperare-si-somn"],"i":["Formula pentru progres rapid: 3-4 zile pe săptămână mai intens, plan dovedit, execuție perfectă la fiecare repetare, fără elan sau ego lifting.","Recuperare serioasă (somn 7-9 ore, proteină, stres gestionat), urmărirea sistematică a greutăților și consecvență, fără schimbat programele."],"e":[],"c":["3-4 zile pe săptămână","somn 7-9 ore"]},{"v":"M7Icuymhtb4","k":"s","t":"Building Muscle Is Simple! Just Do This.","d":"22.04.2025","th":["program-si-split","nutritie","cardio-si-pasi","incepatori"],"i":["Pentru început: upper/lower de 4 zile, fiecare mușchi de două ori pe săptămână, un compus greu primul, 2 exerciții per grupă; notează totul.","Mănâncă mâncare reală, proteine în grame egale cu greutatea țintă în lbs (180 lbs, 180 g), mișcă-te zilnic."],"e":[],"c":["4 zile upper/lower","2 exerciții pe grupă","180 lbs = 180 g proteine pe zi"]},{"v":"T8y4bou8QkE","k":"s","t":"You Do NOT Need To \"SHOCK\" Your Muscles","d":"22.04.2025","th":["principii-antrenament","program-si-split"],"i":["Nu e nevoie să „șochezi” mușchii cu variații fără sfârșit sau rotații de exerciții; la 3 zile pe săptămână ajung concentrarea și progresia."],"e":[],"c":["3 zile pe săptămână"]},{"v":"igx_uBaIiyc","k":"l","t":"If You're Skinny Fat But Want To Get Jacked, Just Do This","d":"20.04.2025","th":["slabit","masa-musculara","program-si-split","nutritie"],"i":["Dacă ești skinny fat, problema e prea puțin mușchi; ai nevoie de antrenament greu, în zona moderată de repetări, cu seturi împinse tare, nu de mai mult volum sau cardio.","Upper/lower de 3-4 ori pe săptămână e suficient dacă progresezi; mănâncă la menținere sau puțin peste, cu proteine suficiente, și mergi zilnic.","Pentru cel masiv și moale, taie ultraprocesatele și gustările inutile, mănâncă alimente integrale, fă pași și revino la antrenament cu intensitate.","Dacă după un an nu vezi progres, sistemul e problema: urmează un plan dovedit în loc să-l modifici; schimbarea vizibilă cere 4-6 luni."],"e":[],"c":["upper/lower 3-4 antrenamente pe săptămână","calorii la menținere sau puțin peste","schimbare vizibilă în 4-6 luni","peste un an fără rezultate înseamnă sistem greșit"]},{"v":"Z5xpoCDc3GY","k":"s","t":"How To Get Ahead Of 99% Of Lifters In 365 days","d":"19.04.2025","th":["principii-antrenament","program-si-split","recuperare-si-somn"],"i":["Formula pe un an: 3-4 zile pe săptămână, plan dovedit, execuție perfectă cu intensitate maximă, fără ego lifting, recuperare serioasă, urmărirea progresului.","Recuperare: 7-9 ore de somn, destule proteine și gestionarea stresului; notează antrenamentele și greutatea."],"e":[],"c":["3-4 zile pe săptămână","7-9 ore somn"]},{"v":"DHh1_HXTUjo","k":"s","t":"20 Pieces Of Advice I Wish I Had When I Started Lifting","d":"18.04.2025","th":["principii-antrenament","incepatori","program-si-split","accidentari-si-articulatii"],"i":["20 de sfaturi: 3-4 zile pe săptămână ajung dacă antrenezi foarte greu; consecvența bate intensitatea; supraîncărcarea progresivă nu e opțională; notează antrenamentele.","Bulk lent, proteine, picioare, somn, mers pe jos ca cardio subapreciat, încălzire îndelungată, fără ego lifting, grijă de articulații, analize de sânge."],"e":[],"c":["20 de sfaturi","3-4 zile pe săptămână","peste 10 ani de sală"]},{"v":"4gBua0YDUWQ","k":"l","t":"The Truth About Getting Jacked (Most Guys Overcomplicate It)","d":"17.04.2025","th":["principii-antrenament","mentalitate","failure-si-progresie"],"i":["Nu există scurtătură: fizicul vine din bazele făcute constant ani la rând, nu din provocări de 30 de zile sau din schimbarea programului la două săptămâni.","Autorul antrenează 3-4 zile pe săptămână (acum 3) și urmărește un singur lucru: să adauge măcar o repetare la un set în fiecare ședință.","Majoritatea oamenilor din sală nu își împing seturile aproape de eșec; creșterea apare când mai faci o repetare cât mintea cere oprirea, fără să strici forma.","Automatizează bazele: antrenament la aceeași oră, mese pregătite în avans, rutină de somn și caiet cu greutățile, ca să nu depinzi de motivație.","Mâncarea reală, mișcarea zilnică, lumina soarelui și circa opt ore de somn fac parte din rutina lui zilnică fixă."],"e":[],"c":["3-4 zile de antrenament pe săptămână","cel puțin o repetare în plus la un set pe ședință","circa 8 ore de somn"]},{"v":"GZVkk8XQLAc","k":"l","t":"What I Eat For A Jacked Physique (My Meal Plan)","d":"15.04.2025","th":["nutritie","masa-musculara"],"i":["Autorul nu numără macro-uri; mănâncă alimente integrale (carne, cartofi dulci, orez, fructe, avocado) și evită produsele procesate (părere proprie).","Pudra de proteine e doar un extra, nu o necesitate; mâncarea densă în nutrienți aduce creșterea reală, mai ales pentru cine are poftă mică de mâncare.","Orezul fiert în supă de oase (nu de pui) crește aportul de proteine față de cel fiert în apă.","Spune că abordarea „if it fits your macros” ignoră sănătatea generală; de când mănâncă curat zice că are mai puțină anxietate, digestie și piele mai bune.","Meniul e aproape același toată săptămâna, cu alternarea cărnurilor, fructelor și legumelor; fără mese libere și fără mâncat în oraș."],"e":[],"c":["187 lbs la 6 ft, țintă în jur de 190 lbs","150 mg pre-workout","smoothie: 12 oz lapte, 1 lingură unt de migdale, 1 lingură miere, 3 curmale, 2 cupe fructe înghețate","carne de vită 85/15, între jumătate de livră și o livră la prânz"]},{"v":"9ctpvaZvO_Q","k":"l","t":"If I wanted to get Jacked but could only train 3 days a week (THIS is the exact split I would use)","d":"13.04.2025","th":["program-si-split","volum-si-frecventa","failure-si-progresie","principii-antrenament"],"i":["Cu doar 3 zile pe săptămână intensitatea trebuie să fie foarte mare, iar fiecare set contează; notează tot și încearcă să îmbunătățești ceva la fiecare antrenament.","Împarte săptămâna în push, picioare, pull: fiecare zi începe cu mișcarea principală (3 seturi de 6-10) și continuă cu accesorii de estetică (8-15 repetări).","Ține același plan minimum 16 săptămâni fără schimbări; apoi poți roti variante apropiate (înclinat cu plat, priză largă cu îngustă) ca să eviți suprasolicitarea.","Progresie simplă: pornești de la 8 repetări pe toate seturile, adaugi o repetare pe set când le reușești pe toate, iar la capătul intervalului crești greutatea.","Pauze de 2 minute la mișcările principale și 1,5 minute la accesorii; în total circa 3 ore de antrenament pe săptămână."],"e":[["incline dumbbell bench press","ziua push"],["low to high cable flies","ziua push"],["incline machine flies / dumbbell flies","ziua push, cu gantere dacă nu ai aparat"],["lateral raises","ziua push"],["overhead tricep extensions (cable)","ziua push"],["barbell squat / pendulum squat","ziua de picioare"],["dumbbell Romanian deadlift","ziua de picioare"],["leg extensions","ziua de picioare"],["lying leg curls","ziua de picioare"],["seated calf raises","ziua de picioare"],["hanging knee raises","opțional pentru abdomen, 3 seturi cu cât mai multe repetări"],["cable crunches","opțional pentru abdomen, 3 seturi cu cât mai multe repetări"],["wide grip lat pulldowns","ziua pull"],["chest supported T-bar rows","ziua pull"],["rear delt machine flies","ziua pull"],["rear delt cable flies (katanas)","ziua pull"],["incline dumbbell curls","ziua pull"],["barbell curls","ziua pull"]],"c":["3 ore de antrenament pe săptămână","pauze 2 minute la principale, 1 minut 30 la accesorii","minimum 16 săptămâni cu același plan","principale: 3 seturi de 6-10 repetări","accesorii: 3 sau 5 seturi de 8-15 repetări","abdomen: 3 seturi"]},{"v":"aEKQFqUR0lo","k":"s","t":"Why Most Fitness Advice Fails Natural Lifters","d":"13.04.2025","th":["principii-antrenament","mentalitate","volum-si-frecventa"],"i":["Autorul spune că mare parte din sfaturi sunt făcute pentru oameni care folosesc substanțe; naturalii nu pot antrena și recupera la fel.","El nu mai face 6-7 zile, drop seturi sau volum nebun și a trecut la sfaturi simple."],"e":[],"c":["6-7 zile pe săptămână (greșeala veche)"]},{"v":"ATUvxP1YTmA","k":"l","t":"How To Get Ahead Of 99% Of Lifters Only Working Out 3 Days A Week","d":"11.04.2025","th":["volum-si-frecventa","recuperare-si-somn","accidentari-si-articulatii","mentalitate"],"i":["Pentru un fizic estetic nu ai nevoie de split perfect sau de zeci de variante pentru piept, ci de intensitate, consecvență și timp; autorul antrenează 3 zile (înainte 4).","Antrenamentul zilnic duce, după el, la câștiguri mici, articulații uzate și oboseală; accidentarea îți strică cel mai mult progresul.","Concentrează-te pe mișcări grele de bază pentru estetică, completate cu accesorii, și renunță la exerciții de umplutură și la goana după pump.","Mușchiul crește din obiceiurile din afara sălii: mese gătite chiar obosit, somn de 7+ ore, mâncare integrală, hidratare.","Alege un singur plan verificat, antrenează-te foarte tare la fiecare set și urmărește greutățile și repetările, nu oglinda zilnic; rezultatele se văd după 6-12 luni."],"e":[],"c":["3 zile pe săptămână (înainte 4)","10 ani de antrenament","somn 7+ ore pe noapte","rezultate vizibile după 6 luni - 1 an"]},{"v":"tMH6Eqg5Nho","k":"l","t":"If I Woke Up Average Tomorrow, Here’s EXACTLY How I’d Get Jacked","d":"09.04.2025","th":["incepatori","program-si-split","volum-si-frecventa","mentalitate"],"i":["Începe cu motivul tău personal; când motivația scade, el te duce la sală, iar consecvența contează mai mult decât programul perfect.","Fiecare grupă măcar o dată pe săptămână; începe cu o compusă (genuflexiuni, piept, îndreptări, presă, tracțiuni), apoi accesorii de estetică.","Recomandă split sus-jos, 3 sau 4 zile; autorul face 8-10 seturi pe grupă pe săptămână cu intensitate mare, deși menționează 10-15 ca interval optim din studii.","Progresie: dacă ai făcut 5x5 cu 135 lbs, săptămâna viitoare țintești 5x6 sau măcar o repetare în plus; fără notare, antrenamentul e doar o alegere la întâmplare.","Mergi zilnic, circa 10.000 de pași, pentru recuperare, digestie și lumină naturală; proteine aproape de 1 g pe livră din greutatea țintă, din mâncare integrală."],"e":[["incline bench press","3x6-10, zi de partea superioară"],["incline dumbbell flies","3x8-12"],["wide grip lat pulldowns"],["T-bar rows"],["lateral raises"],["incline curls"],["tricep overhead extensions"]],"c":["10-15 seturi pe grupă pe săptămână (valoarea citată ca optimă)","8-10 seturi pe săptămână la autor","3 sau 4 zile pe săptămână","10.000 de pași pe zi","1 g proteină per livră din greutatea țintă (180 lbs = 180 g)","5x5 cu 135 lbs, apoi 5x6"]},{"v":"fj6rRzImvSM","k":"l","t":"How to guarantee you will never make gains and stay average","d":"06.04.2025","th":["mentalitate","principii-antrenament","recuperare-si-somn"],"i":["Ce garantează lipsa rezultatelor: antrenamente sărite, program schimbat săptămânal, somn puțin, provocări de 30 de zile și consum nesfârșit de conținut fitness.","Ce funcționează: ridici 3-4 zile pe săptămână, în fiecare săptămână, ani la rând, cu ore fixe de antrenament și de masă, pe baza unui plan.","Echipamentul scump, un split pe 7 zile și multe suplimente nu sunt necesare; contează să notezi antrenamentele și să crești greutatea în timp.","Atinge ținta de proteine, dormi 7-8 ore într-o cameră întunecată și rece, mergi zilnic, mănâncă alimente integrale și planifică ziua următoare."],"e":[],"c":["3-4 zile de antrenament pe săptămână","somn 7-8 ore","mai mult de 10 ani de antrenament"]},{"v":"YuPLuSSt664","k":"l","t":"How I Got Jacked Training 3 Days a Week So You Can Just Copy Me","d":"04.04.2025","th":["program-si-split","volum-si-frecventa","recuperare-si-somn","failure-si-progresie"],"i":["Mult sfat fitness vine de la oameni cu substanțe; un atlet natural nu poate copia volumul și recuperarea lor (părerea autorului).","Trei zile: sus-jos-sus sau push-picioare-pull, cu o zi liberă între antrenamente; fiecare ședință începe cu o mișcare compusă grea, păstrată 12 săptămâni.","După mișcarea grea, accesorii de estetică: 3-5 seturi de 8-12 sau 8-15 repetări, pauză circa 90 s; la final ar trebui să te îndoiești că mai poți.","Rotește variantele (înclinat cu gantere, priză largă cu îngustă) la 12-16 săptămâni, doar ca să eviți suprasolicitarea articulațiilor.","Somn 7-8 ore: cameră neagră și rece, fără cafeină cu 8 ore înainte, fără lumină albastră o oră; ia magneziu glicinat. Proteine circa 1 g pe livră.","Fiecare grupă o dată pe săptămână, sub 12 seturi, funcționează dacă fiecare repetare e făcută cu efort maxim, fără accidentări."],"e":[["incline bench","mișcare compusă grea, 3 seturi de 6-10, pauză 2-3 minute"],["overhead press"],["lat pulldowns","priză largă"],["pendulum squats"],["weighted pull-ups"],["trap bar deadlifts"],["incline dumbbell press","accesoriu"],["incline flies"],["lateral raises"],["face pulls"],["split squats"],["hamstring curls"],["calf raises"],["chest supported T-bar row","ziua pull"],["machine rear delt flies"],["cable rear delt flies (katanas)"],["incline dumbbell curls"],["cable curls"]],"c":["3 zile pe săptămână (marți sus, joi jos, duminică sus)","compusă: 3 seturi de 6-10, pauză 2-3 minute","accesorii: 3-5 seturi de 8-12 sau 8-15, pauză 90 secunde","același exercițiu 12 săptămâni; rotație la 12-16 săptămâni","sub 12 seturi totale pe grupă pe săptămână","1 g proteină per livră","somn 7-8 ore, fără cafeină cu 8 ore înainte de culcare"]},{"v":"oAb71RIdwnc","k":"l","t":"DON'T make these workout mistakes (kills your gains)","d":"02.04.2025","th":["accidentari-si-articulatii","volum-si-frecventa","recuperare-si-somn"],"i":["Accidentarea e cel mai mare dușman al câștigurilor; apare mai ales din suprasolicitare, încălzire sărită, formă proastă din ego și prea multe zile de antrenament.","Un program de 3 zile aduce, după autor, circa 95% din câștiguri, iar a patra zi te duce spre 99%; peste 4 zile nu e necesar decât dacă concurezi.","Cine promovează antrenamente 6-7 zile pe săptămână ia de obicei substanțe care accelerează recuperarea; sfaturile lor te pot accidenta.","Dacă vrei obiceiul zilnic, în zilele libere fă cardio ușor, mers pe înclinație sau puțin abdomen, fără să încarci articulațiile.","La dureri minore reduci mai întâi numărul de zile, apoi numărul total de seturi și repetări pe săptămână."],"e":[],"c":["3 zile = circa 95% din câștiguri","4 zile = circa 99%","peste 4 zile nu e necesar pentru un fizic estetic","de 10 ori mai multă testosteron la cei care iau substanțe (afirmația autorului)"]},{"v":"RubN0kWnD3Q","k":"l","t":"If you’ve been lifting but still look average, watch this.","d":"01.04.2025","th":["principii-antrenament","failure-si-progresie","volum-si-frecventa","mentalitate"],"i":["Mulți rămân blocați pentru că schimbă programul săptămânal și urmăresc zeci de creatori; progresul real vine din rămânerea pe un singur plan.","Intră în sală cu un plan, notează antrenamentele și împinge seturile aproape de eșec, până când mai ai 2-3 repetări posibile; pe mișcări noi oprește-te mai devreme.","Antrenează-te 3-4 zile pe săptămână: sfaturile de la culturiști cu recuperare supraomenească duc la dureri și accidentări pentru majoritatea.","Mănâncă alimente reale și dense în nutrienți, nu mânca prea puțin, adormi și te trezești la aceleași ore.","Nu ai nevoie de periodizare, foi de calcul sau variații continue; ajung compusele, accesoriile pentru estetică, urmărirea greutăților, intensitatea și recuperarea."],"e":[],"c":["3-4 zile pe săptămână","2-3 repetări rămase la finalul unui set cu adevărat greu"]},{"v":"quuU8yJP8G8","k":"l","t":"Getting Jacked Isn’t Complicated… You’re Just Doing Too Much","d":"27.03.2025","th":["program-si-split","principii-antrenament","nutritie","cardio-si-pasi"],"i":["Propune split sus-jos în 4 zile (fiecare grupă de 2 ori pe săptămână); ședința începe cu o compusă grea, apoi circa două exerciții pe grupă mare.","Notează într-un caiet data, exercițiile, seturile, repetările și greutatea, apoi încearcă să le depășești: dacă ai făcut 10, ia 11 repetări sau crești greutatea.","Mănâncă alimente integrale, fără diete rigide (keto, carnivor, vegan); țintește proteina egală cu greutatea țintă în livre (180 lbs = 180 g).","Pregătește mesele din timp, ca să nu ajungi la fast-food când ești obosit și flămând.","Mersul zilnic ajută la slăbit și claritate; urmărește pașii în aplicația de sănătate (circa 10.000) și ieși la lumină naturală."],"e":[],"c":["4 zile pe săptămână, split sus-jos","2 exerciții pe grupă mare","10.000 de pași","180 lbs = 180 g proteină"]},{"v":"zC_w7ddHXq0","k":"l","t":"20 Pieces of Advice After 10 Years in the Gym","d":"26.03.2025","th":["principii-antrenament","mentalitate","nutritie","recuperare-si-somn"],"i":["Mergi la antrenament și când nu ai chef: motivația dispare, iar rezultatele se construiesc în zilele grele; consecvența bate intensitatea ocazională.","3-4 zile pe săptămână ajung dacă te antrenezi foarte tare; progresia, notarea fiecărui antrenament și bazele de modă veche bat metodele sofisticate.","Îngrașă-te încet, puțin peste întreținere; un bulk murdar îți strică hormonii și te obligă la un cut mai lung.","Mersul e cardio-ul cel mai subestimat: arde grăsime, ajută recuperarea și nu agresează articulațiile.","Țintește circa 1 g de proteină per livră, 8 ore de somn într-o cameră întunecată și rece, fă analize de sânge și antrenează picioarele.","Rămâi pe o metodă cel puțin un an, încălzește-te cu atenție, evită ego lifting-ul și stai printre oameni cu aceleași standarde."],"e":[],"c":["3-4 zile pe săptămână","1 g proteină per livră din greutatea corporală","8 ore de somn","cel puțin un an pe aceeași metodă","suplimente folosite de autor: vitamina D, zinc și bor"]},{"v":"pgqFeZ7N8Hw","k":"l","t":"How To Achieve More This Year In The Gym Than Most People Do in 5 years.","d":"23.03.2025","th":["volum-si-frecventa","recuperare-si-somn","principii-antrenament","mentalitate"],"i":["Dacă după un an de antrenament nu vezi schimbări mari și te antrenezi natural peste 4 zile pe săptămână, problema e probabil recuperarea insuficientă.","Formulă în cinci pași: 3-4 zile pe săptămână, plan verificat, recuperare serioasă, urmărirea riguroasă a greutăților și consecvență fără schimbat programe.","Fiecare repetare cu formă bună și efort maxim, fără să sari bara de piept sau aparatul și fără goana după finalul setului.","Dormi 7-9 ore (minim 7, ideal 8), mănâncă destulă proteină și gestionează stresul, pentru că stresul mintal frânează recuperarea și creșterea.","Notează antrenamentele și greutatea corporală; presupunerea „cred că pot adăuga greutate” duce la stagnare."],"e":[],"c":["3-4 zile pe săptămână","somn 7-9 ore, ideal 8","peste 1 an fără rezultate = abordare greșită","peste 4 zile pe săptămână la un natural = semnal de alarmă","peste 15 lbs de mușchi într-un an la unii clienți (afirmația autorului)"]}],"ghid":{"teme":[{"id":"filozofia-canalului","titlu":"Filozofia canalului","rezumat":"Antrenament simplu, greu și puțin, cu progres notat, plus o viață sănătoasă în afara sălii, repetate ani la rând. Totul e gândit pentru cine se antrenează natural și vrea să arate bine, nu să urce pe scenă.","reguli":[{"text":"Mușchiul cere trei lucruri: un set greu ca stimul, recuperare și progres în timp. Splitul perfect, unghiurile și numărul exact de seturi sunt detalii cu randament mic.","surse":["gbIZRqg1xW8","K2EfOas8xkE","w_fkIHPJdU0","Xr6QKztf8zU"]},{"text":"Judecă antrenamentul după progres, nu după cât faci: oboseala, pompa și febra musculară nu dovedesc creșterea, cifrele din caiet da.","surse":["VwuWli9zgw8","muF7RTPUtnY","IM183WSvPpA","J0j90bDSKLs"]},{"text":"Ținta nu e mărimea maximă, ci destul mușchi cât să se vadă că ridici, rămânând suplu, puternic și atletic.","surse":["umnStUj2Myk","W1CD8IrHz_0","MVQWoflvdro","R1Wlezwn_tc"]},{"text":"Gândește în tipare de mișcare, nu în exerciții obligatorii: corpul simte tensiunea, nu numele aparatului. Alege varianta care îți place și nu te doare.","surse":["2XHGW1q_OWI","GkefyWBkOik","D18iX55Q7yE"]},{"text":"Alege o singură sursă și un program dovedit și urmează-l 6–12 luni, fără să amesteci metode de la mai mulți autori.","surse":["0AahBSFSKWU","hL_IAtK-bzM","Jq9ceQWUpfo","uITwVBuL01E"]},{"text":"Sfaturile cu 6–7 zile și 2 ore în sală vin, după autor, de la oameni pe steroizi, care se recuperează altfel. Un antrenat natural nu le poate copia.","surse":["OKRYok3x7PY","OcaOx-SPbo8","Lxvvx1xOh3Q"]},{"text":"Baza ajunge: 3 antrenamente pe săptămână, circa 10.000 de pași, mâncare reală, soare, 7+ ore de somn, apă. Greu nu e să afli ce ai de făcut, ci să o faci destul de mult.","surse":["8KkXKHfMeDk","XEY263yPYbM"]},{"text":"Gândește în ani: autorul socotește 2–3 ani pentru o schimbare serioasă și consideră false promisiunile de 30 de zile sau 12 săptămâni.","surse":["8ZPboN46wZg","BZuePhPJ5sY","sZjRLpk-SHQ"]},{"text":"Versiunea minimă: 5–6 exerciții care acoperă tot corpul, 2–3 zile pe săptămână și cifrele triplate în 5 ani te fac musculos, spune autorul.","surse":["dfLJjmJVZxM"]},{"text":"Repere orientative de forță pentru un bărbat, la o repetare: overhead press 135–150 lb, bancă 225, genuflexiune 315, deadlift 405. Variază cu proporțiile corpului.","surse":["gFlY6IeZbIA","Fs6RYD5h_bM"]}]},{"id":"program","titlu":"Programul: metoda ×4, variante, split, zile","rezumat":"Canalul are acum două scheme pe 3 zile: metoda ×4 (3×4, 2×4, 1×4) și rutina cu maxim de antrenament pentru cine are deja bază. Splitul preferat e piept-umeri-triceps, picioare, spate-biceps.","reguli":[{"text":"Metoda ×4: primul număr arată seturile de lucru pe exercițiu, fără încălzire, iar 4 arată exercițiile de bază din fiecare antrenament.","surse":["1-fhMgpzndk","8VhUvd2KAPY"]},{"text":"Alege după vechime: 3×4 în primii 0–2 ani, 2×4 la 2–3+ ani, 1×4 dacă ești avansat. Nu sunt praguri stricte și nu ești obligat să treci la varianta următoare.","surse":["1-fhMgpzndk","8VhUvd2KAPY"]},{"text":"Trei zile: piept-umeri-triceps, picioare, spate-biceps, cu o zi liberă între ele și două după ultima. Picioarele stau între zilele de sus, iar fiecare grupă mare e lucrată o dată pe săptămână.","surse":["1-fhMgpzndk","-AUq2yVc-0Q","e0DBQ7ZZNRM","5qYOMywutrY"]},{"text":"A patra zi e opțională și merge pe ce rămâne în urmă: gât, antebrațe, abdomen, gambe, plus un sprint.","surse":["1-fhMgpzndk","8VhUvd2KAPY","FZxtY3H9rDs"]},{"text":"Zilele 1×4: 1) press înclinat, fly, laterale la cablu, pushdown; 2) presă de picioare, RDL, extensii, flexii; 3) pulldown larg, ramat sprijinit, rear delt, curl înclinat.","surse":["FZxtY3H9rDs","FdqsrOh-4_4"]},{"text":"Rutina de forță, pentru cine are bază: începi fiecare zi cu un maxim de antrenament (1 repetare, 1 set, la ~85% din maximul real), apoi 4–6 exerciții pentru masă.","surse":["e0DBQ7ZZNRM","UHeYjD00oao","2eM-7Pj3Qmk","xM9_9tb-8cA"]},{"text":"În rutina de forță, maximul alternează săptămânal: bancă plată cu overhead press, genuflexiune cu trap bar deadlift. În ziua de spate rămâne tracțiunea cu greutate.","surse":["e0DBQ7ZZNRM","UHeYjD00oao"]},{"text":"Dacă ai doar două zile: upper/lower (ex. luni și joi) sau full body, cu câteva zile de pauză între ele. Un antrenament pe mușchi poate ajunge dacă antrenezi tare și progresezi.","surse":["4jUUv_-gveo"]},{"text":"În primul an, autorul recomandă upper/lower de 3–4 zile sau push-legs-pull de 3 zile. Contează mai mult consecvența și progresul decât splitul.","surse":["1a8cYxByZOo","L7vM1bry5xY"]},{"text":"Un split e bun dacă răspunzi da la trei întrebări: te recuperezi și devii mai puternic? Ești fără dureri persistente? Lovești fiecare grupă cel puțin o dată în 7 zile?","surse":["KsT4v8OEt98","BsVjlUb0Ax4","5OFcm6naGfk"]}]},{"id":"seturi-repetari-pauze","titlu":"Seturi, repetări, pauze","rezumat":"Puține seturi grele, într-o zonă moderată de repetări, cu pauze destul de lungi. Numărul de seturi scade pe măsură ce crește experiența.","reguli":[{"text":"Majoritatea fac bine cu 2–3 seturi de lucru pe exercițiu. Un singur set e pentru cei cu experiență, care știu să meargă la limită.","surse":["4jUUv_-gveo","8UAwTKLTpm8","zCcNkYPjCM4","1-fhMgpzndk"]},{"text":"Repetări: 6–10 la exercițiile compuse, 8–15 la izolări. Autorul numește moderată zona 6–15, iar peste 15 efortul seamănă tot mai mult cu un cardio.","surse":["1-fhMgpzndk","cBbcY8WsMQ4","kCAf02K1pzc"]},{"text":"La izolări, dacă nu poți crește greutatea, lărgești intervalul (6–10, apoi 6–15, apoi 20) sau folosești o plăcuță de 2,5 lb pe stivă.","surse":["v93wiouVoYA"]},{"text":"Pauze: 2–3 minute la exercițiile compuse, 1–2 minute la izolări.","surse":["1-fhMgpzndk","8VhUvd2KAPY"]},{"text":"Pune 4–5 exerciții pe antrenament. Antrenamentul întreg durează în jur de 30–45 de minute, cu tot cu încălzire.","surse":["8UAwTKLTpm8","yMdcDFVSYuk","4fWA0Epctbk"]},{"text":"Volum săptămânal: autorul pornește de la cam 6 seturi grele pe grupă, apoi ajustezi. El face chiar mai puțin (4–6), pentru că pune calitatea setului înaintea numărului.","surse":["w_fkIHPJdU0","gbIZRqg1xW8"]},{"text":"Testul săptămânii, la autor: fiecare grupă mare a primit cel puțin un set direct foarte greu și a existat progres. Restul numărătorilor le-a abandonat.","surse":["BtYS7WT1aqk"]},{"text":"Autorul nu e de acord cu cele 10–20 de seturi pe grupă pe săptămână: preferă mai puțin și să fie sănătos peste 5 ani, în locul unui posibil câștig de 2–3%. E părerea lui.","surse":["NElCFHF2gyI"]},{"text":"Dacă un set nu-ți ajunge, treci la două, apoi la trei: cauți cantitatea strict necesară, nu cea mai mare pe care o suporți.","surse":["Xj8V30MMAGs"]},{"text":"Un set de lucru durează cam 60–90 de secunde, urmat de circa 2 minute de pauză, deci fiecare exercițiu îți ia 4–5 minute.","surse":["4fWA0Epctbk"]}]},{"id":"progresie-failure","titlu":"Progresie și failure","rezumat":"Ținta fiecărui antrenament e să faci mai mult decât data trecută, iar failure e doar un mijloc. Totul se notează, altfel nu știi ce ai de bătut.","reguli":[{"text":"Ținta nu e failure, ci progresul: mai mult decât data trecută, printr-o repetare în plus, mai multă greutate sau execuție mai bună.","surse":["niRNSxLWHns","qWYd5OUH-_s","fsLV7JlKhI4"]},{"text":"Setul greu merge până la failure sau până la un record nou, ce vine primul. Failure înseamnă că nu mai poți termina o repetare cu tehnică bună.","surse":["e0DBQ7ZZNRM","OjH9KRPmHCE","O6XGuj8qOqA"]},{"text":"Failure e o senzație, nu o măsurătoare: poți merge la limită săptămâni la rând fără să progresezi. Dovada e doar în cifre.","surse":["WWhFU1FCm1I","qWYd5OUH-_s"]},{"text":"Notează trei lucruri la fiecare antrenament: exercițiul, greutatea, seturile și repetările. Pe hârtie sau în telefon, nu în minte.","surse":["vUEQjy1a4ts","6t4ivt0p9Vs","zYdN2NMGPZQ"]},{"text":"Progresia de bază: pornești de jos din interval, adaugi câte o repetare, iar la capătul de sus crești puțin greutatea și reiei de jos. Ex.: 6, 7... 10, apoi +5 lb și iar 6.","surse":["e0DBQ7ZZNRM","bIqpP8T2j48","FZxtY3H9rDs"]},{"text":"Cu mai multe seturi: alege o greutate cu ~2 repetări în rezervă la 6, urci pe rând (6/6, 7/6, 7/7... 10/10), apoi adaugi puțină greutate și reiei.","surse":["4jUUv_-gveo"]},{"text":"La maximul de antrenament: reușești, crești cu cel mai mic pas (5 lb sus, ~10 lb la genuflexiune și trap bar); eșuezi, repeți; eșuezi de două ori, scazi 10% și urci din nou.","surse":["e0DBQ7ZZNRM"]},{"text":"Fă cel mai mic salt care încă e progres: salturile mari strică tehnica și recuperarea. Microdiscurile de 2,5 lb ajută după ce trec câștigurile ușoare de început.","surse":["hoI88DObYt8","bIqpP8T2j48"]},{"text":"Nu trebuie să bați recordul la fiecare antrenament. Contează să faci mult mai mult după 6 luni sau un an; la nivel intermediar progresul nu e liniar.","surse":["GHUiiq6WK4M","zYdN2NMGPZQ","S7gwSl8ALB0"]},{"text":"Când stagnezi, nu adăuga automat volum: verifică somnul, hidratarea, stresul, caloriile și ultimul deload, apoi schimbă o singură variabilă odată.","surse":["S7gwSl8ALB0","ft95b8Yv_Zc","-uqGgp7EpPU"]}]},{"id":"executia-repetarii","titlu":"Execuția repetării","rezumat":"Repetările controlate, identice de la o săptămână la alta, fac progresul real și măsurabil. Tempoul exact nu contează.","reguli":[{"text":"Fă o pauză scurtă (~½ secundă) în partea de jos a repetării: scoate elanul și îți arată dacă ai devenit mai puternic. Autorul nu pretinde că pauza are efect magic asupra mușchiului.","surse":["bu8AL6KcxWU","_Qw6Jwi5Ut8","a0Lr9vx1qyo"]},{"text":"Păstrează aceeași execuție mereu: dacă pui pauză azi, pui și săptămâna viitoare. Doar așa o repetare în plus sau 2,5–5 lb înseamnă progres.","surse":["bu8AL6KcxWU"]},{"text":"Nu sări bara de pe piept la bancă, nu o bate de podea la deadlift și nu folosi recul la presă. Un record obținut prin elan ține de orgoliu, nu de forță.","surse":["bu8AL6KcxWU","Zbr9-U7edWo"]},{"text":"Nu număra secunde: formă bună, control, întindere completă. Întrebarea e dacă fiecare repetare a fost cât de bună ai putut. Nu există tempo magic.","surse":["fKxZnzT62mU","ErlBDk2ujgk","3WC9aezWGTE"]},{"text":"Dacă te balansezi ca să ajungi la 10 repetări, scazi greutatea: elanul reduce tensiunea mecanică, adică motorul creșterii.","surse":["_g8ZbKAOKcg"]},{"text":"Forma se poate strica puțin spre failure, dar rămâi în control și nu arunci greutatea. Repetările nu trebuie să arate perfect, doar să nu fie neglijente.","surse":["Zt2QTAlVAQw","T22M8iHv_qw"]},{"text":"Autorul consideră tensiunea constantă supraestimată: un set aproape de failure creează destulă tensiune și cu o pauză scurtă.","surse":["bu8AL6KcxWU","q4Wx_ebZtDM"]},{"text":"Dacă faci repetări trișate sau parțiale după cele curate, cum a încercat autorul, în jurnal intră doar cele curate.","surse":["D3hIVMR2djg"]}]},{"id":"piept","titlu":"Piept","rezumat":"Două mișcări ajung: o împingere pentru încărcare și un fly pentru întindere, cu accent pe partea de sus a pieptului.","reguli":[{"text":"Lucrează pieptul cu o împingere și un fly, nu cu două împingeri și nici cu 5–6 exerciții.","surse":["QSr5pxHjL2Y","euJsP8OG8FY","MpEN_i7FH0E"]},{"text":"Împingerea preferată e pe înclinat, cu gantere sau la aparat convergent, pentru partea de sus a pieptului, des neglijată și care lucrează bine și restul.","surse":["QSr5pxHjL2Y","xM9_9tb-8cA","4fWA0Epctbk"]},{"text":"Intervale: împingere 6–10 repetări, fly 8–12 (uneori 15), cu +1 repetare pe săptămână și puțină greutate la capătul de sus.","surse":["QSr5pxHjL2Y"]},{"text":"La împingere coboară controlat până la o întindere adâncă, oprește scurt, fără săritură, apoi împinge cu atenția pe piept.","surse":["QSr5pxHjL2Y","nidOZfyTHuY"]},{"text":"Fly-ul (pec deck, cablu, gantere) dă întindere și te lasă să mergi la limită fără grija echilibrului, iar tricepsul nu te oprește înainte de piept.","surse":["xM9_9tb-8cA","4fWA0Epctbk"]},{"text":"Dacă o variantă îți supără articulațiile, schimb-o: aparat, gantere, Smith, flotări sau dips. Ține-o pe cea care nu doare, îți place și la care poți progresa ani la rând.","surse":["QSr5pxHjL2Y","2XHGW1q_OWI"]},{"text":"În rutina de forță, ziua începe cu bancă plată cu bara, 1 repetare la ~85%, apoi press înclinat la aparat și fly.","surse":["xM9_9tb-8cA","e0DBQ7ZZNRM"]},{"text":"Rotește variantele de press la câteva luni, ca să eviți suprasolicitarea. Autorul nu vede nevoia de 15 seturi de piept: oboseala în plus nu înseamnă creștere.","surse":["4fWA0Epctbk"]}]},{"id":"spate","titlu":"Spate","rezumat":"O tracțiune verticală pentru lățime și un ramat orizontal pentru grosime, cu greutate pe care o controlezi.","reguli":[{"text":"Două tipare acoperă spatele: tragere verticală pentru lățime și tragere orizontală pentru grosime.","surse":["IPQPldW5wuc","2XHGW1q_OWI","kMitI9VpNAQ"]},{"text":"Alegerile autorului: pulldown cu priză largă și ramat T-bar cu pieptul sprijinit.","surse":["qYz-7S-rxDw","IPQPldW5wuc","cBriDXhva_M"]},{"text":"La pulldown: coapsele fixate sub pernă, bara spre pieptul de sus, coatele în jos și înapoi, fără să te lași pe spate; revii lent până la întindere completă.","surse":["02Qci1-0Aao","IPQPldW5wuc"]},{"text":"La ramatul sprijinit: pieptul lipit de pernă, stretch complet jos, fără smucit. Sprijinul scoate din ecuație lombarul și picioarele, deci poți merge la limită.","surse":["IPQPldW5wuc","Mlr-Lx-10HQ","cBriDXhva_M"]},{"text":"Interval: 6–10 repetări, +1 pe săptămână, iar la 10 curate crești greutatea și cobori la 6.","surse":["IPQPldW5wuc"]},{"text":"La tracțiuni urci de la 6 la 10–12 repetări curate, apoi adaugi un disc mic (5–10 lb) la centură și reiei de la 6.","surse":["6t4ivt0p9Vs","kMitI9VpNAQ"]},{"text":"Tracțiune cu greutate: priză de sus, cam la lățimea umerilor, umerii jos și înapoi, abdomenul încordat, bărbia peste bară, fără balans; cobori controlat până la brațe întinse.","surse":["XxPnmbSBSZo"]},{"text":"În rutina de forță, ziua de spate începe cu tracțiunea cu greutate (1 repetare la ~85%), urmată de pulldown, ramat sprijinit, curl și rear delt.","surse":["UHeYjD00oao"]},{"text":"Poți înlocui oricând în același tipar: tracțiuni late, landmine row, T-bar, ramat cu bara, ramat inversat.","surse":["GkefyWBkOik","ErlBDk2ujgk"]},{"text":"Înainte de trucuri pentru spate, urcă de la 5 la 20 de tracțiuni cu greutatea corpului. Gândește în 52–100 de săptămâni, nu în 18.","surse":["L2LBks-Vc3c"]}]},{"id":"umeri","titlu":"Umeri","rezumat":"Lucru direct pe lateral și posterior; partea din față primește deja destul din împingeri, după autor.","reguli":[{"text":"Umerii din două mișcări: ridicări laterale pentru lățime și rear delt fly pentru spatele umărului. Fața umărului lucrează deja la împingeri, spune autorul.","surse":["hJiCTV65MjU"]},{"text":"Ridicările laterale merg cel mai bine la cablu: fără avânt, urci și cobori controlat, cu o pauză jos în întindere. Merg și cu gantere, bandă sau discuri.","surse":["hJiCTV65MjU","nidOZfyTHuY"]},{"text":"La rear delt, autorul preferă reverse pec deck, stabil și ușor de progresat. Alternative: cablu sau gantere aplecat.","surse":["hJiCTV65MjU"]},{"text":"Rear delt la cablu: cablurile puțin peste nivelul ochilor, faci pași înapoi până simți tensiune, duci mâinile în jos și peste corp, coate ușor îndoite, fără balans.","surse":["QRUaTRQ_M64"]},{"text":"Interval pentru ambele: 8–15 repetări; dacă azi ai făcut 10, ținta e 11; la 15 curate crești puțin greutatea și reiei de la 8.","surse":["hJiCTV65MjU"]},{"text":"Cine împinge mult poate preveni probleme de umăr cu lucru direct pe posterior, spune autorul.","surse":["4IutvZTTBmQ","cBriDXhva_M"]},{"text":"Overhead press: picioare la lățimea umerilor, abdomen și fese încordate, pauză scurtă pe piept, împins vertical, fără impuls din picioare. În rutina de forță alternează cu banca.","surse":["afR3tPH6y_g","msQ_TxypRII","e0DBQ7ZZNRM"]},{"text":"Press la aparat: scaunul reglat cu mânerele la umeri sau puțin sub, spatele lipit, cobori lent până la ~90° la coate.","surse":["DD_N1OvKSQc"]},{"text":"Dublarea greutății la laterale (de la 15 la 30 lb, spre 30–40 lb) contează mai mult decât căutarea unghiului exact.","surse":["w_fkIHPJdU0","v93wiouVoYA"]}]},{"id":"brate","titlu":"Brațe","rezumat":"Două mișcări pentru biceps și două pentru triceps, duse la forță tot mai mare, fără trucuri.","reguli":[{"text":"Biceps din două mișcări: un curl cu întindere (brațele în spatele corpului) și un curl cu priză neutră, care lucrează și mușchii de sub biceps și antebrațul.","surse":["YqVNxuYVIow","Ijb2DRP2Ozg","4IutvZTTBmQ"]},{"text":"Curl înclinat: reglezi banca după preferință (canalul dă între 30° și 60°), brațele atârnă, pornești din întindere completă, fără elan, și cobori lent.","surse":["rAx_tf13V5k","ErlBDk2ujgk","jWShh_oqKww"]},{"text":"Gândește-te să strângi bicepsul ca să îndoi brațul, nu să ridici gantera: reduce elanul și ține tensiunea unde trebuie.","surse":["fSheXgJp5sw","_g8ZbKAOKcg"]},{"text":"Triceps din două mișcări: extensia deasupra capului și pushdown-ul. Presele lucrează deja tricepsul indirect, deci nu-ți trebuie mai multe.","surse":["hhTPtNsqS5o","jWShh_oqKww"]},{"text":"Pushdown: bară dreaptă, priză la lățimea umerilor, coate lipite, extensie completă fără să miști brațul de sus, revenire lentă până puțin peste 90°.","surse":["smJDNLy6xSM","hhTPtNsqS5o"]},{"text":"Extensie peste cap: bară dreaptă la cablu pentru stabilitate, brațele de sus fixe, întindere adâncă jos, scurtă pauză, apoi extensie completă.","surse":["hhTPtNsqS5o"]},{"text":"Interval: 8–15 repetări, +1 pe antrenament, iar la 15 curate crești puțin greutatea și reiei de jos.","surse":["hhTPtNsqS5o","YqVNxuYVIow"]},{"text":"Brațul nu crește din hack-uri: crește din forță, de exemplu de la 20 la 40 lb pentru 10 repetări în doi ani, la un singur exercițiu bun.","surse":["rsjLRvOrXCg","oZv5qnmAH0I"]},{"text":"Dacă ridici doar gantere de 20 lb la biceps, nu-ți lipsește lucrul direct, ci forța la câteva mișcări.","surse":["xpL6DzUItSs"]}]},{"id":"antebrate","titlu":"Antebrațe","rezumat":"Rulatul pe încheietură e exercițiul de bază, la finalul antrenamentului. Începătorii nu au nevoie de lucru direct.","reguli":[{"text":"Wrist roller-ul lucrează flexorii și extensorii antebrațului și priza. Se face la finalul antrenamentului.","surse":["RgleDMQpIXc","xM9_9tb-8cA","TW6koHrlqp0"]},{"text":"Doză: un set la failure, opțional 2–3 seturi.","surse":["RgleDMQpIXc"]},{"text":"Fără accesoriu, folosești capătul unei bare, o bandă elastică și un disc.","surse":["RgleDMQpIXc"]},{"text":"O urcare și o coborâre fac un set. Crești întâi numărul de rulări, iar greutatea abia când poți face 4 seturi fără oprire.","surse":["3eEAkoKpncA"]},{"text":"Hammer curl-ul lucrează un mușchi mare al antebrațului și îngroașă brațul: coatele lipite, ganterele urcă drept, nu peste corp.","surse":["TW6koHrlqp0","Ijb2DRP2Ozg","3eEAkoKpncA"]},{"text":"Dacă adaugi flexii de încheietură și inverse, fă 1–3 seturi de 8–15 repetări, cu antebrațele ușor în afara băncii.","surse":["vfjwE3k3Rw0","3eEAkoKpncA"]},{"text":"Începătorii n-au nevoie de lucru direct: tracțiunile, ramatul și deadlift-ul le cresc singure multă vreme.","surse":["3eEAkoKpncA"]},{"text":"Trap bar deadlift-ul ține antebrațele sub tensiune: strângi mânerele continuu și renunți la chingi. E preferatul autorului pentru antebrațe.","surse":["3eEAkoKpncA"]},{"text":"Autorul le lucrează și pentru priză și ca să prevină problemele de cot; o spune ca observație proprie.","surse":["vfjwE3k3Rw0","3eEAkoKpncA"]}]},{"id":"picioare","titlu":"Picioare","rezumat":"Patru exerciții de bază: o mișcare mare pentru cvadricepși, un hinge pentru partea din spate, extensii și flexii. Gambele și abdomenul sunt opționale.","reguli":[{"text":"Schema simplă: trap bar deadlift și presă ca exerciții compuse, apoi leg curl și leg extension. Gambele și abdomenul sunt opționale.","surse":["yuNdjkl6Ytc","sYxXsJkT6Fk"]},{"text":"Trap bar-ul e mai ușor de învățat și mai blând cu spatele decât deadlift-ul clasic, spune autorul.","surse":["yuNdjkl6Ytc","sYxXsJkT6Fk"]},{"text":"Execuție la trap bar: picioarele puțin mai înguste decât umerii, cobori ca la genuflexiune, scoți jocul din bară, spatele drept, fără smucitură, împingi prin călcâie.","surse":["clwWwSr4gPI"]},{"text":"Presa încarcă cvadricepșii mult, fără grija echilibrului și fără oboseală generală în plus.","surse":["2eM-7Pj3Qmk","sYxXsJkT6Fk"]},{"text":"Fără presă de picioare: genuflexiune cu bara, fandări inverse sau split squat bulgar.","surse":["yuNdjkl6Ytc","xJHilbebyMo"]},{"text":"Pentru partea din spate a coapsei combini un hinge (RDL sau trap bar) cu o flexie de genunchi (leg curl sau Nordic curl).","surse":["2XHGW1q_OWI","4-ERnMonUGQ"]},{"text":"Interval larg, 6–20 repetări, cu pauze de 1–3 minute. Exemplu la trap bar: de la 6 la 10 repetări, apoi +5 lb și iar de jos.","surse":["yuNdjkl6Ytc"]},{"text":"În rutina de forță începi cu un maxim de antrenament la trap bar sau genuflexiune, apoi 5–6 exerciții; același deadlift revine mai ușor, la 6–10 repetări, pentru masă.","surse":["2eM-7Pj3Qmk","e0DBQ7ZZNRM"]},{"text":"Gambele merg la Smith, cu gantere sau cu bara: repetări foarte multe, de pe un bloc, pentru amplitudine.","surse":["yuNdjkl6Ytc","sYxXsJkT6Fk"]},{"text":"Autorul schimbă variantele la 3–4 luni și lucrează acum pe rând, câte un picior: mai puțină oboseală generală; pe două picioare economisești timp.","surse":["4-ERnMonUGQ"]}]},{"id":"abdomen-gat","titlu":"Abdomen și gât","rezumat":"Abdomenul se vede când slăbești, nu când faci abdomene; gâtul se lucrează direct, cu greutate mică și progresie lentă.","reguli":[{"text":"Abdomenul se vede printr-un deficit caloric și pierdere de grăsime, nu prin roată sau aparat.","surse":["7xQm507XKWE","OQ2KQLjaXRA","w1EBPwnkBdI"]},{"text":"Abdomenele nu topesc grăsimea de pe abdomen: slăbirea localizată nu există (idee citată din Mentzer).","surse":["nJ2pX_KcsHU"]},{"text":"Dacă vrei lucru direct, autorul alege cable crunch cu coardă sau ridicări de genunchi ori picioare din atârnat, în ziua opțională.","surse":["7xQm507XKWE","w1EBPwnkBdI","FZxtY3H9rDs"]},{"text":"Exercițiile compuse lucrează deja abdomenul; lucrul direct contează doar dacă îl vrei mai gros.","surse":["OQ2KQLjaXRA","7xQm507XKWE"]},{"text":"Autorul numește gâtul cel mai ignorat mușchi: se vede mereu, iar un gât puternic ajută, spune el, și la prevenirea accidentărilor.","surse":["-00SlScAgDw","b3-b2SrLS6E"]},{"text":"Pornești cu neck curl cu greutatea corpului, la final de antrenament, până la failure, fără mișcare de crunch; adaugi rotiri și extensii, câte un set.","surse":["-00SlScAgDw"]},{"text":"Ca începător, urci cu greutatea corpului până la ~50 de repetări, apoi un disc de 2,5–5 lb cu un prosop sub el, de la 10 spre 20–30 de repetări.","surse":["STBdKolVZuA","-00SlScAgDw"]},{"text":"Autorul nu depășește 45 lb la neck curl și face în jur de 30 de repetări: greutate moderată, nu maxim.","surse":["STBdKolVZuA"]},{"text":"Măsoară gâtul înainte și după 6 luni. Reperul amintit de autor: brațul aproape cât gâtul.","surse":["vfjwE3k3Rw0","b3-b2SrLS6E"]}]},{"id":"incalzire","titlu":"Încălzire","rezumat":"Mers pe înclinare, bandă elastică, apoi seturi în rampă înainte de primul exercițiu mare. Încălzirea pregătește, nu obosește.","reguli":[{"text":"Începe cu circa 10 minute de mers pe bandă înclinată, ușor.","surse":["1-fhMgpzndk","8VhUvd2KAPY"]},{"text":"Apoi mimează mișcările zilei cu o bandă elastică ușoară, 10–15 repetări, în 1–3 circuite.","surse":["nidOZfyTHuY","T22M8iHv_qw","U9B1qzmQ6Qw"]},{"text":"Înainte de primul exercițiu mare fă seturi în rampă la 25%, 50% și 75% din greutatea de lucru.","surse":["1-fhMgpzndk","8VhUvd2KAPY"]},{"text":"La exercițiile următoare ajunge un set ușor, la ~50% din greutatea de lucru, 5–8 repetări.","surse":["FZxtY3H9rDs","U9B1qzmQ6Qw"]},{"text":"Înainte de maximul de antrenament: 4–5 seturi în rampă, cu repetări tot mai puține și ușoare, ca să nu obosești; ex. la 200 lb: bara, ~100, ~150. Apoi 2–3 minute pauză.","surse":["2eM-7Pj3Qmk","e0DBQ7ZZNRM"]},{"text":"După maxim, primul exercițiu de masă cere mai multă încălzire: un set la ~50% și încă unul-două dacă simți nevoia.","surse":["xM9_9tb-8cA"]},{"text":"Seturile de încălzire servesc să repeți mișcarea, nu sunt stimul de creștere. Dacă obosești la ele, ai exagerat.","surse":["-Oe2CTnFOfE","ErlBDk2ujgk","cBriDXhva_M"]},{"text":"Lasă ~2 minute între ultimul set de încălzire și setul de lucru.","surse":["U9B1qzmQ6Qw","U27_hwmXcMU"]},{"text":"În ziua de picioare mergi mai mult (10–12 minute) și adaugi genuflexiuni și fandări cu greutatea corpului.","surse":["U9B1qzmQ6Qw","yp9lDT0qWGU"]},{"text":"Autorul consideră prea mult 20 de minute de stretching și foam rolling înainte de antrenament, dar spune să găsești ce merge la tine.","surse":["U9B1qzmQ6Qw"]}]},{"id":"mobilitate","titlu":"Mobilitate","rezumat":"O rutină scurtă, de circa 5 minute, care lucrează invers față de statul pe scaun, cu atârnatul la bară ca exercițiu principal.","reguli":[{"text":"Rutina are patru mișcări, circa 5 minute: dead hang, genuflexiune adâncă cu sprijin, dislocate cu bandă și pull-apart cu bandă.","surse":["FqeZjz_UVhw","iRdJk7dl2Tg"]},{"text":"Începe cu o rundă, apoi 2–3. Zilnic, la două zile sau de 3 ori pe săptămână.","surse":["iRdJk7dl2Tg"]},{"text":"Dead hang: pornești de la 5–10 secunde, adaugi câte o secundă pe zi, țintă un minut (autorul pomenește și 2 minute).","surse":["AyqHsxN8z4E","yawtsSeFnVU","2hvjiZhW2V4"]},{"text":"Atârni la lățimea umerilor, relaxat, și oprești setul când cedează priza. Arsura în palme e normală.","surse":["2hvjiZhW2V4","yawtsSeFnVU","HFWyYhnhga8"]},{"text":"Durerea ascuțită sau senzația de ciupit nu sunt normale, spune autorul: nu forța, schimbă priza sau folosește sprijin.","surse":["yawtsSeFnVU","HFWyYhnhga8"]},{"text":"Dacă e prea greu, ține picioarele pe sol sau pe un taburet, ori adună 30 de secunde din mai multe seturi scurte.","surse":["yawtsSeFnVU","HFWyYhnhga8"]},{"text":"Genuflexiune adâncă: te ții de ceva stabil, 30–60 de secunde, cu mici balansuri laterale, ca să se deschidă șoldurile, genunchii și gleznele.","surse":["iRdJk7dl2Tg"]},{"text":"Dislocate și pull-apart: bandă ușoară, prindere lată, lent, 10–15 repetări.","surse":["iRdJk7dl2Tg","FqeZjz_UVhw"]},{"text":"Rutina nu anulează lipsa generală de mișcare din restul zilei.","surse":["iRdJk7dl2Tg"]}]},{"id":"cardio-pasi-sprint","titlu":"Cardio, pași, sprint","rezumat":"Mersul e baza. Zona 2 și sprintul sunt adaosuri utile, iar sprintul se introduce treptat.","reguli":[{"text":"Țintește 8.000–10.000 de pași pe zi; cardio complicat nu e necesar.","surse":["YOZvoWwP7EQ","VwuWli9zgw8","muF7RTPUtnY"]},{"text":"Adună pașii din plimbări de 10–20 de minute: după mese, în pauza de prânz, în timpul apelurilor.","surse":["YOZvoWwP7EQ","S4S7TGkxxh0"]},{"text":"În zilele libere rămâi activ (mers, drumeție, ce-ți place), fără să le transformi în alte antrenamente grele.","surse":["Uyc3ckbLcaI","OKRYok3x7PY","muF7RTPUtnY"]},{"text":"Zona 2, opțional: de 2–3 ori pe săptămână, 30–45 de minute de mers înclinat, jogging sau bicicletă, la un ritm la care poți vorbi.","surse":["ZFwDddMSKNA","JN-H7WmqUC8","8y1egHz8Wfk","muF7RTPUtnY"]},{"text":"Dacă n-ai alergat de ani, nu sprinta la maxim din prima zi: riști o ruptură. Ia 1–2 săptămâni de mers rapid, apoi jogging ușor, apoi rampe, în 3–4 săptămâni.","surse":["VKhiEDYrfME","4Ho5_GLpgaE"]},{"text":"Ședința de sprint: mers 10–15 minute, încălzire dinamică, rampe la 25%, 50%, 75%, pauză 2–3 minute, sprinturi, apoi 5–10 minute de mers.","surse":["VKhiEDYrfME"]},{"text":"Cel mult o ședință pe săptămână, cu 5–6 zile între ele: solicită sistemul nervos, mai ales dacă ridici deja greutăți.","surse":["VKhiEDYrfME","4Ho5_GLpgaE"]},{"text":"Doza din programul actual: un singur sprint de ~15 secunde, după 15 minute de încălzire. Cu bază, autorul a descris și 3–5 repetări la 85–95%, cu pauză completă.","surse":["FZxtY3H9rDs","JN-H7WmqUC8"]},{"text":"Rutina completă a autorului: 3 ședințe de forță, un sprint, 2–3 mersuri în zona 2 și o drumeție de 1–1,5 ore, în total 6–7 ore pe săptămână.","surse":["tem5qbLH_yU","emdDtstpdhQ"]}]},{"id":"somn-recuperare","titlu":"Somn și recuperare","rezumat":"Mușchiul crește în recuperare, iar somnul e baza ei. Când oboseala se adună, ai trei trepte de deload.","reguli":[{"text":"Dormi 7–9 ore, minimum 7.","surse":["gbIZRqg1xW8","8KkXKHfMeDk","L7vM1bry5xY","zCcNkYPjCM4"]},{"text":"Cameră întunecată și răcoroasă (la autor ~66°F), ore de culcare asemănătoare.","surse":["JN-H7WmqUC8","8y1egHz8Wfk","4XH3jADQF7c"]},{"text":"Seara redu lumina puternică și ecranele; autorul le oprește cu o oră înainte de culcare.","surse":["JN-H7WmqUC8","8y1egHz8Wfk","9l_6xX_EiZY"]},{"text":"Dacă ești mereu obosit, încearcă pauze mai lungi: recuperarea cuprinde articulațiile, țesutul conjunctiv și sistemul nervos, nu doar mușchiul.","surse":["m22CSK1BeQo","lEqHr1xFNrk"]},{"text":"Semne că ai nevoie de deload: forță mai mică la 2–3 antrenamente la rând, aceeași greutate pare mai grea, dureri de coate, genunchi sau umeri, lipsă de chef.","surse":["Q_Vrou61U7s"]},{"text":"Trei trepte: scurtezi sesiunea unui mușchi; câteva zile cu seturi și greutate la jumătate; o săptămână fără greu, doar mers și mobilitate. Într-o săptămână nu pierzi mușchi.","surse":["e5QQoVvz27s","Q_Vrou61U7s"]},{"text":"Febra musculară de 3 zile e normală. Dacă te miști bine, te poți antrena; dacă șchiopătezi, mai așteaptă 1–2 zile.","surse":["PyUWVf5sT-E"]},{"text":"După o boală, autorul spune că mușchiul nu se pierde în câteva zile; revii ușor, fără record. După pauze lungi poți coborî la jumătate din greutate.","surse":["PzSoRFzZvps"]},{"text":"Cofeina târzie strică somnul: un energizant de 300 mg i-a făcut rău autorului, iar el recomandă să sari peste pre-workout dacă te afectează.","surse":["75F_fBrqbE0","Aw617z0_Jwk"]},{"text":"Sauna și baia rece sunt opționale: autorul le folosește în zilele de odihnă, pentru relaxare, și nu cere nimănui să le facă.","surse":["8y1egHz8Wfk","JN-H7WmqUC8"]}]},{"id":"nutritie-de-baza","titlu":"Nutriție de bază","rezumat":"Trei mese din alimente întregi, destulă proteină și puține decizii. Porțiile se reglează după scop, iar alimentele rămân aceleași.","reguli":[{"text":"Construiește ziua din 3 mese, fiecare cu proteină, carbohidrat și grăsime, plus fructe sau un shake. Repetă-le ca să nu mai decizi zilnic.","surse":["prlPEyBYx8k","-ch1zQ3RoH0","muF7RTPUtnY"]},{"text":"Alimentele de bază ale autorului: vită, pulpe de pui, ouă, orez, cartofi, ovăz, fructe, miere, avocado, lapte integral.","surse":["L4-puJMoDwA","-ch1zQ3RoH0"]},{"text":"Proteină: 0,7–1 g pe lb din greutatea țintă (la 180 lb, până la 180 g). Autorul spune că 0,6 poate ajunge și că nu trebuie să fie exact.","surse":["f34RCE783lU","zCcNkYPjCM4","fbIrvzknGXY"]},{"text":"Momentul meselor nu e critic: atinge caloriile până seara, în 3–4 mese.","surse":["B4YT98ugQ3c","w_fkIHPJdU0"]},{"text":"Gătește de două ori pe săptămână pentru 3–4 zile, ca să nu decizi când ești flămând și obosit.","surse":["l5QGU5fAf2k","JtS8_w30UuQ","75F_fBrqbE0"]},{"text":"Bea mai ales apă (la autor, cam 90% din băuturi), uneori apă de cocos. Multe calorii vin din sucuri, ceai dulce și cafele aromate.","surse":["-ch1zQ3RoH0"]},{"text":"Autorul respinge ideea că doar caloriile contează: spune că și calitatea mâncării contează pentru sățietate și stare. Afirmațiile despre inflamație sunt convingerea lui.","surse":["EgfDOKTZc2A","n1Y-4fpw7wY","94GwBmWR8ZQ"]},{"text":"Pofta de dulce o stingi cu fructe, curmale, mango uscat sau miere cu lapte.","surse":["WfJxlgXaV5w","72TB-Fe05nY"]},{"text":"Citește etichetele la sosuri, cârnați, ketchup și bulion: pot ascunde zahăr, gume sau arome. Autorul evită și dietele extreme, ca keto sau carnivor.","surse":["Hv1-LP17xcI","UWqmz_mmVP0"]},{"text":"Dacă ai ieșit din plan, revino imediat: o masă proastă nu șterge progresul. Scoate din casă ce te tentează.","surse":["JZnC4Z_NAcc","72TB-Fe05nY"]}]},{"id":"masa-musculara","titlu":"Masă musculară","rezumat":"Surplus mic, cântar des și răbdare de ani. Dacă ești deja suplu și tot arăți moale, ai nevoie de mușchi, nu de altă dietă.","reguli":[{"text":"Calorii de pornire: greutatea în lb înmulțită cu 16–18 (la 194 lb ies 3.100–3.500 kcal).","surse":["OfxF0BXjYVU","prlPEyBYx8k","f34RCE783lU"]},{"text":"Ritm: ~0,5 lb pe săptămână (2 lb pe lună), pornind cu 100–200 kcal peste menținere; mai repede aduce mai ales grăsime.","surse":["UhuopEQ8QT8","OfxF0BXjYVU"]},{"text":"Dacă ești slab și începător, canalul acceptă și ~1 lb pe săptămână; 2–3 lb pe săptămână sunt prea mult.","surse":["f34RCE783lU"]},{"text":"Cântărește-te des și urmărește media săptămânală. Dacă greutatea stă 1–2 săptămâni, adaugi 100–200 kcal; dacă urcă prea repede, scazi.","surse":["OfxF0BXjYVU","prlPEyBYx8k"]},{"text":"Mănânci aceleași alimente și mărești doar porțiile, în loc să adaugi fast food.","surse":["0YP727tA_eQ"]},{"text":"Dacă îți e greu să mănânci, bea calorii: 10–12 oz lapte integral, ½ cană ovăz, 1 lingură unt de nuci, 1 lingură miere, 1 măsură proteină; ~700–1.000 kcal, ~40 g proteină.","surse":["WGoSTMap1kY","KZdr0-tmNs4"]},{"text":"La 12–15% grăsime, dacă tot nu arăți atletic, nu mai slăbi: autorul ar sta 6–12 luni la menținere, urmărind progres real la greutăți.","surse":["E8bmNNi5-TI","I233qZbltas"]},{"text":"Nu poți slăbi până ajungi musculos: dieta și cardio nu construiesc mușchi. Ai nevoie de ani de progres, de exemplu bancă de la 155 la 225 lb.","surse":["L-QUyYo_XsI","t6KWcIbchmc","W1Tv7nmlQko"]},{"text":"Dacă nu crești, verifică patru lucruri: devii mai puternic, mănânci pentru obiectiv, te recuperezi, ai fost consecvent destul?","surse":["AHy7ARspuI8","zTjDkYhb9Bk"]},{"text":"Reper orientativ, nu magic: la 6 ft, 185–195 lb cu 10–12% grăsime, ±5 lb pentru fiecare inch; de la 135 la 185 lb durează ani, nu luni.","surse":["EHDnCWkiH2s","f34RCE783lU"]}]},{"id":"slabit","titlu":"Slăbit","rezumat":"Deficit mic, măsurat cu media săptămânală, mers zilnic și mâncare care sățură. În sală păstrezi forța, nu cauți recorduri.","reguli":[{"text":"Stabilește întâi unde vrei să ajungi, vezi unde ești și repară cel mai mare decalaj. Bulk, cut și menținere sunt faze, nu decizii permanente.","surse":["EHDnCWkiH2s"]},{"text":"La 25–30% grăsime slăbești întâi, spre 10–12%, chiar dacă pari mic; apoi alternezi faze de creștere și de slăbire.","surse":["Sm6Wiwopgek","EHDnCWkiH2s"]},{"text":"Skinny fat: autorul le spune celor mai mulți să slăbească întâi. Dacă greutatea totală e mică, propune recompoziție: greutatea în lb × 13 calorii, 3–6 luni, și urmărești forța.","surse":["EHDnCWkiH2s","sKwDk-aXAts","PeRywgqUOrk"]},{"text":"Calorii de pornire, dacă ai mult de dat jos: greutatea în lb × 11–12 (~2.600 la 240 lb). Varianta mai strictă e × 10; alternativ, 300–500 kcal sub menținere.","surse":["6di4J3K45QE","mIKHtae1zfQ","MKVN0MWo1q0"]},{"text":"Cântărește-te dimineața și compară mediile: dacă după 14 zile media nu scade, tai 100 kcal. Ținta e ~1 lb pe săptămână (1–2 lb dacă ai mult de dat jos).","surse":["mIKHtae1zfQ","6di4J3K45QE"]},{"text":"Dacă faci sport și nu slăbești, ești în general în exces: o perioadă notezi tot într-o aplicație, cu cântar de bucătărie, inclusiv uleiurile. Nu trebuie pe viață.","surse":["JoxF1Q0W1wM","etEDym7TORQ"]},{"text":"Sala nu e unealta de slăbit: repetările multe, pauzele scurte și drop set-urile nu ard mai bine. Grăsimea se pierde prin deficit, mâncare întreagă și pași.","surse":["ClJzeSnf76Y","FN6p6adz_tE"]},{"text":"Când slăbești, scopul e să păstrezi forța, nu să bați recorduri. Nu adăuga zile sau volum; dacă pierzi forță, deficitul e probabil prea mare.","surse":["LMWgz3B6oaU","tNeB_nycTvg","H-x21NmP1P8"]},{"text":"Durata fazelor: dacă slăbești mult, iei pauze la menținere când scad somnul sau energia; bulk 4–6 luni, iar la 15–16% grăsime revii spre 12%.","surse":["iCDZHxEmgQg"]},{"text":"Nu forța ritmul și nu schimba totul dintr-odată: alege ce poți ține 6 luni. Carnea, fructele, cartofii și legumele sățură mai bine decât procesatele, spune autorul.","surse":["YOZvoWwP7EQ","x_EQ7T8NYSI","Nl3ovrTxEtY"]}]},{"id":"suplimente","titlu":"Suplimente","rezumat":"Ultimii 5% din rezultat. Autorul folosește creatină, proteină pudră pentru comoditate și cofeină, iar restul ține de experiența lui personală.","reguli":[{"text":"Suplimentele sunt „credit în plus”, ultimii 5%: nu repară mâncarea, somnul sau antrenamentul slab.","surse":["B4YT98ugQ3c","w_fkIHPJdU0","Aw617z0_Jwk"]},{"text":"Creatină: circa 5 g pe zi, constant; momentul nu contează. Ideea autorului e puțin mai multă energie în seturile grele.","surse":["Aw617z0_Jwk","xC7oyqP931g"]},{"text":"Autorul a evitat ani de zile creatina de teama căderii părului, apoi a luat 5–8 g pe zi un an fără probleme vizibile. Crede că depinde de genetică, dar nu promite nimic.","surse":["NxvfThnOtXk"]},{"text":"Proteina pudră e doar comoditate: autorul o ia pentru că are poftă mică. Dacă ajungi la proteină din mâncare, s-ar putea să nu-ți trebuiască.","surse":["xC7oyqP931g","Aw617z0_Jwk","L4-puJMoDwA"]},{"text":"Pre-workout-ul contează mai ales pentru cofeină (150–200 mg la autor). E opțional, iar cafeaua neagră e o alternativă.","surse":["Aw617z0_Jwk","xC7oyqP931g"]},{"text":"Dacă cumperi, citește eticheta: ingrediente puține, doze clare, fără îndulcitori artificiali, coloranți sau umpluturi.","surse":["Aw617z0_Jwk"]},{"text":"Vitamina D cu K2, zincul, borul și magneziul glicinat sunt alegerile lui după analize proprii, prezentate ca experiență personală, nu sfat medical. El pune întâi soarele și mersul afară.","surse":["C188NHVQpJg","l_90Tkv5VzI","btl1dt5MEhM"]},{"text":"Fii atent la cine recomandă: autorul crede că 99% din suplimente sunt exagerate și că mulți influenceri sunt plătiți să le promoveze.","surse":["lqR_eEOSq7g"]}]},{"id":"sala-acasa","titlu":"Sală acasă","rezumat":"Echipamentul scump nu e necesar: corpul răspunde la rezistență și progres. Canalul dă variante de la zero echipament până la o sală completă.","reguli":[{"text":"Corpul nu știe ce echipament folosești, ci simte rezistența și tensiunea. Autorul a construit mare parte din fizic cu greutăți libere și un rack, aproape 5 ani într-o cameră.","surse":["zzUMtWxMLpo","cefFxDOfMVI","X8whyQdJrT8"]},{"text":"Se poate și fără echipament, cu greutatea corpului: de la 20 de flotări spre 40, 60, 80. Ținta e să fii de 2–3 ori mai puternic în 3–4 ani.","surse":["DAuRFLrOZyU"]},{"text":"Doar cu gantere: push, picioare, pull, 3 zile, 2–3 seturi pe mișcare, pauză 1–2 minute.","surse":["ihREYURzyTA","rFNPSQCBc9o"]},{"text":"Zilele cu gantere: press și fly înclinat, press de umeri, laterale, extensii peste cap; goblet squat, bulgar, RDL, gambe; tracțiuni, ramat, rear delt, curl înclinat, hammer.","surse":["ihREYURzyTA","rFNPSQCBc9o"]},{"text":"Progresie cu gantere: când toate seturile ajung la 10 repetări, adaugi ~5 lb (2,5 kg) și revii la 6. Cu gantere ușoare urci la 15–20+ repetări.","surse":["ihREYURzyTA","rFNPSQCBc9o"]},{"text":"O bară de tracțiuni de ușă (~15–20 USD) rezolvă tragerea verticală și atârnatul.","surse":["ihREYURzyTA","2hvjiZhW2V4"]},{"text":"Fără aparate: fandări inverse pentru cvadricepși, Nordic curl pentru flexia genunchiului, ramat inversat, benzi elastice pentru face pull.","surse":["2XHGW1q_OWI","TYEkRRKcncg"]},{"text":"Dacă investești, autorul a ales un aparat convergent în locul unor gantere grele foarte scumpe și ar recomanda un pec deck care face și reverse fly.","surse":["cefFxDOfMVI"]},{"text":"Cu echipament limitat, 5–10 exerciții repetate un an, cu accent pe progres, sunt de ajuns.","surse":["_O5Cq06Z0FM"]},{"text":"Dacă amenajezi un spațiu, fă întâi un plan scris cu schiță și listă de materiale; autorul a pierdut timp fără ele.","surse":["FYRiwDyXx8Q"]}]},{"id":"varsta-viata-ocupata","titlu":"Vârstă și viață ocupată","rezumat":"Regula creșterii nu depinde de vârstă, dar recuperarea și timpul cer un program mai scurt. Autorul se antrenează ca să poată continua toată viața.","reguli":[{"text":"Se poate construi masă și la 46 de ani: antrenament greu, greutăți tot mai mari la exerciții de bază, odihnă bună. Autorul socotește ~3 ani pentru o schimbare vizibilă.","surse":["vtmY4_1s1_k"]},{"text":"După 30 de ani, spune autorul, recuperarea scade și stresul crește, deci ai nevoie de un plan clar: 3–4 zile, 10.000 de pași, 3–4 mese reale, 7–8 ore de somn.","surse":["582sBxlvftA","x7hOr7fXnww"]},{"text":"Ce merge la 16–20 de ani te ajunge din urmă la 25–30+: volumul mare aduce cu anii dureri de umăr sau lombare și recuperare mai slabă.","surse":["DelpEXC3xvQ"]},{"text":"Cu cât te gândești mai devreme la longevitate, cu atât poți antrena mai mult. Autorul vrea să rămână funcțional: să alerge, să sară, să sprinteze.","surse":["uFjxLXzpbUA","tow9D6MjMR4","DLwdwe_1ECk"]},{"text":"Pe măsură ce îmbătrânește, autorul crede că va trece de la 6–10 la mai multe repetări, pentru inimă și menținerea forței.","surse":["cBbcY8WsMQ4"]},{"text":"Nu trebuie să crești greutatea la nesfârșit: la un nivel ridicat poți încerca o variantă mai grea sau doar să menții. Menținerea costă puțin.","surse":["cZp_s3Y8Jdc","bLVQxZHVGJA","IXkXSmFjgko"]},{"text":"Cu o muncă fizică lungă: antrenează-te dimineața devreme, 3 zile cu zi liberă între ele, 4–5 exerciții, un set (2–3 la început), 6–20 repetări, ~45 de minute.","surse":["75F_fBrqbE0","Fc-PP2DI7QM"]},{"text":"Cu muncă fizică, caloriile și apa trebuie să fie la punct: pregătește dinainte 2–3 mese simple și plănuiește în ce zile gătești.","surse":["75F_fBrqbE0","Fc-PP2DI7QM"]},{"text":"Timp: tot ce face autorul (forță, sprint, zona 2, drumeție) înseamnă 6–7 ore, circa 6% din săptămână. Minimul, dacă ești aglomerat: 3 zile de forță și mers.","surse":["tem5qbLH_yU","emdDtstpdhQ","hgGkEi8Otho"]},{"text":"Cel mai bun moment de antrenament e cel la care poți fi consecvent. Dacă vrei dimineața, autorul sugerează culcare la 20:00 vreo 2 săptămâni.","surse":["i7S2ydHNyA8"]}]},{"id":"accidentari-articulatii","titlu":"Accidentări și articulații","rezumat":"Autorul vede accidentarea ca principalul dușman al progresului și ea vine de obicei din acumulare. Sunt observațiile lui de antrenament, nu sfaturi medicale.","reguli":[{"text":"Accidentarea oprește progresul mai sigur decât orice, iar de obicei vine din acumulare (articulații, stres, recuperare slabă), nu dintr-o singură repetare proastă.","surse":["Q_Vrou61U7s","hL_IAtK-bzM"]},{"text":"Mușchiul se reface mai repede decât tendoanele, articulațiile și sistemul nervos, spune autorul; de aici vin durerile la frecvență mare.","surse":["kh7uKFRGeGg","lNM7WP_Q8cQ","m22CSK1BeQo"]},{"text":"Full body de trei ori pe săptămână, doar pentru începători: la avansați, cu greutăți mari, tendoanele și articulațiile nu apucă să se refacă, după autor.","surse":["g-w7CTmHpEc","cuDppRxClS4"]},{"text":"Autorul spune să nu treci de 4 zile pe săptămână: câștigul posibil e 1–3%, iar costul e mai mult stres pe articulații. Părerea lui.","surse":["LVjooloBATE","QaZJPcC3Ldc","zYG0TB4YHeQ"]},{"text":"La dureri minore, reduci întâi numărul de zile, apoi totalul de seturi și repetări pe săptămână.","surse":["pBs-N1O9nKQ"]},{"text":"Durerile care apar la antrenament (cot, umăr, lombar) sunt semn că ceva nu e în regulă: nu continua forțat de teama de a pierde mușchi.","surse":["c98R5tp7vzE","DelpEXC3xvQ"]},{"text":"Febra musculară e difuză; durerea e ascuțită, localizată și crește la mișcare. Diferența îți spune dacă poți continua, după autor.","surse":["PyUWVf5sT-E"]},{"text":"Dacă un exercițiu îți doare articulațiile, nu e obligatoriu: alegi alternativa din același tipar (split squat, presă, hack squat).","surse":["NbFRi-yhEus","EcGRYz_fGjA"]},{"text":"Evită salturile mari și orgoliul: strică tehnica și duc la accidentări. La deadlift foarte greu, autorul a renunțat la priza mixtă, pe care o leagă de rupturile de biceps.","surse":["hoI88DObYt8","5_vs8uHtuxM"]},{"text":"Când a simțit inflamație la cot, autorul a trecut de la curl înclinat cu gantere la cablu; spune și că prea multe variații de curl pot irita cotul.","surse":["DoZMGROx4mw","rsjLRvOrXCg"]}]},{"id":"mentalitate-consecventa","titlu":"Mentalitate și consecvență","rezumat":"Disciplina zilnică bate motivația. Scrii de ce o faci, ce ai de făcut azi, și te compari doar cu tine.","reguli":[{"text":"Scrie de ce fugi și unde vrei să ajungi. Când n-ai chef, te întorci la cele două: motivația negativă și cea pozitivă se completează.","surse":["8Bz4lVc55Mk","-9tGTJbAAVY","eQ9WsoP7pfQ"]},{"text":"Scrie-ți obiectivele pe hârtie, dimineața. Autorul crede că ajută și spune să nu-l crezi pe cuvânt, ci să încerci.","surse":["88o5if4xIOg","nxRI7jrxHTY"]},{"text":"Fă o listă zilnică de lucruri nenegociabile și bifeaz-o seara: antrenament, mâncare, somn, pași. Intenția singură nu ajunge.","surse":["H_1Wlszwn64","ULe39j3WZ48","JOx4U5GfpL0"]},{"text":"Gândește-te la scop, dar întreabă-te zilnic ce poți face azi, ca un alpinist care se uită la pasul următor.","surse":["za5qnUph5Wk","eQ9WsoP7pfQ"]},{"text":"Nu aștepta motivația: disciplina înseamnă să faci antrenamentul indiferent de dispoziție. Autorul zice că se trezește devreme fără să fie motivat.","surse":["xrGCzDJWZKQ"]},{"text":"Dacă ai ratat o săptămână, nu renunța: revino imediat, trage o învățătură și reia. Consecvența se măsoară în ani.","surse":["E_VBVAD-gYY","c3cVA3A7Yoc","eNnrZex3s1w"]},{"text":"Nu te uita în oglindă după fiecare antrenament: schimbările se văd după 6 luni sau un an.","surse":["rnSPcwVEhA0","xmYG3zKH2b4"]},{"text":"Singura ta competiție e versiunea din săptămâna trecută. Când ajustezi, te uiți în jurnal, nu la emoții.","surse":["OtqjSaag7bw","CUbYdJBj3YU"]},{"text":"La sală nu se uită nimeni la tine, iar anxietatea dinaintea unui set greu e normală. Încrederea vine din expunere repetată, nu aștepta să te simți pregătit.","surse":["7Ao2ofppMso","ZbGPcfYOa0I"]},{"text":"Anii trec oricum: chiar făcut doar 60–70% corect, tot ajungi mult mai departe decât dacă nu încerci.","surse":["t261vAFaV8w"]}]},{"id":"mike-mentzer","titlu":"Mike Mentzer","rezumat":"Sursa de inspirație pentru volumul mic și intensitatea mare. Autorul preia principiile, le adaptează și nu le recomandă începătorilor.","reguli":[{"text":"Esența lui Mentzer: antrenament rar (la 72 de ore sau mai mult), un set la failure pe 4–5 exerciții, 20–30 de minute, cu repetări sau greutate în plus de fiecare dată.","surse":["jrfKmlpme2g","kgZJG14B41E","8y45XSPCSLo"]},{"text":"După un set dus la failure nu mai trebuie al doilea: mecanismul e pornit, ca un întrerupător. Ordinea e semnal, recuperare, apoi creștere.","surse":["qUx8jZdxwsw","VW8k13v1DAI","NsNFXs-gS6M"]},{"text":"Dacă cineva spune că merge doar cu steroizi: aceia s-ar recupera și la mai mult volum, deci fără ajutor principiul contează și mai mult, argumentează autorul.","surse":["sNGEvHVAzWE"]},{"text":"Poziția autorului: crede că ar fi ajuns la același fizic cu un singur set, dar admite că mulți au reușit cu volum mare. Nu cere nimănui să facă la fel.","surse":["8y45XSPCSLo","kgZJG14B41E"]},{"text":"Metoda nu e pentru începători: ei au de învățat execuția. Pentru ei, 2–3 seturi, apoi failure când forma e bună.","surse":["JTYsvbXwRkM","wu12RyDzpsI"]},{"text":"Ajustarea autorului: de peste un an aplică stilul, dar nu mai face din failure ținta, ci o repetare în plus față de data trecută.","surse":["niRNSxLWHns"]},{"text":"Rutina originală, ziua 1: pec deck 6–10, în 3–5 secunde press înclinat 1–3, apoi pulldown cu priză supinată 6–10 și deadlift 5–10 (înlocuibil cu shrug).","surse":["Bc8fhTiTBnI","KKI_Kf6wFRw"]},{"text":"Ziua 2: extensii, imediat presă de picioare, flexii culcat, gambe în picioare, câte un set; picioarele revin abia după 5–8 zile.","surse":["y4uCrUu6VyM","d57ZJN61p8Q"]},{"text":"Ziua 3: laterale, rear delt, curl cu bară dreaptă, pushdown urmat în 3–5 secunde de dips; 5 seturi în total, 6–10 repetări, lent.","surse":["ccncKLw5pEE","SOANI6TeFvw"]},{"text":"Exerciții ridicate în slăvi de Mentzer: dips (piept, umeri, triceps, 6–10 repetări stricte) și pulldown cu priză îngustă supinată pentru biceps.","surse":["ioOwUgq9VyA","8aLmwbpaDKg"]}]}],"schimbari":[{"subiect":"Failure ca țintă","inainte":"Întâi seturi oprite cu 2–3 repetări în rezervă, apoi, din septembrie 2025 până în primăvara lui 2026, un set dus la eșec total ca nucleu al metodei.","acum":"Ținta e progresul față de data trecută; setul merge până la failure sau până la un record nou, ce vine primul. Autorul însuși continuă să facă seturi foarte grele.","surse_inainte":["RubN0kWnD3Q","W5LGNfps21Q","nidOZfyTHuY"],"surse_acum":["niRNSxLWHns","qWYd5OUH-_s","e0DBQ7ZZNRM"]},{"subiect":"Volum","inainte":"3 seturi pe exercițiu și circa 8–10 seturi pe grupă pe săptămână; în septembrie 2025 încă pomenea un minim de 10 seturi pe grupă.","acum":"1–3 seturi pe exercițiu, după vechime, 2–3 pentru majoritate; autorul pornește de la cam 6 seturi grele pe grupă, iar el face 4–6.","surse_inainte":["lVDrlOw3gcQ","tMH6Eqg5Nho","xCCsW-z4-c0"],"surse_acum":["1-fhMgpzndk","4jUUv_-gveo","gbIZRqg1xW8","w_fkIHPJdU0"]},{"subiect":"Cine poate face un singur set","inainte":"Potrivit după circa un an de antrenament.","acum":"1×4 e pentru avansați; primii 0–2 ani merg pe 3×4, iar 2–3+ ani pe 2×4. Pragurile nu sunt stricte.","surse_inainte":["U27_hwmXcMU","c8DdCFc0DOQ"],"surse_acum":["1-fhMgpzndk","8VhUvd2KAPY"]},{"subiect":"Split și frecvență pe grupă","inainte":"Upper/lower de 4 zile, fiecare grupă de două ori pe săptămână, propus și pentru masă.","acum":"3 zile piept-umeri-triceps, picioare, spate-biceps, fiecare grupă o dată pe săptămână. Upper/lower rămâne o opțiune la început sau la 2 zile.","surse_inainte":["quuU8yJP8G8","x8Hyc40M2Z4","M7Icuymhtb4"],"surse_acum":["1-fhMgpzndk","g-w7CTmHpEc","5qYOMywutrY"]},{"subiect":"Câte zile pe săptămână","inainte":"3–4 zile, 45–60 de minute, ca recomandare generală.","acum":"3 zile sunt baza, sub o oră, iar pentru un avansat chiar și două pot ajunge. A patra zi e opțională sau pentru începători.","surse_inainte":["e8aJXIpQaec","HTt1fsJpxSI"],"surse_acum":["IM183WSvPpA","OKRYok3x7PY","dfLJjmJVZxM","4XtKPXrOfeY"]},{"subiect":"Intervalul de repetări","inainte":"În rutina de 3 zile din 2025: 3 seturi de la 8 la 12 repetări la toate exercițiile, apoi greutate.","acum":"6–10 la compuse și 8–15 la izolări.","surse_inainte":["lVDrlOw3gcQ","u8uor1_OBzU","dqOprOM719U"],"surse_acum":["1-fhMgpzndk","L7vM1bry5xY"]},{"subiect":"Încălzire","inainte":"În prezentarea 1×4 din aprilie 2026: câte un singur set de încălzire la 50% pe fiecare exercițiu.","acum":"Circa 10 minute de mers înclinat și seturi în rampă la 25%, 50%, 75% înainte de primul exercițiu mare; 4–5 seturi în rampă înainte de maximul de antrenament.","surse_inainte":["FdqsrOh-4_4","nidOZfyTHuY"],"surse_acum":["1-fhMgpzndk","8VhUvd2KAPY","2eM-7Pj3Qmk"]},{"subiect":"Exercițiile mari cu bara","inainte":"Genuflexiunea, banca și deadlift-ul cu bara nu erau necesare; autorul renunțase la ele în favoarea aparatelor, cablurilor și ganterelor.","acum":"Pentru cine are bază, canalul a adăugat rutina cu maxim de antrenament la bancă, overhead press, genuflexiune, trap bar și tracțiune cu greutate. Metoda ×4 rămâne în paralel.","surse_inainte":["pC-jjoqZReM","ss0n8IeU87k"],"surse_acum":["e0DBQ7ZZNRM","xM9_9tb-8cA","Fs6RYD5h_bM"]},{"subiect":"Proteină","inainte":"Circa 1 g pe lb, ca țintă fixă.","acum":"0,7–1 g pe lb din greutatea țintă, iar autorul spune că și 0,6 poate ajunge; proteina nu mai e prezentată ca prioritate, ci caloriile și antrenamentul.","surse_inainte":["zC_w7ddHXq0","quuU8yJP8G8","x8Hyc40M2Z4"],"surse_acum":["f34RCE783lU","zCcNkYPjCM4","fbIrvzknGXY","aWsiy2crohU"]},{"subiect":"Surplusul la masă","inainte":"300–500 kcal peste menținere.","acum":"Pornești cu 100–200 kcal peste menținere, iar ritmul-țintă e ~0,5 lb pe săptămână. Autorul spune că nu e nevoie de surplus mare.","surse_inainte":["w0FDzY-ilPU","QE8KFdDG4jk","_dky9gJuKzo"],"surse_acum":["UhuopEQ8QT8","KZdr0-tmNs4"]},{"subiect":"Calorii de pornire la masă","inainte":"Menținere = greutatea în lb × 15, plus 200–300 kcal.","acum":"Direct greutatea în lb × 16–18, apoi ajustezi după media săptămânală.","surse_inainte":["x8Hyc40M2Z4","9YsNxVhzcls"],"surse_acum":["prlPEyBYx8k","OfxF0BXjYVU","f34RCE783lU"]},{"subiect":"Calorii de pornire la slăbit","inainte":"Greutatea în lb × 12–14, apoi, în aprilie 2026, × 10.","acum":"În cel mai nou exemplu detaliat, × 11–12, cu întrebarea care e cea mai mare cantitate de mâncare cu care încă pierzi constant grăsime.","surse_inainte":["tq-WkxYtxt4","L-UIadt2VJU"],"surse_acum":["6di4J3K45QE"]},{"subiect":"Skinny fat: ce faci întâi","inainte":"Canalul a oscilat: menținere sau puțin peste (aprilie 2025), slăbit întâi (2025 – începutul lui 2026), recompoziție (iulie 2026).","acum":"Cei mai mulți slăbesc întâi; recompoziția rămâne pentru cine are greutate totală mică. Clipurile noi nu se aliniază complet, deci decizia depinde de punctul tău de plecare.","surse_inainte":["igx_uBaIiyc","b8WRWoCVeEI","cSKe9gyIQlU","eKk5xaFID4w"],"surse_acum":["EHDnCWkiH2s","sKwDk-aXAts","Sm6Wiwopgek"]},{"subiect":"Sprint","inainte":"O ședință pe săptămână cu 3–5 sprinturi, cu dorința de a ajunge la 5.","acum":"În programul prezentat din aprilie 2026 încoace, un singur sprint de ~15 secunde, în ziua opțională, după 15 minute de încălzire.","surse_inainte":["8y1egHz8Wfk","4Ho5_GLpgaE","JN-H7WmqUC8"],"surse_acum":["FdqsrOh-4_4","FZxtY3H9rDs"]},{"subiect":"Cum vede autorul metoda lui Mentzer","inainte":"Un experiment după 10 ani de sală, care nu i-a construit fizicul, nerecomandat începătorilor și intermediarilor timpurii.","acum":"Crede că ar fi avut un fizic mai bun, în jumătate de timp și cu mai puține dureri, dacă ar fi început așa; tot nu o recomandă începătorilor.","surse_inainte":["ccncKLw5pEE","W5LGNfps21Q"],"surse_acum":["JTYsvbXwRkM","8y45XSPCSLo"]}]}};
